/// The complete approval captured by a reviewed Push.
#[derive(Clone, Debug)]
pub struct PushApproval {
    pub credential_redaction_enabled: bool,
    pub subagent_selections: BTreeMap<ResourceId, SubagentSelection>,
    pub recipe: BundleRecipe,
    pub project_content_review_token: Option<String>,
    pub git_history_review_token: Option<String>,
    pub project_content_removal_ids: Vec<ResourceId>,
    pub acknowledged_warning_digests: Vec<String>,
}

impl PushApproval {
    pub fn recommended(review: &PushReviewContext, storage_id: &StorageId) -> Self {
        let recipe = recommended_review_recipe(review, storage_id);
        Self {
            credential_redaction_enabled: review.credential_redaction_enabled,
            subagent_selections: review
                .thread_comparison
                .as_ref()
                .into_iter()
                .flat_map(|comparison| &comparison.entries)
                .map(|entry| (entry.resource_id.clone(), entry.subagent_selection.clone()))
                .collect(),
            recipe,
            project_content_review_token: None,
            git_history_review_token: review.git_history_review_token.clone(),
            project_content_removal_ids: Vec::new(),
            acknowledged_warning_digests: Vec::new(),
        }
    }
}

/// Production project-sync use cases over an explicit machine repository.
#[derive(Clone, Copy)]
pub struct ProjectSyncService<'a> {
    repository: &'a LocalStateRepository,
}

impl<'a> ProjectSyncService<'a> {
    pub fn new(repository: &'a LocalStateRepository) -> Self {
        Self { repository }
    }

    pub fn create_setup_draft(
        &self,
        project_root: &Path,
    ) -> Result<CreateSetupDraftResult, String> {
        let project_root = project_root
            .to_str()
            .ok_or_else(|| "project root is not valid UTF-8".to_string())?;
        create_setup_draft_with_repository(self.repository, project_root)
    }

    pub fn update_setup_draft(
        &self,
        draft: ProjectSetupDraft,
    ) -> Result<ProjectSetupDraft, String> {
        update_setup_draft_with_repository(self.repository, draft)
    }

    pub fn inspect_setup_draft(
        &self,
        draft_id: &SetupDraftId,
    ) -> Result<SetupDraftInspection, String> {
        inspect_setup_draft_with_repository(self.repository, draft_id)
    }

    pub fn finalize_project_setup(
        &self,
        draft_id: &SetupDraftId,
        expected_revision: u64,
    ) -> Result<ProjectDetail, String> {
        finalize_project_setup_with_repository(self.repository, draft_id, expected_revision)
    }

    pub fn prepare_push_review(
        &self,
        local_project_id: &LocalProjectId,
        storage_id: &StorageId,
    ) -> Result<PushReviewContext, String> {
        self.prepare_push_review_with_phases(local_project_id, storage_id, &mut |_, _| {})
    }

    pub fn prepare_push_review_with_phases(
        &self,
        local_project_id: &LocalProjectId,
        storage_id: &StorageId,
        on_phase: &mut dyn FnMut(&str, Duration),
    ) -> Result<PushReviewContext, String> {
        prepare_push_review_with_progress(self.repository, local_project_id, storage_id, on_phase)
    }

    pub fn push_reviewed(
        &self,
        local_project_id: &LocalProjectId,
        storage_id: &StorageId,
        approval: PushApproval,
    ) -> Result<ProjectOperationResult, String> {
        self.push_reviewed_with_progress(
            local_project_id,
            storage_id,
            approval,
            &mut |_| {},
            &mut |_, _| {},
        )
    }

    /// *Finish that push*: the record an earlier push claimed and never
    /// wrote is written once, and the result is reported. The user's verb.
    pub fn finish_unfinished_push(
        &self,
        local_project_id: &LocalProjectId,
        storage_id: &StorageId,
    ) -> Result<(), String> {
        finish_unfinished_push(self.repository, local_project_id, storage_id)
    }

    pub fn push_reviewed_with_progress(
        &self,
        local_project_id: &LocalProjectId,
        storage_id: &StorageId,
        approval: PushApproval,
        on_progress: &mut dyn FnMut(FetchProgress),
        on_phase: &mut dyn FnMut(&str, Duration),
    ) -> Result<ProjectOperationResult, String> {
        push_bundle_reviewed_with_progress(
            self.repository,
            local_project_id,
            storage_id,
            approval.recipe,
            ProjectContentPushReview {
                credential_redaction_enabled: approval.credential_redaction_enabled,
                subagent_selections: approval.subagent_selections,
                review_token: approval.project_content_review_token,
                git_history_review_token: approval.git_history_review_token,
                removal_ids: approval.project_content_removal_ids.into_iter().collect(),
                acknowledged_warning_digests: approval
                    .acknowledged_warning_digests
                    .into_iter()
                    .collect(),
            },
            on_progress,
            on_phase,
        )
    }

    pub fn plan_bundle_restore(
        &self,
        storage_id: &StorageId,
        bundle_id: &BundleId,
        binding: &ProjectBinding,
    ) -> Result<RestorePlan, String> {
        self.plan_bundle_restore_with_progress(
            storage_id,
            bundle_id,
            binding,
            &mut |_| {},
            &mut |_, _| {},
        )
    }

    pub fn plan_bundle_restore_with_progress(
        &self,
        storage_id: &StorageId,
        bundle_id: &BundleId,
        binding: &ProjectBinding,
        on_progress: &mut dyn FnMut(FetchProgress),
        on_phase: &mut dyn FnMut(&str, Duration),
    ) -> Result<RestorePlan, String> {
        plan_bundle_restore_with_progress(
            self.repository,
            storage_id,
            bundle_id,
            binding,
            on_progress,
            on_phase,
        )
    }

    pub fn apply_bundle_restore(
        &self,
        review: &RestorePlan,
        approved_action_ids: Vec<ActionId>,
    ) -> Result<RestoreResult, String> {
        self.apply_bundle_restore_with_progress(
            review,
            approved_action_ids,
            &mut |_| {},
            &mut |_, _| {},
        )
    }

    pub fn apply_bundle_restore_with_progress(
        &self,
        review: &RestorePlan,
        approved_action_ids: Vec<ActionId>,
        on_progress: &mut dyn FnMut(FetchProgress),
        on_phase: &mut dyn FnMut(&str, Duration),
    ) -> Result<RestoreResult, String> {
        apply_bundle_restore_with_progress(
            self.repository,
            review,
            approved_action_ids,
            on_progress,
            on_phase,
        )
    }

    pub fn compare_threads(
        &self,
        local_project_id: &LocalProjectId,
        storage_id: &StorageId,
    ) -> Result<ThreadSyncComparison, String> {
        get_project_thread_sync_comparison_with_progress(
            self.repository,
            local_project_id,
            storage_id,
            &mut |_, _| {},
        )
    }

    pub fn get_project_activity(
        &self,
        local_project_id: &LocalProjectId,
        storage_id: Option<&StorageId>,
        branch: Option<&str>,
        before_time: Option<u64>,
        window_days: Option<u64>,
        review: bool,
    ) -> Result<ProjectActivity, String> {
        get_project_activity_with_repository(
            self.repository,
            local_project_id,
            storage_id,
            branch,
            before_time,
            window_days,
            review,
        )
    }

    pub fn get_project_session_detail(
        &self,
        local_project_id: &LocalProjectId,
        resource_id: &ResourceId,
    ) -> Result<ProjectSessionDetail, SessionDetailError> {
        get_project_session_detail_with_repository(
            self.repository,
            local_project_id,
            resource_id.as_str(),
        )
    }

    pub fn get_project_session_timeline_page(
        &self,
        local_project_id: &LocalProjectId,
        resource_id: &ResourceId,
        request: ProjectSessionTimelineRequest,
    ) -> Result<ProjectSessionTimelinePage, SessionDetailError> {
        get_project_session_timeline_page_with_repository(
            self.repository,
            local_project_id,
            resource_id.as_str(),
            request,
        )
    }

    pub fn get_project_session_event_detail(
        &self,
        local_project_id: &LocalProjectId,
        resource_id: &ResourceId,
        snapshot_id: &str,
        event_id: &str,
    ) -> Result<SessionEventDetail, SessionDetailError> {
        get_project_session_event_detail_with_repository(
            self.repository,
            local_project_id,
            resource_id.as_str(),
            snapshot_id,
            event_id,
        )
    }

    pub fn inspect_bundle(
        &self,
        storage_id: &StorageId,
        bundle_id: &BundleId,
    ) -> Result<BundleSnapshot, String> {
        let (_, engine) = storage_engine(self.repository, storage_id)?;
        engine.inspect(bundle_id)
    }

    pub fn clear_storage_data(
        &self,
        storage_id: &StorageId,
        expected_config_revision: u64,
    ) -> Result<StorageDataClearResult, String> {
        let machine_home = self
            .repository
            .root()
            .parent()
            .ok_or("Mallard state has no machine-home parent")?;
        let catalog_repository =
            crate::storage_catalog::persistence::CatalogStateRepository::from_home_dir(
                machine_home.to_path_buf(),
            )?;
        clear_storage_data_with_repositories(
            self.repository,
            &catalog_repository,
            storage_id,
            expected_config_revision,
        )
    }
}

pub(super) fn provider_registry() -> &'static AgentProviderRegistry {
    AgentProviderRegistry::production()
}

/// Whether a provider's sessions ride the checkpoint cursor (metadata-only
/// review rows, captured only as byte-pinning candidates) instead of being
/// captured up front.
fn provider_supports_tail_cursor(provider: &ProviderKey) -> bool {
    provider_registry()
        .get(provider)
        .is_some_and(|adapter| adapter.supports_tail_cursor())
}

pub(super) fn claim_history_scan_log_at(
    logged_at: &mut BTreeMap<String, u64>,
    local_project_id: &str,
    now: u64,
) -> bool {
    let allowed = logged_at
        .get(local_project_id)
        .is_none_or(|previous| now.saturating_sub(*previous) >= HISTORY_SCAN_LOG_THROTTLE_SECS);
    if allowed {
        logged_at.insert(local_project_id.to_string(), now);
    }
    allowed
}

pub(super) fn should_log_history_scan(local_project_id: &LocalProjectId) -> bool {
    HISTORY_SCAN_LOGGED_AT
        .lock()
        .map(|mut logged_at| {
            claim_history_scan_log_at(&mut logged_at, local_project_id.as_str(), now_secs())
        })
        // A poisoned throttle must not hide operational diagnostics.
        .unwrap_or(true)
}

