fn build_activity_from_local_read(
    repository: &LocalStateRepository,
    state: &LocalProjectActivityStateSnapshot,
    local: &ProjectLocalRead,
    remote_snapshot: Option<&BundleSnapshot>,
    branch: Option<&str>,
    before_time: Option<u64>,
    window_days: Option<u64>,
    review: bool,
    mut warnings: Vec<String>,
) -> Result<ProjectActivity, String> {
    let local_sessions = project_activity::scan_local_session_views(
        repository,
        provider_registry(),
        &local.activity_project,
        &local.views,
        &mut warnings,
    )?;
    let remote_sessions = remote_snapshot
        .map(project_activity::remote_sessions_from_snapshot)
        .unwrap_or_default();
    project_activity::build_project_activity(
        provider_registry(),
        &local.activity_project,
        &state.conversation_bindings,
        &state.materializations,
        &state.config,
        local_sessions,
        remote_sessions,
        branch,
        before_time,
        window_days,
        review,
        warnings,
    )
}

pub(super) fn get_project_activity_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: Option<&StorageId>,
    branch: Option<&str>,
    before_time: Option<u64>,
    window_days: Option<u64>,
    review: bool,
) -> Result<ProjectActivity, String> {
    let state = repository.load_project_activity_state_snapshot()?;
    let local = load_project_local_read_from_state(repository.root(), &state, local_project_id)?;
    let mut warnings = Vec::new();
    let remote = match storage_id {
        Some(storage_id) => match project_activity::fetch_activity_snapshot(
            &state.config,
            storage_id,
            &local.activity_project.bundle_id,
        ) {
            Ok(snapshot) => snapshot,
            Err(error) => {
                warnings.push(format!(
                    "remote sessions are unavailable from '{}': {}",
                    storage_id, error
                ));
                None
            }
        },
        None => None,
    };
    build_activity_from_local_read(
        repository,
        &state,
        &local,
        remote.as_ref(),
        branch,
        before_time,
        window_days,
        review,
        warnings,
    )
}

/// Stages from one refresh. Local rows remain usable if storage or comparison fails.
#[derive(Serialize, Clone, Debug)]
#[serde(tag = "stage", rename_all = "snake_case")]
pub enum ProjectActivityRefreshEvent {
    Activity {
        activity: ProjectActivity,
        storage_pending: bool,
    },
    ActivityError {
        message: String,
        storage_pending: bool,
    },
    Comparison {
        comparison: ThreadSyncComparison,
    },
    ComparisonError {
        message: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        managed_cloud_status:
            Option<mallard_infrastructure::managed_cloud::client::ManagedCloudStatus>,
    },
}

pub(super) fn refresh_project_activity_with_progress(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
    branch: Option<&str>,
    window_days: Option<u64>,
    review: bool,
    on_event: &mut dyn FnMut(ProjectActivityRefreshEvent) -> Result<(), String>,
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<(), String> {
    let metrics_before = mallard_infrastructure::sync_metrics::global_snapshot();
    let started = Instant::now();
    let state = repository.load_project_activity_state_snapshot()?;
    let local = load_project_local_read_from_state(repository.root(), &state, local_project_id)?;
    on_phase("load binding and discover local state", started.elapsed());
    let mut send_activity =
        |snapshot: Option<&BundleSnapshot>, warnings: Vec<String>, storage_pending: bool| {
            match build_activity_from_local_read(
                repository,
                &state,
                &local,
                snapshot,
                branch,
                None,
                window_days,
                review,
                warnings,
            ) {
                Ok(activity) => on_event(ProjectActivityRefreshEvent::Activity {
                    activity,
                    storage_pending,
                }),
                Err(message) => on_event(ProjectActivityRefreshEvent::ActivityError {
                    message,
                    storage_pending,
                }),
            }
        };
    send_activity(None, Vec::new(), true)?;
    let started = Instant::now();
    let remote = load_project_remote_read(repository, local_project_id, storage_id);
    on_phase("inspect remote head", started.elapsed());
    match remote {
        Ok(remote) => {
            send_activity(remote.current.as_ref(), Vec::new(), false)?;
            match build_comparison_from_reads(
                repository,
                local_project_id,
                storage_id,
                &local,
                &remote,
                on_phase,
            ) {
                Ok(comparison) => on_event(ProjectActivityRefreshEvent::Comparison { comparison })?,
                Err(message) => on_event(ProjectActivityRefreshEvent::ComparisonError {
                    managed_cloud_status: cloud_status_for(
                        &state.config,
                        local_project_id,
                        storage_id,
                    ),
                    message,
                })?,
            }
        }
        Err(message) => {
            send_activity(
                None,
                vec![format!(
                    "remote sessions are unavailable from '{}': {}",
                    storage_id, message
                )],
                false,
            )?;
            on_event(ProjectActivityRefreshEvent::ComparisonError {
                managed_cloud_status: cloud_status_for(&state.config, local_project_id, storage_id),
                message,
            })?;
        }
    }
    mallard_infrastructure::sync_metrics::log_operation_delta("refresh", &metrics_before);
    Ok(())
}

