/// Delete Mallard-managed objects and derived local sync state only.
pub(super) fn clear_storage_data_with_repositories(
    repository: &LocalStateRepository,
    catalog_repository: &crate::storage_catalog::persistence::CatalogStateRepository,
    storage_id: &StorageId,
    expected_config_revision: u64,
) -> Result<StorageDataClearResult, String> {
    let ((remote, local), catalog) = catalog_repository.clear_storage_data(storage_id, || {
        repository.clear_storage_data(storage_id, expected_config_revision, |storage| {
            let store = ConfiguredObjectStore::shared(storage)?;
            clear_managed_storage_data(&store)
        })
    })?;
    Ok(storage_data_clear_result(remote, local, catalog))
}

fn storage_data_clear_result(
    remote: ManagedStorageClearResult,
    local: StorageSyncMetadataResetResult,
    catalog: crate::storage_catalog::persistence::CatalogStorageDataClearResult,
) -> StorageDataClearResult {
    let local_records_removed = local
        .scope_bases_removed
        .saturating_add(local.conversation_acceptances_removed)
        .saturating_add(local.materializations_removed)
        .saturating_add(catalog.claims_removed)
        .saturating_add(catalog.preservation_witnesses_removed)
        .saturating_add(catalog.terminal_operations_removed);
    StorageDataClearResult {
        storage_id: local.storage_id,
        config_revision: local.config_revision,
        repository_objects_deleted: remote.repository_objects_deleted,
        library_objects_deleted: remote.library_objects_deleted,
        project_links_reset: local.links_reset,
        catalog_links_reset: catalog.links_reset,
        local_records_removed,
    }
}

pub(super) fn remove_project_link_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<bool, String> {
    let _host_operation = repository.acquire_host_operation()?;
    let removed = repository.mutate_config(|config| {
        let before = config.links.len();
        config.links.retain(|link| {
            &link.local_project_id != local_project_id || &link.storage_id != storage_id
        });
        // Scope bases live on the link itself and are removed with it.
        let removed = before != config.links.len();
        Ok(removed)
    })?;
    if removed {
        if let Some(storage) = repository
            .load_config()?
            .storages
            .iter()
            .find(|storage| &storage.id == storage_id)
        {
            if storage.provider
                == mallard_infrastructure::storage_providers::managed_cloud::provider_key()
            {
                ConfiguredObjectStore::forget(storage_id);
            }
        }
    }
    Ok(removed)
}

pub(super) fn format_mb(bytes: u64) -> String {
    format!("{:.1} MB", bytes as f64 / 1_000_000.0)
}

pub(super) fn format_fetch_started_message(
    upload: bool,
    total_objects: usize,
    total_bytes: u64,
    storage_name: &str,
) -> String {
    let (arrow, action, preposition) = if upload {
        ("↑", "Uploading", "to")
    } else {
        ("↓", "Downloading", "from")
    };
    format!(
        "{arrow}  {action} {total_objects} objects ({}) {preposition} {storage_name}",
        format_mb(total_bytes)
    )
}

fn is_selectable_pull_conversation_action(action: &ConversationPlanAction) -> bool {
    matches!(
        action.action,
        ConversationPlanActionType::AdoptCloudMetadata
            | ConversationPlanActionType::MaterializeCloud
            | ConversationPlanActionType::KeepBoth
            | ConversationPlanActionType::CreateLocal
    )
}

/// Whether a Pull row's action installs storage bytes: the three that
/// materialize a stored transcript. Metadata adoption and the report rows
/// write no payload, so they weigh nothing in the review.
fn pull_action_installs_bytes(action: ConversationReviewAction) -> bool {
    matches!(
        action,
        ConversationReviewAction::MaterializeCloud
            | ConversationReviewAction::KeepBoth
            | ConversationReviewAction::CreateLocal
    )
}

/// What an approved Pull selection installs, priced from the pinned
/// manifest: the approved file actions' storage-side sizes plus every file
/// the manifest lists for each conversation the selection materializes.
/// Metadata adoptions write no payload and count nothing. The same sum the
/// review meter shows, so the two agree on the version the review pinned.
fn pull_bytes_of_selection<'a>(
    manifest: &BundleManifest,
    plan: &RestorePlan,
    approved: &BTreeSet<ActionId>,
    conversations: impl IntoIterator<Item = (ConversationPlanActionType, Option<&'a CloudThreadId>)>,
) -> Result<u64, String> {
    let mut total = plan
        .actions
        .iter()
        .filter(|action| approved.contains(&action.action_id))
        .filter_map(|action| action.source_size)
        .fold(0_u64, u64::saturating_add);
    for (action, cloud_thread_id) in conversations {
        if !matches!(
            action,
            ConversationPlanActionType::MaterializeCloud
                | ConversationPlanActionType::KeepBoth
                | ConversationPlanActionType::CreateLocal
        ) {
            continue;
        }
        let cloud_thread_id =
            cloud_thread_id.ok_or("conversation Pull action lacks its cloud id")?;
        let (_, thread) = manifest
            .find_conversation(cloud_thread_id)
            .ok_or("conversation Pull action names a thread this version does not hold")?;
        total = total.saturating_add(manifest.conversation_bytes(thread));
    }
    Ok(total)
}

/// The refusal past the Pull limit, worded as the review meter words it so
/// the sentence is the same wherever it is read.
fn pull_limit_sentence(total: u64, limit: u64) -> String {
    format!(
        "{} over the {} pull limit — exclude sessions or files to pull.",
        provider_capture::format_bytes(total.saturating_sub(limit)),
        provider_capture::format_bytes(limit)
    )
}

pub(super) fn pull_plan_action_counts(plan: &RestorePlan) -> (usize, usize) {
    let ordinary = plan
        .actions
        .iter()
        .filter(|action| !matches!(&action.kind, RestoreActionKind::Manual { .. }))
        .count();
    let conversations = plan
        .conversation_actions
        .iter()
        .filter(|action| is_selectable_pull_conversation_action(action))
        .count();
    (ordinary, conversations)
}

/// The review row key for one conversation action: its recorded source
/// resource id when review captured one, else the shared row-key rule —
/// the local resource id when the action names a local thread, the cloud
/// resource id for a cloud-only action (CreateLocal).
fn conversation_action_row_key(action: &ConversationPlanAction) -> Option<ResourceId> {
    action.source_resource_id.clone().or_else(|| {
        match (&action.thread_id, &action.cloud_thread_id) {
            (Some(thread_id), _) => conversation_resource_id(&action.provider, thread_id).ok(),
            (None, Some(cloud_thread_id)) => {
                cloud_conversation_resource_id(&action.provider, cloud_thread_id).ok()
            }
            (None, None) => None,
        }
    })
}

pub(super) fn pull_action_resource_label(
    plan: &RestorePlan,
    action_id: &ActionId,
) -> Option<String> {
    if let Some(action) = plan
        .actions
        .iter()
        .find(|action| &action.action_id == action_id)
    {
        return Some(action.resource_id.to_string());
    }
    plan.conversation_actions
        .iter()
        .find(|action| &action.action_id == action_id)
        .and_then(conversation_action_row_key)
        .map(|resource_id| resource_id.to_string())
}

pub(super) fn pull_review_resource_labels(plan: &RestorePlan) -> Vec<String> {
    let ordinary = plan
        .actions
        .iter()
        .filter(|action| !matches!(&action.kind, RestoreActionKind::Manual { .. }))
        .map(|action| action.resource_id.to_string());
    let conversations = plan
        .conversation_actions
        .iter()
        .filter(|action| is_selectable_pull_conversation_action(action))
        .filter_map(conversation_action_row_key)
        .map(|resource_id| resource_id.to_string());
    ordinary
        .chain(conversations)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

/// Provider facts come from the registered adapter descriptor; setup code
/// never hard-codes a provider list or name.
pub(super) fn provider_descriptor(provider: &ProviderKey) -> Result<ProviderDescriptor, String> {
    provider_registry()
        .get(provider)
        .map(|adapter| adapter.descriptor())
        .ok_or_else(|| format!("no provider adapter is registered for '{}'", provider))
}

fn provider_name(provider: &ProviderKey) -> String {
    provider_descriptor(provider)
        .map(|descriptor| descriptor.display_name)
        .unwrap_or_else(|_| provider.to_string())
}

fn provider_default_directory(provider: &ProviderKey) -> Option<String> {
    provider_descriptor(provider)
        .ok()
        .and_then(|descriptor| descriptor.default_profile_directory)
}

fn suggested_profile_name(provider: &ProviderKey, path: &Path) -> String {
    let default_directory = provider_default_directory(provider);
    let default = mallard_infrastructure::persistence::user_home_dir()
        .zip(default_directory.as_ref())
        .map(|(home, directory)| home.join(directory));
    if default.as_ref().is_some_and(|default| {
        prospective_canonical(default).ok().as_ref() == prospective_canonical(path).ok().as_ref()
    }) {
        return format!("Default {}", provider_name(provider));
    }
    let stem = if default_directory.as_ref().is_some_and(|directory| {
        path.file_name()
            .is_some_and(|name| name == directory.as_str())
    }) {
        path.parent().and_then(Path::file_name)
    } else {
        path.file_name()
    };
    stem.and_then(|name| name.to_str())
        .filter(|name| !name.trim().is_empty())
        .map(|name| format!("{} · {}", name, provider_name(provider)))
        .unwrap_or_else(|| format!("{} profile", provider_name(provider)))
}

pub(super) fn probe_provider_profile_with_repository(
    repository: &LocalStateRepository,
    provider: &ProviderKey,
    requested_path: &str,
) -> Result<ProviderProfileProbe, String> {
    // Probing creates local provider state authority, so the key must
    // resolve through the registry — unlike remote viewing, which accepts
    // any structurally valid key.
    provider_descriptor(provider)?;
    validate_absolute_clean_path("provider profile path", requested_path)?;
    let requested = PathBuf::from(requested_path);
    let default_directory = provider_default_directory(provider);
    let child = default_directory
        .as_ref()
        .map(|directory| requested.join(directory));
    let (resolved, detected_child) = match (child, &default_directory) {
        (Some(child), Some(directory))
            if requested
                .file_name()
                .is_none_or(|name| name != directory.as_str())
                && child.is_dir() =>
        {
            (child, true)
        }
        _ => (requested, false),
    };
    let metadata = fs_profile_metadata(&resolved)?;
    if !metadata.is_dir() {
        return Err(format!(
            "{} profile '{}' is not a directory",
            provider_name(provider),
            resolved.display()
        ));
    }
    let canonical = fs_canonicalize(&resolved)?;
    let repository_root = prospective_canonical(repository.root())?;
    if paths_overlap(&canonical, &repository_root) {
        return Err(format!(
            "{} profile '{}' overlaps Mallard application data",
            provider_name(provider),
            canonical.display()
        ));
    }
    let snapshot = repository.load_project_state_snapshot()?;
    let state = &snapshot.bindings;
    for (storage, root) in configured_local_storage_roots(&snapshot.config)? {
        let storage_root = prospective_canonical(&root)?;
        if paths_overlap(&canonical, &storage_root) {
            return Err(format!(
                "{} profile '{}' overlaps local storage '{}'",
                provider_name(provider),
                canonical.display(),
                storage.name
            ));
        }
    }
    let readable = fs::read_dir(&canonical).is_ok();
    let writable = !metadata.permissions().readonly();
    for binding in state
        .bindings
        .iter()
        .filter(|binding| binding.state == BindingState::Active)
    {
        let project_root = Path::new(&binding.canonical_project_root);
        if paths_overlap(&canonical, project_root) {
            return Err(format!(
                "{} profile '{}' overlaps project '{}'",
                provider_name(provider),
                canonical.display(),
                binding.local_project_id
            ));
        }
    }
    let existing_profile_id = state
        .profiles
        .iter()
        .find(|profile| {
            &profile.provider == provider && Path::new(&profile.canonical_path) == canonical
        })
        .map(|profile| profile.profile_id.clone());
    Ok(ProviderProfileProbe {
        provider: provider.clone(),
        requested_path: requested_path.to_string(),
        resolved_path: resolved.to_string_lossy().into_owned(),
        canonical_path: canonical.to_string_lossy().into_owned(),
        suggested_name: suggested_profile_name(provider, &resolved),
        readable,
        writable,
        detected_child,
        existing_profile_id,
    })
}

pub(crate) fn create_provider_profile_with_repository(
    repository: &LocalStateRepository,
    provider: &ProviderKey,
    display_name: &str,
    path: &str,
) -> Result<ProviderProfile, String> {
    let probe = probe_provider_profile_with_repository(repository, provider, path)?;
    if !probe.readable {
        return Err(format!(
            "{} profile '{}' is not readable",
            provider_name(provider),
            probe.resolved_path
        ));
    }
    if let Some(profile_id) = &probe.existing_profile_id {
        return repository
            .load_bindings()?
            .profiles
            .into_iter()
            .find(|profile| &profile.profile_id == profile_id)
            .ok_or_else(|| "provider profile disappeared during creation".to_string());
    }
    let now = now_secs();
    let profile = ProviderProfile {
        profile_id: LocalProviderProfileId::parse(generated_named_id("profile")?)?,
        provider: provider.clone(),
        display_name: if display_name.trim().is_empty() {
            probe.suggested_name
        } else {
            display_name.trim().to_string()
        },
        path: probe.resolved_path,
        canonical_path: probe.canonical_path,
        provider_config: mallard_domain::AgentProviderConfig::version_1(),
        revision: 0,
        created_at: now,
        updated_at: now,
    };
    profile.validate_structure()?;
    repository.mutate_bindings(|_, state| {
        if let Some(existing) = state.profiles.iter().find(|existing| {
            existing.provider == profile.provider
                && existing.canonical_path == profile.canonical_path
        }) {
            return Ok(existing.clone());
        }
        state.profiles.push(profile.clone());
        Ok(profile)
    })
}

/// Auto-register default profiles for every provider the registry declares a
/// default home directory for. Registration-driven: a new provider needs no
/// change here.
fn ensure_default_provider_profiles(repository: &LocalStateRepository) -> Result<(), String> {
    let Some(home) = mallard_infrastructure::persistence::user_home_dir() else {
        return Ok(());
    };
    for descriptor in provider_registry().descriptors() {
        let Some(directory) = &descriptor.default_profile_directory else {
            continue;
        };
        let path = home.join(directory);
        if path.is_dir() {
            if probe_provider_profile_with_repository(
                repository,
                &descriptor.key,
                &path.to_string_lossy(),
            )
            .is_err()
            {
                continue;
            }
            let _ = create_provider_profile_with_repository(
                repository,
                &descriptor.key,
                &format!("Default {}", descriptor.display_name),
                &path.to_string_lossy(),
            )?;
        }
    }
    Ok(())
}

fn inspect_provider_profile(profile: &ProviderProfile) -> (bool, bool, bool, Option<String>) {
    let path = Path::new(&profile.path);
    let result = (|| {
        let metadata = fs_profile_metadata(path)?;
        if !metadata.is_dir() {
            return Err("profile path is not a directory".to_string());
        }
        let canonical = fs_canonicalize(path)?;
        if canonical != profile.canonical_path {
            return Err("profile path now resolves to a different directory".to_string());
        }
        let readable = fs::read_dir(&canonical).is_ok();
        Ok((readable, !metadata.permissions().readonly()))
    })();
    match result {
        Ok((readable, writable)) => (true, readable, writable, None),
        Err(error) => (false, false, false, Some(error)),
    }
}

pub(super) fn list_provider_profiles_with_repository(
    repository: &LocalStateRepository,
) -> Result<Vec<ProviderProfileSummary>, String> {
    ensure_default_provider_profiles(repository)?;
    let state = repository.load_bindings()?;
    let mut profiles = state
        .profiles
        .iter()
        .cloned()
        .map(|profile| {
            let (available, readable, writable, error) = inspect_provider_profile(&profile);
            let used_by_projects = state
                .bindings
                .iter()
                .filter(|binding| {
                    binding.state == BindingState::Active
                        && binding
                            .profile_ids
                            .values()
                            .any(|id| id == &profile.profile_id)
                })
                .map(|binding| binding.local_project_id.clone())
                .collect();
            ProviderProfileSummary {
                profile,
                available,
                readable,
                writable,
                used_by_projects,
                error,
            }
        })
        .collect::<Vec<_>>();
    profiles.sort_by(|left, right| {
        left.profile
            .provider
            .cmp(&right.profile.provider)
            .then_with(|| left.profile.display_name.cmp(&right.profile.display_name))
    });
    Ok(profiles)
}

fn resolve_profile_paths(
    repository: &LocalStateRepository,
    profile_ids: &BTreeMap<ProviderKey, LocalProviderProfileId>,
) -> Result<BTreeMap<ProviderKey, String>, String> {
    let state = repository.load_bindings()?;
    resolve_profile_paths_from_state(&state, profile_ids)
}

fn resolve_profile_paths_from_state(
    state: &MachineProjectState,
    profile_ids: &BTreeMap<ProviderKey, LocalProviderProfileId>,
) -> Result<BTreeMap<ProviderKey, String>, String> {
    if profile_ids.is_empty() {
        return Err("choose at least one local provider profile".to_string());
    }
    let mut resolved = BTreeMap::new();
    for (provider, profile_id) in profile_ids {
        let profile = state
            .profiles
            .iter()
            .find(|profile| &profile.profile_id == profile_id)
            .ok_or_else(|| format!("unknown provider profile '{}'", profile_id))?;
        if &profile.provider != provider {
            return Err(format!(
                "{} cannot use {} profile '{}'",
                provider_name(provider),
                provider_name(&profile.provider),
                profile.display_name
            ));
        }
        let (available, readable, _, error) = inspect_provider_profile(profile);
        if !available || !readable {
            return Err(error.unwrap_or_else(|| {
                format!(
                    "{} profile '{}' is not readable",
                    provider_name(provider),
                    profile.path
                )
            }));
        }
        // Every machine operation — capture, planning pins, and the
        // materialization boundary check — must agree on one spelling, so
        // the runtime home is always the profile's canonical path.
        resolved.insert(provider.clone(), profile.canonical_path.clone());
    }
    Ok(resolved)
}

/// Validate the project and provider-home boundaries setup will persist
/// without scanning any syncable resources.
fn validate_setup_paths(
    repository: &LocalStateRepository,
    selected_path: &str,
    profile_paths: &BTreeMap<ProviderKey, String>,
) -> Result<PathBuf, String> {
    validate_absolute_clean_path("project root", selected_path)?;
    let project_root = fs_canonicalize(Path::new(selected_path))?;
    if !project_root.is_dir() {
        return Err(format!(
            "project root '{}' is not a directory",
            selected_path
        ));
    }
    let repository_root = prospective_canonical(repository.root())?;
    if paths_overlap(&project_root, &repository_root) {
        return Err("project root overlaps Mallard application data".to_string());
    }
    let config = repository.load_config()?;
    for (storage, root) in configured_local_storage_roots(&config)? {
        let storage_root = prospective_canonical(&root)?;
        if paths_overlap(&project_root, &storage_root) {
            return Err(format!(
                "project root '{}' overlaps local storage '{}'",
                project_root.display(),
                storage.name
            ));
        }
    }

    if profile_paths.is_empty() {
        return Err("choose at least one local provider profile".to_string());
    }
    for (provider, path) in profile_paths {
        let path = fs_canonicalize(Path::new(path))?;
        if paths_overlap(&project_root, &path) {
            return Err(format!(
                "project root '{}' overlaps {} profile '{}'",
                project_root.display(),
                provider_name(provider),
                path.display()
            ));
        }
    }
    Ok(project_root)
}

#[derive(Clone)]
struct ProjectContentVersion {
    descriptor: ResourceDescriptor,
    entry_type: ProjectContentEntryType,
    relative_path: String,
    logical_path: String,
    size: Option<u64>,
    mode: Option<u32>,
    source_mtime: Option<u64>,
    digest: String,
}

pub(super) fn inspect_project_files_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<ProjectContentInventory, String> {
    let _host_operation = repository.acquire_host_operation()?;
    inspect_project_files_guarded(repository, local_project_id, storage_id)
}

fn inspect_project_files_guarded(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<ProjectContentInventory, String> {
    let state = repository.load_project_state_snapshot()?;
    let config = &state.config;
    let project = config
        .project(local_project_id)
        .cloned()
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
    let link = require_project_link(&config, &project, storage_id)?;
    let binding = state
        .bindings
        .active_for(local_project_id)
        .cloned()
        .ok_or_else(|| {
            format!(
                "project '{}' is not mapped on this machine",
                local_project_id
            )
        })?;
    let eligibility = project_file_sync_eligibility(&binding);
    let (_, engine) = storage_engine_from_state(repository, config, &state.bindings, storage_id)?;
    // Observed, not inspected: the files are judged against the project
    // area's base only while that base is on the selected chain.
    let observation = engine.observe(&project.bundle_id)?;
    let discovery = if eligibility.state == ProjectFileSyncEligibilityState::Eligible {
        let resolved = resolve_project_binding_from_state(&state.bindings, &binding)?;
        let mut request = capture_request_for_resolved_binding_from_state(
            repository.root(),
            config,
            &state.bindings,
            &resolved,
        )?;
        request.include_project_content = true;
        Some(provider_capture::discover_full(
            provider_registry(),
            &request,
        )?)
    } else {
        None
    };
    build_project_files_inventory(
        local_project_id,
        storage_id,
        &project,
        link,
        &binding,
        eligibility,
        &engine,
        observation.snapshot(),
        &observation.mainline,
        discovery.as_ref(),
    )
}

/// Project-files section over a shared Discovery (walked with project
/// content included) and one already-read remote snapshot, with the chain
/// it was selected on: the project area's base is read through that chain
/// (`project_base`) before its manifest is opened. The review token minted
/// here binds current disk state and the observed remote head.
#[allow(clippy::too_many_arguments)]
fn build_project_files_inventory(
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
    project: &LocalProjectRegistration,
    link: &ProjectStorageLink,
    binding: &ProjectBinding,
    eligibility: ProjectFileSyncEligibility,
    engine: &StorageEngine,
    remote: Option<&BundleSnapshot>,
    mainline: &Mainline,
    discovery: Option<&provider_capture::Discovery>,
) -> Result<ProjectContentInventory, String> {
    let remote_versions = remote
        .map(|snapshot| project_content_versions(&snapshot.manifest))
        .transpose()?
        .unwrap_or_default();
    let mut warnings = Vec::new();
    let (base_versions, base_unavailable) =
        match project_base(link, mainline, remote.map(|snapshot| &snapshot.manifest)) {
            ProjectBase::None => (BTreeMap::new(), false),
            ProjectBase::Current => (remote_versions.clone(), false),
            ProjectBase::Reviewed(base) => match engine.inspect_manifest_version(
                &project.bundle_id,
                base.reviewed_in.revision,
                &base.reviewed_in.commit_id,
                base.reviewed_in.manifest_size,
                &base.reviewed_in.manifest_sha256,
            ) {
                Ok(manifest) => (project_content_versions(&manifest)?, false),
                Err(error) => {
                    warnings.push(format!(
                        "Reviewed project-content base is unavailable: {}",
                        error
                    ));
                    (BTreeMap::new(), true)
                }
            },
        };
    let effective_recipe = link
        .recipe
        .clone()
        .unwrap_or_else(|| project.recipe.clone());
    let selected_ids = effective_recipe.selected_ids();
    let preferences = link.project_content_preferences.clone();

    let mut local_versions = BTreeMap::<ResourceId, ProjectContentVersion>::new();
    let mut local_blocked_versions = BTreeMap::<ResourceId, ProjectContentVersion>::new();
    let mut local_blockers = BTreeMap::<ResourceId, String>::new();
    let mut local_warnings = BTreeMap::<ResourceId, String>::new();
    let mut ignored_count = 0;
    let mut blocked_count = 0;
    if eligibility.state == ProjectFileSyncEligibilityState::Eligible {
        let discovered = discovery
            .ok_or_else(|| {
                "project-files discovery is missing for an eligible binding".to_string()
            })?
            .project_content_inventory();
        ignored_count = discovered.ignored_count;
        blocked_count = discovered.blocked_count;
        warnings.extend(discovered.warnings.clone());
        for candidate in discovered.resources {
            let descriptor = provider_capture::domain_resource_descriptor(&candidate, None)?;
            let resource_id = descriptor.resource_id.clone();
            let facts = candidate.project_content.ok_or_else(|| {
                format!(
                    "project-content resource '{}' lacks typed facts",
                    resource_id
                )
            })?;
            match facts {
                provider_capture::ProjectContentCandidate::Blocked { relative_path } => {
                    let reason = candidate.blocked_reason.ok_or_else(|| {
                        format!(
                            "blocked project-content resource '{}' lacks a reason",
                            resource_id
                        )
                    })?;
                    local_blockers.insert(resource_id.clone(), reason);
                    local_blocked_versions.insert(
                        resource_id,
                        ProjectContentVersion {
                            logical_path: format!("project/{}", relative_path),
                            relative_path,
                            entry_type: ProjectContentEntryType::Blocked,
                            size: None,
                            mode: None,
                            source_mtime: None,
                            descriptor,
                            digest: String::new(),
                        },
                    );
                }
                provider_capture::ProjectContentCandidate::Directory {
                    relative_path,
                    mode,
                    source_mtime,
                    review_digest,
                } => {
                    local_versions.insert(
                        resource_id,
                        ProjectContentVersion {
                            logical_path: format!("project/{}", relative_path),
                            relative_path,
                            entry_type: ProjectContentEntryType::Directory,
                            size: None,
                            mode: Some(mode),
                            source_mtime: Some(source_mtime),
                            descriptor,
                            digest: review_digest,
                        },
                    );
                }
                provider_capture::ProjectContentCandidate::File {
                    relative_path,
                    size,
                    mode,
                    source_mtime,
                    review_digest,
                    warning,
                } => {
                    if let Some(warning) = warning {
                        local_warnings.insert(resource_id.clone(), warning.code().to_string());
                    }
                    local_versions.insert(
                        resource_id,
                        ProjectContentVersion {
                            logical_path: format!("project/{}", relative_path),
                            relative_path,
                            entry_type: ProjectContentEntryType::File,
                            size: Some(size),
                            mode: Some(mode),
                            source_mtime: Some(source_mtime),
                            descriptor,
                            digest: review_digest,
                        },
                    );
                }
            }
        }
    }

    let all_ids = local_versions
        .keys()
        .chain(local_blocked_versions.keys())
        .chain(local_blockers.keys())
        .chain(remote_versions.keys())
        .chain(base_versions.keys())
        .cloned()
        .collect::<BTreeSet<_>>();
    let mut entries = Vec::with_capacity(all_ids.len());
    for resource_id in all_ids {
        let local = local_versions.get(&resource_id);
        let local_blocked = local_blocked_versions.get(&resource_id);
        let remote_version = remote_versions.get(&resource_id);
        let base = base_versions.get(&resource_id);
        let blocked_reason = local_blockers.get(&resource_id).cloned();
        let representative = local.or(local_blocked).or(remote_version).or(base);
        let Some(representative) = representative else {
            continue;
        };
        let local_digest = local.map(|version| version.digest.clone());
        let storage_digest = remote_version.map(|version| version.digest.clone());
        let base_digest = base.map(|version| version.digest.clone());
        let state = if blocked_reason.is_some() {
            "blocked"
        } else if base_unavailable
            && (remote_version.is_some() || selected_ids.contains(&resource_id))
        {
            "unknown"
        } else {
            classify_project_content_state(
                local_digest.as_deref(),
                storage_digest.as_deref(),
                base_digest.as_deref(),
            )
        };
        let selected_in_recipe = selected_ids.contains(&resource_id);
        let newly_discovered = local.is_some() && remote_version.is_none() && !selected_in_recipe;
        let selected_after_scan = newly_discovered
            && blocked_reason.is_none()
            && !preferences.excluded_resource_ids.contains(&resource_id);
        let warning_code = local_warnings.get(&resource_id).cloned();
        let warning_digest = warning_code.as_ref().and_then(|warning| {
            local_digest
                .as_ref()
                .map(|digest| project_content_warning_digest(&resource_id, digest, warning))
        });
        entries.push(ProjectContentEntry {
            descriptor: representative.descriptor.clone(),
            entry_type: if blocked_reason.is_some() {
                ProjectContentEntryType::Blocked
            } else {
                representative.entry_type
            },
            relative_path: representative.relative_path.clone(),
            logical_path: representative.logical_path.clone(),
            size: local
                .or(local_blocked)
                .or(remote_version)
                .and_then(|version| version.size),
            mode: local
                .or(local_blocked)
                .or(remote_version)
                .and_then(|version| version.mode),
            source_mtime: local
                .or(local_blocked)
                .or(remote_version)
                .and_then(|version| version.source_mtime),
            state: state.to_string(),
            local_present: local.is_some() || local_blocked.is_some(),
            storage_present: remote_version.is_some(),
            base_present: base.is_some(),
            local_digest: local_digest.clone(),
            storage_digest,
            base_digest,
            review_digest: local_digest,
            selected_in_recipe,
            newly_discovered,
            selected_after_scan,
            blocked_reason,
            warning_code,
            warning_digest,
        });
    }
    entries.sort_by(|left, right| {
        left.relative_path.cmp(&right.relative_path).then_with(|| {
            project_content_entry_rank(left.entry_type)
                .cmp(&project_content_entry_rank(right.entry_type))
        })
    });
    warnings.sort();
    warnings.dedup();
    let review_token =
        (eligibility.state == ProjectFileSyncEligibilityState::Eligible).then(|| {
            project_content_review_token(
                binding,
                &eligibility,
                remote,
                preferences.revision,
                &entries,
            )
        });
    Ok(ProjectContentInventory {
        local_project_id: local_project_id.clone(),
        storage_id: storage_id.clone(),
        project_root: binding.project_root.clone(),
        eligibility,
        review_token,
        storage_revision: remote.map(|snapshot| snapshot.head.revision),
        preference_revision: preferences.revision,
        excluded_resource_ids: preferences.excluded_resource_ids.into_iter().collect(),
        entries,
        ignored_count,
        blocked_count,
        warnings,
        scanned_at: now_secs(),
    })
}

fn project_content_entry_rank(entry_type: ProjectContentEntryType) -> u8 {
    match entry_type {
        ProjectContentEntryType::Directory => 0,
        ProjectContentEntryType::File => 1,
        ProjectContentEntryType::Blocked => 2,
    }
}

fn project_content_versions(
    manifest: &BundleManifest,
) -> Result<BTreeMap<ResourceId, ProjectContentVersion>, String> {
    let mut versions = BTreeMap::new();
    let Some(project_scope) = manifest.scope(&SyncScopeKey::Project) else {
        return Ok(versions);
    };
    for (logical_path, entry) in &project_scope.files {
        let Some(descriptor) = project_scope.resources.get(&entry.resource_id) else {
            continue;
        };
        if kind_primitive(&descriptor.kind) != Some(ResourceKindPrimitive::ProjectContentFile) {
            continue;
        }
        let relative_path = project_content_relative_path(logical_path)?;
        let mode = entry.mode.unwrap_or(0o600) & 0o777;
        let version = ProjectContentVersion {
            descriptor: descriptor.clone(),
            entry_type: ProjectContentEntryType::File,
            logical_path: logical_path.to_string(),
            relative_path: relative_path.clone(),
            size: Some(entry.size),
            mode: Some(mode),
            source_mtime: Some(entry.source_mtime),
            digest: project_content_version_digest("file", &relative_path, &entry.sha256, mode),
        };
        if versions
            .insert(entry.resource_id.clone(), version)
            .is_some()
        {
            return Err(format!(
                "project-content resource '{}' owns more than one entry",
                entry.resource_id
            ));
        }
    }
    for (logical_path, entry) in &project_scope.directories {
        let Some(descriptor) = project_scope.resources.get(&entry.resource_id) else {
            continue;
        };
        if kind_primitive(&descriptor.kind) != Some(ResourceKindPrimitive::ProjectContentDirectory)
        {
            continue;
        }
        let relative_path = project_content_relative_path(logical_path)?;
        let mode = entry.mode.unwrap_or(0o700) & 0o777;
        let version = ProjectContentVersion {
            descriptor: descriptor.clone(),
            entry_type: ProjectContentEntryType::Directory,
            logical_path: logical_path.to_string(),
            relative_path: relative_path.clone(),
            size: None,
            mode: Some(mode),
            source_mtime: Some(entry.source_mtime),
            digest: project_content_version_digest("dir", &relative_path, "", mode),
        };
        if versions
            .insert(entry.resource_id.clone(), version)
            .is_some()
        {
            return Err(format!(
                "project-content resource '{}' owns more than one entry",
                entry.resource_id
            ));
        }
    }
    Ok(versions)
}

fn project_content_relative_path(
    logical_path: &mallard_domain::LogicalPath,
) -> Result<String, String> {
    logical_path
        .as_str()
        .strip_prefix("project/")
        .filter(|relative| !relative.is_empty())
        .map(str::to_string)
        .ok_or_else(|| format!("project-content path '{}' is invalid", logical_path))
}

fn project_content_version_digest(
    entry_type: &str,
    relative_path: &str,
    content_sha256: &str,
    mode: u32,
) -> String {
    let digest = Sha256::digest(
        format!(
            "{}\0{}\0{}\0{:03o}",
            entry_type,
            relative_path,
            content_sha256,
            mode & 0o777
        )
        .as_bytes(),
    );
    hex_digest(&digest)
}

fn project_content_ancestor_paths(relative_path: &str) -> Vec<String> {
    let components = relative_path.split('/').collect::<Vec<_>>();
    (1..components.len())
        .map(|end| components[..end].join("/"))
        .collect()
}

/// The project area's base, read by the rule of section 4.1 of
/// `PLAN_CLEARED_STORAGE_PUSH_AGAIN.md` before anything opens the manifest
/// it names. It counts while the publication it was reviewed in is on the
/// selected chain, and while the selected manifest holds exactly the
/// reviewed content. Any other base is stale and is read as if it were not
/// recorded, whether or not its manifest can still be read. After another
/// computer's clear that manifest is usually gone; when it can still be
/// read (the object cache, an interrupted clear, a displaced Push), it
/// describes a history the storage no longer has, and judged against it a
/// file this computer changed there would pass as changed only in the
/// storage and be replaced plainly.
enum ProjectBase<'a> {
    /// No base, or a stale one: every file is compared by content alone.
    None,
    /// Reviewed on the selected chain: the manifest it names is the base.
    Reviewed(&'a ScopeBase),
    /// The selected manifest holds exactly the reviewed content, so it is
    /// the base, whoever wrote it (row A5).
    Current,
}

fn project_base<'a>(
    link: &'a ProjectStorageLink,
    mainline: &Mainline,
    current: Option<&BundleManifest>,
) -> ProjectBase<'a> {
    let Some(base) = link.scope_bases.get(&SyncScopeKey::Project) else {
        return ProjectBase::None;
    };
    if mainline.contains(base.reviewed_in.revision, &base.reviewed_in.commit_id) {
        return ProjectBase::Reviewed(base);
    }
    let same_content = current
        .and_then(|manifest| manifest.scope(&SyncScopeKey::Project))
        .is_some_and(|scope| scope.content_sha256 == base.scope_sha256);
    if same_content {
        ProjectBase::Current
    } else {
        ProjectBase::None
    }
}

/// Raw content digests per project-content logical path in the base
/// manifest — what the restore planner compares a diverged file's disk
/// bytes against. Never mode-composited: a mode-only change must not force
/// a preservation copy. A base that is absent, stale or unreadable returns
/// empty, which the planner treats as "preserve" (fail closed — never
/// silently lose local bytes the app cannot prove are stored).
fn project_content_base_content_digests(
    engine: &StorageEngine,
    bundle_id: &BundleId,
    link: &ProjectStorageLink,
    mainline: &Mainline,
    current: &BundleManifest,
) -> BTreeMap<mallard_domain::LogicalPath, String> {
    fn content_digests(manifest: &BundleManifest) -> BTreeMap<mallard_domain::LogicalPath, String> {
        let Some(scope) = manifest.scope(&SyncScopeKey::Project) else {
            return BTreeMap::new();
        };
        scope
            .files
            .iter()
            .filter(|(_, entry)| {
                scope
                    .resources
                    .get(&entry.resource_id)
                    .is_some_and(|descriptor| {
                        kind_primitive(&descriptor.kind)
                            == Some(ResourceKindPrimitive::ProjectContentFile)
                    })
            })
            .map(|(logical_path, entry)| (logical_path.clone(), entry.sha256.clone()))
            .collect()
    }
    match project_base(link, mainline, Some(current)) {
        ProjectBase::None => BTreeMap::new(),
        ProjectBase::Current => content_digests(current),
        ProjectBase::Reviewed(base) => engine
            .inspect_manifest_version(
                bundle_id,
                base.reviewed_in.revision,
                &base.reviewed_in.commit_id,
                base.reviewed_in.manifest_size,
                &base.reviewed_in.manifest_sha256,
            )
            .map(|manifest| content_digests(&manifest))
            .unwrap_or_default(),
    }
}

fn classify_project_content_state(
    local: Option<&str>,
    storage: Option<&str>,
    base: Option<&str>,
) -> &'static str {
    match (local, storage, base) {
        (Some(local), Some(storage), _) if local == storage => "synced",
        (Some(_), None, None) => "local_only",
        (None, Some(_), None) => "storage_only",
        (Some(local), Some(storage), Some(base)) if storage == base && local != base => {
            "local_ahead"
        }
        (Some(local), Some(storage), Some(base)) if local == base && storage != base => {
            "storage_ahead"
        }
        (Some(local), None, Some(base)) if local == base => "storage_ahead",
        (None, Some(storage), Some(base)) if storage == base => "missing",
        (Some(_), Some(_), _) | (Some(_), None, Some(_)) => "diverged",
        (None, _, Some(_)) => "storage_ahead",
        (None, None, None) => "unknown",
    }
}

fn project_content_review_token(
    binding: &ProjectBinding,
    eligibility: &ProjectFileSyncEligibility,
    remote: Option<&BundleSnapshot>,
    preference_revision: u64,
    entries: &[ProjectContentEntry],
) -> String {
    let mut hasher = Sha256::new();
    hasher.update(b"project-content-review-v1\0");
    hasher.update(binding.local_project_id.as_str().as_bytes());
    hasher.update(binding.host_id.as_str().as_bytes());
    hasher.update(binding.replica_id.as_str().as_bytes());
    hasher.update(binding.revision.to_be_bytes());
    hasher.update(format!("{:?}", eligibility.state).as_bytes());
    hasher.update(preference_revision.to_be_bytes());
    if let Some(remote) = remote {
        hasher.update(remote.head.revision.to_be_bytes());
        hasher.update(remote.head.commit_id.as_bytes());
        hasher.update(remote.head.manifest_sha256.as_bytes());
    }
    for entry in entries {
        hasher.update(entry.descriptor.resource_id.as_str().as_bytes());
        hasher.update(entry.relative_path.as_bytes());
        hasher.update(entry.state.as_bytes());
        if let Some(digest) = &entry.review_digest {
            hasher.update(digest.as_bytes());
        }
        if let Some(reason) = &entry.blocked_reason {
            hasher.update(reason.as_bytes());
        }
        if let Some(warning) = &entry.warning_code {
            hasher.update(warning.as_bytes());
        }
    }
    hex_digest(&hasher.finalize())
}

fn project_content_warning_digest(
    resource_id: &ResourceId,
    review_digest: &str,
    warning_code: &str,
) -> String {
    let digest = Sha256::digest(
        format!(
            "project-content-warning-v1\0{}\0{}\0{}",
            resource_id, review_digest, warning_code
        )
        .as_bytes(),
    );
    hex_digest(&digest)
}

fn project_file_sync_eligibility(binding: &ProjectBinding) -> ProjectFileSyncEligibility {
    let root = Path::new(&binding.project_root);
    let canonical = match fs::canonicalize(root) {
        Ok(canonical) => canonical,
        Err(error) => {
            return ProjectFileSyncEligibility {
                state: ProjectFileSyncEligibilityState::Unknown,
                reason: format!("Project folder cannot be resolved: {}", error),
                detected_root: None,
            }
        }
    };
    if canonical != binding.canonical_project_root {
        return ProjectFileSyncEligibility {
            state: ProjectFileSyncEligibilityState::Unknown,
            reason: "Project binding resolves to a different folder".to_string(),
            detected_root: None,
        };
    }
    match std::process::Command::new("git")
        .env("LC_ALL", "C")
        .env("LANG", "C")
        .arg("-C")
        .arg(&canonical)
        .args(["rev-parse", "--show-toplevel"])
        .output()
    {
        Ok(output) if output.status.success() => {
            let detected = String::from_utf8_lossy(&output.stdout).trim().to_string();
            ProjectFileSyncEligibility {
                state: ProjectFileSyncEligibilityState::GitManaged,
                reason: "Git manages files in this project folder".to_string(),
                detected_root: (!detected.is_empty()).then_some(detected),
            }
        }
        Ok(output)
            if String::from_utf8_lossy(&output.stderr)
                .to_ascii_lowercase()
                .contains("not a git repository") =>
        {
            ProjectFileSyncEligibility {
                state: ProjectFileSyncEligibilityState::Eligible,
                reason: "Project folder is not inside a Git work tree".to_string(),
                detected_root: None,
            }
        }
        Ok(output) => ProjectFileSyncEligibility {
            state: ProjectFileSyncEligibilityState::Unknown,
            reason: format!(
                "Git eligibility probe failed with status {}",
                output
                    .status
                    .code()
                    .map(|code| code.to_string())
                    .unwrap_or_else(|| "unknown".to_string())
            ),
            detected_root: None,
        },
        Err(error) => ProjectFileSyncEligibility {
            state: ProjectFileSyncEligibilityState::Unknown,
            reason: format!("Git eligibility probe could not run: {}", error),
            detected_root: None,
        },
    }
}

pub(super) fn get_bundle_inventory_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
) -> Result<ResourceInventory, String> {
    let state = repository.load_project_state_snapshot()?;
    state
        .config
        .project(local_project_id)
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
    let binding = state.bindings.active_for(local_project_id).ok_or_else(|| {
        format!(
            "project '{}' is not mapped on this machine",
            local_project_id
        )
    })?;
    let resolved = resolve_project_binding_from_state(&state.bindings, binding)?;
    let request = capture_request_for_resolved_binding_from_state(
        repository.root(),
        &state.config,
        &state.bindings,
        &resolved,
    )?;
    let discovery = provider_capture::discover_full(provider_registry(), &request)?;
    build_resource_inventory(&state.config, local_project_id, binding, &discovery)
}

/// Project/link recipes are machine-local selection state. A remote manifest's
/// generic resources can seed that state, but its conversation entries remain
/// cloud identities and are reviewed through `ThreadSyncComparison` instead.
fn machine_local_recipe_from_manifest(manifest: &BundleManifest) -> Result<BundleRecipe, String> {
    let mut recipe = BundleRecipe::default();
    for scope in manifest.scopes.values() {
        for (resource_id, entry) in &scope.recipe.entries {
            if !is_conversation_resource_id(resource_id.as_str()) {
                recipe.entries.insert(resource_id.clone(), entry.clone());
            }
        }
    }
    recipe.validate_machine_local()?;
    Ok(recipe)
}

/// Inventory section over a shared discovery. Inventory is read-only: a
/// reviewed Push is the only flow that changes a destination recipe.
fn build_resource_inventory(
    config: &SyncConfig,
    local_project_id: &LocalProjectId,
    binding: &ProjectBinding,
    discovery: &provider_capture::Discovery,
) -> Result<ResourceInventory, String> {
    let discovered = discovery.project_inventory();
    let project = config
        .project(local_project_id)
        .cloned()
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
    let mut recipe = project.recipe.clone();
    recipe.validate_machine_local()?;
    remove_excluded_codex_subagents_from_recipe(
        &mut recipe,
        discovery.excluded_subagent_resource_ids(),
    );
    let mut inventory = inventory_from_candidates(
        binding.project_root.clone(),
        Some(project.bundle_id.clone()),
        &discovered.resources,
        recipe,
        discovered.warnings,
    )?;
    let visible: BTreeSet<_> = inventory
        .resources
        .iter()
        .map(|resource| resource.descriptor.resource_id.clone())
        .collect();
    let selected_entries = inventory.recipe.entries.clone();
    for (resource_id, entry) in &selected_entries {
        if visible.contains(resource_id) {
            continue;
        }
        let descriptor = ResourceDescriptor {
            resource_id: resource_id.clone(),
            kind: contracts::requirement(),
            provider: None,
            provider_resource_type: None,
            display_name: resource_id.to_string(),
            provenance: contracts::provenance_unknown(),
            apply_policy: entry.apply_policy.clone(),
            codec_version: 1,
            attributes: mallard_domain::BoundedPortableObject::empty(),
        };
        let presentation = contract_presentation(&descriptor);
        inventory.resources.push(InventoryResource {
            kind_label: presentation.kind_label,
            apply_policy_label: presentation.apply_policy_label,
            selectable: presentation.selectable,
            descriptor,
            category: "tools".to_string(),
            // One sentence, not two. This carried a `description` as well —
            // "Selected resource is unavailable on this machine" — which the
            // row printed above the blocker line that said the same thing in
            // different words. The blocked reason is the one that also drives
            // the row's state, so it is the one that speaks.
            description: None,
            logical_paths: Vec::new(),
            default_selected: true,
            blocked_reason: Some(
                "Selected for sync, but unavailable at the mapped paths on this machine"
                    .to_string(),
            ),
        });
    }
    inventory.resources.sort_by(|left, right| {
        left.descriptor
            .resource_id
            .cmp(&right.descriptor.resource_id)
    });
    Ok(inventory)
}

fn inventory_from_candidates(
    project: String,
    bundle_id: Option<BundleId>,
    candidates: &[ResourceCandidate],
    recipe: BundleRecipe,
    warnings: Vec<String>,
) -> Result<ResourceInventory, String> {
    let mut resources = Vec::with_capacity(candidates.len());
    for candidate in candidates {
        let mut descriptor = provider_capture::domain_resource_descriptor(candidate, None)?;
        if let Some(entry) = recipe.entries.get(&descriptor.resource_id) {
            descriptor.apply_policy = entry.apply_policy.clone();
        }
        descriptor.validate()?;
        let category = resource_category(&descriptor.kind).to_string();
        let presentation = contract_presentation(&descriptor);
        resources.push(InventoryResource {
            category,
            kind_label: presentation.kind_label,
            apply_policy_label: presentation.apply_policy_label,
            selectable: presentation.selectable,
            description: None,
            logical_paths: candidate.logical_paths.clone(),
            default_selected: candidate.selected_by_default,
            blocked_reason: candidate.blocked_reason.clone(),
            descriptor,
        });
    }
    resources.sort_by(|left, right| {
        left.descriptor
            .resource_id
            .cmp(&right.descriptor.resource_id)
    });
    Ok(ResourceInventory {
        project,
        bundle_id,
        resources,
        recipe,
        generated_at: now_secs(),
        warnings,
    })
}

fn remove_excluded_codex_subagents_from_recipe(
    recipe: &mut BundleRecipe,
    excluded_resource_ids: &BTreeSet<String>,
) -> bool {
    let previous_entry_count = recipe.entries.len();
    recipe
        .entries
        .retain(|resource_id, _| !excluded_resource_ids.contains(resource_id.as_str()));
    recipe.entries.len() != previous_entry_count
}

struct ContractPresentation {
    kind_label: String,
    apply_policy_label: String,
    selectable: bool,
}

/// Safe labels and selectability from the registered contracts. Unknown
/// coordinates render as their raw coordinate and are never selectable.
fn contract_presentation(descriptor: &ResourceDescriptor) -> ContractPresentation {
    let registry = PortableResourceRegistry::production();
    let policy = registry.apply_policy(&descriptor.apply_policy);
    ContractPresentation {
        kind_label: registry.resource_kind_label(&descriptor.kind),
        apply_policy_label: registry.apply_policy_label(&descriptor.apply_policy),
        selectable: registry
            .resolve_resource_kind(&descriptor.kind, &descriptor.attributes)
            .is_ok_and(|kind| kind.is_some())
            && policy.is_some_and(|policy| policy != mallard_domain::ApplyPolicyPrimitive::Never),
    }
}

/// The presentation category the registered resource-kind adapter declares.
/// An unregistered kind lands in the tools group as an unavailable row.
fn resource_category(kind: &mallard_domain::ResourceKindCoordinate) -> &'static str {
    PortableResourceRegistry::production()
        .resource_kind_adapter(kind)
        .map(|adapter| adapter.category().as_str())
        .unwrap_or("tools")
}

type StorageEngine = BundleEngine<ConfiguredObjectStore>;

fn find_remote_bundle_matches_with_repository(
    repository: &LocalStateRepository,
    storage_id: &StorageId,
    repository_fingerprint: &str,
) -> Result<Vec<BundleSnapshotSummary>, String> {
    if repository_fingerprint.len() != 64
        || !repository_fingerprint
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit())
    {
        return Err("repository fingerprint must be a SHA-256 hex digest".to_string());
    }
    Ok(
        list_remote_bundle_snapshots_with_repository(repository, storage_id)?
            .into_iter()
            .filter(|snapshot| {
                snapshot.repository_fingerprint.as_deref() == Some(repository_fingerprint)
            })
            .collect(),
    )
}

pub(super) fn list_remote_bundle_snapshots_with_repository(
    repository: &LocalStateRepository,
    storage_id: &StorageId,
) -> Result<Vec<BundleSnapshotSummary>, String> {
    let (_, engine) = storage_engine(repository, storage_id)?;
    list_bundle_snapshots_with_engine(&engine)
}

fn list_bundle_snapshots_with_engine(
    engine: &StorageEngine,
) -> Result<Vec<BundleSnapshotSummary>, String> {
    let fetched_at = now_secs();
    let mut snapshots = match engine.store().managed_cloud() {
        // Mallard Cloud lists one repository at a time: discovery reads the
        // account's repository list, whose rows carry each head's indexed
        // summary (plan decision 10). Display only.
        Some(cloud) => managed_cloud_bundle_snapshots(engine.storage_id(), cloud, fetched_at)?,
        None => engine
            .list_remote_bundles()?
            .into_iter()
            .map(|bundle| BundleSnapshotSummary {
                storage_id: engine.storage_id().clone(),
                bundle_id: bundle.bundle_id,
                display_name: bundle.display_name,
                kind: bundle.kind,
                revision: bundle.revision,
                updated_at: bundle.updated_at,
                resource_count: bundle.resources as usize,
                registration_only: bundle.registration_only,
                providers: bundle.providers,
                repository_fingerprint: bundle.repository_fingerprint,
                fetched_at,
            })
            .collect::<Vec<_>>(),
    };
    snapshots.sort_by(|left, right| {
        right
            .updated_at
            .cmp(&left.updated_at)
            .then_with(|| left.bundle_id.cmp(&right.bundle_id))
    });
    Ok(snapshots)
}

/// One discovery row per project repository the account belongs to whose
/// index holds a private head. A row's facts are the head's record facts as
/// the service indexed them.
fn managed_cloud_bundle_snapshots(
    storage_id: &StorageId,
    cloud: &mallard_infrastructure::managed_cloud::ManagedObjectStore,
    fetched_at: u64,
) -> Result<Vec<BundleSnapshotSummary>, String> {
    let mut rows = Vec::new();
    for repository in cloud.list_project_repositories()? {
        let (Some(bundle_id), Some(head), Some(summary)) = (
            repository.bundle_id.as_deref(),
            repository.private_head.as_ref(),
            repository.private_summary.as_ref(),
        ) else {
            continue;
        };
        let Ok(bundle_id) = BundleId::parse(bundle_id.to_string()) else {
            continue;
        };
        rows.push(BundleSnapshotSummary {
            storage_id: storage_id.clone(),
            bundle_id,
            display_name: summary.display_name.clone(),
            kind: BundleKind::Project,
            revision: head.revision,
            updated_at: head.updated_at,
            resource_count: summary.resources as usize,
            registration_only: summary.registration_only,
            providers: summary
                .providers
                .iter()
                .filter_map(|provider| ProviderKey::parse(provider.clone()).ok())
                .collect(),
            repository_fingerprint: repository.repository_fingerprint.clone(),
            fetched_at,
        });
    }
    Ok(rows)
}

/// Supply the local origin to Cloud creation without putting paths in a manifest.
fn set_cloud_project_origin(
    engine: &StorageEngine,
    project: &LocalProjectRegistration,
    binding: &ProjectBinding,
) -> Result<(), String> {
    if let Some(cloud) = engine.store().managed_cloud() {
        cloud.set_project_origin(
            &project.bundle_id,
            origin_url(Path::new(&binding.canonical_project_root)).as_deref(),
        )?;
    }
    Ok(())
}

/// Publish the registration claim that makes a just-linked bundle discoverable
/// before its first push: an empty revision-1 manifest carrying the bundle
/// identity and repository fingerprint. Idempotent — an established head of
/// any kind is left untouched — and loud: a storage that cannot be written is
/// reported at link time, not at the first push.
fn publish_registration_claim(
    repository: &LocalStateRepository,
    storage: &StorageConfig,
    project: &LocalProjectRegistration,
    binding: &ProjectBinding,
) -> Result<(), String> {
    let engine = engine_for_storage_config(storage)?;
    set_cloud_project_origin(&engine, project, binding)?;
    let (origin_host_token, origin_replica_token) =
        repository.derive_origin_tokens(&project.bundle_id, &binding.replica_id)?;
    engine
        .publish_registration(
            &BundleIdentity {
                bundle_id: project.bundle_id.clone(),
                display_name: project.display_name.clone(),
                kind: BundleKind::Project,
                repository_fingerprint: project.repository_fingerprint.clone(),
            },
            &PortableOrigin {
                origin_host_token,
                origin_replica_token,
                shared_label: None,
            },
            now_secs(),
        )
        .map(|_| ())
        .map_err(|error| format!("register the repo in '{}': {}", storage.name, error))
}

/// While this link's bundle has no published content, find same-repository
/// sibling bundles and classify what the user can connect to. Read-only —
/// refresh never writes claims; only link, setup, and Push flows do. A
/// converged link returns before any storage listing happens.
#[derive(Serialize, Clone, Debug)]
#[serde(tag = "state", rename_all = "snake_case")]
pub enum SiblingBundleStatus {
    None,
    /// Same-repository bundles exist that this link cannot see; connecting
    /// to one converges. Content-bearing siblings sort first.
    SiblingFound {
        matches: Vec<BundleSnapshotSummary>,
    },
    /// Every party is an empty registration — a concurrent-claim race. The
    /// deterministic survivor is the smallest bundle id; only the losing
    /// side receives this state.
    RegistrationTwin {
        survivor: Box<BundleSnapshotSummary>,
    },
}

pub(super) fn sibling_bundle_status_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<SiblingBundleStatus, String> {
    let config = repository.load_config()?;
    let project = config
        .project(local_project_id)
        .cloned()
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
    if !config
        .links
        .iter()
        .any(|link| link.local_project_id == *local_project_id && link.storage_id == *storage_id)
    {
        return Err(format!(
            "project '{}' is not linked to storage '{}'",
            local_project_id, storage_id
        ));
    }
    let Some(fingerprint) = project.repository_fingerprint.clone() else {
        return Ok(SiblingBundleStatus::None);
    };
    let (_, engine) = storage_engine(repository, storage_id)?;
    let own = engine.inspect_optional(&project.bundle_id)?;
    let own_registration = match &own {
        Some(snapshot) if !snapshot.manifest.is_registration_only() => {
            return Ok(SiblingBundleStatus::None);
        }
        Some(_) => true,
        None => false,
    };
    let mut matches: Vec<BundleSnapshotSummary> =
        find_remote_bundle_matches_with_repository(repository, storage_id, &fingerprint)?
            .into_iter()
            .filter(|candidate| candidate.bundle_id != project.bundle_id)
            .collect();
    if matches.is_empty() {
        return Ok(SiblingBundleStatus::None);
    }
    matches.sort_by(|left, right| {
        left.registration_only
            .cmp(&right.registration_only)
            .then_with(|| right.updated_at.cmp(&left.updated_at))
            .then_with(|| left.bundle_id.cmp(&right.bundle_id))
    });
    if !own_registration || matches.iter().any(|candidate| !candidate.registration_only) {
        return Ok(SiblingBundleStatus::SiblingFound { matches });
    }
    let survivor = matches
        .iter()
        .min_by(|left, right| left.bundle_id.cmp(&right.bundle_id))
        .cloned()
        .expect("non-empty matches have a minimum");
    if project.bundle_id < survivor.bundle_id {
        // This side holds the smallest id: the twins converge onto it.
        return Ok(SiblingBundleStatus::None);
    }
    Ok(SiblingBundleStatus::RegistrationTwin {
        survivor: Box::new(survivor),
    })
}

/// The provider-native session id inside a `<provider>:session:<component>`
/// capture resource id.
fn provider_session_id_from_resource(resource_id: &str) -> Option<&str> {
    let (_, rest) = resource_id.split_once(':')?;
    rest.strip_prefix("session:")
        .filter(|session_id| !session_id.is_empty())
}

fn thread_capture_unavailable_detail(blocked_reason: Option<&str>) -> String {
    let Some(reason) = blocked_reason else {
        return "Session could not be read safely during this scan.".to_string();
    };
    if reason.contains(&format!(
        "exceeds {} bytes",
        conversation_file_limit_bytes()
    )) {
        return format!(
            "Session file exceeds the {} MiB per-file sync limit.",
            conversation_file_limit_bytes() / (1024 * 1024)
        );
    }
    if reason.contains("hard-linked") {
        return "Session file is hard-linked and cannot be synced safely.".to_string();
    }
    if reason.contains("not a regular no-follow file") {
        return "Session path is not a regular file and cannot be synced safely.".to_string();
    }
    "Session is unavailable for safe capture.".to_string()
}

fn count_thread_sync_state(counts: &mut ThreadSyncCounts, state: ThreadSyncState) {
    match state {
        ThreadSyncState::Synced => counts.synced += 1,
        ThreadSyncState::LocalOnly | ThreadSyncState::LocalAhead => counts.local += 1,
        ThreadSyncState::StorageOnly | ThreadSyncState::StorageAhead => counts.storage += 1,
        ThreadSyncState::Diverged => counts.diverged += 1,
        ThreadSyncState::Unavailable => counts.unavailable += 1,
        ThreadSyncState::Unknown => counts.unknown += 1,
    }
}

fn relation_sync_state(relation: TailClassification) -> ThreadSyncState {
    match relation {
        TailClassification::Sync(_) | TailClassification::MissingBoth => ThreadSyncState::Synced,
        TailClassification::LocalOutstanding => ThreadSyncState::LocalAhead,
        TailClassification::MissingCloud => ThreadSyncState::LocalOnly,
        TailClassification::CloudOutstanding => ThreadSyncState::StorageAhead,
        TailClassification::MissingLocal => ThreadSyncState::StorageOnly,
        TailClassification::Divergent => ThreadSyncState::Diverged,
        TailClassification::Unknown => ThreadSyncState::Unknown,
    }
}

type ReviewedCodexRoots = BTreeMap<
    PathBuf,
    (
        codex_history_graph::ResolvedCodexRoot,
        codex_history_graph::CodexSourceSnapshots,
    ),
>;

struct PreparedCodexPublication {
    root: codex_history_graph::ResolvedCodexRoot,
    sources: codex_history_graph::CodexSourceSnapshots,
    tree: codex_subagents::CapturedTree,
}

type PreparedCodexPublications = BTreeMap<ResourceId, Result<PreparedCodexPublication, String>>;

struct ThreadReview {
    prepared_codex: PreparedCodexPublications,
    entries: Vec<ThreadSyncEntry>,
    push_actions: Vec<ConversationPlanAction>,
    pull_actions: Vec<ConversationPlanAction>,
    pull_review: Vec<ConversationReviewRow>,
    /// Provider aliases displaced by Codex copy-on-write materialization and
    /// proven byte-identical to their immutable retained-source checkpoint.
    /// Their files remain available for physical `history_base` dependencies;
    /// changed or unproven retained aliases are independent logical rows and
    /// therefore never enter this suppression set.
    suppressed_provider_ids: BTreeSet<(ProviderKey, String)>,
    /// Per-provider review failures. A failed provider's rows fail closed
    /// without blocking any other provider (D8).
    provider_errors: BTreeMap<ProviderKey, String>,
}

struct EmptyBundleBytes;

impl BundleBytes for EmptyBundleBytes {
    fn body(&mut self, logical_path: &LogicalPath) -> Result<VerifiedBody, String> {
        Err(format!(
            "fresh bundle has no stored payload for '{}'",
            logical_path
        ))
    }

    fn read_bounded(
        &mut self,
        logical_path: &LogicalPath,
        _max_bytes: u64,
        _label: &str,
    ) -> Result<Vec<u8>, String> {
        Err(format!(
            "fresh bundle has no stored payload for '{}'",
            logical_path
        ))
    }
}

#[derive(Clone)]
pub(crate) struct LocalThreadReview {
    pub(crate) binding: Option<LocalConversationBinding>,
    pub(crate) binding_resolution: BindingResolution,
    pub(crate) resource_id: ResourceId,
    pub(crate) descriptor: Option<ResourceDescriptor>,
    pub(crate) provider_thread_id: String,
    pub(crate) source_path: PathBuf,
    pub(crate) source_mtime: u64,
    /// Transcript plus sidecars, what a push capture of this thread weighs.
    pub(crate) capture_bytes: u64,
    pub(crate) captured: Option<CapturedThread>,
}

/// Captured transcript bytes attached to a reviewed local thread when a
/// capture selected it: always for providers without a cursor codec, and
/// only for byte-pinning work on providers with one.
#[derive(Clone)]
pub(crate) struct CapturedThread {
    pub(crate) conversation: provider_capture::CapturedConversation,
    pub(crate) transcript: provider_capture::CapturedFile,
}

fn bounded_file_expectation(path: &Path) -> Result<TargetExpectation, String> {
    let metadata = match fs::symlink_metadata(path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(TargetExpectation::Absent)
        }
        Err(error) => {
            return Err(format!(
                "inspect provider target '{}': {error}",
                path.display()
            ))
        }
    };
    if !metadata.file_type().is_file() || metadata.file_type().is_symlink() {
        return Err(format!(
            "provider target '{}' is not a regular no-follow file",
            path.display()
        ));
    }
    if metadata.len() > MAX_CONVERSATION_TARGET_BYTES {
        return Err(format!(
            "provider target '{}' exceeds the conversation limit",
            path.display()
        ));
    }
    let content = fs::read(path)
        .map_err(|error| format!("read provider target '{}': {error}", path.display()))?;
    mallard_infrastructure::sync_metrics::record_transcript_bytes_read(path, content.len() as u64);
    mallard_infrastructure::sync_metrics::record_bytes_hashed(path, content.len() as u64);
    Ok(TargetExpectation::Sha256(hex_digest(
        Sha256::digest(&content).as_slice(),
    )))
}

/// The machine-local transcript source pinned by capture. Every provider
/// records it during discovery, so Apply never re-derives machine
/// paths from portable ones.
fn captured_transcript_source(
    conversation: &provider_capture::CapturedConversation,
) -> Result<PathBuf, String> {
    conversation
        .source_physical_path
        .clone()
        .ok_or_else(|| "captured conversation has no machine-local transcript source".to_string())
}

/// Review every conversation of every bound provider, isolating provider
/// failures: an unreadable profile fails that provider's rows closed and
/// never blocks another provider's safe review (D8).
///
/// `mainline` is the selected chain `snapshot` was read from. A saved
/// acceptance counts only while the publication it names is on it
/// (`ConversationCheckpoint::read_on`).
#[allow(clippy::too_many_arguments)]
fn thread_review(
    repository: &LocalStateRepository,
    snapshot: Option<&BundleSnapshot>,
    mainline: &Mainline,
    bytes: &mut dyn BundleBytes,
    views: &[provider_capture::LocalSessionView],
    captured: &provider_capture::CapturedResources,
    candidate_pins: &BTreeMap<String, TargetExpectation>,
    resolved: &ResolvedBinding,
    storage_id: Option<&StorageId>,
    created_at: u64,
    expires_at: u64,
    purpose: ReviewPurpose,
    resource_filter: Option<&BTreeSet<ResourceId>>,
    settings: &AppSettings,
) -> Result<ThreadReview, String> {
    let mut merged = ThreadReview {
        prepared_codex: BTreeMap::new(),
        entries: Vec::new(),
        push_actions: Vec::new(),
        pull_actions: Vec::new(),
        pull_review: Vec::new(),
        suppressed_provider_ids: BTreeSet::new(),
        provider_errors: BTreeMap::new(),
    };
    let registry = provider_registry();
    for provider in resolved.binding.profile_ids.keys() {
        if registry.get(provider).is_none() {
            merged.provider_errors.insert(
                provider.clone(),
                format!("no provider adapter is registered for '{}'", provider),
            );
            continue;
        }
        let review = match resolved.homes.get(provider) {
            Some(home) => provider_thread_review(
                repository,
                snapshot,
                mainline,
                bytes,
                views,
                captured,
                candidate_pins,
                resolved,
                provider,
                Path::new(home),
                storage_id,
                created_at,
                expires_at,
                purpose,
                resource_filter,
                &settings,
            ),
            None => Err(format!(
                "provider '{}' profile is unavailable on this machine",
                provider
            )),
        };
        match review {
            Ok(review) => {
                merged.prepared_codex.extend(review.prepared_codex);
                merged.entries.extend(review.entries);
                merged.push_actions.extend(review.push_actions);
                merged.pull_actions.extend(review.pull_actions);
                merged.pull_review.extend(review.pull_review);
                merged
                    .suppressed_provider_ids
                    .extend(review.suppressed_provider_ids);
            }
            Err(error) => {
                merged.provider_errors.insert(provider.clone(), error);
            }
        }
    }
    merged.entries.sort_by(|left, right| {
        left.cloud_thread_id
            .cmp(&right.cloud_thread_id)
            .then_with(|| left.provider.cmp(&right.provider))
            .then_with(|| left.thread_id.cmp(&right.thread_id))
    });
    merged
        .push_actions
        .sort_by(|left, right| left.thread_id.cmp(&right.thread_id));
    merged
        .pull_actions
        .sort_by(|left, right| left.thread_id.cmp(&right.thread_id));
    merged.pull_review.sort_by(|left, right| {
        left.provider
            .cmp(&right.provider)
            .then_with(|| left.thread_id.cmp(&right.thread_id))
    });
    Ok(merged)
}

/// The reviewed provider-scope coordinates from a snapshot, or the absent
/// pin for a repository/scope that does not exist yet.
fn provider_scope_pin(snapshot: Option<&BundleSnapshot>, provider: &ProviderKey) -> (u64, String) {
    snapshot
        .and_then(|snapshot| snapshot.manifest.provider_scope(provider))
        .map(|scope| (scope.revision, scope.content_sha256.clone()))
        .unwrap_or_else(absent_scope_pin)
}

/// Locate one Codex rollout by thread id under the profile's canonical
/// session roots. Codex embeds the thread UUID in the rollout file name, so
/// the walk matches on the suffix without opening unrelated files.
pub(super) fn codex_rollout_lookup(
    provider_home: &Path,
) -> impl Fn(&str) -> Result<Option<PathBuf>, String> + '_ {
    let lookup = RolloutLookup::new(provider_home);
    move |thread_id: &str| lookup.find_rollout(thread_id)
}

/// Applied receipts retain provider aliases when a binding moves to a fresh
/// alias. The receipt ledger is authoritative for
/// imported logical IDs as well as deterministic first-contact IDs, and it
/// naturally supports repeated moves without adding schema state.
fn applied_provider_alias_owners(
    materializations: &Materializations,
    binding: &ProjectBinding,
    provider: &ProviderKey,
    profile_id: &LocalProviderProfileId,
) -> BTreeMap<String, BTreeSet<ThreadId>> {
    let mut owners = BTreeMap::<String, BTreeSet<ThreadId>>::new();
    for record in &materializations.records {
        if record.host_id != binding.host_id
            || record.replica_id != binding.replica_id
            || record.local_project_id != binding.local_project_id
            || record.bundle_id != binding.bundle_id
        {
            continue;
        }
        for receipt in record
            .receipts
            .iter()
            .filter(|receipt| receipt.status == ActionStatus::Applied)
        {
            let Some(conversation) = &receipt.conversation else {
                continue;
            };
            if conversation.host_id != binding.host_id
                || conversation.replica_id != binding.replica_id
                || conversation.provider_profile_id != *profile_id
                || conversation.materialization_state != ConversationMaterializationState::Resumable
            {
                continue;
            }
            let Ok((receipt_provider, receipt_thread_id)) =
                parse_conversation_resource_id(receipt.resource_id.as_str())
            else {
                continue;
            };
            if &receipt_provider != provider || receipt_thread_id != conversation.thread_id {
                continue;
            }
            if let Some(provider_thread_id) = &conversation.provider_thread_id {
                owners
                    .entry(provider_thread_id.clone())
                    .or_default()
                    .insert(conversation.thread_id.clone());
            }
        }
    }
    owners
}

fn displaced_provider_alias_owners(
    bundle_id: &BundleId,
    provider: &ProviderKey,
    provider_thread_id: &str,
    scoped_bindings: &[LocalConversationBinding],
    historical_alias_owners: &BTreeMap<String, BTreeSet<ThreadId>>,
) -> Result<BTreeSet<ThreadId>, String> {
    let mut owners = historical_alias_owners
        .get(provider_thread_id)
        .cloned()
        .unwrap_or_default();
    let initial_owner = initial_conversation_thread_id(bundle_id, provider, provider_thread_id)?;
    owners.insert(initial_owner);
    owners.retain(|owner| {
        scoped_bindings.iter().any(|binding| {
            binding.thread_id == *owner
                && binding
                    .provider_thread_id
                    .as_deref()
                    .is_some_and(|current| current != provider_thread_id)
        })
    });
    Ok(owners)
}

/// Synthesized `WholeThread`-equivalent evidence for providers that have not
/// adopted the portable tail codec: field-wise equality over
/// `(codec, whole-thread, 0, count, semantic digest)` reproduces their
/// existing digest-pair comparison semantics.
fn synthesized_whole_thread_tail(
    codec: &str,
    message_count: u64,
    semantic_digest: &str,
) -> PortableConversationTail {
    PortableConversationTail {
        codec: codec.to_string(),
        partition_kind: TailPartitionKind::WholeThread,
        start_record_count: 0,
        accepted_end_record_count: message_count,
        accepted_tail_state: semantic_digest.to_string(),
    }
}

/// A cursor an observation derived and the stamp of the file it was read
/// from: what a checkpoint saves as its physical mapping.
struct SeededCursor {
    root: CodexSeededRoot,
    source: jsonl_tail_io::SourceStamp,
}

/// A worker's complete observation outcome.
pub(crate) struct ProviderLocalObservation {
    observation: LocalTailObservation,
    seeded: Option<SeededCursor>,
    /// Physical files the derivation read, each under its read-time stamp;
    /// empty when the outcome must not be retained.
    depends_on: jsonl_tail_io::SourceStamps,
}

/// A parallel observation worker's slot value.
type ObservationOutcome = Result<ProviderLocalObservation, String>;

fn take_observation_outcome(
    thread_id: &ThreadId,
    slot: &mut std::sync::OnceLock<ObservationOutcome>,
) -> ObservationOutcome {
    slot.take().unwrap_or_else(|| {
        Err(format!(
            "thread observation worker produced no outcome for thread '{}'",
            thread_id
        ))
    })
}

/// One reviewed thread's derived local state. Serializable because the
/// observation cache persists it between processes; the value is a pure
/// function of the session bytes it was derived from.
#[derive(Serialize, Deserialize, Clone)]
pub(crate) struct LocalTailObservation {
    /// Read-time evidence for same-process Push reuse. Disk observations do
    /// not carry executable evidence and must be derived again.
    #[serde(skip)]
    push_reuse: Option<PushObservationEvidence>,
    pub(crate) subagents: Option<owned_subagents::TreeObservation>,
    discovery: Option<codex_subagents::DiscoveryObservation>,
    evidence: TailSideEvidence,
    /// The checkpoint-format raw range pin for a publishing plan.
    raw_range_pin: Option<RawRangePin>,
    /// Acceptance evidence re-established by first-contact adoption: the
    /// reviewed cloud wire pin plus its local-form twin at the same end,
    /// proven by encoding this local chain under the binding root and
    /// folding the wire state at the cloud pin's recorded end. Set only on
    /// the full-resolve path; it never comes from a cursor ride or any
    /// non-verifying branch.
    verified_acceptance: Option<VerifiedAdoption>,
    /// The session no longer continues the version that was accepted: see
    /// `edited_since_acceptance`. The comparison reads the accepted pins
    /// of such a session as absent, and no cursor is saved from the read.
    edited_since_acceptance: bool,
}

/// A full derivation and the exact files it read. This stays in memory;
/// Push reuse evidence never enters portable state or the observation disk cache.
#[derive(Clone)]
struct PushObservationEvidence {
    seeded: CodexSeededRoot,
    layout: Option<RootTailLayout>,
    sources: BTreeMap<PathBuf, jsonl_tail_io::SourceStamp>,
    conversation_limit: u64,
}

impl LocalTailObservation {
    pub(crate) fn matches_codex_selection(&self, lookup: &RolloutLookup) -> bool {
        let Some(owned_subagents::TreeObservation::Codex(tree)) = &self.subagents else {
            return true;
        };
        // An excluded or missing child has no captured current mapping.
        // Recompute its membership instead of trusting an old header path.
        if !tree.missing.is_empty() || !tree.header_dependencies.is_empty() {
            return false;
        }
        let matches = |mapping: &mallard_domain::RootPhysicalMapping| {
            lookup
                .find_current(&mapping.provider_thread_id)
                .ok()
                .flatten()
                .as_deref()
                == Some(Path::new(&mapping.root_path))
        };
        matches(&tree.main.mapping)
            && tree
                .children
                .values()
                .all(|child| matches(&child.discovery.mapping))
    }

    pub(crate) fn matches_push_capture(
        &self,
        source: &Path,
        stamp: &jsonl_tail_io::SourceStamp,
        provider_thread_id: &str,
        layout: Option<&RootTailLayout>,
    ) -> bool {
        let Some(proof) = &self.push_reuse else {
            return false;
        };
        // A file-only proof cannot establish changing child membership or
        // missing files. Such observations keep the normal review path.
        let closed_scope = match self.subagents.as_ref() {
            Some(owned_subagents::TreeObservation::Codex(tree)) => {
                !tree.omitted
                    && tree.missing.is_empty()
                    && tree.children.is_empty()
                    && tree.main.creations.is_empty()
                    && tree.header_dependencies.is_empty()
            }
            Some(owned_subagents::TreeObservation::Claude(tree)) => {
                !tree.omitted
                    && tree.missing.is_empty()
                    && tree.children.is_empty()
                    && tree.main.links.is_empty()
            }
            None => false,
        };
        closed_scope
            && self.verified_acceptance.is_none()
            && self.raw_range_pin.is_some()
            && matches!(&self.evidence, TailSideEvidence::Present(tail) if tail == &proof.seeded.observed_tail)
            && proof.layout.as_ref() == layout
            && proof.seeded.mapping.provider_thread_id == provider_thread_id
            && Path::new(&proof.seeded.mapping.root_path) == source
            && proof.conversation_limit == conversation_file_limit_bytes()
            && proof.sources.get(source) == Some(stamp)
            && proof
                .sources
                .iter()
                .all(|(path, stamp)| stamp.verify(path).is_ok())
    }
}

/// Load only the physical sources this thread consumes. A null reference
/// means a native transcript that has not yet been encoded or restored.
/// A referenced file must verify; missing or damaged files never rescan.
fn load_source_path_origins<'a>(
    repository: &LocalStateRepository,
    document: &mallard_domain::ConversationBindings,
    project: &ProjectBinding,
    profile_id: &LocalProviderProfileId,
    sources: impl Iterator<Item = &'a str>,
) -> Result<PathOrigins, String> {
    let mut origins = PathOrigins::default();
    for source in sources {
        if origins.sources.contains_key(source) {
            continue;
        }
        if let Some(row) = document.bindings.iter().find(|row| {
            row.host_id == project.host_id
                && row.replica_id == project.replica_id
                && row.local_project_id == project.local_project_id
                && &row.provider_profile_id == profile_id
                && row.provider_thread_id.as_deref() == Some(source)
        }) {
            if row.path_origins_ref.is_some() {
                origins.merge(&repository.load_path_origins(row)?)?;
            }
        }
    }
    Ok(origins)
}

/// The §6.4 encode-compare adoption outcome: dual pins for this review only;
/// the durable pins are written by the Push or Pull the adoption enables.
#[derive(Serialize, Deserialize, Clone)]
pub(crate) struct VerifiedAdoption {
    wire_tail: PortableConversationTail,
    local_tail: PortableConversationTail,
}

/// The §6.4 encode-compare: build the wire form of the resolved local thread
/// under its own binding root, fold the wire state at the cloud pin's end,
/// and compare. Equal ⇒ dual pins re-established (cloud wire pin + the
/// local-form twin at the same end). Every failure path returns `None`:
/// unproven adoption must fail closed.
fn adopt_codex_acceptance(
    resolved: &codex_history_graph::ResolvedCodexRoot,
    probe: &PortableConversationTail,
    effective_kind: TailPartitionKind,
    effective_start: u64,
    layout: Option<&RootTailLayout>,
    project_root: &str,
    canonical_project_root: &str,
    origins: &PathOrigins,
    stored_redaction: Option<&mallard_domain::ConversationWireRedaction>,
) -> Option<VerifiedAdoption> {
    if probe.codec != mallard_domain::PORTABLE_TAIL_CODEC_WIRE_V1
        || probe.partition_kind != effective_kind
        || probe.start_record_count != effective_start
        || probe.accepted_end_record_count < effective_start
        || probe.accepted_end_record_count > resolved.chain.len() as u64
    {
        return None;
    }
    let artifact = encode_standalone_codex_root(
        resolved,
        project_root,
        (canonical_project_root != project_root).then_some(canonical_project_root),
        layout,
        &mut credential_redaction::shared()
            .run_from_stamp(stored_redaction)
            .ok()?,
        origins,
    )
    .ok()?;
    adopt_codex_artifact(resolved, &artifact, probe, effective_kind, effective_start)
}

fn adopt_codex_artifact(
    resolved: &codex_history_graph::ResolvedCodexRoot,
    artifact: &StandaloneConversationArtifact<credential_redaction::RedactedWireBytes>,
    probe: &PortableConversationTail,
    effective_kind: TailPartitionKind,
    effective_start: u64,
) -> Option<VerifiedAdoption> {
    if probe.codec != mallard_domain::PORTABLE_TAIL_CODEC_WIRE_V1
        || probe.partition_kind != effective_kind
        || probe.start_record_count != effective_start
        || probe.accepted_end_record_count > resolved.chain.len() as u64
    {
        return None;
    }
    let wire_state_at_probe_end =
        if probe.accepted_end_record_count == artifact.portable_tail.accepted_end_record_count {
            artifact.portable_tail.accepted_tail_state.clone()
        } else {
            // The cloud pin is a strict prefix: fold the encoded wire chain
            // at exactly its recorded end.
            let analysis = analyze_codex_transcript(&artifact.root_bytes);
            let wire_chain = analysis.lineage.chain()?;
            mallard_domain::compute_conversation_tail_state(
                effective_kind,
                effective_start,
                probe.accepted_end_record_count,
                wire_chain,
            )
            .ok()?
        };
    if wire_state_at_probe_end != probe.accepted_tail_state {
        return None;
    }
    let local_state = mallard_domain::compute_conversation_tail_state(
        effective_kind,
        effective_start,
        probe.accepted_end_record_count,
        &resolved.chain,
    )
    .ok()?;
    let local_tail = PortableConversationTail {
        codec: mallard_domain::PORTABLE_TAIL_CODEC_V1.to_string(),
        partition_kind: effective_kind,
        start_record_count: effective_start,
        accepted_end_record_count: probe.accepted_end_record_count,
        accepted_tail_state: local_state,
    };
    local_tail.validate().ok()?;
    Some(VerifiedAdoption {
        wire_tail: probe.clone(),
        local_tail,
    })
}

/// The complete records of one transcript and the names their saved digests
/// are kept under.
struct AcceptedRecords<'a> {
    records_of: &'a str,
    length_of: &'a str,
    complete: &'a [u8],
}

/// Whether the messages up to the accepted end still give the accepted
/// value. The messages and the accepted version are of one form, local or
/// wire.
fn accepted_prefix_matches(
    accepted: &PortableConversationTail,
    chain: &[mallard_domain::CanonicalConversationMessage],
) -> bool {
    mallard_domain::compute_conversation_tail_state(
        accepted.partition_kind,
        accepted.start_record_count,
        accepted.accepted_end_record_count,
        chain,
    )
    .is_ok_and(|state| state == accepted.accepted_tail_state)
}

/// Whether a session that was read in full was edited after it was
/// accepted. Three things make an edit, asked in the order of their cost:
///
/// - the session has more messages than its accepted version, the one
///   comparison that takes the accepted messages on trust;
/// - the messages up to the accepted end no longer give the accepted
///   value; and
/// - a record whose digest was saved at the last Push or Pull changed or
///   is missing, which is what the first encoding of a Push refuses.
///
/// A rewind changes the messages and no record. A Claude desktop import
/// changes records and no message. Neither is an edit. A session without
/// saved digests, or whose digests cannot be read, is not marked either:
/// the Push reports that itself.
fn edited_since_acceptance(
    repository: &LocalStateRepository,
    accepted: Option<&PortableConversationTail>,
    binding: Option<&LocalConversationBinding>,
    chain: &[mallard_domain::CanonicalConversationMessage],
    records: AcceptedRecords<'_>,
) -> bool {
    let Some(accepted) = accepted else {
        return false;
    };
    chain.len() as u64 > accepted.accepted_end_record_count
        && !accepted_prefix_matches(accepted, chain)
        && binding
            .filter(|row| row.path_origins_ref.is_some())
            .and_then(|row| repository.load_path_origins(row).ok())
            .is_some_and(|origins| {
                !origins.accepted_records_hold(
                    records.records_of,
                    records.length_of,
                    records.complete,
                )
            })
}

/// Derive local Codex evidence: ride the checkpoint cursor when it is valid,
/// fall back to a full re-resolve, and seed first-contact state. Returns the
/// observation plus the refreshed checkpoint value to persist.
///
/// `adoption_probe` carries the reviewed cloud wire tail when the thread has
/// no accepted pin. It forces the full-resolve path so the local thread can
/// be **encoded** under its own binding root and the wire fold compared to
/// the cloud pin at its recorded end: equality proves the cloud version is a
/// prefix of local and re-establishes the dual acceptance pins
/// (first-contact adoption, e.g. after a removed project is re-registered);
/// anything else leaves the pair unproven and blocked. Retained records use their
/// verified origin edits; native records use the source binding matcher.
#[allow(clippy::too_many_arguments)]
fn observe_codex_local(
    reviewed_roots: Option<&std::sync::Mutex<ReviewedCodexRoots>>,
    local: Option<&LocalThreadReview>,
    previous_discovery: Option<&codex_subagents::DiscoveryObservation>,
    checkpoint: Option<&ConversationCheckpoint>,
    layout: Option<&RootTailLayout>,
    provider_home: &Path,
    adoption_probe: Option<&PortableConversationTail>,
    repository: &LocalStateRepository,
    project: &ProjectBinding,
    profile_id: &LocalProviderProfileId,
    stored_redaction: Option<&mallard_domain::ConversationWireRedaction>,
) -> Result<ProviderLocalObservation, String> {
    let project_root = project.project_root.as_str();
    let canonical_project_root = project.canonical_project_root.as_str();
    let Some(local) = local else {
        return Ok(ProviderLocalObservation {
            observation: LocalTailObservation {
                push_reuse: None,
                subagents: None,
                discovery: None,
                evidence: TailSideEvidence::ConfirmedAbsent,
                raw_range_pin: None,
                verified_acceptance: None,
                edited_since_acceptance: false,
            },
            seeded: None,
            depends_on: Default::default(),
        });
    };
    let source = local.source_path.clone();
    RolloutLookup::new(provider_home).verify_current(&local.provider_thread_id, &source)?;
    let mut creations = previous_discovery
        .map(|previous| previous.creations.clone())
        .unwrap_or_default();
    let lookup = codex_rollout_lookup(provider_home);

    // A valid Ready checkpoint under a matching layout rides the cursor on
    // the file it was saved from, untouched or grown since. Any other file
    // state, and a cursor saved without one, takes the full resolve below:
    // the content decides, never the stamp. An adoption probe needs the
    // canonical chain and takes the full resolve as well.
    if let (Some(checkpoint), Some(layout), None) = (checkpoint, layout, adoption_probe) {
        if let PhysicalMappingState::Ready {
            root_mapping,
            raw_range_pin,
            source_state: Some(saved),
        } = &checkpoint.physical
        {
            // The stat keeps a changed file from being read twice; the
            // window's own stamp, below, is the one that decides.
            if layout.matches(&checkpoint.observed_tail)
                && root_mapping.root_path == source.to_string_lossy()
                && jsonl_tail_io::SourceStamp::stat(&source).is_ok_and(|now| now.continues(saved))
            {
                let tail = match jsonl_tail_io::read_tail_window(&source, root_mapping) {
                    Ok(tail) => tail,
                    Err(_) => {
                        return Ok(ProviderLocalObservation {
                            observation: LocalTailObservation {
                                push_reuse: None,
                                subagents: None,
                                discovery: None,
                                evidence: TailSideEvidence::Invalid,
                                raw_range_pin: None,
                                verified_acceptance: None,
                                edited_since_acceptance: false,
                            },
                            seeded: None,
                            depends_on: Default::default(),
                        })
                    }
                };
                let refresh = if tail.stamp.continues(saved) {
                    codex_history_graph::refresh_codex_tail_with_records(
                        layout,
                        &checkpoint.observed_tail,
                        root_mapping,
                        &tail,
                        &mut |record, offset| {
                            codex_subagents::record_creation(&mut creations, record, offset)
                        },
                    )?
                } else {
                    codex_history_graph::CodexTailRefresh::NeedsFullResolve
                };
                match refresh {
                    codex_history_graph::CodexTailRefresh::Unchanged => {
                        return Ok(ProviderLocalObservation {
                            observation: LocalTailObservation {
                                push_reuse: None,
                                subagents: None,
                                discovery: if previous_discovery.is_some() {
                                    Some(codex_subagents::DiscoveryObservation {
                                        mapping: root_mapping.clone(),
                                        stamp: tail.stamp.clone(),
                                        creations: creations.clone(),
                                    })
                                } else {
                                    None
                                },
                                evidence: TailSideEvidence::Present(
                                    checkpoint.observed_tail.clone(),
                                ),
                                raw_range_pin: Some(raw_range_pin.clone()),
                                verified_acceptance: None,
                                edited_since_acceptance: false,
                            },
                            seeded: None,
                            depends_on: jsonl_tail_io::SourceStamps::of(&source, &tail.stamp),
                        });
                    }
                    codex_history_graph::CodexTailRefresh::Extended {
                        observed_tail,
                        mapping,
                    } => {
                        let range_start = raw_range_pin
                            .start_byte_offset
                            .min(mapping.consumed_byte_offset);
                        // Re-prove the accepted-to-current interval. Bytes at
                        // or past the tail window are already trusted from
                        // the fold; an earlier range start needs one bounded
                        // range read whose overlap with the window must match
                        // byte-for-byte, else the file raced and the
                        // observation fails closed.
                        let mut depends_on = jsonl_tail_io::SourceStamps::of(&source, &tail.stamp);
                        let range_bytes = if range_start >= tail.window_offset {
                            tail.bytes[(range_start - tail.window_offset) as usize
                                ..(mapping.consumed_byte_offset - tail.window_offset) as usize]
                                .to_vec()
                        } else {
                            let (range, range_stamp) = match jsonl_tail_io::read_range(
                                &source,
                                range_start,
                                mapping.consumed_byte_offset,
                            ) {
                                Ok(range) => range,
                                Err(_) => {
                                    return Ok(ProviderLocalObservation {
                                        observation: LocalTailObservation {
                                            push_reuse: None,
                                            subagents: None,
                                            discovery: if previous_discovery.is_some() {
                                                Some(codex_subagents::DiscoveryObservation {
                                                    mapping: mapping.clone(),
                                                    stamp: tail.stamp.clone(),
                                                    creations: creations.clone(),
                                                })
                                            } else {
                                                None
                                            },
                                            evidence: TailSideEvidence::Invalid,
                                            raw_range_pin: None,
                                            verified_acceptance: None,
                                            edited_since_acceptance: false,
                                        },
                                        seeded: None,
                                        depends_on: Default::default(),
                                    })
                                }
                            };
                            // A second read of the same file: under another
                            // stamp the outcome serves this review and is
                            // not retained.
                            depends_on.record(&source, &range_stamp);
                            let overlap_from = (tail.window_offset - range_start) as usize;
                            let trusted = &tail.bytes
                                [..(mapping.consumed_byte_offset - tail.window_offset) as usize];
                            if &range[overlap_from..] != trusted {
                                return Ok(ProviderLocalObservation {
                                    observation: LocalTailObservation {
                                        push_reuse: None,
                                        subagents: None,
                                        discovery: if previous_discovery.is_some() {
                                            Some(codex_subagents::DiscoveryObservation {
                                                mapping: mapping.clone(),
                                                stamp: tail.stamp.clone(),
                                                creations: creations.clone(),
                                            })
                                        } else {
                                            None
                                        },
                                        evidence: TailSideEvidence::Invalid,
                                        raw_range_pin: None,
                                        verified_acceptance: None,
                                        edited_since_acceptance: false,
                                    },
                                    seeded: None,
                                    depends_on: Default::default(),
                                });
                            }
                            range
                        };
                        mallard_infrastructure::sync_metrics::record_bytes_hashed(
                            &source,
                            range_bytes.len() as u64,
                        );
                        let pin = RawRangePin {
                            start_byte_offset: range_start,
                            end_byte_offset: mapping.consumed_byte_offset,
                            range_sha256: hex_digest(Sha256::digest(&range_bytes).as_slice()),
                        };
                        return Ok(ProviderLocalObservation {
                            observation: LocalTailObservation {
                                push_reuse: None,
                                subagents: None,
                                discovery: if previous_discovery.is_some() {
                                    Some(codex_subagents::DiscoveryObservation {
                                        mapping: mapping.clone(),
                                        stamp: tail.stamp.clone(),
                                        creations: creations.clone(),
                                    })
                                } else {
                                    None
                                },
                                evidence: TailSideEvidence::Present(observed_tail.clone()),
                                raw_range_pin: Some(pin.clone()),
                                verified_acceptance: None,
                                edited_since_acceptance: false,
                            },
                            seeded: Some(SeededCursor {
                                root: CodexSeededRoot {
                                    layout: layout.clone(),
                                    observed_tail,
                                    prefix_witness: checkpoint.prefix_witness.clone(),
                                    mapping,
                                    lineage_digest: String::new(),
                                    semantic_digest: String::new(),
                                },
                                source: tail.stamp.clone(),
                            }),
                            depends_on,
                        });
                    }
                    codex_history_graph::CodexTailRefresh::NeedsFullResolve => {}
                    codex_history_graph::CodexTailRefresh::Invalid { .. } => {
                        return Ok(ProviderLocalObservation {
                            observation: LocalTailObservation {
                                push_reuse: None,
                                subagents: None,
                                discovery: None,
                                evidence: TailSideEvidence::Invalid,
                                raw_range_pin: None,
                                verified_acceptance: None,
                                edited_since_acceptance: false,
                            },
                            seeded: None,
                            depends_on: Default::default(),
                        });
                    }
                }
            }
        }
    }

    // First contact or unusable cursor: fully resolve and seed.
    let (resolved, sources) = match (match (reviewed_roots, local.captured.as_ref()) {
        (Some(_), Some(captured)) => Ok((
            captured.transcript.bytes.clone(),
            captured
                .transcript
                .source_stamp
                .clone()
                .ok_or("captured Codex source stamp is missing")?,
        )),
        _ => jsonl_tail_io::read_snapshot(&source).map(|(bytes, stamp)| (bytes.into(), stamp)),
    })
    .and_then(|(bytes, stamp)| {
        codex_history_graph::resolve_captured_codex_root(&source, bytes, stamp, &lookup)
    }) {
        Ok(resolved) => resolved,
        Err(_) => {
            return Ok(ProviderLocalObservation {
                observation: LocalTailObservation {
                    push_reuse: None,
                    subagents: None,
                    discovery: None,
                    evidence: TailSideEvidence::Invalid,
                    raw_range_pin: None,
                    verified_acceptance: None,
                    edited_since_acceptance: false,
                },
                seeded: None,
                depends_on: Default::default(),
            })
        }
    };
    // The stored layout stays authoritative — including a paginated layout
    // imported at Pull install over a null-base file; a derivation that
    // cannot agree with it is corruption, never a reseed.
    let Ok((effective_kind, effective_start)) =
        codex_history_graph::effective_tail_partition(layout, &resolved)
    else {
        return Ok(ProviderLocalObservation {
            observation: LocalTailObservation {
                push_reuse: None,
                subagents: None,
                discovery: None,
                evidence: TailSideEvidence::Invalid,
                raw_range_pin: None,
                verified_acceptance: None,
                edited_since_acceptance: false,
            },
            seeded: None,
            depends_on: Default::default(),
        });
    };
    // First-contact adoption (§6.4): encode the local thread under its own
    // binding root and compare the wire fold at the cloud pin's recorded
    // end. Equality proves the cloud version is a prefix of local and
    // re-establishes the dual pins; any failure — including a root the
    // encoder refuses (non-POSIX or path-map control namespace collision)
    // — leaves the pair unproven and blocked.
    let origins = if adoption_probe.is_some() {
        load_source_path_origins(
            repository,
            &repository.load_conversation_bindings()?,
            project,
            profile_id,
            resolved
                .segments
                .iter()
                .map(|segment| segment.provider_thread_id.as_str()),
        )?
    } else {
        PathOrigins::default()
    };
    let verified_acceptance = adoption_probe.and_then(|probe| {
        adopt_codex_acceptance(
            &resolved,
            probe,
            effective_kind,
            effective_start,
            layout,
            project_root,
            canonical_project_root,
            &origins,
            stored_redaction,
        )
    });
    let (leaf_bytes, leaf_stamp) = sources.get(&source).ok_or("main snapshot is missing")?;
    let seeded = codex_history_graph::seed_codex_root(&resolved, &leaf_bytes, layout)?;
    if checkpoint
        .and_then(|checkpoint| checkpoint.prefix_witness.as_ref())
        .is_some_and(|stored| seeded.prefix_witness.as_ref() != Some(stored))
    {
        return Ok(ProviderLocalObservation {
            observation: LocalTailObservation {
                push_reuse: None,
                subagents: None,
                discovery: None,
                evidence: TailSideEvidence::Invalid,
                raw_range_pin: None,
                verified_acceptance: None,
                edited_since_acceptance: false,
            },
            seeded: None,
            depends_on: Default::default(),
        });
    }
    let accepted_start = checkpoint
        .and_then(|checkpoint| match &checkpoint.physical {
            PhysicalMappingState::Ready { raw_range_pin, .. } => {
                Some(raw_range_pin.start_byte_offset)
            }
            PhysicalMappingState::Detached { .. } => None,
        })
        .unwrap_or(0)
        .min(seeded.mapping.consumed_byte_offset);
    let pin = RawRangePin {
        start_byte_offset: accepted_start,
        end_byte_offset: seeded.mapping.consumed_byte_offset,
        range_sha256: hex_digest(
            Sha256::digest(
                &leaf_bytes[accepted_start as usize..seeded.mapping.consumed_byte_offset as usize],
            )
            .as_slice(),
        ),
    };
    let leaf = resolved
        .segments
        .last()
        .ok_or("resolved Codex root has no segments")?;
    let edited = edited_since_acceptance(
        repository,
        checkpoint.and_then(|checkpoint| checkpoint.accepted_local_tail.as_ref()),
        local.binding.as_ref(),
        &resolved.chain,
        AcceptedRecords {
            records_of: &leaf.rollout_id,
            length_of: &leaf.provider_thread_id,
            complete: &leaf_bytes[..leaf.consumed_byte_len as usize],
        },
    );
    let outcome = ProviderLocalObservation {
        observation: LocalTailObservation {
            // An edited session is never published and saves no cursor: the
            // next comparison reads it in full again.
            push_reuse: (!edited).then(|| PushObservationEvidence {
                seeded: seeded.clone(),
                layout: layout.cloned(),
                sources: sources
                    .iter()
                    .map(|(path, (_, stamp))| (path.clone(), stamp.clone()))
                    .collect(),
                conversation_limit: conversation_file_limit_bytes(),
            }),
            subagents: None,
            discovery: Some(codex_subagents::DiscoveryObservation {
                mapping: seeded.mapping.clone(),
                stamp: leaf_stamp.clone(),
                creations: resolved.leaf_creations.clone(),
            }),
            evidence: TailSideEvidence::Present(seeded.observed_tail.clone()),
            raw_range_pin: Some(pin),
            verified_acceptance,
            edited_since_acceptance: edited,
        },
        seeded: (!edited).then(|| SeededCursor {
            root: seeded,
            source: leaf_stamp.clone(),
        }),
        depends_on: sources
            .iter()
            .map(|(path, (_, stamp))| (path, stamp))
            .collect(),
    };
    if let Some(roots) = reviewed_roots {
        let mut roots = roots
            .lock()
            .map_err(|_| "Codex review snapshot lock failed")?;
        let retained: u64 = roots
            .values()
            .flat_map(|(_, sources)| sources.values())
            .map(|(bytes, _)| bytes.len() as u64)
            .sum();
        let size: u64 = sources.values().map(|(bytes, _)| bytes.len() as u64).sum();
        if retained.saturating_add(size) > provider_capture::MAX_CAPTURE_BYTES {
            return Err("Codex review exceeds the aggregate capture limit".into());
        }
        roots.insert(source, (resolved, sources));
    }
    Ok(outcome)
}

/// The Claude adoption refold: the cloud pin folds the **redacted wire
/// form**, so the probe is compared against the wire chain — the redacted
/// re-analysis of the same local slice — never against the local fold. The
/// re-established local pin folds the local chain at the same recorded end;
/// cross-form layout equality (identical identities and counts, guaranteed
/// by the per-record content-only encoder) is what makes the shared end
/// coordinate meaningful. Equality proves the cloud version is a prefix of
/// local and re-establishes the dual acceptance pins.
fn adopt_claude_acceptance(
    chain: &[mallard_domain::CanonicalConversationMessage],
    wire_chain: &[mallard_domain::CanonicalConversationMessage],
    probe: &PortableConversationTail,
) -> Option<VerifiedAdoption> {
    if probe.codec != mallard_domain::CLAUDE_PORTABLE_TAIL_CODEC_WIRE_V1
        || probe.partition_kind != TailPartitionKind::WholeThread
        || probe.start_record_count != 0
        || probe.accepted_end_record_count > chain.len() as u64
        || wire_chain.len() != chain.len()
    {
        return None;
    }
    let wire_state = mallard_domain::compute_conversation_tail_state(
        TailPartitionKind::WholeThread,
        0,
        probe.accepted_end_record_count,
        wire_chain,
    )
    .ok()?;
    if wire_state != probe.accepted_tail_state {
        return None;
    }
    let local_state = mallard_domain::compute_conversation_tail_state(
        TailPartitionKind::WholeThread,
        0,
        probe.accepted_end_record_count,
        chain,
    )
    .ok()?;
    let local_tail = PortableConversationTail {
        codec: mallard_domain::CLAUDE_PORTABLE_TAIL_CODEC_V1.to_string(),
        partition_kind: TailPartitionKind::WholeThread,
        start_record_count: 0,
        accepted_end_record_count: probe.accepted_end_record_count,
        accepted_tail_state: local_state,
    };
    local_tail.validate().ok()?;
    Some(VerifiedAdoption {
        wire_tail: probe.clone(),
        local_tail,
    })
}

/// Derive local Claude evidence: ride the checkpoint cursor when it is
/// valid, degrade every non-fast-path outcome to one bounded full
/// re-analyze, and seed first-contact state. Unlike Codex — whose paginated
/// rollouts are contractually append-only, making a violated cursor
/// contract evidence of corruption — Claude files legitimately rewind,
/// re-root mid-file, and re-emit records, so `NeedsFullResolve` and
/// `Invalid` cursor outcomes both take the full path, whose conclusion is
/// exactly what an authoritative full capture would produce.
fn observe_claude_local(
    local: Option<&LocalThreadReview>,
    previous: Option<&claude_subagents::TreeObservation>,
    checkpoint: Option<&ConversationCheckpoint>,
    layout: Option<&RootTailLayout>,
    adoption_probe: Option<&PortableConversationTail>,
    repository: &LocalStateRepository,
    project: &ProjectBinding,
    profile_id: &LocalProviderProfileId,
    stored_redaction: Option<&mallard_domain::ConversationWireRedaction>,
) -> Result<ProviderLocalObservation, String> {
    let project_root = project.project_root.as_str();
    let canonical_project_root = project.canonical_project_root.as_str();
    let invalid = || ProviderLocalObservation {
        observation: LocalTailObservation {
            push_reuse: None,
            subagents: None,
            discovery: None,
            evidence: TailSideEvidence::Invalid,
            raw_range_pin: None,
            verified_acceptance: None,
            edited_since_acceptance: false,
        },
        seeded: None,
        depends_on: Default::default(),
    };
    let Some(local) = local else {
        return Ok(ProviderLocalObservation {
            observation: LocalTailObservation {
                push_reuse: None,
                subagents: None,
                discovery: None,
                evidence: TailSideEvidence::ConfirmedAbsent,
                raw_range_pin: None,
                verified_acceptance: None,
                edited_since_acceptance: false,
            },
            seeded: None,
            depends_on: Default::default(),
        });
    };
    let source = local.source_path.clone();

    let stamp = jsonl_tail_io::SourceStamp::read(&source)?;
    let previous =
        previous.filter(|tree| tree.main.mapping.provider_thread_id == local.provider_thread_id);
    let mut links = previous
        .map(|tree| tree.main.links.clone())
        .unwrap_or_default();
    let finish = |mut outcome: ProviderLocalObservation,
                  links: claude_subagents::ChildLinks|
     -> Result<ProviderLocalObservation, String> {
        if !matches!(outcome.observation.evidence, TailSideEvidence::Present(_)) {
            return Ok(outcome);
        }
        stamp.verify(&source)?;
        let mapping = outcome
            .seeded
            .as_ref()
            .map(|seeded| &seeded.root.mapping)
            .or_else(|| {
                checkpoint.and_then(|checkpoint| match &checkpoint.physical {
                    PhysicalMappingState::Ready { root_mapping, .. } => Some(root_mapping),
                    _ => None,
                })
            })
            .ok_or("Claude child discovery lacks its parent mapping")?
            .clone();
        let Ok(tree) = claude_subagents::observe_tree(
            claude_subagents::MainObservation { mapping, links },
            local.binding.as_ref(),
            previous,
        ) else {
            // Keep the proven parent; None remains unproven child evidence.
            return Ok(outcome);
        };
        outcome.depends_on.extend(&tree.dependencies);
        outcome.observation.subagents = Some(owned_subagents::TreeObservation::Claude(tree));
        Ok(outcome)
    };

    let mut cold_bytes = None;
    // A valid Ready checkpoint under a matching layout rides the cursor on
    // the file it was saved from, untouched or grown since. Any other file
    // state, and a cursor saved without one, takes the full path: the
    // content decides, never the stamp. An adoption probe needs the
    // canonical chain and takes the full path as well.
    if let (Some(checkpoint), Some(layout), None) = (checkpoint, layout, adoption_probe) {
        if let PhysicalMappingState::Ready {
            root_mapping,
            raw_range_pin,
            source_state: Some(saved),
        } = &checkpoint.physical
        {
            if layout.matches(&checkpoint.observed_tail)
                && root_mapping.root_path == source.to_string_lossy()
                && stamp.continues(saved)
            {
                if previous.is_none() {
                    let bytes = jsonl_tail_io::read_bounded(&source)?;
                    let complete = jsonl_tail_io::safe_record_end(&bytes) as usize;
                    links = claude_subagents::collect_main_links(
                        &bytes[..complete],
                        &local.provider_thread_id,
                    )?;
                    mallard_infrastructure::sync_metrics::record_records_parsed(
                        &source,
                        bytes[..complete].iter().filter(|b| **b == b'\n').count() as u64,
                    );
                    cold_bytes = Some(bytes);
                }
                // Any failed read or non-linear outcome falls through to the
                // bounded full re-analyze below instead of reporting Invalid
                // evidence (D3a).
                if let Ok(tail) = jsonl_tail_io::read_tail_window(&source, root_mapping) {
                    match claude_subagents::refresh_main(
                        layout,
                        &checkpoint.observed_tail,
                        root_mapping,
                        &tail,
                        &mut links,
                    )? {
                        claude_history_tail::ClaudeTailRefresh::Unchanged => {
                            return finish(
                                ProviderLocalObservation {
                                    observation: LocalTailObservation {
                                        push_reuse: None,
                                        subagents: None,
                                        discovery: None,
                                        evidence: TailSideEvidence::Present(
                                            checkpoint.observed_tail.clone(),
                                        ),
                                        raw_range_pin: Some(raw_range_pin.clone()),
                                        verified_acceptance: None,
                                        edited_since_acceptance: false,
                                    },
                                    seeded: None,
                                    depends_on: jsonl_tail_io::SourceStamps::of(&source, &stamp),
                                },
                                links,
                            );
                        }
                        claude_history_tail::ClaudeTailRefresh::Extended {
                            observed_tail,
                            mapping,
                        } => {
                            // Re-prove the accepted-to-current interval,
                            // exactly as the Codex cursor does; a raced
                            // range read degrades to the full path.
                            let range_start = raw_range_pin
                                .start_byte_offset
                                .min(mapping.consumed_byte_offset);
                            let range_bytes = if range_start >= tail.window_offset {
                                Some(
                                    tail.bytes[(range_start - tail.window_offset) as usize
                                        ..(mapping.consumed_byte_offset - tail.window_offset)
                                            as usize]
                                        .to_vec(),
                                )
                            } else {
                                match jsonl_tail_io::read_range(
                                    &source,
                                    range_start,
                                    mapping.consumed_byte_offset,
                                ) {
                                    Ok((range, _)) => {
                                        let overlap_from =
                                            (tail.window_offset - range_start) as usize;
                                        let trusted = &tail.bytes[..(mapping.consumed_byte_offset
                                            - tail.window_offset)
                                            as usize];
                                        (&range[overlap_from..] == trusted).then_some(range)
                                    }
                                    Err(_) => None,
                                }
                            };
                            if let Some(range_bytes) = range_bytes {
                                mallard_infrastructure::sync_metrics::record_bytes_hashed(
                                    &source,
                                    range_bytes.len() as u64,
                                );
                                let pin = RawRangePin {
                                    start_byte_offset: range_start,
                                    end_byte_offset: mapping.consumed_byte_offset,
                                    range_sha256: hex_digest(
                                        Sha256::digest(&range_bytes).as_slice(),
                                    ),
                                };
                                return finish(
                                    ProviderLocalObservation {
                                        observation: LocalTailObservation {
                                            push_reuse: None,
                                            subagents: None,
                                            discovery: None,
                                            evidence: TailSideEvidence::Present(
                                                observed_tail.clone(),
                                            ),
                                            raw_range_pin: Some(pin),
                                            verified_acceptance: None,
                                            edited_since_acceptance: false,
                                        },
                                        seeded: Some(SeededCursor {
                                            root: CodexSeededRoot {
                                                layout: layout.clone(),
                                                observed_tail,
                                                prefix_witness: None,
                                                mapping,
                                                lineage_digest: String::new(),
                                                semantic_digest: String::new(),
                                            },
                                            source: stamp.clone(),
                                        }),
                                        depends_on: jsonl_tail_io::SourceStamps::of(
                                            &source, &stamp,
                                        ),
                                    },
                                    links,
                                );
                            }
                        }
                        claude_history_tail::ClaudeTailRefresh::NeedsFullResolve
                        | claude_history_tail::ClaudeTailRefresh::Invalid { .. } => {}
                    }
                }
            }
        }
    }

    // Full path: one bounded read plus one full analyze of the complete
    // records — one Claude file is the whole root, so there is no graph to
    // resolve.
    mallard_infrastructure::sync_metrics::record_full_graph_resolve(&source);
    let Ok(bytes) = cold_bytes
        .map(Ok)
        .unwrap_or_else(|| jsonl_tail_io::read_bounded(&source))
    else {
        return Ok(invalid());
    };
    let consumed = jsonl_tail_io::safe_record_end(&bytes) as usize;
    if consumed == 0 {
        return Ok(invalid());
    }
    let (analysis, watermark) =
        claude_subagents::analyze_main(&bytes[..consumed], &local.provider_thread_id, &mut links)?;
    let CodecLineage::Complete { chain, .. } = &analysis.lineage else {
        return Ok(invalid());
    };
    // A stored layout must equal the native Claude derivation (WholeThread
    // at zero under the Claude local codec); any other stored layout is
    // corruption, never a reseed.
    if layout.is_some_and(|layout| {
        layout.codec != mallard_domain::CLAUDE_PORTABLE_TAIL_CODEC_V1
            || layout.partition_kind != TailPartitionKind::WholeThread
            || layout.start_record_count != 0
    }) {
        return Ok(invalid());
    }
    let origins = if adoption_probe.is_some() {
        load_source_path_origins(
            repository,
            &repository.load_conversation_bindings()?,
            project,
            profile_id,
            std::iter::once(local.provider_thread_id.as_str()),
        )?
    } else {
        PathOrigins::default()
    };
    let verified_acceptance = adoption_probe.and_then(|probe| {
        // The probe folds the published wire form — `redact(pathenc(x))` —
        // so the analyzed local slice runs the same pure composition the
        // push uses before the wire-vs-wire comparison. Any failure leaves
        // the pair unproven — adoption is a fast path, never a correctness
        // requirement.
        let mapper = SessionPathMapper::new(
            project_root,
            (canonical_project_root != project_root).then_some(canonical_project_root),
            mallard_infrastructure::session_path_map::home_dir_text().as_deref(),
        )
        .ok()?;
        let text = std::str::from_utf8(&bytes[..consumed]).ok()?;
        let mut encoded = String::with_capacity(text.len());
        let mut ordinal = 0;
        for (index, line) in text.split('\n').enumerate() {
            if index > 0 {
                encoded.push('\n');
            }
            if line.trim().is_empty() {
                encoded.push_str(line);
                continue;
            }
            let record = serde_json::from_str(line).ok()?;
            let mapped = mapper
                .encode_record_with_origins(
                    &record,
                    origins.record(&local.provider_thread_id, ordinal),
                )
                .ok()?;
            encoded.push_str(&serde_json::to_string(&mapped.wire).ok()?);
            ordinal += 1;
        }
        origins
            .verify_source_length(&local.provider_thread_id, ordinal, false)
            .ok()?;
        let (redacted, _changed_lines) = credential_redaction::shared()
            .run_from_stamp(stored_redaction)
            .ok()?
            .redact_jsonl_text(&encoded)
            .ok()?;
        let wire_analysis = mallard_infrastructure::providers::claude::analyze_claude_transcript(
            redacted.as_bytes(),
        );
        let wire_chain = wire_analysis.lineage.chain()?;
        adopt_claude_acceptance(chain, wire_chain, probe)
    });
    let Some(seeded) = claude_history_tail::seed_claude_root_with_watermark(
        &source,
        &bytes[..consumed],
        &analysis,
        watermark,
    )?
    else {
        // Unreachable in practice: the analyzed slice ends at a record
        // boundary by construction.
        return Ok(invalid());
    };
    let accepted_start = checkpoint
        .and_then(|checkpoint| match &checkpoint.physical {
            PhysicalMappingState::Ready { raw_range_pin, .. } => {
                Some(raw_range_pin.start_byte_offset)
            }
            PhysicalMappingState::Detached { .. } => None,
        })
        .unwrap_or(0)
        .min(seeded.mapping.consumed_byte_offset);
    let pin = RawRangePin {
        start_byte_offset: accepted_start,
        end_byte_offset: seeded.mapping.consumed_byte_offset,
        range_sha256: hex_digest(
            Sha256::digest(
                &bytes[accepted_start as usize..seeded.mapping.consumed_byte_offset as usize],
            )
            .as_slice(),
        ),
    };
    let edited = edited_since_acceptance(
        repository,
        checkpoint.and_then(|checkpoint| checkpoint.accepted_local_tail.as_ref()),
        local.binding.as_ref(),
        chain,
        AcceptedRecords {
            records_of: &local.provider_thread_id,
            length_of: &local.provider_thread_id,
            complete: &bytes[..consumed],
        },
    );
    let mut outcome = finish(
        ProviderLocalObservation {
            observation: LocalTailObservation {
                push_reuse: Some(PushObservationEvidence {
                    seeded: CodexSeededRoot {
                        layout: seeded.layout.clone(),
                        observed_tail: seeded.observed_tail.clone(),
                        prefix_witness: None,
                        mapping: seeded.mapping.clone(),
                        lineage_digest: seeded.lineage_digest.clone(),
                        semantic_digest: seeded.semantic_digest.clone(),
                    },
                    layout: layout.cloned(),
                    sources: BTreeMap::from([(source.clone(), stamp.clone())]),
                    conversation_limit: conversation_file_limit_bytes(),
                }),
                subagents: None,
                discovery: None,
                evidence: TailSideEvidence::Present(seeded.observed_tail.clone()),
                raw_range_pin: Some(pin),
                verified_acceptance,
                edited_since_acceptance: edited,
            },
            seeded: Some(SeededCursor {
                root: CodexSeededRoot {
                    layout: seeded.layout,
                    observed_tail: seeded.observed_tail,
                    prefix_witness: None,
                    mapping: seeded.mapping,
                    lineage_digest: seeded.lineage_digest,
                    semantic_digest: seeded.semantic_digest,
                },
                source: stamp.clone(),
            }),
            depends_on: jsonl_tail_io::SourceStamps::of(&source, &stamp),
        },
        links,
    )?;
    if edited {
        // The child tree above is read from this mapping. An edited session
        // is never published and saves no cursor: the next comparison reads
        // it in full again.
        outcome.seeded = None;
        outcome.observation.push_reuse = None;
    }
    Ok(outcome)
}

#[allow(clippy::too_many_arguments)]
fn provider_thread_review(
    repository: &LocalStateRepository,
    snapshot: Option<&BundleSnapshot>,
    mainline: &Mainline,
    bytes: &mut dyn BundleBytes,
    views: &[provider_capture::LocalSessionView],
    captured: &provider_capture::CapturedResources,
    candidate_pins: &BTreeMap<String, TargetExpectation>,
    resolved: &ResolvedBinding,
    provider: &ProviderKey,
    provider_home: &Path,
    storage_id: Option<&StorageId>,
    created_at: u64,
    expires_at: u64,
    purpose: ReviewPurpose,
    resource_filter: Option<&BTreeSet<ResourceId>>,
    settings: &AppSettings,
) -> Result<ThreadReview, String> {
    let credential_redaction_enabled = settings.credential_redaction_enabled;
    let binding = &resolved.binding;
    let adapter = provider_registry().require(provider)?;
    let provider_label = provider_registry()
        .get(provider)
        .map(|registered| registered.descriptor().display_name)
        .unwrap_or_else(|| provider.to_string());
    let profile_id = binding.profile_ids.get(provider).cloned().ok_or_else(|| {
        format!(
            "{} conversations require a mapped {} profile",
            provider_label, provider_label
        )
    })?;
    let reconstructs_graph = adapter.reconstructs_rollout_graph();
    let local_only_children_kept = adapter.update_keeps_local_only_children();
    let supports_cursor = adapter.supports_tail_cursor();
    let (pinned_scope_revision, pinned_scope_sha256) = provider_scope_pin(snapshot, provider);
    let domain_resources = provider_capture::domain_resources(captured)?;
    let provider_scope = snapshot.and_then(|snapshot| snapshot.manifest.provider_scope(provider));

    let build_local_threads = |state: &LocalProjectActivityStateSnapshot| -> Result<
        (BTreeMap<ThreadId, LocalThreadReview>, BTreeSet<String>),
        String,
    > {
        if state.bindings.active_for(&binding.local_project_id) != Some(binding)
            || state.host_identity.host_id != binding.host_id
            || !state.bindings.profiles.iter().any(|profile| {
                profile.profile_id == profile_id
                    && &profile.provider == provider
                    && Path::new(&profile.canonical_path) == provider_home
            })
        {
            return Err("project binding changed; refresh before continuing".to_string());
        }
        let historical_alias_owners = if reconstructs_graph {
            applied_provider_alias_owners(&state.materializations, binding, provider, &profile_id)
        } else {
            BTreeMap::new()
        };
        let scoped = state
            .conversation_bindings
            .bindings
            .iter()
            .filter(|conversation| {
                conversation.host_id == binding.host_id
                    && conversation.replica_id == binding.replica_id
                    && conversation.local_project_id == binding.local_project_id
                    && conversation.provider_profile_id == profile_id
            })
            .cloned()
            .collect::<Vec<_>>();
        let by_provider = scoped
            .iter()
            .filter_map(|conversation| {
                conversation
                    .provider_thread_id
                    .as_ref()
                    .map(|provider_id| (provider_id.clone(), conversation.clone()))
            })
            .collect::<BTreeMap<_, _>>();
        let mut local_threads = BTreeMap::<ThreadId, LocalThreadReview>::new();
        let mut suppressed_provider_ids = BTreeSet::new();
        // Every local row starts from bounded discovery metadata; captured
        // bytes attach when a capture selected the session. Identity comes
        // from the captured analysis when bytes are present (the stricter
        // reading) and from the bounded head scan otherwise.
        for view in views {
            if &view.provider != provider || view.descriptor.blocked_reason.is_some() {
                continue;
            }
            if resource_filter.is_some_and(|selected| {
                ResourceId::parse(view.descriptor.resource_id.clone())
                    .map(|resource_id| !selected.contains(&resource_id))
                    .unwrap_or(true)
            }) {
                continue;
            }
            let resource_id_text = view.descriptor.resource_id.as_str();
            let captured_thread = captured
                .conversations
                .get(resource_id_text)
                .map(|conversation| -> Result<CapturedThread, String> {
                    let transcript = captured
                        .files
                        .get(&conversation.transcript_logical_path)
                        .cloned()
                        .ok_or_else(|| {
                            format!(
                                "captured conversation '{}' has no transcript payload",
                                resource_id_text
                            )
                        })?;
                    Ok(CapturedThread {
                        conversation: conversation.clone(),
                        transcript,
                    })
                })
                .transpose()?;
            let provider_thread_id = match &captured_thread {
                Some(captured_thread) => captured_thread
                    .conversation
                    .source_thread_id
                    .clone()
                    .ok_or_else(|| {
                        format!(
                            "captured {} conversation lacks an active session id",
                            provider_label
                        )
                    })?,
                None => view.provider_thread_id.clone(),
            };
            let local_binding = by_provider.get(&provider_thread_id).cloned();
            let (logical_thread_id, binding_resolution) = match &local_binding {
                Some(local_binding) => (local_binding.thread_id.clone(), BindingResolution::Bound),
                None => {
                    // Copy-on-write leaves the source provider rollout in
                    // place. It receives a separate, stable local
                    // branch identity: exact checkpoint evidence below hides
                    // it only while its bytes remain unchanged. If Codex later
                    // appends to the retained entry, that same identity becomes
                    // ordinary reviewable local work instead of colliding with
                    // the logical thread that moved to a fresh alias.
                    let displaced_owners = displaced_provider_alias_owners(
                        &binding.bundle_id,
                        provider,
                        &provider_thread_id,
                        &scoped,
                        &historical_alias_owners,
                    )?;
                    if !displaced_owners.is_empty() {
                        let (retained_thread_id, unchanged) =
                            project_activity::retained_provider_alias_identity(
                                &binding.bundle_id,
                                &binding.local_project_id,
                                provider,
                                &provider_thread_id,
                                &view.source_path,
                                &displaced_owners,
                                &scoped
                                    .iter()
                                    .map(|binding| binding.thread_id.clone())
                                    .collect(),
                                &state.config,
                            )?;
                        if unchanged {
                            suppressed_provider_ids.insert(provider_thread_id);
                            continue;
                        }
                        (retained_thread_id, BindingResolution::Missing)
                    } else {
                        // Unbound local conversations publish as fresh threads;
                        // canonical containment does not prove identity.
                        (
                            initial_conversation_thread_id(
                                &binding.bundle_id,
                                provider,
                                &provider_thread_id,
                            )?,
                            BindingResolution::Missing,
                        )
                    }
                }
            };
            if local_threads.contains_key(&logical_thread_id) {
                return Err(format!(
                    "multiple local {} conversations resolve to logical thread '{}'",
                    provider_label, logical_thread_id
                ));
            }
            let resource_id = ResourceId::parse(resource_id_text.to_string())?;
            let descriptor = match domain_resources.get(&resource_id).cloned() {
                Some(descriptor) => Some(descriptor),
                None => Some(provider_capture::domain_resource_descriptor(
                    &view.descriptor,
                    None,
                )?),
            };
            local_threads.insert(
                logical_thread_id.clone(),
                LocalThreadReview {
                    binding: local_binding,
                    binding_resolution,
                    resource_id,
                    descriptor,
                    provider_thread_id,
                    source_path: view.source_path.clone(),
                    source_mtime: view.source_mtime,
                    capture_bytes: view.capture_bytes,
                    captured: captured_thread,
                },
            );
        }
        Ok((local_threads, suppressed_provider_ids))
    };

    // Phase A: first-contact seeding. Bound cursor-provider tasks without a
    // layout are fully parsed once; the immutable layout lands on the
    // binding and the first checkpoint lands on the destination link.
    // Observation-class work: nothing here builds artifacts or touches
    // cloud state.
    if supports_cursor && purpose != ReviewPurpose::Observe {
        let state = repository.load_project_activity_state_snapshot()?;
        let (local_threads, _) = build_local_threads(&state)?;
        let mut seed_candidates: Vec<(ThreadId, ConversationCheckpoint)> = Vec::new();
        for (thread_id, local) in &local_threads {
            let Some(local_binding) = &local.binding else {
                continue;
            };
            if local_binding.root_tail_layout.is_some() {
                continue;
            }
            let source = local.source_path.clone();
            let Ok((leaf_bytes, source_stamp)) = jsonl_tail_io::read_snapshot(&source) else {
                continue;
            };
            let (seeded, raw_range_pin) = if reconstructs_graph {
                let lookup = codex_rollout_lookup(provider_home);
                let leaf_bytes: mallard_infrastructure::payload::PayloadBytes = leaf_bytes.into();
                let Ok((resolved_root, _)) = codex_history_graph::resolve_captured_codex_root(
                    &source,
                    leaf_bytes.clone(),
                    source_stamp.clone(),
                    &lookup,
                ) else {
                    continue;
                };
                let Ok(seeded) =
                    codex_history_graph::seed_codex_root(&resolved_root, &leaf_bytes, None)
                else {
                    continue;
                };
                let consumed = seeded.mapping.consumed_byte_offset;
                let pin = RawRangePin {
                    start_byte_offset: 0,
                    end_byte_offset: consumed,
                    range_sha256: hex_digest(
                        Sha256::digest(&leaf_bytes[..consumed as usize]).as_slice(),
                    ),
                };
                (seeded, pin)
            } else {
                // Claude: one file is the whole root; analyze the complete
                // records and seed from that analysis.
                let bytes = leaf_bytes;
                let consumed = jsonl_tail_io::safe_record_end(&bytes) as usize;
                if consumed == 0 {
                    continue;
                }
                let analysis = mallard_infrastructure::providers::claude::analyze_claude_transcript(
                    &bytes[..consumed],
                );
                let Ok(Some(seeded)) =
                    claude_history_tail::seed_claude_root(&source, &bytes[..consumed], &analysis)
                else {
                    continue;
                };
                (
                    CodexSeededRoot {
                        layout: seeded.layout,
                        observed_tail: seeded.observed_tail,
                        prefix_witness: None,
                        mapping: seeded.mapping,
                        lineage_digest: seeded.lineage_digest,
                        semantic_digest: seeded.semantic_digest,
                    },
                    seeded.raw_range_pin,
                )
            };
            let target_thread = local_binding.thread_id.clone();
            let seeded_layout = seeded.layout.clone();
            let binding_revision = repository.mutate_conversation_bindings(|document| {
                let row = document
                    .bindings
                    .iter_mut()
                    .find(|row| {
                        row.host_id == binding.host_id
                            && row.replica_id == binding.replica_id
                            && row.local_project_id == binding.local_project_id
                            && row.provider_profile_id == profile_id
                            && row.thread_id == target_thread
                    })
                    .ok_or_else(|| "seeded conversation binding disappeared".to_string())?;
                if row.root_tail_layout.is_none() {
                    row.root_tail_layout = Some(seeded_layout.clone());
                    row.revision = row.revision.saturating_add(1);
                    row.updated_at = created_at.max(row.updated_at);
                }
                Ok(row.revision)
            })?;
            if storage_id.is_some() {
                seed_candidates.push((
                    thread_id.clone(),
                    ConversationCheckpoint {
                        accepted_subagents: Default::default(),
                        generation: 0,
                        accepted: None,
                        accepted_local_tail: None,
                        observed_tail: seeded.observed_tail.clone(),
                        physical: PhysicalMappingState::Ready {
                            root_mapping: seeded.mapping.clone(),
                            raw_range_pin,
                            source_state: Some(source_stamp.file_state()),
                        },
                        prefix_witness: seeded.prefix_witness.clone(),
                        binding_revision,
                    },
                ));
            }
        }
        // Every first-contact checkpoint lands through one config
        // transaction: the link is resolved once, an already-present
        // checkpoint is never replaced, and nothing is written when every
        // candidate was already present or the link is gone.
        if let Some(storage_id) = storage_id {
            if !seed_candidates.is_empty() {
                let scope = SyncScopeKey::Provider(provider.clone());
                repository
                    .transact_config(|config| {
                        let Some(link) = config.links.iter_mut().find(|link| {
                            link.local_project_id == binding.local_project_id
                                && &link.storage_id == storage_id
                        }) else {
                            return Ok::<_, String>(ConfigMutation::Unchanged(()));
                        };
                        let threads = link
                            .conversation_checkpoints
                            .entry(scope.clone())
                            .or_default();
                        let mut inserted = false;
                        for (thread_id, checkpoint) in &seed_candidates {
                            if !threads.contains_key(thread_id) {
                                threads.insert(thread_id.clone(), checkpoint.clone());
                                inserted = true;
                            }
                        }
                        if inserted {
                            Ok(ConfigMutation::Changed(()))
                        } else {
                            Ok(ConfigMutation::Unchanged(()))
                        }
                    })
                    .map_err(config_transaction_error)?;
            }
        }
    }

    // Phase B reads one snapshot after seeding. Helpers and plan pins use
    // the same validated documents.
    let state = repository.load_project_activity_state_snapshot()?;
    let machine = &state.bindings;
    let document = &state.conversation_bindings;
    let host_identity = &state.host_identity;
    let config = &state.config;
    let profile = machine
        .profiles
        .iter()
        .find(|profile| profile.profile_id == profile_id)
        .ok_or_else(|| format!("mapped {} profile disappeared", provider_label))?;
    let saved_checkpoints: BTreeMap<ThreadId, ConversationCheckpoint> = storage_id
        .and_then(|storage_id| {
            config
                .links
                .iter()
                .find(|link| {
                    link.local_project_id == binding.local_project_id
                        && &link.storage_id == storage_id
                })
                .and_then(|link| {
                    link.conversation_checkpoints
                        .get(&SyncScopeKey::Provider(provider.clone()))
                        .cloned()
                })
        })
        .unwrap_or_default();
    // The review reads every checkpoint against the selected chain: a stale
    // acceptance is absent for the adoption probe, the evidence and the
    // pins. Only checkpoint maintenance below works on the saved values, so
    // that reading never forgets one.
    let checkpoints: BTreeMap<ThreadId, ConversationCheckpoint> = saved_checkpoints
        .iter()
        .map(|(thread_id, checkpoint)| (thread_id.clone(), checkpoint.read_on(mainline)))
        .collect();
    let (local_threads, suppressed_provider_ids) = build_local_threads(&state)?;
    let bindings_by_thread = document
        .bindings
        .iter()
        .filter(|conversation| {
            conversation.host_id == binding.host_id
                && conversation.replica_id == binding.replica_id
                && conversation.local_project_id == binding.local_project_id
                && conversation.provider_profile_id == profile_id
        })
        .map(|conversation| (conversation.thread_id.clone(), conversation.clone()))
        .collect::<BTreeMap<_, _>>();

    // Review units pair each local row only with the cloud row named by its
    // mapping. Equality across local and cloud ID spaces does not prove
    // identity. Unbound local sessions never match cloud rows, and unclaimed
    // cloud rows use their own cloud IDs as cloud-only review units.
    let all_local_unit_ids = bindings_by_thread
        .keys()
        .cloned()
        .chain(local_threads.keys().cloned())
        .collect::<BTreeSet<_>>();
    let mut claimed = BTreeSet::new();
    for row in bindings_by_thread.values() {
        if let Some(cloud_thread_id) = &row.cloud_thread_id {
            // Document validation makes a duplicate claim unreachable; this
            // is a defensive review error, never a silent fold.
            if !claimed.insert(cloud_thread_id.clone()) {
                return Err(format!(
                    "cloud thread '{}' is claimed by multiple local conversations",
                    cloud_thread_id
                ));
            }
        }
    }
    let units = all_local_unit_ids
        .iter()
        .map(|thread_id| {
            (
                Some(thread_id.clone()),
                bindings_by_thread
                    .get(thread_id)
                    .and_then(|row| row.cloud_thread_id.clone()),
            )
        })
        .chain(
            provider_scope
                .into_iter()
                .flat_map(|scope| scope.conversations.keys())
                .filter(|cloud_thread_id| !claimed.contains(*cloud_thread_id))
                .map(|cloud_thread_id| (None, Some(cloud_thread_id.clone()))),
        )
        .filter(|(local_thread_id, cloud_thread_id)| {
            resource_filter.is_none_or(|selected| {
                local_thread_id
                    .as_ref()
                    .and_then(|thread_id| local_threads.get(thread_id))
                    .is_some_and(|local| selected.contains(&local.resource_id))
                    || cloud_thread_id
                        .as_ref()
                        .and_then(|thread_id| {
                            provider_scope.and_then(|scope| scope.conversations.get(thread_id))
                        })
                        .is_some_and(|thread| selected.contains(&thread.resource_id))
            })
        })
        .collect::<Vec<(Option<ThreadId>, Option<CloudThreadId>)>>();
    let local_unit_ids = units
        .iter()
        .filter_map(|(thread_id, _)| thread_id.clone())
        .collect::<BTreeSet<_>>();

    // The only payload reads planning performs: Pull opens the transcripts
    // of threads it could offer to materialize locally in one batched
    // prefetch, to refuse stored internal-subagent rollouts before review.
    let mut offerable_cloud_transcripts = BTreeMap::new();
    if purpose.builds_pull_plan() {
        for (thread_id, thread) in provider_scope
            .into_iter()
            .flat_map(|scope| scope.conversations.iter())
            .filter(|(thread_id, _)| !claimed.contains(*thread_id))
            .filter(|(_, thread)| {
                resource_filter.is_none_or(|selected| selected.contains(&thread.resource_id))
            })
        {
            let Some(entry) = thread
                .files
                .iter()
                .find(|file| file.role == ConversationFileRole::Transcript)
                .and_then(|file| {
                    provider_scope
                        .and_then(|scope| scope.files.get(&file.logical_path))
                        .map(|entry| (file.logical_path.clone(), entry.sha256.clone(), entry.size))
                })
            else {
                continue;
            };
            offerable_cloud_transcripts.insert(thread_id.clone(), entry);
        }
        let prefetch_paths = offerable_cloud_transcripts
            .values()
            .filter(|(_, _, size)| *size <= conversation_file_limit_bytes())
            .map(|(logical_path, _, _)| logical_path.clone())
            .collect::<Vec<_>>();
        let _ = bytes.prefetch(&prefetch_paths);
    }
    let index_path =
        (adapter.index_fragment_limit() > 0).then(|| provider_home.join("session_index.jsonl"));
    let index_expectation = match (purpose.builds_pull_plan(), &index_path) {
        (true, Some(path)) => Some(bounded_file_expectation(path)?),
        _ => None,
    };
    let child_lookup = RolloutLookup::new(provider_home);
    let reviewed_roots = std::sync::Mutex::new(ReviewedCodexRoots::new());
    let mut entries = Vec::new();
    let mut push_actions = Vec::new();
    let mut pull_actions = Vec::new();
    let mut pull_review = Vec::new();
    let (pinned_revision, pinned_commit_id, pinned_manifest_sha256) = snapshot
        .map(|snapshot| {
            (
                snapshot.head.revision,
                snapshot.head.commit_id.clone(),
                snapshot.head.manifest_sha256.clone(),
            )
        })
        .unwrap_or_else(absent_bundle_head_pin);

    // Cursor-provider local observation is the one expensive Phase B stage —
    // full resolves on first contact, adoption probes, and imported layouts. It
    // is pure per-thread filesystem work, so it runs through the bounded
    // worker pool; everything consuming the results below (evidence
    // upgrades, classification, decisions, plan pins) stays serial and
    // looks the observations up by thread ID, so worker count never changes
    // the review's output. A thread whose observation fails keeps its own
    // error: its row is blocked with that message below, and neither the
    // other threads nor the provider as a whole are affected.
    let mut cursor_observations: BTreeMap<ThreadId, LocalTailObservation> = BTreeMap::new();
    let mut cursor_refreshed: BTreeMap<ThreadId, SeededCursor> = BTreeMap::new();
    let mut cursor_deps: BTreeMap<ThreadId, jsonl_tail_io::SourceStamps> = BTreeMap::new();
    let mut observation_failures: BTreeMap<ThreadId, String> = BTreeMap::new();
    if supports_cursor {
        let observation_tasks: Vec<_> = local_unit_ids
            .iter()
            .filter_map(|thread_id| {
                let local = local_threads.get(thread_id);
                let local_binding = local
                    .and_then(|local| local.binding.as_ref())
                    .or_else(|| bindings_by_thread.get(thread_id));
                let expected_local_missing = local.is_none()
                    && local_binding.is_some_and(|binding| binding.provider_thread_id.is_some());
                if expected_local_missing {
                    return None;
                }
                let checkpoint = checkpoints.get(thread_id);
                let layout = local_binding.and_then(|binding| binding.root_tail_layout.as_ref());
                // The adoption probe is mapping-driven: the cloud tail it
                // refolds against is the row this thread's binding names,
                // never an id-equality lookup.
                let adoption_probe = checkpoint
                    .and_then(|checkpoint| checkpoint.accepted.as_ref())
                    .is_none()
                    .then(|| {
                        local_binding
                            .and_then(|binding| binding.cloud_thread_id.as_ref())
                            .and_then(|cloud_thread_id| {
                                provider_scope
                                    .and_then(|scope| scope.conversations.get(cloud_thread_id))
                            })
                            .and_then(|thread| thread.portable_tail.as_ref())
                    })
                    .flatten();
                Some((
                    thread_id,
                    local,
                    checkpoint,
                    layout,
                    adoption_probe,
                    local_binding.map(|binding| binding.revision),
                ))
            })
            .collect();
        // Compare reuses an observation while every file it was read from
        // still carries its read-time stamp. Push additionally requires
        // that evidence to match the selected capture. Pull and cache
        // misses use the bounded observation worker pool.
        let previous_trees = storage_id
            .map(|storage_id| {
                super::observation_cache::observation_cache().subagent_cursors(
                    provider_home,
                    repository.root(),
                    &binding.local_project_id,
                    storage_id,
                    &observation_tasks
                        .iter()
                        .map(|(id, ..)| (**id).clone())
                        .collect::<Vec<_>>(),
                )
            })
            .unwrap_or_default();
        let cached: BTreeMap<ThreadId, LocalTailObservation> = match storage_id {
            Some(storage_id) if purpose == ReviewPurpose::Observe => {
                let queries: Vec<_> = observation_tasks
                    .iter()
                    .filter(|(_, local, _, _, probe, _)| local.is_some() && probe.is_none())
                    .map(|(thread_id, _, checkpoint, _, _, binding_revision)| {
                        super::observation_cache::ObservationQuery {
                            thread_id: (**thread_id).clone(),
                            checkpoint_generation: checkpoint
                                .map(|checkpoint| checkpoint.generation),
                            binding_revision: *binding_revision,
                        }
                    })
                    .collect();
                super::observation_cache::observation_cache().take_reusable_observations(
                    provider_home,
                    repository.root(),
                    &binding.local_project_id,
                    storage_id,
                    &queries,
                )
            }
            Some(storage_id) if purpose == ReviewPurpose::PushPlan => {
                let queries = observation_tasks
                    .iter()
                    .filter_map(
                        |(thread_id, local, checkpoint, layout, probe, binding_revision)| {
                            if probe.is_some() {
                                return None;
                            }
                            let local = (*local)?;
                            let transcript = &local.captured.as_ref()?.transcript;
                            Some(super::observation_cache::PushObservationQuery {
                                observation: super::observation_cache::ObservationQuery {
                                    thread_id: (**thread_id).clone(),
                                    checkpoint_generation: checkpoint
                                        .map(|checkpoint| checkpoint.generation),
                                    binding_revision: *binding_revision,
                                },
                                source: &local.source_path,
                                stamp: transcript.source_stamp.as_ref()?,
                                provider_thread_id: &local.provider_thread_id,
                                layout: *layout,
                            })
                        },
                    )
                    .collect::<Vec<_>>();
                super::observation_cache::observation_cache().take_push_observations(
                    provider_home,
                    repository.root(),
                    &binding.local_project_id,
                    storage_id,
                    &queries,
                )
            }
            _ => BTreeMap::new(),
        };
        if purpose == ReviewPurpose::PushPlan {
            for (thread_id, observation) in &cached {
                if let Some(proof) = &observation.push_reuse {
                    if let Some(source) = proof
                        .sources
                        .get(Path::new(&proof.seeded.mapping.root_path))
                    {
                        cursor_refreshed.insert(
                            thread_id.clone(),
                            SeededCursor {
                                root: proof.seeded.clone(),
                                source: source.clone(),
                            },
                        );
                    }
                    cursor_deps.insert(thread_id.clone(), proof.sources.iter().collect());
                }
            }
        }
        let observation_tasks: Vec<_> = observation_tasks
            .into_iter()
            .filter(|(thread_id, ..)| !cached.contains_key(*thread_id))
            .collect();
        cursor_observations.extend(cached);
        let mut slots: Vec<std::sync::OnceLock<ObservationOutcome>> = observation_tasks
            .iter()
            .map(|_| std::sync::OnceLock::new())
            .collect();
        if !observation_tasks.is_empty() {
            let workers = provider_capture::bounded_refresh_workers(observation_tasks.len());
            let cursor = std::sync::atomic::AtomicUsize::new(0);
            let tasks = &observation_tasks;
            let task_slots = &slots;
            std::thread::scope(|scope| {
                for _ in 0..workers {
                    scope.spawn(|| loop {
                        let index = cursor.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        let Some((task_id, local, checkpoint, layout, probe, _)) = tasks.get(index)
                        else {
                            break;
                        };
                        let outcome = if reconstructs_graph {
                            observe_codex_local(
                                (purpose == ReviewPurpose::PushPlan).then_some(&reviewed_roots),
                                *local,
                                previous_trees.get(*task_id).and_then(|tree| tree.codex()).filter(|tree| local.is_some_and(|local| local.provider_thread_id == tree.main.mapping.provider_thread_id)).map(|tree| &tree.main),
                                *checkpoint,
                                *layout,
                                provider_home,
                                *probe,
                                repository,
                                binding,
                                &profile_id, local.and_then(|local| local.binding.as_ref()).or_else(|| bindings_by_thread.get(*task_id)).and_then(|row| row.cloud_thread_id.as_ref()).and_then(|id| provider_scope.and_then(|scope| scope.conversations.get(id))).and_then(|row| row.wire_redaction.as_ref()),
                            )
                        } else {
                            observe_claude_local(
                                *local,
                                previous_trees.get(*task_id).and_then(|tree| tree.claude()),
                                *checkpoint,
                                *layout,
                                *probe,
                                repository,
                                binding,
                                &profile_id, local.and_then(|local| local.binding.as_ref()).or_else(|| bindings_by_thread.get(*task_id)).and_then(|row| row.cloud_thread_id.as_ref()).and_then(|id| provider_scope.and_then(|scope| scope.conversations.get(id))).and_then(|row| row.wire_redaction.as_ref()),
                            )
                        };
                        let outcome = outcome.and_then(|mut outcome| {
                            if reconstructs_graph {
                                if let Some(local) = local {
                                    if matches!(outcome.observation.evidence, TailSideEvidence::Present(_)) {
                                        let previous = previous_trees.get(*task_id).and_then(|tree| tree.codex()).filter(|tree| tree.main.mapping.provider_thread_id == local.provider_thread_id);
                                        // A cursor ride carries its discovery whenever a
                                        // previous one exists; without one the main is
                                        // read in full.
                                        let discovery = match outcome.observation.discovery.take() {
                                            Some(discovery) => discovery,
                                            None => {
                                                let (bytes, stamp) = jsonl_tail_io::read_snapshot(&local.source_path)?;
                                                let (resolved, _) = codex_history_graph::resolve_captured_codex_root(&local.source_path, bytes.clone().into(), stamp.clone(), &|id| child_lookup.find_rollout(id))?;
                                                let seeded = codex_history_graph::seed_codex_root(&resolved, &bytes, *layout)?;
                                                codex_subagents::DiscoveryObservation { mapping: seeded.mapping, stamp, creations: resolved.leaf_creations }
                                            }
                                        };
                                        let Ok(tree) = codex_subagents::observe_tree(discovery, local.binding.as_ref(), &child_lookup, previous) else { return Ok(outcome); };
                                        outcome.depends_on.extend(&tree.dependencies());
                                        outcome.observation.subagents = Some(owned_subagents::TreeObservation::Codex(tree));
                                    }
                                }
                            }
                            Ok(outcome)
                        });
                        let _ = task_slots[index].set(outcome);
                    });
                }
            });
        }
        // Ordered merge. A thread whose observation failed keeps its error
        // and blocks its own row below; it never fails the provider. An
        // unexpectedly unset slot is a controlled stage error, never a panic.
        for ((thread_id, ..), slot) in observation_tasks.iter().zip(slots.iter_mut()) {
            match take_observation_outcome(thread_id, slot) {
                Ok(ProviderLocalObservation {
                    observation,
                    seeded,
                    depends_on,
                }) => {
                    if let Some(seeded) = seeded {
                        cursor_refreshed.insert((*thread_id).clone(), seeded);
                    }
                    if depends_on.is_pinned() {
                        cursor_deps.insert((*thread_id).clone(), depends_on);
                    }
                    cursor_observations.insert((*thread_id).clone(), observation);
                }
                Err(message) => {
                    observation_failures.insert((*thread_id).clone(), message);
                }
            }
        }
    }

    // Checkpoint maintenance: persist every advanced observation in one
    // config transaction so the next Refresh rides the new cursors instead
    // of re-deriving from the last applied pins. Known no-ops and Detached
    // checkpoints are excluded before the transaction; each remaining
    // candidate then re-checks the live document. Generation
    // compare-and-swap skips any checkpoint a concurrent operation moved, a
    // Detached mapping is never reattached by observation, byte-identical
    // replacements are skipped, and `accepted` never changes here.
    let mut maintained: BTreeMap<ThreadId, u64> = BTreeMap::new();
    if purpose != ReviewPurpose::Observe {
        if let Some(storage_id) = storage_id {
            let mut candidates: Vec<(ThreadId, Option<u64>, ConversationCheckpoint)> = Vec::new();
            for (thread_id, seeded) in &cursor_refreshed {
                let Some(pin) = cursor_observations
                    .get(thread_id)
                    .and_then(|observation| observation.raw_range_pin.clone())
                else {
                    continue;
                };
                let Some(local_binding) = local_threads
                    .get(thread_id)
                    .and_then(|local| local.binding.as_ref())
                    .or_else(|| bindings_by_thread.get(thread_id))
                else {
                    continue;
                };
                let stored = saved_checkpoints.get(thread_id);
                if matches!(
                    stored.map(|checkpoint| &checkpoint.physical),
                    Some(PhysicalMappingState::Detached { .. })
                ) {
                    continue;
                }
                let replacement = ConversationCheckpoint {
                    accepted_subagents: stored
                        .map(|checkpoint| checkpoint.accepted_subagents.clone())
                        .unwrap_or_default(),
                    generation: stored
                        .map(|checkpoint| checkpoint.generation.saturating_add(1))
                        .unwrap_or(0),
                    accepted: stored.and_then(|checkpoint| checkpoint.accepted.clone()),
                    accepted_local_tail: stored
                        .and_then(|checkpoint| checkpoint.accepted_local_tail.clone()),
                    observed_tail: seeded.root.observed_tail.clone(),
                    physical: PhysicalMappingState::Ready {
                        root_mapping: seeded.root.mapping.clone(),
                        raw_range_pin: pin,
                        source_state: Some(seeded.source.file_state()),
                    },
                    prefix_witness: seeded.root.prefix_witness.clone(),
                    binding_revision: local_binding.revision,
                };
                if stored.is_some_and(|checkpoint| {
                    checkpoint.observed_tail == replacement.observed_tail
                        && checkpoint.physical == replacement.physical
                        && checkpoint.prefix_witness == replacement.prefix_witness
                        && checkpoint.binding_revision == replacement.binding_revision
                }) {
                    continue;
                }
                let expected_generation = stored.map(|checkpoint| checkpoint.generation);
                candidates.push((thread_id.clone(), expected_generation, replacement));
            }
            if !candidates.is_empty() {
                let scope = SyncScopeKey::Provider(provider.clone());
                let (applied, _) = repository
                    .transact_config(|config| {
                        let mut applied: BTreeMap<ThreadId, u64> = BTreeMap::new();
                        let Some(link) = config.links.iter_mut().find(|link| {
                            link.local_project_id == binding.local_project_id
                                && &link.storage_id == storage_id
                        }) else {
                            return Ok::<_, String>(ConfigMutation::Unchanged(applied));
                        };
                        let threads = link
                            .conversation_checkpoints
                            .entry(scope.clone())
                            .or_default();
                        for (thread_id, expected_generation, replacement) in &candidates {
                            match (threads.get(thread_id), expected_generation) {
                                (Some(stored), Some(expected))
                                    if stored.generation == *expected =>
                                {
                                    if matches!(
                                        stored.physical,
                                        PhysicalMappingState::Detached { .. }
                                    ) {
                                        continue;
                                    }
                                    if stored.observed_tail == replacement.observed_tail
                                        && stored.physical == replacement.physical
                                        && stored.prefix_witness == replacement.prefix_witness
                                        && stored.binding_revision == replacement.binding_revision
                                    {
                                        continue;
                                    }
                                    threads.insert(thread_id.clone(), replacement.clone());
                                    applied.insert(thread_id.clone(), replacement.generation);
                                }
                                (None, None) => {
                                    threads.insert(thread_id.clone(), replacement.clone());
                                    applied.insert(thread_id.clone(), replacement.generation);
                                }
                                _ => {}
                            }
                        }
                        if applied.is_empty() {
                            Ok(ConfigMutation::Unchanged(applied))
                        } else {
                            Ok(ConfigMutation::Changed(applied))
                        }
                    })
                    .map_err(config_transaction_error)?;
                maintained = applied;
            }
        }
    }

    // Retain freshly derived observations for the next operation, keyed by
    // the post-maintenance checkpoint generation and pinned to the stamps
    // their files were read under. Adoption-probe threads are never
    // retained: a thread without accepted evidence re-proves its refold
    // every review while a cloud tail exists for it.
    if let Some(storage_id) = storage_id {
        if supports_cursor && !cursor_deps.is_empty() {
            let stored: Vec<_> = cursor_deps
                .iter()
                .filter_map(|(thread_id, depends_on)| {
                    let observation = cursor_observations.get(thread_id)?;
                    if !matches!(observation.evidence, TailSideEvidence::Present(_))
                        || observation.subagents.is_none()
                    {
                        return None;
                    }
                    let local = local_threads.get(thread_id)?;
                    let checkpoint = checkpoints.get(thread_id);
                    let local_binding = local
                        .binding
                        .as_ref()
                        .or_else(|| bindings_by_thread.get(thread_id));
                    let probe_active = checkpoint
                        .and_then(|checkpoint| checkpoint.accepted.as_ref())
                        .is_none()
                        && local_binding
                            .and_then(|binding| binding.cloud_thread_id.as_ref())
                            .and_then(|cloud_thread_id| {
                                provider_scope
                                    .and_then(|scope| scope.conversations.get(cloud_thread_id))
                            })
                            .and_then(|thread| thread.portable_tail.as_ref())
                            .is_some();
                    if probe_active {
                        return None;
                    }
                    let checkpoint_generation = match maintained.get(thread_id) {
                        Some(generation) => Some(*generation),
                        None => checkpoint.map(|checkpoint| checkpoint.generation),
                    };
                    Some(super::observation_cache::StoredObservation {
                        thread_id: thread_id.clone(),
                        depends_on: depends_on.clone(),
                        checkpoint_generation,
                        binding_revision: local_binding.map(|binding| binding.revision),
                        observation: observation.clone(),
                    })
                })
                .collect();
            if !stored.is_empty() {
                super::observation_cache::observation_cache().store_observations(
                    provider_home,
                    repository.root(),
                    &binding.local_project_id,
                    storage_id,
                    stored,
                );
            }
        }
    }

    for (unit_local_id, unit_cloud_id) in units {
        let observation_failure = unit_local_id
            .as_ref()
            .and_then(|thread_id| observation_failures.get(thread_id));
        // Everything cloud-sided resolves through the unit's cloud id (the
        // mapping, or the cloud-only row key); everything local-sided stays
        // on the local id. There is no cross-space lookup left to miss.
        let thread = unit_cloud_id.as_ref().and_then(|cloud_thread_id| {
            provider_scope.and_then(|scope| scope.conversations.get(cloud_thread_id))
        });
        let local = unit_local_id
            .as_ref()
            .and_then(|thread_id| local_threads.get(thread_id));
        let local_binding = local.and_then(|local| local.binding.as_ref()).or_else(|| {
            unit_local_id
                .as_ref()
                .and_then(|thread_id| bindings_by_thread.get(thread_id))
        });
        let checkpoint = unit_local_id
            .as_ref()
            .and_then(|thread_id| checkpoints.get(thread_id));
        let cloud_descriptor = thread.and_then(|thread| {
            provider_scope.and_then(|scope| scope.resources.get(&thread.resource_id))
        });
        let descriptor = local
            .and_then(|local| local.descriptor.as_ref())
            .or(cloud_descriptor);

        // Accepted dual pins: the wire pin and its local-form twin are
        // recorded atomically; evidence mirrors both columns.
        let accepted_evidence = match checkpoint.and_then(|checkpoint| checkpoint.accepted.as_ref())
        {
            Some(accepted) => TailSideEvidence::Present(accepted.portable_tail.clone()),
            None => TailSideEvidence::ConfirmedAbsent,
        };
        let accepted_local_evidence =
            match checkpoint.and_then(|checkpoint| checkpoint.accepted_local_tail.as_ref()) {
                Some(tail) => TailSideEvidence::Present(tail.clone()),
                None => TailSideEvidence::ConfirmedAbsent,
            };
        // Cloud side.
        let cloud_evidence = match thread {
            Some(thread) => match (&thread.portable_tail, supports_cursor) {
                (Some(tail), _) => TailSideEvidence::Present(tail.clone()),
                (None, true) => TailSideEvidence::Invalid,
                (None, false) => TailSideEvidence::Present(synthesized_whole_thread_tail(
                    &thread.lineage_codec,
                    thread.message_count,
                    &thread.semantic_digest,
                )),
            },
            None => TailSideEvidence::ConfirmedAbsent,
        };
        // Local side. A binding that names a provider alias promises a
        // local copy: its absence from capture is unproven loss, never a
        // confirmed absence.
        let expected_local_missing = local.is_none()
            && local_binding.is_some_and(|binding| binding.provider_thread_id.is_some());
        let local_observation = if expected_local_missing {
            LocalTailObservation {
                push_reuse: None,
                subagents: None,
                discovery: None,
                evidence: TailSideEvidence::Invalid,
                raw_range_pin: None,
                verified_acceptance: None,
                edited_since_acceptance: false,
            }
        } else if unit_local_id.is_none() {
            // Cloud-only unit: there is no local side to observe.
            LocalTailObservation {
                push_reuse: None,
                subagents: None,
                discovery: None,
                evidence: TailSideEvidence::ConfirmedAbsent,
                raw_range_pin: None,
                verified_acceptance: None,
                edited_since_acceptance: false,
            }
        } else if supports_cursor {
            match unit_local_id
                .as_ref()
                .and_then(|thread_id| cursor_observations.remove(thread_id))
            {
                Some(observation) => observation,
                // A failed observation proves nothing about the local side;
                // the row is blocked with its read error below.
                None if observation_failure.is_some() => LocalTailObservation {
                    push_reuse: None,
                    subagents: None,
                    discovery: None,
                    evidence: TailSideEvidence::Invalid,
                    raw_range_pin: None,
                    verified_acceptance: None,
                    edited_since_acceptance: false,
                },
                None => return Err("local observation missing for reviewed thread".to_string()),
            }
        } else {
            // Providers without a cursor codec prove their tail from
            // captured bytes; a local row without them cannot happen in a
            // correctly assembled review and fails the provider closed.
            let captured = match local {
                None => None,
                Some(local) => Some(local.captured.as_ref().ok_or_else(|| {
                    format!(
                        "{} conversation was reviewed without captured bytes",
                        provider_label
                    )
                })?),
            };
            let evidence = match captured {
                None => TailSideEvidence::ConfirmedAbsent,
                Some(captured) => match &captured.conversation.lineage {
                    CodecLineage::Complete {
                        chain,
                        semantic_digest,
                        ..
                    } => TailSideEvidence::Present(synthesized_whole_thread_tail(
                        adapter.codec_key(),
                        chain.len() as u64,
                        semantic_digest,
                    )),
                    CodecLineage::Unknown { .. } => TailSideEvidence::Invalid,
                },
            };
            LocalTailObservation {
                push_reuse: None,
                subagents: None,
                discovery: None,
                evidence,
                raw_range_pin: captured.map(|captured| RawRangePin {
                    start_byte_offset: 0,
                    end_byte_offset: captured.transcript.bytes.len() as u64,
                    range_sha256: captured.transcript.bytes.sha256().to_string(),
                }),
                verified_acceptance: None,
                edited_since_acceptance: false,
            }
        };
        // A proven adoption re-establishes both acceptance pins for this
        // review only; the durable pins are written by the Push or Pull it
        // enables.
        let (mut accepted_evidence, mut accepted_local_evidence) =
            match (&accepted_evidence, &local_observation.verified_acceptance) {
                (TailSideEvidence::ConfirmedAbsent, Some(adoption)) => (
                    TailSideEvidence::Present(adoption.wire_tail.clone()),
                    TailSideEvidence::Present(adoption.local_tail.clone()),
                ),
                _ => (accepted_evidence, accepted_local_evidence),
            };
        let physical_detached = matches!(
            checkpoint.map(|checkpoint| &checkpoint.physical),
            Some(PhysicalMappingState::Detached { .. })
        );

        let outgoing_stamp = settings.wire_children(provider);
        let subagent_selection = if outgoing_stamp == ConversationWireChildren::Off {
            SubagentSelection {
                wire_children: outgoing_stamp,
                omitted: true,
                ..Default::default()
            }
        } else {
            local_observation
                .subagents
                .as_ref()
                .map(|tree| tree.selection())
                .unwrap_or_default()
        };
        let compare_children = thread
            .map(|row| row.wire_children)
            .unwrap_or(outgoing_stamp)
            == ConversationWireChildren::On;
        let comparison_omitted = !compare_children
            || local_observation
                .subagents
                .as_ref()
                .is_some_and(|tree| tree.omitted());
        let mut child_pins = BTreeMap::<SubagentKey, SubagentTailPins>::new();
        let child_observation = (|| -> Result<(), String> {
            if !compare_children {
                return Ok(());
            }
            let local_tree = local_observation.subagents.as_ref();
            if let Some(tree) = local_tree {
                if tree.omitted() {
                    return Ok(());
                }
            } else if local.is_some() {
                return Err("child membership could not be observed".into());
            }
            for (key, pair) in checkpoint
                .into_iter()
                .flat_map(|checkpoint| &checkpoint.accepted_subagents)
            {
                child_pins
                    .entry(key.clone())
                    .or_insert(SubagentTailPins {
                        accepted: None,
                        local: None,
                        cloud: None,
                    })
                    .accepted = Some(pair.clone());
            }
            for file in thread.into_iter().flat_map(|thread| &thread.files) {
                if let ConversationFileRole::SubagentTranscript {
                    child_key,
                    normalized,
                } = &file.role
                {
                    child_pins
                        .entry(child_key.clone())
                        .or_insert(SubagentTailPins {
                            accepted: None,
                            local: None,
                            cloud: None,
                        })
                        .cloud = Some(normalized.clone());
                }
            }
            if let Some(tree) = local_tree {
                for (key, state) in tree.states() {
                    child_pins
                        .entry(key.clone())
                        .or_insert(SubagentTailPins {
                            accepted: None,
                            local: None,
                            cloud: None,
                        })
                        .local = Some(state.clone());
                }
                if !tree.missing().is_empty() {
                    return Err(format!(
                        "Missing local child: {}.",
                        tree.missing()
                            .iter()
                            .map(ToString::to_string)
                            .collect::<Vec<_>>()
                            .join(", ")
                    ));
                }
                if !child_pins
                    .values()
                    .any(|pin| pin.local.is_some() && pin.cloud.is_some() && pin.accepted.is_none())
                    && !matches!(
                        (&accepted_evidence, &cloud_evidence),
                        (
                            TailSideEvidence::ConfirmedAbsent,
                            TailSideEvidence::Present(_)
                        )
                    )
                {
                    return Ok(());
                }
                let local = local.unwrap();
                if let Some(tree) = tree.claude() {
                    let mapper = SessionPathMapper::new(
                        &binding.project_root,
                        (binding.canonical_project_root != binding.project_root)
                            .then_some(binding.canonical_project_root.as_str()),
                        mallard_infrastructure::session_path_map::home_dir_text().as_deref(),
                    )?;
                    let origins = local_binding
                        .filter(|row| row.path_origins_ref.is_some())
                        .map(|row| repository.load_path_origins(row))
                        .transpose()?
                        .unwrap_or_default();
                    let captured = claude_subagents::capture_children(
                        &tree.main,
                        local_binding,
                        &mapper,
                        &origins,
                        &mut credential_redaction::shared()
                            .run_from_stamp(thread.and_then(|row| row.wire_redaction.as_ref()))?,
                        Some(&child_pins),
                    )?;
                    if captured.omitted {
                        return Err("Claude child scope changed during observation".into());
                    }
                    for (key, child) in &captured.children {
                        if let Some(pin) = child_pins.get_mut(key) {
                            if pin.accepted.is_none()
                                && pin.local.as_ref() == Some(&child.accepted.local)
                            {
                                pin.accepted = child.adoption.clone();
                            }
                        }
                    }
                    return Ok(());
                }
                let bytes = jsonl_tail_io::read_bounded(&local.source_path)?;
                let tree = codex_subagents::capture_tree(
                    &bytes,
                    &local.provider_thread_id,
                    local_binding,
                    &child_lookup,
                )?;
                // First contact must prove every overlapping child in wire form.
                let mut identities = BTreeMap::from([(
                    local.provider_thread_id.clone(),
                    codex_subagents::PORTABLE_MAIN_ID.to_string(),
                )]);
                identities.extend(tree.children.iter().map(|(key, child)| {
                    (
                        child.resolved.leaf_meta.id.clone(),
                        codex_subagents::portable_child_id(key),
                    )
                }));
                let origins = local_binding
                    .filter(|row| row.path_origins_ref.is_some())
                    .map(|row| repository.load_path_origins(row))
                    .transpose()?
                    .unwrap_or_default();
                if let (TailSideEvidence::ConfirmedAbsent, TailSideEvidence::Present(probe)) =
                    (&accepted_evidence, &cloud_evidence)
                {
                    let (main_bytes, stamp) = jsonl_tail_io::read_snapshot(&local.source_path)?;
                    let (resolved, sources) = codex_history_graph::resolve_captured_codex_root(
                        &local.source_path,
                        main_bytes.into(),
                        stamp,
                        &|id| child_lookup.find_rollout(id),
                    )?;
                    let layout =
                        local_binding.and_then(|binding| binding.root_tail_layout.as_ref());
                    let (kind, start) =
                        codex_history_graph::effective_tail_partition(layout, &resolved)?;
                    let wire =
                        mallard_infrastructure::codex_standalone_builder::encode_codex_tree_member(
                            &resolved,
                            &sources,
                            &binding.project_root,
                            (binding.canonical_project_root != binding.project_root)
                                .then_some(binding.canonical_project_root.as_str()),
                            layout,
                            &mut credential_redaction::shared().run_from_stamp(
                                thread.and_then(|row| row.wire_redaction.as_ref()),
                            )?,
                            &origins,
                            OriginLookup::ByPosition,
                            &identities,
                        )?;
                    if let Some(adoption) =
                        adopt_codex_artifact(&resolved, &wire, probe, kind, start)
                    {
                        accepted_evidence = TailSideEvidence::Present(adoption.wire_tail);
                        accepted_local_evidence = TailSideEvidence::Present(adoption.local_tail);
                    }
                }
                for (key, child) in &tree.children {
                    let pin = child_pins.get_mut(key).unwrap();
                    if pin.accepted.is_some() || pin.cloud.is_none() {
                        continue;
                    }
                    let cloud = pin.cloud.as_ref().unwrap();
                    let origins = local_binding
                        .filter(|row| row.path_origins_ref.is_some())
                        .map(|row| repository.load_path_origins(row))
                        .transpose()?
                        .unwrap_or_default();
                    let wire =
                        mallard_infrastructure::codex_standalone_builder::encode_codex_tree_member(
                            &child.resolved,
                            &child.sources,
                            &binding.project_root,
                            (binding.canonical_project_root != binding.project_root)
                                .then_some(binding.canonical_project_root.as_str()),
                            Some(&codex_subagents::whole_child_layout()),
                            &mut credential_redaction::shared().run_from_stamp(
                                thread.and_then(|row| row.wire_redaction.as_ref()),
                            )?,
                            &origins,
                            OriginLookup::ByPosition,
                            &identities,
                        )?;
                    if let Some(adoption) = adopt_codex_artifact(
                        &child.resolved,
                        &wire,
                        &codex_subagents::native_child_tail(cloud, true),
                        TailPartitionKind::WholeThread,
                        0,
                    ) {
                        pin.accepted = Some(AcceptedSubagentState {
                            local: SubagentContentState::from_tail(&adoption.local_tail)?,
                            normalized: cloud.clone(),
                        });
                    }
                }
            }
            Ok(())
        })();
        // An edited session no longer continues the version that was
        // accepted. The pins stay saved and are read as absent here, which
        // leaves two copies that nothing relates.
        if local_observation.edited_since_acceptance {
            accepted_evidence = TailSideEvidence::ConfirmedAbsent;
            accepted_local_evidence = TailSideEvidence::ConfirmedAbsent;
        }
        let relation_result: Result<TailClassification, TailEvidenceBlocker> =
            if descriptor.is_none() && (local.is_some() || thread.is_some()) {
                Err(TailEvidenceBlocker::InvalidSide)
            } else {
                VerifiedTailEvidence::new(
                    accepted_evidence.clone(),
                    accepted_local_evidence.clone(),
                    local_observation.evidence.clone(),
                    cloud_evidence.clone(),
                )
                .and_then(|evidence| {
                    if child_observation.is_err() {
                        return Err(TailEvidenceBlocker::InvalidSide);
                    }
                    let children = child_pins
                        .values()
                        .map(mallard_domain::compare_subagent_tail)
                        .collect::<Result<Vec<_>, _>>()?;
                    Ok(mallard_domain::fold_conversation_relations(
                        compare_conversation_tail(&evidence),
                        children,
                        local_only_children_kept,
                    ))
                })
            };
        let evidence_blocker = relation_result.as_ref().err().copied();
        let relation = if let Ok(relation) = relation_result {
            relation
        } else {
            TailClassification::Unknown
        };
        // Cursor-provider capturability is proven by the resolved logical
        // root, not by the append-bearing leaf in isolation. A valid
        // paginated Codex thread can have an empty leaf while all of its
        // messages live in history_base. The observation functions validate
        // that complete chain (or a trusted checkpoint continuation) before
        // returning Present evidence.
        let local_capturable = if purpose == ReviewPurpose::Observe && !supports_cursor {
            local.is_some()
        } else if supports_cursor {
            local.is_some() && matches!(&local_observation.evidence, TailSideEvidence::Present(_))
        } else {
            local.is_some_and(|local| {
                local
                    .captured
                    .as_ref()
                    .is_some_and(|captured| captured.conversation.lineage.is_complete())
            }) && !matches!(local_observation.evidence, TailSideEvidence::Invalid)
        };
        let cloud_readable = thread.is_some_and(|thread| {
            matches!(thread.lineage_status, ConversationLineageStatus::Complete)
        }) && !matches!(cloud_evidence, TailSideEvidence::Invalid);
        let missing_local_subagents = local_observation
            .subagents
            .as_ref()
            .filter(|_| compare_children)
            .map(|tree| tree.missing().clone())
            .unwrap_or_default();
        let present_tail = |side: &TailSideEvidence| match side {
            TailSideEvidence::Present(tail) => Some(tail.clone()),
            _ => None,
        };
        let missing_child_recovery = !missing_local_subagents.is_empty()
            && (|| {
                let recovery_pins = ConversationTailPins {
                    subagents: child_pins.clone(),
                    missing_local_subagents: missing_local_subagents.clone(),
                    subagents_omitted: comparison_omitted,
                    local_only_subagents_kept: local_only_children_kept,
                    accepted: present_tail(&accepted_evidence),
                    accepted_local: present_tail(&accepted_local_evidence),
                    local: present_tail(&local_observation.evidence),
                    cloud: present_tail(&cloud_evidence),
                    checkpoint_generation: checkpoint.map(|value| value.generation),
                    lineage_digest: None,
                    semantic_digest: None,
                    raw_range: None,
                };
                recovery_pins.validate_missing_child_recovery().is_ok()
            })();
        let export_settings_changed = thread.is_some_and(|row| {
            row.wire_children != outgoing_stamp
                || row.wire_redaction.as_ref()
                    != Some(
                        &credential_redaction::shared()
                            .begin_run()
                            .with_enabled(credential_redaction_enabled)
                            .stamp(),
                    )
        });
        let capabilities = ConversationCapabilities {
            export_settings_changed,
            missing_child_recovery,
            binding: if local_binding.is_some() {
                BindingResolution::Bound
            } else {
                local
                    .map(|local| local.binding_resolution)
                    .unwrap_or(BindingResolution::Missing)
            },
            local_safely_capturable: local_capturable
                && (purpose == ReviewPurpose::Observe || local_observation.raw_range_pin.is_some()),
            cloud_materializable: cloud_readable,
            operation_state: if physical_detached {
                ConversationOperationState::Detached
            } else {
                ConversationOperationState::Ready
            },
            // The durable pin's presence, not the reviewed evidence: the
            // adoption probe upgrades evidence for this review only, and the
            // Pull it enables is what writes the pin.
            acceptance_durably_pinned: checkpoint
                .and_then(|checkpoint| checkpoint.accepted.as_ref())
                .is_some(),
        };
        let classified = ClassifiedThread::new(relation, capabilities);
        let push = classified.decision(ConversationPlanDirection::Push);
        let outgoing_child_failure = local.is_some()
            && outgoing_stamp == ConversationWireChildren::On
            && !local_observation
                .subagents
                .as_ref()
                .is_some_and(|tree| tree.missing().is_empty());
        let push = if push.selectable && outgoing_child_failure {
            let mut blocked = mallard_domain::blocked_conversation_decision(
                ConversationBlocker::ObservationFailed,
            );
            blocked.blocked_reason =
                Some("Child conversations could not be verified for Push.".into());
            blocked
        } else {
            push
        };
        let pull = classified.decision(ConversationPlanDirection::Pull);
        // Redaction ruleset gate: a cloud row stamped by a foreign ruleset
        // blocks both directions with the typed blocker before any plan is
        // built — neither re-encoding the prefix nor materializing foreign
        // wire bytes is permitted.
        let (push, pull) = if thread.is_some_and(|row| {
            credential_redaction::shared()
                .run_from_stamp(row.wire_redaction.as_ref())
                .is_err()
        }) {
            let blocked = mallard_domain::blocked_conversation_decision(
                ConversationBlocker::RedactionRulesetMismatch,
            );
            (blocked.clone(), blocked)
        } else {
            (push, pull)
        };
        // Path-map codec gate, the same shape: a claude row whose
        // out-of-band declaration names a foreign codec can be neither
        // re-encoded nor decoded by this binary. Manifest validation makes
        // the stamp mandatory for claude rows, so only a foreign value can
        // reach this check.
        let (push, pull) = match thread.and_then(|thread| thread.wire_path_map.as_ref()) {
            Some(stamp)
                if stamp.codec != mallard_infrastructure::session_path_map::PATH_MAP_CODEC_V1 =>
            {
                let blocked = mallard_domain::blocked_conversation_decision(
                    ConversationBlocker::PathMapCodecMismatch,
                );
                (blocked.clone(), blocked)
            }
            _ => (push, pull),
        };

        // Observation gate: a local session that could not be read or
        // parsed blocks both directions with its own error. The row stays
        // visible, the message names the cause, and no other thread is
        // affected.
        let observation_detail = observation_failure.map(|message| {
            format!(
                "This conversation's local session could not be read for review: {}",
                message
            )
        });
        let (push, pull) = match &observation_detail {
            Some(detail) => {
                let mut blocked = mallard_domain::blocked_conversation_decision(
                    ConversationBlocker::ObservationFailed,
                );
                blocked.blocked_reason = Some(detail.clone());
                (blocked.clone(), blocked)
            }
            None => (push, pull),
        };

        // Stored internal-subagent rollouts are never offered by Pull.
        if purpose.builds_pull_plan() && pull.action == ConversationReviewAction::CreateLocal {
            if let Some((logical_path, sha256, size)) = unit_cloud_id
                .as_ref()
                .and_then(|cloud_thread_id| offerable_cloud_transcripts.get(cloud_thread_id))
            {
                if cached_transcript_is_internal_subagent(sha256, *size, bytes, logical_path)? {
                    continue;
                }
            }
        }

        let source_resource_id = local
            .map(|local| local.resource_id.clone())
            .or_else(|| thread.map(|thread| thread.resource_id.clone()));
        let provider_thread_id = local
            .map(|local| local.provider_thread_id.clone())
            .or_else(|| local_binding.and_then(|binding| binding.provider_thread_id.clone()));
        // The shared row-key rule: the local id keys any unit with a local
        // side; a cloud-only unit keys by its cloud id. The namespaces are
        // prefix-disjoint, so the two key forms can never collide.
        let unit_display_id = match (&unit_local_id, &unit_cloud_id) {
            (Some(thread_id), _) => thread_id.to_string(),
            (None, Some(cloud_thread_id)) => cloud_thread_id.to_string(),
            (None, None) => unreachable!("review unit names at least one identity"),
        };
        let mut pull = pull;
        if pull.action == ConversationReviewAction::KeepBoth && missing_child_recovery {
            pull.blocked_reason = child_observation.as_ref().err().map(|message| {
                format!("{message} Keep both restores the cloud copy and retains the local files.")
            });
        }
        let display_name = thread
            .and_then(|thread| thread.display_title.clone())
            .or_else(|| descriptor.map(|descriptor| descriptor.display_name.clone()))
            .unwrap_or_else(|| unit_display_id.clone());
        let conversation_id = match (&unit_local_id, &unit_cloud_id) {
            (Some(thread_id), _) => conversation_resource_id(provider, thread_id)?,
            (None, Some(cloud_thread_id)) => {
                cloud_conversation_resource_id(provider, cloud_thread_id)?
            }
            (None, None) => unreachable!("review unit names at least one identity"),
        };
        let review_resource_id = match source_resource_id
            .clone()
            .or_else(|| descriptor.map(|descriptor| descriptor.resource_id.clone()))
        {
            Some(resource_id) => resource_id,
            None => conversation_id.clone(),
        };

        entries.push(ThreadSyncEntry {
            subagent_selection: subagent_selection.clone(),
            provider: provider.clone(),
            provider_display_name: provider_label.clone(),
            access: ProviderAccessState::BoundReady,
            thread_id: provider_thread_id
                .clone()
                .or_else(|| thread.and_then(|thread| thread.source_thread_id.clone()))
                .unwrap_or_else(|| unit_display_id.clone()),
            conversation_resource_id: conversation_id,
            resource_id: review_resource_id.clone(),
            display_name,
            state: relation_sync_state(relation),
            local_present: local.is_some(),
            storage_present: thread.is_some(),
            capture_bytes: local
                .map(|local| local.capture_bytes + subagent_selection.estimated_bytes),
            pull_bytes: thread.and_then(|thread| {
                snapshot.map(|snapshot| snapshot.manifest.conversation_bytes(thread))
            }),
            status_detail: capabilities
                .operation_state
                .eq(&ConversationOperationState::Pending)
                .then(|| {
                    format!(
                        "A {} sync operation is still pending for this conversation. \
                         Finish or recover it first.",
                        provider_label
                    )
                })
                .or_else(|| {
                    physical_detached.then(|| {
                        "This conversation's local mapping was replaced. Pull to \
                         re-establish it."
                            .to_string()
                    })
                })
                .or_else(|| observation_detail.clone())
                .or_else(|| outgoing_child_failure.then(|| "Child conversations could not be verified for Push.".to_string()))
                .or_else(|| (export_settings_changed && push.action == ConversationReviewAction::Publish).then(|| "Export settings changed".to_string()))
                .or_else(|| child_observation.as_ref().err().map(|message| {
                    if missing_child_recovery { format!("{message} Pull with Keep both to restore the cloud copy and retain local files.") }
                    else { message.clone() }
                }))
                .or_else(|| {
                    evidence_blocker
                        .is_some()
                        .then(|| "Conversation state could not be proven safely.".to_string())
                }),
            local_updated_at: local.map(|local| local.source_mtime),
            storage_updated_at: thread.map(|thread| thread.updated_at),
            // The unit's honest mapping is `None` for local-only rows.
            cloud_thread_id: unit_cloud_id.clone(),
            forked_from: thread
                .and_then(|thread| thread.forked_from.clone())
                .or_else(|| local_binding.and_then(|binding| binding.forked_from.clone())),
            compared_against_storage: true,
            provider_thread_id: provider_thread_id.clone(),
            push_decision: push.clone(),
            pull_decision: pull.clone(),
        });

        if purpose == ReviewPurpose::Observe {
            continue;
        }
        // Executable actions freeze the local target from captured bytes,
        // or from the pin a previous capture froze. A local
        // row reviewed without either can only produce non-selectable
        // actions; its Absent pin makes any out-of-contract apply attempt
        // fail the stale-pin check instead of running.
        let expected_local_target = local
            .and_then(|local| local.captured.as_ref())
            .map(|captured| {
                TargetExpectation::Sha256(captured.transcript.bytes.sha256().to_string())
            })
            .or_else(|| {
                local.and_then(|local| candidate_pins.get(local.resource_id.as_str()).cloned())
            })
            .unwrap_or(TargetExpectation::Absent);
        let required_codec = thread
            .map(|thread| thread.lineage_codec.clone())
            .or_else(|| {
                local
                    .and_then(|local| local.captured.as_ref())
                    .map(|captured| captured.conversation.lineage_codec.clone())
            })
            .unwrap_or_else(|| adapter.codec_key().to_string());
        let accepted_tail_pin = match &accepted_evidence {
            TailSideEvidence::Present(tail) => Some(tail.clone()),
            _ => None,
        };
        let accepted_local_tail_pin = match &accepted_local_evidence {
            TailSideEvidence::Present(tail) => Some(tail.clone()),
            _ => None,
        };
        let local_tail_pin = match &local_observation.evidence {
            TailSideEvidence::Present(tail) => Some(tail.clone()),
            _ => None,
        };
        let cloud_tail_pin = match &cloud_evidence {
            TailSideEvidence::Present(tail) => Some(tail.clone()),
            _ => None,
        };
        // The post-maintenance checkpoint generation this review saw; apply
        // requires the live checkpoint to still carry exactly this value.
        let checkpoint_generation_pin = unit_local_id
            .as_ref()
            .and_then(|thread_id| maintained.get(thread_id))
            .copied()
            .or_else(|| checkpoint.map(|checkpoint| checkpoint.generation));

        // The decision, never the raw classification: the redaction gate
        // above overrides `push`, and re-deriving from `classified` here
        // would ask a question the override has already answered. Blocked
        // rows are held out of planning by their non-selectable decision;
        // reading that decision directly is what makes it explicit.
        if purpose.builds_push_plan() && push.action.planned_action().is_some() {
            let publishes = matches!(
                push.action,
                ConversationReviewAction::Publish | ConversationReviewAction::CreateCloud
            );
            // The mapping travels verbatim: `None` is legal only for an
            // unmapped CreateCloud (the cloud id is minted at push apply);
            // action validation rejects an unmapped Publish.
            let push_action = build_conversation_plan_action(ConversationPlanActionRequest {
                action_id: ActionId::parse(generated_named_id("action")?)?,
                direction: ConversationPlanDirection::Push,
                classified,
                provider: provider.clone(),
                thread_id: unit_local_id.clone(),
                cloud_thread_id: local_binding.and_then(|binding| binding.cloud_thread_id.clone()),
                source_resource_id: source_resource_id.clone(),
                pins: ConversationActionPins {
                    subagent_selection: subagent_selection.clone(),
                    credential_redaction_enabled,
                    export_settings_changed,
                    context: ConversationContextPins {
                        host_id: binding.host_id.clone(),
                        replica_id: binding.replica_id.clone(),
                        local_project_id: binding.local_project_id.clone(),
                        provider_profile_id: profile_id.clone(),
                        host_identity_revision: host_identity.revision,
                        profile_revision: profile.revision,
                        project_binding_revision: binding.revision,
                        bindings_document_revision: document.revision,
                        binding_revision: local_binding.map(|binding| binding.revision),
                    },
                    revision: ConversationRevisionPins {
                        bundle_revision: pinned_revision,
                        commit_id: pinned_commit_id.clone(),
                        manifest_sha256: pinned_manifest_sha256.clone(),
                        scope_revision: pinned_scope_revision,
                        scope_sha256: pinned_scope_sha256.clone(),
                    },
                    tail: ConversationTailPins {
                        subagents: child_pins.clone(),
                        subagents_omitted: comparison_omitted,
                        local_only_subagents_kept: local_only_children_kept,
                        missing_local_subagents: missing_local_subagents.clone(),
                        accepted: accepted_tail_pin.clone(),
                        accepted_local: accepted_local_tail_pin.clone(),
                        local: local_tail_pin.clone(),
                        cloud: cloud_tail_pin.clone(),
                        checkpoint_generation: checkpoint_generation_pin,
                        lineage_digest: None,
                        semantic_digest: None,
                        raw_range: publishes
                            .then(|| local_observation.raw_range_pin.clone())
                            .flatten(),
                    },
                    target: ConversationTargetPins {
                        local: expected_local_target.clone(),
                        provider_state: Vec::new(),
                    },
                    codec: required_codec.clone(),
                    expires_at,
                },
            })?
            .expect("selectable Push classification produces an action");
            push_actions.push(push_action);
        }

        // A durably pinned current thread produces no Pull row at all: the
        // plan-level apply advances scope bases, so the review only carries
        // rows that change something. `NoChanges` also stays a Push-only
        // action inside validated plans.
        if purpose.builds_pull_plan() && pull.action != ConversationReviewAction::NoChanges {
            // Review mints nothing (plans are pure intent): destination
            // provider ids, the CreateLocal thread id, and every keep-both
            // identity are minted inside apply. What stays pinned here are
            // the identity-independent targets — the local source digest,
            // the index-file expectation, and the in-place (non-codex)
            // MaterializeCloud transcript target; destination absence for
            // minted identities is asserted at apply instead.
            let mut expected_provider_state = Vec::new();
            let materializing_digests = matches!(
                pull.action,
                ConversationReviewAction::MaterializeCloud
                    | ConversationReviewAction::KeepBoth
                    | ConversationReviewAction::CreateLocal
            );
            match pull.action {
                ConversationReviewAction::MaterializeCloud => {
                    let local = local.ok_or_else(|| {
                        "cloud materialization lacks a captured local state".to_string()
                    })?;
                    if local.binding.is_none() {
                        return Err(
                            "cloud materialization requires a bound provider session".to_string()
                        );
                    }
                    // Codex can create a physical history_base child at any
                    // time without changing the parent's bytes or binding.
                    // No target digest or dependency rescan can make an
                    // in-place replacement atomic with that external writer.
                    // Every Codex cloud update is therefore copy-on-write —
                    // its fresh identity and targets exist only at apply.
                    // Other providers have no physical rollout graph and
                    // retain the ordinary in-place recipe under the row's
                    // existing provider id, which is identity-independent
                    // and stays pinned here.
                    if !reconstructs_graph {
                        let sidecars = thread
                            .map(|thread| conversation_sidecar_refs(provider, thread))
                            .transpose()?
                            .unwrap_or_default();
                        let targets = adapter.materialization_targets(
                            &mallard_infrastructure::providers::MaterializationTargetRequest {
                                provider_home,
                                project_root: &binding.project_root,
                                provider_session_id: &local.provider_thread_id,
                                source_provider_session_id: thread
                                    .and_then(|thread| thread.source_thread_id.as_deref()),
                                existing_transcript_path: Some(local.source_path.as_path()),
                                sidecars: &sidecars,
                                planned_at: created_at,
                            },
                        )?;
                        for planned in &targets {
                            expected_provider_state.push(ProviderStateExpectation {
                                target_path: planned.target_path.to_string_lossy().into_owned(),
                                expectation: if planned.role == ConversationFileRole::Transcript {
                                    expected_local_target.clone()
                                } else {
                                    bounded_file_expectation(&planned.target_path)?
                                },
                            });
                        }
                        if provider.as_str() == "claude" {
                            if let (Some(row), Some(cloud)) = (local_binding, thread) {
                                // A child is known here by the Pull that
                                // installed it, or by the reference of the
                                // local transcript when the provider wrote
                                // it on this computer.
                                let observed = local_observation
                                    .subagents
                                    .as_ref()
                                    .and_then(|tree| tree.claude());
                                for file in &cloud.files {
                                    if let ConversationFileRole::SubagentTranscript {
                                        child_key,
                                        ..
                                    } = &file.role
                                    {
                                        if let Some(agent) = row
                                            .installed_subagents
                                            .get(child_key)
                                            .map(|child| &child.provider_thread_id)
                                            .or_else(|| {
                                                observed
                                                    .and_then(|tree| tree.children.get(child_key))
                                                    .map(|child| &child.agent_id)
                                            })
                                        {
                                            let target = claude_subagents::child_path(
                                                &local.source_path,
                                                &local.provider_thread_id,
                                                agent,
                                            )?;
                                            expected_provider_state.push(
                                                ProviderStateExpectation {
                                                    target_path: target
                                                        .to_string_lossy()
                                                        .into_owned(),
                                                    expectation: bounded_file_expectation(&target)?,
                                                },
                                            );
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if let Some(index_path) = &index_path {
                        expected_provider_state.push(ProviderStateExpectation {
                            target_path: index_path.to_string_lossy().into_owned(),
                            expectation: index_expectation
                                .clone()
                                .unwrap_or(TargetExpectation::Absent),
                        });
                    }
                }
                ConversationReviewAction::KeepBoth => {
                    // The binding move: the local rollout is never edited,
                    // only pinned byte-identical. The remote branch's fresh
                    // identities (provider alias, preserved thread, ordinal,
                    // marker title) are minted at apply.
                    let local = local.ok_or_else(|| {
                        "conversation keep-both lacks a captured local branch".to_string()
                    })?;
                    let target = local.source_path.clone();
                    expected_provider_state.push(ProviderStateExpectation {
                        target_path: target.to_string_lossy().into_owned(),
                        expectation: expected_local_target.clone(),
                    });
                    if let Some(index_path) = &index_path {
                        expected_provider_state.push(ProviderStateExpectation {
                            target_path: index_path.to_string_lossy().into_owned(),
                            expectation: index_expectation
                                .clone()
                                .unwrap_or(TargetExpectation::Absent),
                        });
                    }
                }
                ConversationReviewAction::CreateLocal => {
                    if let Some(index_path) = &index_path {
                        expected_provider_state.push(ProviderStateExpectation {
                            target_path: index_path.to_string_lossy().into_owned(),
                            expectation: index_expectation
                                .clone()
                                .unwrap_or(TargetExpectation::Absent),
                        });
                    }
                }
                _ => {}
            }
            // As on the push side: the overridden decision decides.
            let action_id = pull
                .action
                .planned_action()
                .map(|_| ActionId::parse(generated_named_id("action")?))
                .transpose()?;
            if let Some(action_id) = action_id.clone() {
                let pull_action = build_conversation_plan_action(ConversationPlanActionRequest {
                    action_id,
                    direction: ConversationPlanDirection::Pull,
                    classified,
                    provider: provider.clone(),
                    thread_id: unit_local_id.clone(),
                    cloud_thread_id: unit_cloud_id.clone(),
                    source_resource_id: source_resource_id.clone(),
                    pins: ConversationActionPins {
                        subagent_selection: Default::default(),
                        credential_redaction_enabled: thread
                            .and_then(|row| row.wire_redaction.as_ref())
                            .is_none_or(|stamp| {
                                stamp.codec != credential_redaction::REDACTION_OFF_CODEC_V1
                            }),
                        export_settings_changed: false,
                        context: ConversationContextPins {
                            host_id: binding.host_id.clone(),
                            replica_id: binding.replica_id.clone(),
                            local_project_id: binding.local_project_id.clone(),
                            provider_profile_id: profile_id.clone(),
                            host_identity_revision: host_identity.revision,
                            profile_revision: profile.revision,
                            project_binding_revision: binding.revision,
                            bindings_document_revision: document.revision,
                            binding_revision: local_binding.map(|binding| binding.revision),
                        },
                        revision: ConversationRevisionPins {
                            bundle_revision: pinned_revision,
                            commit_id: pinned_commit_id.clone(),
                            manifest_sha256: pinned_manifest_sha256.clone(),
                            scope_revision: pinned_scope_revision,
                            scope_sha256: pinned_scope_sha256.clone(),
                        },
                        tail: ConversationTailPins {
                            subagents: child_pins.clone(),
                            subagents_omitted: comparison_omitted,
                            local_only_subagents_kept: local_only_children_kept,
                            missing_local_subagents: missing_local_subagents.clone(),
                            accepted: accepted_tail_pin,
                            accepted_local: accepted_local_tail_pin,
                            local: local_tail_pin,
                            cloud: cloud_tail_pin,
                            checkpoint_generation: checkpoint_generation_pin,
                            lineage_digest: materializing_digests
                                .then(|| thread.map(|thread| thread.lineage_digest.clone()))
                                .flatten(),
                            semantic_digest: materializing_digests
                                .then(|| thread.map(|thread| thread.semantic_digest.clone()))
                                .flatten(),
                            raw_range: None,
                        },
                        target: ConversationTargetPins {
                            local: expected_local_target,
                            provider_state: expected_provider_state,
                        },
                        codec: required_codec,
                        expires_at,
                    },
                })?
                .expect("selectable Pull classification produces an action");
                pull_actions.push(pull_action);
            }
            let installs_bytes = pull_action_installs_bytes(pull.action);
            pull_review.push(ConversationReviewRow {
                stored_without_credential_redaction: thread
                    .and_then(|row| row.wire_redaction.as_ref())
                    .is_some_and(|stamp| {
                        stamp.codec == credential_redaction::REDACTION_OFF_CODEC_V1
                    }),
                provider: provider.clone(),
                thread_id: unit_local_id.clone(),
                cloud_thread_id: unit_cloud_id.clone(),
                resource_id: review_resource_id,
                action: pull.action,
                blocker: pull.blocker,
                blocked_reason: pull.blocked_reason.clone(),
                action_id,
                // The stored title only. Deliberately not `display_name` from
                // above: that one tails off into the descriptor name and then
                // the raw id, and a Claude descriptor's name IS the session
                // UUID, so reusing it would print an id as a title.
                display_title: thread.and_then(|thread| thread.display_title.clone()),
                source_size: installs_bytes
                    .then(|| {
                        thread.and_then(|thread| {
                            snapshot.map(|snapshot| snapshot.manifest.conversation_bytes(thread))
                        })
                    })
                    .flatten(),
                stored_ended_at: thread.and_then(|thread| thread.last_message_at()),
            });
        }
    }
    let mut prepared_codex = BTreeMap::new();
    if reconstructs_graph && purpose == ReviewPurpose::PushPlan {
        let mut roots = reviewed_roots
            .into_inner()
            .map_err(|_| "Codex review snapshot lock failed")?;
        let mut retained_bytes = 0_u64;
        for action in &push_actions {
            let Some(resource_id) = action.source_resource_id.as_ref() else {
                continue;
            };
            let prepared = (|| {
                let local = action
                    .thread_id
                    .as_ref()
                    .and_then(|id| local_threads.get(id))
                    .ok_or("Codex review source is missing")?;
                child_lookup.verify_current(&local.provider_thread_id, &local.source_path)?;
                let (root, sources) = match roots.remove(&local.source_path) {
                    Some(root) => root,
                    None => {
                        let transcript = &local
                            .captured
                            .as_ref()
                            .ok_or("Codex review capture is missing")?
                            .transcript;
                        codex_history_graph::resolve_captured_codex_root(
                            &local.source_path,
                            transcript.bytes.clone(),
                            transcript
                                .source_stamp
                                .clone()
                                .ok_or("Codex review source stamp is missing")?,
                            &|id| child_lookup.find_rollout(id),
                        )?
                    }
                };
                let tree = if action.pins.subagent_selection.wire_children
                    == ConversationWireChildren::Off
                {
                    codex_subagents::CapturedTree::omitted()
                } else {
                    codex_subagents::capture_resolved_tree(
                        &root,
                        &sources,
                        local.binding.as_ref(),
                        &child_lookup,
                    )?
                };
                let size = sources
                    .values()
                    .map(|(bytes, _)| bytes.len() as u64)
                    .sum::<u64>()
                    + tree
                        .children
                        .values()
                        .flat_map(|child| child.sources.values())
                        .map(|(bytes, _)| bytes.len() as u64)
                        .sum::<u64>();
                if retained_bytes.saturating_add(size) > provider_capture::MAX_CAPTURE_BYTES {
                    return Err("Codex review exceeds the aggregate capture limit".into());
                }
                retained_bytes += size;
                Ok(PreparedCodexPublication {
                    root,
                    sources,
                    tree,
                })
            })();
            prepared_codex.insert(resource_id.clone(), prepared);
        }
    }
    Ok(ThreadReview {
        prepared_codex,
        entries,
        push_actions,
        pull_actions,
        pull_review,
        suppressed_provider_ids: suppressed_provider_ids
            .into_iter()
            .map(|provider_id| (provider.clone(), provider_id))
            .collect(),
        provider_errors: BTreeMap::new(),
    })
}

/// Mint one provider thread ID for a new local copy (CreateLocal or the
/// remote branch of KeepBoth) through the provider adapter's own allocator.
/// Minted IDs join the occupied set so one review never proposes the same
/// identity twice.
fn mint_provider_thread_id(
    adapter: &dyn mallard_infrastructure::providers::SessionAdapter,
    occupied: &mut BTreeSet<String>,
) -> Result<String, String> {
    let taken = |candidate: &str| occupied.contains(candidate);
    let minted = adapter.mint_provider_thread_id(&taken)?;
    occupied.insert(minted.clone());
    Ok(minted)
}

/// The sidecar references (`(kind, kind-relative path)`) carried by one
/// portable conversation, decoded from its canonical sidecar namespace
/// (keyed by the row's own cloud thread id).
fn conversation_sidecar_refs(
    provider: &ProviderKey,
    thread: &ConversationThread,
) -> Result<Vec<(String, String)>, String> {
    let prefix = format!(
        "state/conversations/{}/{}/sidecars/",
        provider, thread.thread_id
    );
    let mut sidecars = Vec::new();
    for file in &thread.files {
        if let ConversationFileRole::Sidecar { sidecar_kind } = &file.role {
            let remainder = file
                .logical_path
                .as_str()
                .strip_prefix(&prefix)
                .and_then(|rest| rest.strip_prefix(&format!("{}/", sidecar_kind)))
                .ok_or_else(|| {
                    format!(
                        "conversation sidecar '{}' is outside its namespace",
                        file.logical_path
                    )
                })?;
            sidecars.push((sidecar_kind.clone(), remainder.to_string()));
        }
    }
    Ok(sidecars)
}

