struct ProjectLocalRead {
    activity_project: ResolvedActivityProject,
    resolved: ResolvedBinding,
    discovery: Discovery,
    views: Vec<LocalSessionView>,
}

fn load_project_local_read(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
) -> Result<ProjectLocalRead, String> {
    let state = repository.load_project_activity_state_snapshot()?;
    load_project_local_read_from_state(repository.root(), &state, local_project_id)
}

fn load_project_local_read_from_state(
    repository_root: &Path,
    state: &LocalProjectActivityStateSnapshot,
    local_project_id: &LocalProjectId,
) -> Result<ProjectLocalRead, String> {
    let activity_project = project_activity::resolve_activity_project_from_state(
        &state.config,
        &state.bindings,
        local_project_id,
    )?;
    let resolved = ResolvedBinding {
        binding: activity_project.binding.clone(),
        homes: activity_project
            .homes
            .iter()
            .map(|(provider, home)| (provider.clone(), home.home.to_string_lossy().into_owned()))
            .collect(),
    };
    let capture_request = capture_request_for_resolved_binding_from_state(
        repository_root,
        &state.config,
        &state.bindings,
        &resolved,
    )?;
    let (discovery, views) =
        provider_capture::discover_sessions(provider_registry(), &capture_request)?;
    Ok(ProjectLocalRead {
        activity_project,
        resolved,
        discovery,
        views,
    })
}

/// Observe a linked bundle, and classify the continuity of this link's
/// history on it. Nothing is written. A base or an acceptance that names a
/// publication off the selected chain is stale: every comparison reads it as
/// absent (`classify_scope_continuity`, `ConversationCheckpoint::read_on`),
/// and the next Push or Pull replaces it. When the publication a stale base
/// was reviewed in is listed and connected to the chain, another computer's
/// record outranked it after this computer's Push was confirmed, or after
/// its Pull: the verdict is `Displaced`, with which of the two saved it, and
/// the standing notice tells the user. Recovery is a user action (CAS-free
/// plan, decision 12): no base returns to a shared ancestor, no acceptance is
/// forgotten, no event is sent, and the user compares and pushes again.
fn observe_linked_bundle(
    repository: &LocalStateRepository,
    engine: &StorageEngine,
    link: &ProjectStorageLink,
) -> Result<(BundleObservation, RemoteContinuity), String> {
    let observation = engine.observe(&link.bundle_id)?;
    let continuity = classify_remote_continuity(
        &observation.mainline,
        &observation.unselected,
        repository_bases(link),
        |displaced| {
            // One read of an immutable record, only while displaced: whether
            // this computer's copy of the project published it.
            let origin = engine.published_by(&link.bundle_id, displaced)?;
            let binding = repository
                .load_bindings()?
                .active_for(&link.local_project_id)
                .cloned()
                .ok_or_else(|| {
                    format!(
                        "project '{}' is not mapped on this machine",
                        link.local_project_id
                    )
                })?;
            let (_, own) = repository.derive_origin_tokens(&link.bundle_id, &binding.replica_id)?;
            Ok(if origin.origin_replica_token == own {
                SavedBy::Push
            } else {
                SavedBy::Pull
            })
        },
    )?;
    Ok((observation, continuity))
}

struct ProjectRemoteRead {
    storage_name: String,
    link: ProjectStorageLink,
    engine: StorageEngine,
    current: Option<BundleSnapshot>,
    mainline: Mainline,
    remote_continuity: RemoteContinuity,
}

fn load_project_remote_read(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<ProjectRemoteRead, String> {
    let state = repository.load_project_state_snapshot()?;
    let config = &state.config;
    let project = config
        .project(local_project_id)
        .cloned()
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
    let link = require_project_link(&config, &project, storage_id)?.clone();
    let storage_name = config
        .storages
        .iter()
        .find(|storage| storage.id == *storage_id)
        .map(|storage| storage.name.clone())
        .ok_or_else(|| format!("unknown storage '{}'", storage_id))?;
    let (_, engine) = storage_engine_from_state(repository, config, &state.bindings, storage_id)?;
    let (observation, remote_continuity) = observe_linked_bundle(repository, &engine, &link)?;
    Ok(ProjectRemoteRead {
        storage_name,
        link,
        engine,
        current: observation.current.map(|(snapshot, _)| snapshot),
        mainline: observation.mainline,
        remote_continuity,
    })
}

fn build_comparison_from_reads(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
    local: &ProjectLocalRead,
    remote: &ProjectRemoteRead,
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<ThreadSyncComparison, String> {
    build_thread_sync_comparison(
        repository,
        local_project_id,
        storage_id,
        remote.storage_name.clone(),
        &remote.link,
        &local.resolved,
        &local.discovery,
        &local.views,
        &remote.engine,
        remote.current.as_ref(),
        &remote.mainline,
        remote.remote_continuity.clone(),
        on_phase,
        &mallard_infrastructure::app_settings::load_app_settings(repository)?,
    )
}

pub(super) fn get_project_thread_sync_comparison_with_progress(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<ThreadSyncComparison, String> {
    let metrics_before = mallard_infrastructure::sync_metrics::global_snapshot();
    let phase_started = Instant::now();
    let local = load_project_local_read(repository, local_project_id)?;
    on_phase(
        "load binding and discover local state",
        phase_started.elapsed(),
    );
    let phase_started = Instant::now();
    let remote = load_project_remote_read(repository, local_project_id, storage_id)?;
    on_phase("inspect remote head", phase_started.elapsed());
    let comparison = build_comparison_from_reads(
        repository,
        local_project_id,
        storage_id,
        &local,
        &remote,
        on_phase,
    )?;
    mallard_infrastructure::sync_metrics::log_operation_delta("refresh", &metrics_before);
    Ok(comparison)
}

/// Thread-comparison section over discovery metadata and one already-read
/// remote snapshot. Full local transcripts are not captured here.
#[allow(clippy::too_many_arguments)]
fn build_thread_sync_comparison(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
    storage_name: String,
    link: &ProjectStorageLink,
    resolved: &ResolvedBinding,
    discovery: &provider_capture::Discovery,
    views: &[provider_capture::LocalSessionView],
    engine: &StorageEngine,
    current: Option<&BundleSnapshot>,
    mainline: &Mainline,
    remote_continuity: RemoteContinuity,
    on_phase: &mut dyn FnMut(&str, Duration),
    settings: &AppSettings,
) -> Result<ThreadSyncComparison, String> {
    let phase_started = Instant::now();
    let discovered = discovery.project_inventory();
    let mut warnings = discovered.warnings.clone();
    // Compare uses discovery metadata, stored checkpoints, and bounded tail
    // observations only. It never captures full payloads or builds actions.
    let created_at = now_secs();
    let captured = provider_capture::CapturedResources::default();
    let no_pins = BTreeMap::new();
    let mut review = match current {
        Some(snapshot) => {
            let mut bytes = engine.byte_source(snapshot, None);
            thread_review(
                repository,
                Some(snapshot),
                mainline,
                &mut bytes,
                views,
                &captured,
                &no_pins,
                resolved,
                Some(storage_id),
                created_at,
                created_at,
                ReviewPurpose::Observe,
                None,
                &settings,
            )?
        }
        None => {
            let mut bytes = EmptyBundleBytes;
            thread_review(
                repository,
                None,
                mainline,
                &mut bytes,
                views,
                &captured,
                &no_pins,
                resolved,
                Some(storage_id),
                created_at,
                created_at,
                ReviewPurpose::Observe,
                None,
                &settings,
            )?
        }
    };
    on_phase("compare conversations", phase_started.elapsed());
    let phase_started = Instant::now();

    // Locally discovered but uncapturable sessions of any bound provider
    // hold their own row instead of failing the review.
    let represented_provider_ids = review
        .entries
        .iter()
        .filter_map(|entry| {
            entry
                .provider_thread_id
                .clone()
                .map(|provider_id| (entry.provider.clone(), provider_id))
        })
        .collect::<BTreeSet<_>>();
    let state = repository.load_project_activity_state_snapshot()?;
    let conversation_bindings = &state.conversation_bindings;
    let fallback_config = &state.config;
    // Providers whose adapter reconstructs a rollout graph keep alias owners
    // and scoped bindings for standalone-thread fallback identity.
    let mut graph_fallback_state = BTreeMap::new();
    for (provider, profile_id) in &resolved.binding.profile_ids {
        if !provider_registry()
            .get(provider)
            .is_some_and(|adapter| adapter.reconstructs_rollout_graph())
        {
            continue;
        }
        let scoped = conversation_bindings
            .bindings
            .iter()
            .filter(|binding| {
                binding.host_id == resolved.binding.host_id
                    && binding.replica_id == resolved.binding.replica_id
                    && binding.local_project_id == resolved.binding.local_project_id
                    && binding.provider_profile_id == *profile_id
            })
            .cloned()
            .collect::<Vec<_>>();
        graph_fallback_state.insert(
            provider.clone(),
            (
                applied_provider_alias_owners(
                    &state.materializations,
                    &resolved.binding,
                    provider,
                    profile_id,
                ),
                scoped,
            ),
        );
    }
    for candidate in discovered.resources.iter().filter(|candidate| {
        kind_primitive(&candidate.kind) == Some(ResourceKindPrimitive::Conversation)
    }) {
        let Some(provider) = candidate.provider.clone() else {
            continue;
        };
        let provider_thread_id = provider_session_id_from_resource(&candidate.resource_id)
            .unwrap_or(&candidate.display_name)
            .to_string();
        if represented_provider_ids.contains(&(provider.clone(), provider_thread_id.clone()))
            || review
                .suppressed_provider_ids
                .contains(&(provider.clone(), provider_thread_id.clone()))
        {
            continue;
        }
        let detail = thread_capture_unavailable_detail(candidate.blocked_reason.as_deref());
        let blocked = ConversationDecision {
            action: ConversationReviewAction::Blocked,
            blocker: Some(ConversationBlocker::CodecUnsupported),
            selectable: false,
            blocked_reason: Some(detail.clone()),
        };
        let provider_display_name = provider_registry()
            .get(&provider)
            .map(|adapter| adapter.descriptor().display_name)
            .unwrap_or_else(|| provider.to_string());
        let bound_thread_id = conversation_bindings
            .bindings
            .iter()
            .find(|binding| {
                binding.local_project_id == *local_project_id
                    && binding.provider_thread_id.as_deref() == Some(&provider_thread_id)
                    && resolved.binding.profile_ids.get(&provider)
                        == Some(&binding.provider_profile_id)
            })
            .map(|binding| binding.thread_id.clone());
        let thread_id = if let Some(thread_id) = bound_thread_id {
            thread_id
        } else if let (Some((owners, scoped)), Some(view)) = (
            graph_fallback_state.get(&provider),
            views.iter().find(|view| {
                view.provider == provider && view.provider_thread_id == provider_thread_id
            }),
        ) {
            let moved_owners = displaced_provider_alias_owners(
                &resolved.binding.bundle_id,
                &provider,
                &provider_thread_id,
                scoped,
                owners,
            )?;
            if moved_owners.is_empty() {
                initial_conversation_thread_id(
                    &resolved.binding.bundle_id,
                    &provider,
                    &provider_thread_id,
                )?
            } else {
                project_activity::retained_provider_alias_identity(
                    &resolved.binding.bundle_id,
                    &resolved.binding.local_project_id,
                    &provider,
                    &provider_thread_id,
                    &view.source_path,
                    &moved_owners,
                    &scoped
                        .iter()
                        .map(|binding| binding.thread_id.clone())
                        .collect(),
                    &fallback_config,
                )?
                .0
            }
        } else {
            initial_conversation_thread_id(
                &resolved.binding.bundle_id,
                &provider,
                &provider_thread_id,
            )?
        };
        review.entries.push(ThreadSyncEntry {
            subagent_selection: SubagentSelection::default(),
            provider: provider.clone(),
            provider_display_name,
            access: ProviderAccessState::BoundReady,
            thread_id: provider_thread_id.clone(),
            conversation_resource_id: conversation_resource_id(&provider, &thread_id)?,
            resource_id: ResourceId::parse(candidate.resource_id.clone())?,
            display_name: candidate.display_name.clone(),
            state: ThreadSyncState::Unavailable,
            local_present: true,
            storage_present: false,
            status_detail: Some(detail),
            local_updated_at: None,
            storage_updated_at: None,
            cloud_thread_id: None,
            forked_from: None,
            // Capture-blocked candidates never enter the typed pipeline —
            // no relation was computed against the storage for this row.
            compared_against_storage: false,
            provider_thread_id: Some(provider_thread_id),
            capture_bytes: views
                .iter()
                .find(|view| view.descriptor.resource_id == candidate.resource_id)
                .map(|view| view.capture_bytes),
            pull_bytes: None,
            push_decision: blocked.clone(),
            pull_decision: blocked,
        });
    }

    // Remote provider scopes without a local binding stay visible as
    // view-only rows: mixed repositories remain fully visible from a
    // single-provider binding, and viewing never advances a base.
    if let Some(snapshot) = current {
        for (provider, scope) in snapshot.manifest.provider_scopes() {
            if resolved.binding.profile_ids.contains_key(provider) {
                continue;
            }
            let registered = provider_registry().contains(provider);
            let provider_display_name = provider_registry()
                .get(provider)
                .map(|adapter| adapter.descriptor().display_name)
                .unwrap_or_else(|| provider.to_string());
            let access = if registered {
                ProviderAccessState::ViewOnly
            } else {
                ProviderAccessState::Unsupported
            };
            let view_only = ConversationDecision {
                action: ConversationReviewAction::Blocked,
                blocker: Some(ConversationBlocker::MissingBinding),
                selectable: false,
                blocked_reason: Some(if registered {
                    format!(
                        "View only — connect a {} profile to sync this session.",
                        provider_display_name
                    )
                } else {
                    format!(
                        "View only — this Mallard build has no '{}' provider.",
                        provider
                    )
                }),
            };
            for (thread_id, thread) in &scope.conversations {
                review.entries.push(ThreadSyncEntry {
                    subagent_selection: SubagentSelection::default(),
                    provider: provider.clone(),
                    provider_display_name: provider_display_name.clone(),
                    access,
                    thread_id: thread
                        .source_thread_id
                        .clone()
                        .unwrap_or_else(|| thread_id.to_string()),
                    conversation_resource_id: cloud_conversation_resource_id(provider, thread_id)?,
                    resource_id: thread.resource_id.clone(),
                    display_name: thread
                        .display_title
                        .clone()
                        .unwrap_or_else(|| thread_id.to_string()),
                    state: ThreadSyncState::StorageOnly,
                    local_present: false,
                    storage_present: true,
                    status_detail: view_only.blocked_reason.clone(),
                    local_updated_at: None,
                    storage_updated_at: Some(thread.updated_at),
                    cloud_thread_id: Some(thread_id.clone()),
                    forked_from: thread.forked_from.clone(),
                    compared_against_storage: true,
                    provider_thread_id: thread.source_thread_id.clone(),
                    capture_bytes: None,
                    pull_bytes: Some(snapshot.manifest.conversation_bytes(thread)),
                    push_decision: view_only.clone(),
                    pull_decision: view_only.clone(),
                });
            }
        }
    }

    review.entries.sort_by(|left, right| {
        right
            .local_updated_at
            .into_iter()
            .chain(right.storage_updated_at)
            .max()
            .cmp(
                &left
                    .local_updated_at
                    .into_iter()
                    .chain(left.storage_updated_at)
                    .max(),
            )
            .then_with(|| left.provider.cmp(&right.provider))
            .then_with(|| left.thread_id.cmp(&right.thread_id))
    });
    let mut counts = ThreadSyncCounts::default();
    for entry in &review.entries {
        count_thread_sync_state(&mut counts, entry.state);
    }
    for error in review.provider_errors.values() {
        warnings.push(error.clone());
    }
    warnings.sort();
    warnings.dedup();
    on_phase("classify threads and build review", phase_started.elapsed());

    let scopes = scope_sync_rows(link, resolved, current, mainline);
    let reserved_bytes = discovered
        .resources
        .iter()
        .filter(|candidate| {
            kind_primitive(&candidate.kind) != Some(ResourceKindPrimitive::Conversation)
                && candidate.blocked_reason.is_none()
        })
        .map(|candidate| discovery.capture_bytes_of(&candidate.resource_id))
        .fold(0_u64, u64::saturating_add);
    if link.managed_cloud_repository_id.is_some() {
        for entry in &mut review.entries {
            if entry.status_detail.is_none() {
                entry.status_detail = match entry.state {
                    ThreadSyncState::Synced => Some("Synced to the Cloud draft."),
                    ThreadSyncState::LocalOnly => {
                        Some("Not in the Cloud draft. Push to save it there.")
                    }
                    ThreadSyncState::LocalAhead => {
                        Some("Changes to push. Push to update the Cloud draft.")
                    }
                    ThreadSyncState::StorageOnly => {
                        Some("In the Cloud draft. Pull to download it here.")
                    }
                    ThreadSyncState::StorageAhead => Some("Changes to pull from the Cloud draft."),
                    _ => None,
                }
                .map(str::to_owned);
            }
        }
    }
    Ok(ThreadSyncComparison {
        managed_cloud_status: link
            .managed_cloud_repository_id
            .as_ref()
            .and_then(|_| engine.store().managed_cloud()?.status(&link.bundle_id)),
        project_id: local_project_id.clone(),
        storage_id: storage_id.clone(),
        storage_name,
        revision: current.map(|snapshot| snapshot.head.revision),
        base_revision: repository_base_from_link(link).map(|base| base.revision),
        compared_at: created_at,
        entries: review.entries,
        counts,
        scopes,
        provider_errors: review.provider_errors,
        warnings,
        capture_budget: Some(CaptureBudget {
            limit_bytes: provider_capture::MAX_CAPTURE_BYTES,
            reserved_bytes,
        }),
        remote_continuity,
    })
}

/// One continuity row per sync scope: the project scope plus every provider
/// scope present locally (bound) or remotely.
fn scope_sync_rows(
    link: &ProjectStorageLink,
    resolved: &ResolvedBinding,
    current: Option<&BundleSnapshot>,
    mainline: &Mainline,
) -> Vec<ScopeSyncRow> {
    let mut scope_keys = BTreeSet::new();
    scope_keys.insert(SyncScopeKey::Project);
    for provider in resolved.binding.profile_ids.keys() {
        scope_keys.insert(SyncScopeKey::Provider(provider.clone()));
    }
    if let Some(snapshot) = current {
        for key in snapshot.manifest.scopes.keys() {
            scope_keys.insert(key.clone());
        }
    }
    for key in link.scope_bases.keys() {
        scope_keys.insert(key.clone());
    }
    scope_keys
        .into_iter()
        .map(|key| {
            let remote = current
                .and_then(|snapshot| snapshot.manifest.scope(&key))
                .map(|scope| (scope.revision, scope.content_sha256.clone()));
            let base = link.scope_bases.get(&key);
            let continuity = classify_scope_continuity(
                remote
                    .as_ref()
                    .map(|(revision, digest)| (*revision, digest.as_str())),
                base,
                mainline,
            );
            let provider = key.provider_key().cloned();
            let access = match &provider {
                None => ProviderAccessState::BoundReady,
                Some(provider) if resolved.homes.contains_key(provider) => {
                    ProviderAccessState::BoundReady
                }
                Some(provider) if resolved.binding.profile_ids.contains_key(provider) => {
                    ProviderAccessState::BoundUnavailable
                }
                Some(provider) if provider_registry().contains(provider) => {
                    ProviderAccessState::ViewOnly
                }
                Some(_) => ProviderAccessState::Unsupported,
            };
            ScopeSyncRow {
                scope: key.canonical(),
                provider,
                access,
                remote_revision: remote.as_ref().map(|(revision, _)| *revision),
                base_revision: base.map(|base| base.scope_revision),
                continuity,
            }
        })
        .collect()
}
/// One-call preparation for the Push dialog: a single provider walk, one
/// engine construction, and one remote head+manifest read feed every section.
/// Sections that can degrade (thread comparison, capabilities, project files)
/// carry per-section errors instead of failing the whole dialog, preserving
/// the storage-offline behavior of the standalone commands.
#[derive(Serialize, Clone, Debug, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum PushDestinationPullReason {
    RemoteWithoutBase,
    BindingChanged,
    RemoteAdvanced,
}

#[derive(Serialize, Clone, Debug, PartialEq, Eq)]
#[serde(tag = "state", rename_all = "snake_case")]
pub enum PushDestinationStatus {
    Ready {
        #[serde(skip_serializing_if = "Option::is_none")]
        revision: Option<u64>,
    },
    RequiresPull {
        reason: PushDestinationPullReason,
        remote_revision: u64,
        #[serde(skip_serializing_if = "Option::is_none")]
        base_revision: Option<u64>,
        /// The writable scopes that actually block this Push. Unbound and
        /// unknown provider scopes never appear here.
        #[serde(default)]
        blocking_scopes: Vec<String>,
    },
    Unavailable {
        message: String,
    },
}

/// The sync scopes a Push from this binding may write: the project scope
/// plus one scope per bound provider.
fn writable_scopes_for_binding(binding: &ProjectBinding) -> BTreeSet<SyncScopeKey> {
    let mut scopes = BTreeSet::new();
    scopes.insert(SyncScopeKey::Project);
    for provider in binding.profile_ids.keys() {
        scopes.insert(SyncScopeKey::Provider(provider.clone()));
    }
    scopes
}

/// Push-side destination status, decided per writable scope so unrelated
/// provider changes never block each other (D6): each writable scope compares
/// its reviewed base with the verified current manifest. Ancestry answers
/// whether the remote moved forward; the scope digest answers whether this
/// Push's own scopes were touched. A remote change in an unbound or unknown
/// provider scope is carried, not blocking.
///
/// A history that was cleared, or cleared and pushed again, is no blocker of
/// its own. Its bases are stale and read as absent, so the same rows decide:
/// a scope the stream no longer holds is a first publication target, and a
/// scope another computer wrote since is one this computer never reviewed.
/// A Push onto an empty stream writes its first record.
fn classify_push_destination(
    current: Option<&BundleSnapshot>,
    mainline: &Mainline,
    link: &ProjectStorageLink,
    binding: &ProjectBinding,
) -> PushDestinationStatus {
    let remote_revision = current.map(|snapshot| snapshot.head.revision);
    // The binding-revision overlay is push policy, not continuity: a base
    // reviewed under an older binding cannot authorize this Push.
    let stale_binding_scopes = writable_scopes_for_binding(binding)
        .into_iter()
        .filter(|scope| {
            link.scope_bases
                .get(scope)
                .is_some_and(|base| base.binding_revision != binding.revision)
        })
        .map(|scope| scope.canonical())
        .collect::<Vec<_>>();
    if !stale_binding_scopes.is_empty() {
        return PushDestinationStatus::RequiresPull {
            reason: PushDestinationPullReason::BindingChanged,
            remote_revision: remote_revision.unwrap_or(0),
            base_revision: repository_base_from_link(link).map(|base| base.revision),
            blocking_scopes: stale_binding_scopes,
        };
    }
    let mut unreviewed_scopes = Vec::new();
    let mut advanced_scopes = Vec::new();
    for scope in writable_scopes_for_binding(binding) {
        let remote = current
            .and_then(|snapshot| snapshot.manifest.scope(&scope))
            .map(|remote| (remote.revision, remote.content_sha256.clone()));
        let base = link.scope_bases.get(&scope);
        match classify_scope_continuity(
            remote
                .as_ref()
                .map(|(revision, digest)| (*revision, digest.as_str())),
            base,
            mainline,
        ) {
            ScopeContinuity::Fresh | ScopeContinuity::InSync { .. } => {}
            // The scope disappeared remotely while global lineage held: a
            // pull re-reviews before this replica may republish it.
            ScopeContinuity::RemoteMissing { .. } | ScopeContinuity::Advanced { .. } => {
                advanced_scopes.push(scope.canonical())
            }
            ScopeContinuity::Unreviewed { .. } => unreviewed_scopes.push(scope.canonical()),
        }
    }
    if !advanced_scopes.is_empty() {
        return PushDestinationStatus::RequiresPull {
            reason: PushDestinationPullReason::RemoteAdvanced,
            remote_revision: remote_revision.unwrap_or(0),
            base_revision: repository_base_from_link(link).map(|base| base.revision),
            blocking_scopes: advanced_scopes,
        };
    }
    if !unreviewed_scopes.is_empty() {
        return PushDestinationStatus::RequiresPull {
            reason: PushDestinationPullReason::RemoteWithoutBase,
            remote_revision: remote_revision.unwrap_or(0),
            base_revision: None,
            blocking_scopes: unreviewed_scopes,
        };
    }
    PushDestinationStatus::Ready {
        revision: remote_revision,
    }
}

fn push_destination_error(status: &PushDestinationStatus) -> Option<String> {
    match status {
        PushDestinationStatus::Ready { .. } => None,
        // These reach the user verbatim in the Push error banner when the head
        // moves between the review's classification and the publish re-check,
        // so they lead with what happened and what to do; the lineage numbers
        // stay at the end for support and log greps.
        PushDestinationStatus::RequiresPull {
            reason: PushDestinationPullReason::RemoteWithoutBase,
            ..
        } => Some(
            "this storage already holds data for this project that has never been reviewed on this computer; pull and review it before pushing"
                .to_string(),
        ),
        PushDestinationStatus::RequiresPull {
            reason: PushDestinationPullReason::BindingChanged,
            ..
        } => Some(
            "the project folder or an agent profile changed since this computer last synced with this storage; pull and review before pushing"
                .to_string(),
        ),
        PushDestinationStatus::RequiresPull {
            reason: PushDestinationPullReason::RemoteAdvanced,
            remote_revision,
            base_revision,
            blocking_scopes,
        } => Some(format!(
            "this storage has changes saved after this computer last synced ({}); pull and review them before pushing (base version {}, remote version {})",
            blocking_scopes.join(", "),
            base_revision
                .map(|revision| revision.to_string())
                .unwrap_or_else(|| "unknown".to_string()),
            remote_revision,
        )),
        PushDestinationStatus::Unavailable { message } => Some(message.clone()),
    }
}

#[derive(Serialize, Clone, Debug)]
pub struct PushReviewContext {
    pub credential_redaction_enabled: bool,
    pub project: ProjectDetail,
    pub inventory: ResourceInventory,
    pub destination_status: PushDestinationStatus,
    pub thread_comparison: Option<ThreadSyncComparison>,
    pub thread_comparison_error: Option<String>,
    pub project_files: Option<ProjectContentInventory>,
    pub project_files_error: Option<String>,
    pub git_history: Option<mallard_domain::GitHistorySnapshot>,
    pub git_history_review_token: Option<String>,
    pub prepared_at: u64,
    pub git_history_changed: bool,
    /// The commits this Push adds, against storage's history. `None` when
    /// storage has none, or none this branch shares.
    pub git_history_outgoing: Option<mallard_domain::GitHistoryOutgoing>,
}

/// Git history travels only to Mallard Cloud, the one storage that shows it.
/// Every other storage gets none: no capture, no review token, and so no
/// history-only Push.
fn capture_binding_git_history(
    config: &SyncConfig,
    storage_id: &StorageId,
    project: &LocalProjectRegistration,
    binding: &ProjectBinding,
) -> Result<Option<mallard_domain::GitHistorySnapshot>, String> {
    let shows_git_history = config.storages.iter().any(|storage| {
        storage.id == *storage_id
            && storage.provider
                == mallard_infrastructure::storage_providers::managed_cloud::provider_key()
    });
    if !shows_git_history {
        return Ok(None);
    }
    if project.repository_fingerprint.is_some() {
        if project_file_sync_eligibility(binding).state
            != ProjectFileSyncEligibilityState::GitManaged
        {
            return Err(
                "The Git project is unavailable. Restore its repository before Push.".into(),
            );
        }
        project_activity::capture_git_history(Path::new(&binding.project_root)).map(Some)
    } else {
        Ok(None)
    }
}

#[cfg(test)]
fn prepare_push_review_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<PushReviewContext, String> {
    prepare_push_review_with_progress(repository, local_project_id, storage_id, &mut |_, _| {})
}

pub(super) fn prepare_push_review_with_progress(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<PushReviewContext, String> {
    let phase_started = Instant::now();
    // The review token minted here is what a later push validates, so mint it
    // while pushes, pulls, and repairs are excluded.
    let _host_operation = repository.acquire_host_operation()?;
    let settings = mallard_infrastructure::app_settings::load_app_settings(repository)?;
    let credential_redaction_enabled = settings.credential_redaction_enabled;
    let state = repository.load_project_state_snapshot()?;
    let config = &state.config;
    let project = config
        .project(local_project_id)
        .cloned()
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
    let link = require_project_link(&config, &project, storage_id)?.clone();
    let storage_name = config
        .storages
        .iter()
        .find(|storage| storage.id == *storage_id)
        .map(|storage| storage.name.clone())
        .ok_or_else(|| format!("unknown storage '{}'", storage_id))?;
    let machine = &state.bindings;
    let binding = machine
        .active_for(local_project_id)
        .cloned()
        .ok_or_else(|| {
            format!(
                "project '{}' is not mapped on this machine",
                local_project_id
            )
        })?;
    let resolved = resolve_project_binding_from_state(machine, &binding)?;

    on_phase("load config and binding", phase_started.elapsed());
    let phase_started = Instant::now();

    // Project content stays out of the dialog-open walk: eligible (non-Git)
    // projects defer it to the explicit Scan, and Git-managed projects get a
    // storage-side inventory below without any local content walk.
    let eligibility = project_file_sync_eligibility(&binding);
    let capture_request = capture_request_for_resolved_binding_from_state(
        repository.root(),
        config,
        machine,
        &resolved,
    )?;
    let (discovery, views) =
        provider_capture::discover_sessions(provider_registry(), &capture_request)?;
    on_phase("discover local state", phase_started.elapsed());
    let phase_started = Instant::now();

    let inventory = build_resource_inventory(config, local_project_id, &binding, &discovery)?;

    on_phase("build resource inventory", phase_started.elapsed());
    let phase_started = Instant::now();

    let remote = storage_engine_from_state(repository, config, machine, storage_id).and_then(
        |(_, engine)| {
            let (observation, continuity) = observe_linked_bundle(repository, &engine, &link)?;
            let current = observation.current.map(|(snapshot, _)| snapshot);
            Ok((engine, current, observation.mainline, continuity))
        },
    );
    // Continuity is classified from the one listing the observation made;
    // the destination status maps it push-side and the thread comparison
    // carries it verbatim.
    let (destination_status, remote_continuity) = match &remote {
        Ok((_, current, mainline, continuity)) => {
            let destination =
                classify_push_destination(current.as_ref(), mainline, &link, &binding);
            (destination, Some(continuity.clone()))
        }
        Err(error) => (
            PushDestinationStatus::Unavailable {
                message: error.clone(),
            },
            None,
        ),
    };
    on_phase("inspect remote head", phase_started.elapsed());

    // Every bound provider participates in the typed thread comparison.
    let wants_thread_comparison = !binding.profile_ids.is_empty();
    // Only Git-managed projects surface a stored project-files inventory here
    // (remote/base entries, no local walk). Eligible projects use the explicit
    // Scan button instead.
    let wants_project_files = eligibility.state == ProjectFileSyncEligibilityState::GitManaged;
    let mut thread_comparison = None;
    let mut thread_comparison_error = None;
    let mut project_files = None;
    let mut project_files_error = None;
    match &remote {
        Ok((engine, current, mainline, _)) => {
            if wants_thread_comparison {
                let phase_started = Instant::now();
                match build_thread_sync_comparison(
                    repository,
                    local_project_id,
                    storage_id,
                    storage_name.clone(),
                    &link,
                    &resolved,
                    &discovery,
                    &views,
                    engine,
                    current.as_ref(),
                    mainline,
                    remote_continuity
                        .clone()
                        .expect("continuity is classified whenever the storage engine opened"),
                    &mut *on_phase,
                    &settings,
                ) {
                    Ok(comparison) => thread_comparison = Some(comparison),
                    Err(error) => thread_comparison_error = Some(error),
                }
                on_phase("thread comparison", phase_started.elapsed());
            }
            if wants_project_files {
                let phase_started = Instant::now();
                match build_project_files_inventory(
                    local_project_id,
                    storage_id,
                    &project,
                    &link,
                    &binding,
                    eligibility.clone(),
                    engine,
                    current.as_ref(),
                    mainline,
                    // Git-managed inventories never walk local content, so the
                    // shared discovery (walked without it) is not offered.
                    None,
                ) {
                    Ok(inventory) => project_files = Some(inventory),
                    Err(error) => project_files_error = Some(error),
                }
                on_phase("project files inventory", phase_started.elapsed());
            }
        }
        Err(error) => {
            if wants_thread_comparison {
                thread_comparison_error = Some(error.clone());
            }
            if wants_project_files {
                project_files_error = Some(error.clone());
            }
        }
    }

    let detail = get_project_with_repository(repository, local_project_id)?
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;

    let git_history = capture_binding_git_history(config, storage_id, &project, &binding)?;
    let git_history_review_token = git_history
        .as_ref()
        .map(project_activity::git_history_review_token)
        .transpose()?;
    let stored_git_history = remote
        .as_ref()
        .ok()
        .and_then(|(_, current, _, _)| current.as_ref())
        .and_then(|snapshot| snapshot.manifest.git_history.as_ref());
    let previous_git_token = stored_git_history
        .map(|history| {
            let mut metadata = history.clone();
            metadata.map_sessions(std::iter::empty());
            project_activity::git_history_review_token(&metadata)
        })
        .transpose()?;
    let git_history_changed =
        git_history_review_token.is_some() && git_history_review_token != previous_git_token;
    let git_history_outgoing = git_history
        .as_ref()
        .zip(stored_git_history)
        .and_then(|(history, stored)| history.outgoing_since(stored));

    Ok(PushReviewContext {
        credential_redaction_enabled,
        project: detail,
        inventory,
        destination_status,
        thread_comparison,
        thread_comparison_error,
        project_files,
        project_files_error,
        git_history,
        git_history_review_token,
        git_history_changed,
        git_history_outgoing,
        prepared_at: now_secs(),
    })
}

pub(super) fn get_push_destination_status_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<PushDestinationStatus, String> {
    let _host_operation = repository.acquire_host_operation()?;
    let state = repository.load_project_state_snapshot()?;
    let config = &state.config;
    let project = config
        .project(local_project_id)
        .cloned()
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
    let link = require_project_link(&config, &project, storage_id)?.clone();
    let binding = state
        .bindings
        .active_for(local_project_id)
        .cloned()
        .ok_or_else(|| {
            format!(
                "project '{}' is not mapped on this machine",
                local_project_id
            )
        })?;
    let (_, engine) = storage_engine_from_state(repository, config, &state.bindings, storage_id)?;
    let (observation, _) = observe_linked_bundle(repository, &engine, &link)?;
    Ok(classify_push_destination(
        observation.snapshot(),
        &observation.mainline,
        &link,
        &binding,
    ))
}

#[cfg(test)]
fn push_bundle_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<ProjectOperationResult, String> {
    let service = ProjectSyncService::new(repository);
    let review = service.prepare_push_review(local_project_id, storage_id)?;
    let approval = PushApproval::recommended(&review, storage_id);
    service.push_reviewed(local_project_id, storage_id, approval)
}

pub(super) fn recommended_review_recipe(
    review: &PushReviewContext,
    storage_id: &StorageId,
) -> BundleRecipe {
    let mut recipe = review
        .project
        .links
        .iter()
        .find(|link| link.storage_id == *storage_id)
        .and_then(|link| link.recipe.clone())
        .unwrap_or_else(|| review.inventory.recipe.clone());
    let Some(comparison) = &review.thread_comparison else {
        return recipe;
    };
    for entry in comparison
        .entries
        .iter()
        .filter(|entry| entry.push_decision.selectable)
    {
        let Some(resource) = review
            .inventory
            .resources
            .iter()
            .find(|resource| resource.descriptor.resource_id == entry.resource_id)
        else {
            continue;
        };
        recipe.entries.insert(
            entry.resource_id.clone(),
            RecipeEntry {
                resource_id: entry.resource_id.clone(),
                apply_policy: resource.descriptor.apply_policy.clone(),
                required: false,
            },
        );
    }
    if comparison
        .entries
        .iter()
        .any(|entry| recipe.entries.contains_key(&entry.resource_id))
    {
        if let Some(resource) = review
            .inventory
            .resources
            .iter()
            .find(|resource| resource.descriptor.resource_id.as_str() == "codex:session-index")
        {
            recipe.entries.insert(
                resource.descriptor.resource_id.clone(),
                RecipeEntry {
                    resource_id: resource.descriptor.resource_id.clone(),
                    apply_policy: resource.descriptor.apply_policy.clone(),
                    required: false,
                },
            );
        }
    }
    recipe
}

type CapturedPublicationSource = (
    provider_capture::CapturedConversation,
    provider_capture::CapturedFile,
    BTreeMap<String, provider_capture::CapturedFile>,
);

fn take_captured_conversation_for_action(
    captured: &mut provider_capture::CapturedResources,
    action: &ConversationPlanAction,
) -> Result<CapturedPublicationSource, String> {
    let resource_id = action
        .source_resource_id
        .as_ref()
        .ok_or_else(|| "conversation Push action lacks a captured source".to_string())?;
    // A capture failure is the thread's own: the message names what went
    // wrong reading or scrubbing its source.
    if let Some(message) = captured.failed_conversations.get(resource_id.as_str()) {
        return Err(format!("capture failed: {message}"));
    }
    let conversation = captured
        .conversations
        .remove(resource_id.as_str())
        .ok_or_else(|| {
            format!(
                "reviewed conversation source '{}' is no longer capturable",
                resource_id
            )
        })?;
    let transcript = captured
        .files
        .remove(&conversation.transcript_logical_path)
        .ok_or_else(|| {
            format!(
                "reviewed conversation source '{}' lost its transcript",
                resource_id
            )
        })?;
    let mut sidecars = BTreeMap::new();
    for sidecar in &conversation.sidecar_files {
        let file = captured
            .files
            .remove(&sidecar.logical_path)
            .ok_or_else(|| {
                format!(
                    "captured conversation '{}' lost sidecar '{}'",
                    resource_id, sidecar.logical_path
                )
            })?;
        sidecars.insert(sidecar.logical_path.clone(), file);
    }
    Ok((conversation, transcript, sidecars))
}

/// The Claude wire-form publication set: the redacted transcript
/// (certified `redact(w) == w`), the genuine wire fold over those bytes,
/// and the wire re-analysis facts the cloud row publishes. All fields are
/// wire-form; the local fold never appears here.
struct ClaudeWirePublication {
    bytes: credential_redaction::RedactedWireBytes,
    wire_tail: PortableConversationTail,
    head_message_id: Option<mallard_domain::MessageId>,
    message_count: u64,
    lineage_digest: String,
    semantic_digest: String,
}

#[allow(clippy::too_many_arguments)]
fn conversation_thread_from_capture(
    previous: Option<&ConversationThread>,
    action: &ConversationPlanAction,
    result_thread_id: &CloudThreadId,
    local_binding: Option<&LocalConversationBinding>,
    descriptor: &ResourceDescriptor,
    conversation: &provider_capture::CapturedConversation,
    artifact: Option<&StandaloneConversationArtifact<credential_redaction::RedactedWireBytes>>,
    claude_wire: Option<&ClaudeWirePublication>,
    published_bytes: &PayloadBytes,
    published_by: &PortableOrigin,
    updated_at: u64,
    redaction_run: &mut credential_redaction::RedactionRun<'_>,
) -> Result<(ConversationThread, ResourceDescriptor, LogicalPath), String> {
    let resource_id = cloud_conversation_resource_id(&action.provider, result_thread_id)?;
    let logical_path = cloud_conversation_transcript_path(&action.provider, result_thread_id)?;
    // Codex publishes the complete flattened standalone graph: identity,
    // counts, digests, and the portable tail all come from the verified
    // artifact, never from the leaf-only capture.
    // Every published fact is wire-form: Codex facts come from the
    // verified standalone artifact, Claude facts from the wire re-analysis
    // of the redacted bytes. Local-capture digests never reach the row.
    let (lineage_status, head_message_id, message_count, lineage_digest, semantic_digest) =
        match (artifact, claude_wire) {
            (Some(artifact), _) => (
                ConversationLineageStatus::Complete,
                artifact
                    .last_canonical_message_id
                    .as_deref()
                    .map(mallard_domain::MessageId::parse)
                    .transpose()?,
                artifact.message_count,
                artifact.lineage_digest.clone(),
                artifact.semantic_digest.clone(),
            ),
            (None, Some(wire)) => (
                ConversationLineageStatus::Complete,
                wire.head_message_id.clone(),
                wire.message_count,
                wire.lineage_digest.clone(),
                wire.semantic_digest.clone(),
            ),
            (None, None) => {
                return Err(format!(
                    "conversation '{}' has no wire publication and cannot be published",
                    result_thread_id
                ));
            }
        };
    let forked_from = match action.action {
        ConversationPlanActionType::CreateCloud => {
            local_binding.and_then(|binding| binding.forked_from.clone())
        }
        _ => previous.and_then(|thread| thread.forked_from.clone()),
    };
    // Preservation provenance travels exactly like fork provenance: a
    // preserved copy's first push is CreateCloud (the local binding is the
    // only source); later pushes carry the manifest record forward.
    let preserved = match action.action {
        ConversationPlanActionType::CreateCloud => {
            local_binding.and_then(|binding| binding.preserved.clone())
        }
        _ => previous.and_then(|thread| thread.preserved.clone()),
    };
    let sidecar_refs = conversation
        .sidecar_files
        .iter()
        .map(|sidecar| {
            mallard_domain::cloud_conversation_sidecar_path(
                &action.provider,
                result_thread_id,
                &sidecar.sidecar_kind,
                &sidecar.relative_path,
            )
            .map(|logical_path| ConversationFileRef {
                logical_path,
                role: ConversationFileRole::Sidecar {
                    sidecar_kind: sidecar.sidecar_kind.clone(),
                },
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    // Explicit provider titles win. Preserve an existing portable title when
    // the local index no longer contains it, then derive a bounded fallback
    // from the exact wire transcript. Reconstructed Codex bytes include
    // history_base ancestors; Claude summarizes its redacted wire form.
    // The title is content-derived (provider index titles, the bounded
    // first-user fallback), so it passes the same scrub as transcript
    // content before it becomes cloud metadata.
    let transcript_title = if artifact.is_some() {
        first_codex_user_summary(published_bytes.as_bytes())
    } else if claude_wire.is_some() {
        provider_registry()
            .require(&action.provider)?
            .summarize_bytes(published_bytes.as_bytes())?
            .title
    } else {
        None
    };
    let display_title = Some(descriptor.display_name.clone())
        .filter(|name| Some(name.as_str()) != conversation.source_thread_id.as_deref())
        .or_else(|| {
            previous
                .filter(|thread| thread.wire_redaction.as_ref() == Some(&redaction_run.stamp()))
                .and_then(|thread| thread.display_title.clone())
        })
        .or(transcript_title)
        .or_else(|| previous.and_then(|thread| thread.display_title.clone()))
        .map(|title| redaction_run.redact_str(&title).unwrap_or(title));
    let thread = ConversationThread {
        thread_id: result_thread_id.clone(),
        provider: action.provider.clone(),
        display_title,
        presentation: conversation.presentation.clone(),
        resource_id: resource_id.clone(),
        files: std::iter::once(ConversationFileRef {
            logical_path: logical_path.clone(),
            role: ConversationFileRole::Transcript,
        })
        .chain(sidecar_refs)
        .collect(),
        lineage_status,
        lineage_codec: conversation.lineage_codec.clone(),
        head_message_id,
        message_count,
        lineage_digest,
        semantic_digest,
        portable_tail: artifact
            .map(|artifact| artifact.portable_tail.clone())
            .or_else(|| claude_wire.map(|wire| wire.wire_tail.clone())),
        wire_children: action.pins.subagent_selection.wire_children,
        wire_redaction: Some(redaction_run.stamp()),
        // Claude's path-map declaration is this out-of-band stamp; Codex
        // carries its declaration in-band and must not repeat it here.
        wire_path_map: claude_wire.map(|_| mallard_domain::ConversationWirePathMap {
            codec: mallard_infrastructure::session_path_map::PATH_MAP_CODEC_V1.to_string(),
        }),
        forked_from,
        preserved,
        source_thread_id: conversation.source_thread_id.clone(),
        created_by_origin: previous
            .and_then(|thread| thread.created_by_origin.clone())
            .or_else(|| Some(published_by.clone())),
        last_updated_by_origin: Some(published_by.clone()),
        created_at: previous
            .map(|thread| thread.created_at)
            .unwrap_or(updated_at),
        updated_at,
    };
    let mut portable_descriptor = descriptor.clone();
    portable_descriptor.display_name = redaction_run
        .redact_str(&portable_descriptor.display_name)
        .unwrap_or(portable_descriptor.display_name);
    portable_descriptor.resource_id = resource_id;
    portable_descriptor.kind = contracts::conversation();
    portable_descriptor.provider = Some(action.provider.clone());
    portable_descriptor.apply_policy = contracts::safe_file();
    portable_descriptor.set_attribute(
        "content_sha256",
        serde_json::Value::String(published_bytes.sha256().to_string()),
    )?;
    Ok((thread, portable_descriptor, logical_path))
}

/// Split one flat reviewed recipe into per-scope recipes by resource
/// ownership: project content and requirements to the project scope,
/// provider-owned resources to their provider's scope. Conversation entries
/// are appended later from the reviewed conversation set.
fn split_recipe_by_scope(
    recipe: &BundleRecipe,
    captured_descriptors: &BTreeMap<ResourceId, ResourceDescriptor>,
    previous: Option<&BundleManifest>,
) -> Result<BTreeMap<SyncScopeKey, BundleRecipe>, String> {
    let mut by_scope: BTreeMap<SyncScopeKey, BundleRecipe> = BTreeMap::new();
    for (resource_id, entry) in &recipe.entries {
        let provider = captured_descriptors
            .get(resource_id)
            .map(|descriptor| descriptor.provider.clone())
            .or_else(|| {
                previous.and_then(|manifest| {
                    manifest
                        .find_resource(resource_id)
                        .map(|(_, descriptor)| descriptor.provider.clone())
                })
            })
            .ok_or_else(|| {
                format!(
                    "selected resource '{}' is unavailable and has no previous captured version",
                    resource_id
                )
            })?;
        let scope = match provider {
            Some(provider) => SyncScopeKey::Provider(provider),
            None => SyncScopeKey::Project,
        };
        let scoped = by_scope.entry(scope).or_insert_with(|| BundleRecipe {
            schema_version: recipe.schema_version,
            revision: recipe.revision,
            entries: BTreeMap::new(),
        });
        scoped.entries.insert(resource_id.clone(), entry.clone());
    }
    Ok(by_scope)
}

/// Pull seeds machine-local selection from generic resources only and resets
/// its local concurrency revision. Reuse the published scope recipe revision
/// when that generic selection is unchanged so a converged Pull cannot create
/// a recipe-metadata-only remote revision on the next Push.
fn preserve_unchanged_scope_recipe_revision(
    recipe: &mut BundleRecipe,
    previous: Option<&BundleRecipe>,
) {
    let Some(previous) = previous else {
        return;
    };
    let previous_generic_entries = previous
        .entries
        .iter()
        .filter(|(resource_id, _)| !is_conversation_resource_id(resource_id.as_str()))
        .map(|(resource_id, entry)| (resource_id.clone(), entry.clone()))
        .collect::<BTreeMap<_, _>>();
    if recipe.schema_version == previous.schema_version
        && recipe.entries == previous_generic_entries
    {
        recipe.revision = previous.revision;
    }
}

fn captured_with_for_provider(provider: &ProviderKey) -> CapturedWith {
    let mut captured_with = CapturedWith {
        app_version: env!("CARGO_PKG_VERSION").to_string(),
        provider_versions: BTreeMap::new(),
        codec_versions: BTreeMap::new(),
    };
    if let Some(adapter) = provider_registry().get(provider) {
        captured_with
            .codec_versions
            .insert(adapter.codec_key().to_string(), adapter.codec_version());
    }
    captured_with
}

/// Build a scoped publish request from the reviewed flat selection. Only the
/// binding's writable scopes appear; every other scope — unbound providers
/// and unknown future providers alike — is carried verbatim by the engine's
/// mutation firewall.
/// Shared, read-only inputs for building one conversation's publication.
#[derive(Clone, Copy)]
struct ConversationPublicationContext<'a> {
    repository: &'a LocalStateRepository,
    plan_id: &'a PlanId,
    storage_id: &'a StorageId,
    project: &'a LocalProjectRegistration,
    binding: &'a ProjectBinding,
    homes: &'a BTreeMap<ProviderKey, String>,
    child_lookup: Option<&'a RolloutLookup>,
    previous_manifest: Option<&'a BundleManifest>,
    domain_captured: &'a BTreeMap<ResourceId, ResourceDescriptor>,
    document: &'a mallard_domain::ConversationBindings,
    reviewed_config: &'a SyncConfig,
    published_by: &'a PortableOrigin,
    updated_at: u64,
}

/// The published transcript's placement in its scope: byte-identical to the
/// reviewed manifest entry, or a fresh capture.
enum PublishedFile {
    Retained(BundleFileEntry),
    Captured(CapturedBundleFile),
}

impl PublishedFile {
    fn from_child_capture(file: CapturedBundleFile, previous: Option<&BundleFileEntry>) -> Self {
        match previous {
            Some(entry)
                if entry.resource_id == file.resource_id
                    && entry.sha256 == file.bytes.sha256()
                    && entry.size == file.bytes.len() as u64
                    && entry.source_mtime == file.source_mtime
                    && entry.mode == file.mode =>
            {
                Self::Retained(entry.clone())
            }
            _ => Self::Captured(file),
        }
    }
}

/// One built conversation publication: everything the scope commit writes,
/// produced without touching the scope. A builder failure therefore leaves
/// the scope exactly as the previous manifest had it.
struct ConversationPublication {
    path_origins: PathOrigins,
    cloud_thread_id: CloudThreadId,
    thread: ConversationThread,
    descriptor: ResourceDescriptor,
    logical_path: LogicalPath,
    transcript: PublishedFile,
    sidecars: Vec<(LogicalPath, PublishedFile)>,
    checkpoint: ConversationCheckpoint,
    operation: ConversationApplyOperation,
}

/// One selected conversation the Push could not build. The batch continues
/// without it; the result reports it under the review's resource id.
#[derive(Clone, Debug)]
struct PushThreadFailure {
    resource_id: ResourceId,
    message: String,
    /// The session whose saved cursor must no longer be used: it was edited
    /// after it was accepted.
    edited_since_acceptance: Option<(ProviderKey, ThreadId)>,
}

/// Why one conversation was not built.
struct PublicationRefusal {
    message: String,
    edited_since_acceptance: bool,
}

impl From<String> for PublicationRefusal {
    fn from(message: String) -> Self {
        Self {
            message,
            edited_since_acceptance: false,
        }
    }
}

impl From<&str> for PublicationRefusal {
    fn from(message: &str) -> Self {
        message.to_string().into()
    }
}

/// What a refused conversation is checked against: the transcript the Push
/// captured, its messages, and the version that was accepted. A refusal
/// alone does not say why the session no longer matches its review. An edit
/// does: pushing again cannot succeed, and the comparison that offered the
/// Push read through a cursor that never saw the edit.
struct AcceptanceWitness<'a> {
    accepted: &'a PortableConversationTail,
    binding: &'a LocalConversationBinding,
    chain: Vec<mallard_domain::CanonicalConversationMessage>,
    transcript: mallard_infrastructure::payload::PayloadBytes,
    records_of: String,
    length_of: String,
    complete: usize,
}

impl<'a> AcceptanceWitness<'a> {
    fn of(
        context: ConversationPublicationContext<'a>,
        action: &ConversationPlanAction,
        (conversation, transcript, _): &CapturedPublicationSource,
        prepared: Option<&Result<PreparedCodexPublication, String>>,
    ) -> Option<Self> {
        let thread_id = action.thread_id.as_ref()?;
        let accepted = context
            .reviewed_config
            .links
            .iter()
            .find(|link| {
                link.local_project_id == context.project.local_project_id
                    && &link.storage_id == context.storage_id
            })?
            .conversation_checkpoints
            .get(&SyncScopeKey::Provider(action.provider.clone()))?
            .get(thread_id)?
            .accepted_local_tail
            .as_ref()?;
        let binding = context.document.bindings.iter().find(|candidate| {
            candidate.host_id == context.binding.host_id
                && candidate.replica_id == context.binding.replica_id
                && candidate.local_project_id == context.binding.local_project_id
                && candidate.provider_profile_id == action.pins.context.provider_profile_id
                && &candidate.thread_id == thread_id
        })?;
        let (chain, records_of, length_of, complete) = match prepared {
            Some(prepared) => {
                let root = &prepared.as_ref().ok()?.root;
                let leaf = root.segments.last()?;
                (
                    root.chain.clone(),
                    leaf.rollout_id.clone(),
                    leaf.provider_thread_id.clone(),
                    leaf.consumed_byte_len,
                )
            }
            None => {
                let source = conversation.source_thread_id.clone()?;
                (
                    conversation.lineage.chain()?.to_vec(),
                    source.clone(),
                    source,
                    jsonl_tail_io::safe_record_end(&transcript.bytes),
                )
            }
        };
        Some(Self {
            accepted,
            binding,
            chain,
            transcript: transcript.bytes.clone(),
            records_of,
            length_of,
            complete: usize::try_from(complete)
                .ok()
                .filter(|complete| *complete <= transcript.bytes.len())?,
        })
    }

    fn edited(&self, repository: &LocalStateRepository) -> bool {
        edited_since_acceptance(
            repository,
            Some(self.accepted),
            Some(self.binding),
            &self.chain,
            AcceptedRecords {
                records_of: &self.records_of,
                length_of: &self.length_of,
                complete: &self.transcript[..self.complete],
            },
        )
    }
}

/// Whether this Push is the first one of a copy that Keep both preserved.
/// The copy is published under a new cloud identity, so no accepted version
/// exists that a record of it could contradict. Its saved origins are those
/// of the session it was kept from, and the edit that made it a copy is in
/// its records.
fn first_push_of_a_kept_copy(
    action: &ConversationPlanAction,
    binding: Option<&LocalConversationBinding>,
    checkpoint: Option<&ConversationCheckpoint>,
) -> bool {
    action.action == ConversationPlanActionType::CreateCloud
        && binding.is_some_and(|row| row.preserved.is_some() && row.cloud_thread_id.is_none())
        && checkpoint.is_none_or(|checkpoint| checkpoint.accepted.is_none())
}

/// Encode once more, by digest, a Claude transcript in which a saved record
/// changed or is missing, or keep the refusal the first encoding gave.
///
/// A kept copy needs no proof. A mapped session needs two: its messages up
/// to the accepted end give the accepted value in the local form, and the
/// new wire form gives the accepted wire value at the same end. A Claude
/// desktop import passes both, because it changes records and no message.
/// A record that is no longer part of the conversation is in neither
/// proof: it is published as a new scan reads it.
fn encode_rewritten_claude_transcript(
    refusal: EncodeRefusal,
    encode: impl Fn(
        OriginLookup,
        &mut credential_redaction::RedactionRun<'_>,
    ) -> Result<EncodedMainTranscript, EncodeRefusal>,
    redaction: &mut credential_redaction::RedactionRun<'_>,
    kept_copy: bool,
    checkpoint: Option<&ConversationCheckpoint>,
    chain: Option<&[mallard_domain::CanonicalConversationMessage]>,
    stored_redaction: Option<&mallard_domain::ConversationWireRedaction>,
) -> Result<EncodedMainTranscript, EncodeRefusal> {
    if kept_copy {
        return encode(OriginLookup::ByDigest, redaction);
    }
    let (Some(accepted), Some(accepted_local), Some(chain)) = (
        checkpoint.and_then(|checkpoint| checkpoint.accepted.as_ref()),
        checkpoint.and_then(|checkpoint| checkpoint.accepted_local_tail.as_ref()),
        chain,
    ) else {
        return Err(refusal);
    };
    if !accepted_prefix_matches(accepted_local, chain) {
        return Err(refusal);
    }
    let encoded = encode(OriginLookup::ByDigest, redaction)?;
    // The accepted wire value is of the redaction it was published under.
    let under_stored_redaction = if stored_redaction == Some(&redaction.stamp()) {
        None
    } else {
        Some(encode(
            OriginLookup::ByDigest,
            &mut credential_redaction::shared().run_from_stamp(stored_redaction)?,
        )?)
    };
    let proven = under_stored_redaction
        .as_ref()
        .unwrap_or(&encoded)
        .analysis
        .lineage
        .chain()
        .is_some_and(|wire_chain| accepted_prefix_matches(&accepted.portable_tail, wire_chain));
    if proven {
        Ok(encoded)
    } else {
        Err(refusal)
    }
}

/// Build one conversation, and say of a refused one whether it was edited
/// after it was accepted.
fn build_conversation_publication_or_refusal(
    context: ConversationPublicationContext<'_>,
    action: &ConversationPlanAction,
    previous_thread: Option<ConversationThread>,
    captured: CapturedPublicationSource,
    prepared_codex: Option<Result<PreparedCodexPublication, String>>,
    redaction_run: &mut credential_redaction::RedactionRun<'_>,
) -> Result<ConversationPublication, PublicationRefusal> {
    let witness = AcceptanceWitness::of(context, action, &captured, prepared_codex.as_ref());
    build_conversation_publication(
        context,
        action,
        previous_thread,
        captured,
        prepared_codex,
        redaction_run,
    )
    .map_err(|message| {
        if witness.is_some_and(|witness| witness.edited(context.repository)) {
            PublicationRefusal {
                message: owned_subagents::PUSH_EDITED.to_string(),
                edited_since_acceptance: true,
            }
        } else {
            message.into()
        }
    })
}

/// Build one reviewed conversation action's publication: resolve its cloud
/// identity, re-verify the reviewed pins against the captured bytes, encode
/// and certify the wire form, and plan its checkpoint and apply operation.
/// Reads the scope for the previous row only; writes nothing, so a failure
/// anywhere in here is the thread's alone.
#[allow(clippy::too_many_lines)]
fn build_conversation_publication(
    context: ConversationPublicationContext<'_>,
    action: &ConversationPlanAction,
    previous_thread: Option<ConversationThread>,
    captured: CapturedPublicationSource,
    prepared_codex: Option<Result<PreparedCodexPublication, String>>,
    redaction_run: &mut credential_redaction::RedactionRun<'_>,
) -> Result<ConversationPublication, String> {
    let ConversationPublicationContext {
        child_lookup,
        repository,
        plan_id,
        storage_id,
        project,
        binding,
        homes,
        previous_manifest,
        domain_captured,
        document,
        reviewed_config,
        published_by,
        updated_at,
    } = context;
    let scope_key = SyncScopeKey::Provider(action.provider.clone());
    let (conversation, transcript, mut sidecar_files) = captured;
    // Push actions always name a registered local thread (D5).
    let local_thread_id = action.thread_id.clone().ok_or_else(|| {
        format!(
            "conversation Push action '{}' lacks its local thread id",
            action.action_id
        )
    })?;
    let local_binding = document.bindings.iter().find(|candidate| {
        candidate.host_id == binding.host_id
            && candidate.replica_id == binding.replica_id
            && candidate.local_project_id == binding.local_project_id
            && candidate.provider_profile_id == action.pins.context.provider_profile_id
            && candidate.thread_id == local_thread_id
    });
    let mut source_origins = PathOrigins::default();
    let mut claude_path_origins = PathOrigins::default();
    // Resolve the cloud identity first. A mapped action publishes under
    // its existing cloud id after cross-checking the live row — any
    // mismatch in either direction is a hard error, never a silent
    // adoption. An unmapped CreateCloud mints here, at apply: a single
    // attempt, fail-closed against the previous manifest's ids and every
    // binding row's claim; the caller rejects an id resolved twice in one
    // batch. List-then-write makes the previous-manifest check sound — if
    // another publication was selected after observation, the publish itself
    // stops before its record.
    let live_mapping = local_binding.and_then(|row| row.cloud_thread_id.clone());
    let result_thread_id = match &action.cloud_thread_id {
        Some(reviewed) => {
            if live_mapping.as_ref() != Some(reviewed) {
                return Err(format!(
                    "conversation '{}' cloud mapping changed after review; \
                     refresh and push again",
                    local_thread_id
                ));
            }
            reviewed.clone()
        }
        None => {
            if action.action != ConversationPlanActionType::CreateCloud {
                return Err(format!(
                    "conversation Push action '{}' lacks its reviewed cloud thread id",
                    action.action_id
                ));
            }
            if let Some(live) = &live_mapping {
                return Err(format!(
                    "conversation '{}' is already mapped to cloud thread '{}'; \
                     refresh and push again",
                    local_thread_id, live
                ));
            }
            let minted = CloudThreadId::generate()?;
            let manifest_collision = previous_manifest.is_some_and(|manifest| {
                manifest
                    .all_conversations()
                    .any(|(_, thread_id, _)| thread_id == &minted)
            });
            let binding_collision = document
                .bindings
                .iter()
                .any(|row| row.cloud_thread_id.as_ref() == Some(&minted));
            if manifest_collision || binding_collision {
                return Err(format!(
                    "minted cloud thread id '{}' collides with existing state",
                    minted
                ));
            }
            minted
        }
    };
    let descriptor = action
        .source_resource_id
        .as_ref()
        .and_then(|resource_id| domain_captured.get(resource_id))
        .ok_or_else(|| {
            format!(
                "conversation Push action '{}' lost its descriptor",
                action.action_id
            )
        })?;
    // Publishing apply is the single reconstruction point: the complete
    // logical graph becomes one verified standalone artifact whose
    // cumulative tail must equal the planned local value.
    let reconstructs_graph = provider_registry()
        .require(&action.provider)?
        .reconstructs_rollout_graph();
    let supports_cursor = provider_supports_tail_cursor(&action.provider);
    // The stale check for cursor providers is pin-vs-checkpoint
    // equality: any checkpoint advance between review and apply is a
    // typed stale error, so nothing below trusts state the review did
    // not pin.
    let stored_checkpoint = reviewed_config
        .links
        .iter()
        .find(|link| {
            link.local_project_id == project.local_project_id && &link.storage_id == storage_id
        })
        .and_then(|link| link.conversation_checkpoints.get(&scope_key))
        .and_then(|threads| threads.get(&local_thread_id));
    if supports_cursor
        && stored_checkpoint.map(|checkpoint| checkpoint.generation)
            != action.pins.tail.checkpoint_generation
    {
        return Err(format!(
            "conversation '{}' checkpoint advanced after review; refresh and push again",
            result_thread_id
        ));
    }
    if let Some(previous) = previous_thread.as_ref() {
        credential_redaction::shared().run_from_stamp(previous.wire_redaction.as_ref())?;
        if (previous.wire_redaction.as_ref() != Some(&redaction_run.stamp())
            || previous.wire_children != action.pins.subagent_selection.wire_children)
            != action.pins.export_settings_changed
        {
            return Err("conversation export settings changed after review".into());
        }
    }
    // The Claude wire re-encodes the accepted prefix on every push, so
    // the stored row's path-map codec must be the one this binary
    // carries — a foreign codec can never be silently re-encoded.
    if let Some(stamp) = previous_thread
        .as_ref()
        .and_then(|thread| thread.wire_path_map.as_ref())
    {
        if stamp.codec != mallard_infrastructure::session_path_map::PATH_MAP_CODEC_V1 {
            return Err(format!(
                "path_map_codec_mismatch: conversation '{}' was published under \
                 path-map codec '{}'; this app carries '{}'. Align app versions \
                 before pushing.",
                result_thread_id,
                stamp.codec,
                mallard_infrastructure::session_path_map::PATH_MAP_CODEC_V1
            ));
        }
    }
    let mut child_payloads = Vec::new();
    let mut accepted_subagents = BTreeMap::new();
    let mut child_origins = PathOrigins::default();
    let mut captured_sources = owned_subagents::SourceSnapshots::new();
    let mut captured_tree = None;
    let mut captured_claude_children = None;
    let (artifact, seeded, claude_wire) = if reconstructs_graph {
        // Operation-level Windows gate: the path-map root grammar is
        // checked before any rollout bytes are parsed.
        validate_pathmap_root("project root", &binding.project_root)?;
        homes.get(&action.provider).ok_or_else(|| {
            format!(
                "conversation Push action '{}' has no provider home",
                action.action_id
            )
        })?;
        let source = captured_transcript_source(&conversation)?;
        let child_lookup = child_lookup.ok_or("Codex filename inventory is missing")?;
        child_lookup.verify_current(
            conversation
                .source_thread_id
                .as_deref()
                .ok_or("Codex source identity is missing")?,
            &source,
        )?;
        let PreparedCodexPublication {
            root: resolved_root,
            sources,
            tree,
        } = prepared_codex.ok_or("Codex reviewed snapshots are missing")??;
        let (reviewed_bytes, reviewed_stamp) = sources
            .get(&source)
            .ok_or("Codex reviewed current source is missing")?;
        if reviewed_bytes.sha256() != transcript.bytes.sha256()
            || transcript.source_stamp.as_ref() != Some(reviewed_stamp)
        {
            return Err(owned_subagents::PUSH_CHANGED.into());
        }
        reviewed_stamp.verify(&source)?;
        let reviewed_keys = action.pins.subagent_selection.keys.clone();
        if tree.omitted != action.pins.subagent_selection.omitted
            || tree.children.keys().cloned().collect::<BTreeSet<_>>() != reviewed_keys
        {
            return Err(owned_subagents::PUSH_CHANGED.into());
        }
        let mut identities = BTreeMap::from([(
            resolved_root.leaf_meta.id.clone(),
            codex_subagents::PORTABLE_MAIN_ID.to_string(),
        )]);
        identities.extend(tree.children.iter().map(|(key, child)| {
            (
                child.resolved.leaf_meta.id.clone(),
                codex_subagents::portable_child_id(key),
            )
        }));
        let installed_origins = local_binding
            .filter(|row| row.path_origins_ref.is_some())
            .map(|row| repository.load_path_origins(row))
            .transpose()?
            .unwrap_or_default();
        for (key, child) in &tree.children {
            if let Some(observed) = action
                .pins
                .tail
                .subagents
                .get(key)
                .and_then(|pins| pins.local.as_ref())
            {
                owned_subagents::verify_reviewed_state(observed, &child.local)?;
            }
            let artifact =
                mallard_infrastructure::codex_standalone_builder::encode_codex_tree_member(
                    &child.resolved,
                    &child.sources,
                    &binding.project_root,
                    (binding.canonical_project_root != binding.project_root)
                        .then_some(binding.canonical_project_root.as_str()),
                    Some(&codex_subagents::whole_child_layout()),
                    redaction_run,
                    &installed_origins,
                    OriginLookup::ByPosition,
                    &identities,
                )?;
            let normalized = SubagentContentState::from_tail(&artifact.portable_tail)?;
            accepted_subagents.insert(
                key.clone(),
                AcceptedSubagentState {
                    local: child.local.clone(),
                    normalized: normalized.clone(),
                },
            );
            child_origins.merge(&artifact.path_origins)?;
            child_payloads.push((
                key.clone(),
                normalized,
                artifact.root_bytes.into_bytes(),
                child
                    .sources
                    .get(&child.path)
                    .ok_or("child source stamp is missing")?
                    .1
                    .mtime_secs(),
            ));
            captured_sources.extend(child.sources.clone());
        }
        captured_tree = Some(tree);
        source_origins.merge(&load_source_path_origins(
            repository,
            document,
            binding,
            &action.pins.context.provider_profile_id,
            resolved_root
                .segments
                .iter()
                .map(|segment| segment.provider_thread_id.as_str()),
        )?)?;
        let stored_layout = local_binding.and_then(|binding| binding.root_tail_layout.as_ref());
        let seeded =
            codex_history_graph::seed_codex_root(&resolved_root, &transcript.bytes, stored_layout)?;
        if Some(&seeded.observed_tail) != action.pins.tail.local.as_ref() {
            return Err(owned_subagents::PUSH_CHANGED.into());
        }
        // The prefix witness is the append-only trust anchor for the
        // fixed partition: the reviewed checkpoint's local-form witness
        // must survive this full local reconstruction bit for bit, or
        // content before the accepted start was mutated in place —
        // invisible to cursor-riding review, and never publishable.
        let stored_witness =
            stored_checkpoint.and_then(|checkpoint| checkpoint.prefix_witness.clone());
        if let Some(stored) = stored_witness {
            if seeded.prefix_witness.as_ref() != Some(&stored) {
                return Err(format!(
                    "conversation '{}' content before its fixed start changed; \
                     the prefix witness no longer matches",
                    result_thread_id
                ));
            }
        }
        let encode = |lookup, redaction: &mut credential_redaction::RedactionRun<'_>| {
            mallard_infrastructure::codex_standalone_builder::encode_codex_tree_member(
                &resolved_root,
                &sources,
                &binding.project_root,
                (binding.canonical_project_root != binding.project_root)
                    .then_some(binding.canonical_project_root.as_str()),
                stored_layout,
                redaction,
                &source_origins,
                lookup,
                &identities,
            )
        };
        let artifact = match encode(OriginLookup::ByPosition, redaction_run) {
            Err(refusal)
                if refusal.saved_record_changed
                    && first_push_of_a_kept_copy(action, local_binding, stored_checkpoint) =>
            {
                encode(OriginLookup::ByDigest, redaction_run)
            }
            artifact => artifact,
        }?;
        captured_sources.extend(sources);
        (Some(artifact), seeded, None)
    } else if supports_cursor {
        if let Some(row) = local_binding.filter(|row| row.path_origins_ref.is_some()) {
            source_origins = repository.load_path_origins(row)?;
        }

        // Claude: the local fold (review check, `accepted_local_tail`)
        // seeds from the original bytes; the wire fold seeds from the
        // path-encoded, redacted transcript — two genuinely different
        // folds, since the wire form carries token paths and redacted
        // content. Apply re-derives the observed tail from the exact
        // installed bytes on pull.
        //
        // Operation-level Windows gate: the path-map root grammar is
        // checked before any transcript bytes are parsed.
        validate_pathmap_root("project root", &binding.project_root)?;
        let source = captured_transcript_source(&conversation)?;
        let analysis = mallard_infrastructure::providers::SessionAnalysis {
            source_provider_session_id: conversation.source_thread_id.clone(),
            source_cwd: conversation.source_cwd.clone(),
            is_internal_subagent: false,
            record_count: conversation.record_count,
            lineage: conversation.lineage.clone(),
        };
        let seeded = claude_history_tail::seed_claude_root(&source, &transcript.bytes, &analysis)?
            .ok_or_else(|| {
                format!(
                    "conversation '{}' does not end at a record boundary; \
                         refresh and push again",
                    result_thread_id
                )
            })?;
        let reviewed = action
            .pins
            .tail
            .local
            .as_ref()
            .ok_or(owned_subagents::PUSH_CHANGED)?;
        owned_subagents::verify_reviewed_state(
            &SubagentContentState::from_tail(reviewed)?,
            &SubagentContentState::from_tail(&seeded.observed_tail)?,
        )?;
        let source_stamp = transcript
            .source_stamp
            .clone()
            .ok_or("Claude capture lacks a source stamp")?;
        captured_sources.insert(
            source.clone(),
            (transcript.bytes.clone(), source_stamp.clone()),
        );
        let mapper = SessionPathMapper::new(
            &binding.project_root,
            (binding.canonical_project_root != binding.project_root)
                .then_some(binding.canonical_project_root.as_str()),
            mallard_infrastructure::session_path_map::home_dir_text().as_deref(),
        )?;
        let source_id = conversation
            .source_thread_id
            .as_deref()
            .ok_or("conversation lacks a physical source ID")?;
        let encode = |lookup, redaction: &mut credential_redaction::RedactionRun<'_>| {
            mallard_infrastructure::providers::claude::publication::encode_main_transcript(
                &transcript.bytes,
                source_id,
                &mapper,
                &source_origins,
                lookup,
                redaction,
            )
        };
        let encoded = match encode(OriginLookup::ByPosition, redaction_run) {
            Err(refusal) if refusal.saved_record_changed => encode_rewritten_claude_transcript(
                refusal,
                encode,
                redaction_run,
                first_push_of_a_kept_copy(action, local_binding, stored_checkpoint),
                stored_checkpoint,
                conversation.lineage.chain(),
                previous_thread
                    .as_ref()
                    .and_then(|thread| thread.wire_redaction.as_ref()),
            ),
            encoded => encoded,
        }
        .map_err(|error| format!("conversation '{}': {error}", result_thread_id))?;
        let redacted = encoded.bytes;
        let wire_analysis = encoded.analysis;
        let child_links = encoded.child_links;
        claude_path_origins = encoded.path_origins;
        let wire_seeded = claude_history_tail::seed_claude_root_with_watermark(
            &source,
            redacted.as_bytes(),
            &wire_analysis,
            encoded.watermark,
        )?
        .ok_or_else(|| {
            format!(
                "redaction_gate_failed: conversation '{}' redacted transcript lost \
                 its record boundary",
                result_thread_id
            )
        })?;
        // Cross-form layout equality is a frozen encoder requirement:
        // redaction is per-record and content-only, so the wire fold
        // must partition exactly like the local fold.
        if wire_seeded.observed_tail.partition_kind != seeded.observed_tail.partition_kind
            || wire_seeded.observed_tail.start_record_count
                != seeded.observed_tail.start_record_count
            || wire_seeded.observed_tail.accepted_end_record_count
                != seeded.observed_tail.accepted_end_record_count
        {
            return Err(format!(
                "redaction_gate_failed: conversation '{}' redaction changed the \
                 record layout",
                result_thread_id
            ));
        }
        let CodecLineage::Complete {
            chain,
            lineage_digest,
            semantic_digest,
        } = &wire_analysis.lineage
        else {
            return Err(format!(
                "redaction_gate_failed: conversation '{}' redacted transcript failed \
                 its re-analysis",
                result_thread_id
            ));
        };
        let mut children =
            if action.pins.subagent_selection.wire_children == ConversationWireChildren::Off {
                claude_subagents::CapturedChildren::omitted()
            } else {
                claude_subagents::capture_children(
                    &claude_subagents::MainObservation {
                        mapping: seeded.mapping.clone(),
                        links: child_links,
                    },
                    local_binding,
                    &mapper,
                    &source_origins,
                    redaction_run,
                    None,
                )?
            };
        let reviewed_keys = action.pins.subagent_selection.keys.clone();
        if children.omitted != action.pins.subagent_selection.omitted
            || children.children.keys().cloned().collect::<BTreeSet<_>>() != reviewed_keys
        {
            return Err(owned_subagents::PUSH_CHANGED.into());
        }
        for (key, child) in &children.children {
            if let Some(observed) = action
                .pins
                .tail
                .subagents
                .get(key)
                .and_then(|pin| pin.local.as_ref())
            {
                owned_subagents::verify_reviewed_state(observed, &child.accepted.local)?;
            }
            accepted_subagents.insert(key.clone(), child.accepted.clone());
            child_origins.merge(&child.origins)?;
            child_payloads.push((
                key.clone(),
                child.accepted.normalized.clone(),
                child.bytes.clone(),
                child.source_mtime,
            ));
        }
        captured_sources.append(&mut children.sources);
        captured_claude_children = Some(children);
        let claude_wire = ClaudeWirePublication {
            wire_tail: PortableConversationTail {
                codec: mallard_domain::CLAUDE_PORTABLE_TAIL_CODEC_WIRE_V1.to_string(),
                partition_kind: wire_seeded.observed_tail.partition_kind,
                start_record_count: wire_seeded.observed_tail.start_record_count,
                accepted_end_record_count: wire_seeded.observed_tail.accepted_end_record_count,
                accepted_tail_state: wire_seeded.observed_tail.accepted_tail_state.clone(),
            },
            head_message_id: chain.last().map(|message| message.message_id.clone()),
            message_count: chain.len() as u64,
            lineage_digest: lineage_digest.clone(),
            semantic_digest: semantic_digest.clone(),
            bytes: redacted,
        };
        (
            None,
            CodexSeededRoot {
                layout: seeded.layout,
                observed_tail: seeded.observed_tail,
                prefix_witness: None,
                mapping: seeded.mapping,
                lineage_digest: seeded.lineage_digest,
                semantic_digest: seeded.semantic_digest,
            },
            Some(claude_wire),
        )
    } else {
        // Publish leak gate: only a conversation wire builder produces
        // `RedactedWireBytes`, so a provider without one cannot push
        // conversations.
        return Err(format!(
            "conversation Push action '{}' targets provider '{}', which has no \
             conversation wire builder",
            action.action_id, action.provider
        ));
    };
    // Both builders return certified immutable wire bytes. The Codex
    // certificate covers source and inserted records before serialization.
    let published_wire: credential_redaction::RedactedWireBytes = match (&artifact, &claude_wire) {
        (Some(artifact), _) => artifact.root_bytes.clone(),
        (None, Some(wire)) => wire.bytes.clone(),
        (None, None) => {
            return Err(format!(
                "conversation Push action '{}' produced no wire bytes",
                action.action_id
            ))
        }
    };
    let published_bytes = published_wire.into_bytes();
    let (mut thread, descriptor, logical_path) = conversation_thread_from_capture(
        previous_thread.as_ref(),
        action,
        &result_thread_id,
        local_binding,
        descriptor,
        &conversation,
        artifact.as_ref(),
        claude_wire.as_ref(),
        &published_bytes,
        published_by,
        updated_at,
        redaction_run,
    )?;
    let resource_id = descriptor.resource_id.clone();
    let published_digest = published_bytes.sha256().to_string();
    let artifact_sha256 = artifact
        .as_ref()
        .map(|artifact| artifact.artifact_sha256.clone())
        .unwrap_or_else(|| published_digest.clone());
    let retained_entry = previous_manifest
        .and_then(|manifest| manifest.scope(&scope_key))
        .and_then(|previous_scope| previous_scope.files.get(&logical_path));
    let transcript_placement = match retained_entry {
        Some(entry)
            if entry.resource_id == resource_id
                && entry.sha256 == published_digest
                && entry.size == published_bytes.len() as u64 =>
        {
            PublishedFile::Retained(entry.clone())
        }
        _ => PublishedFile::Captured(CapturedBundleFile {
            resource_id: resource_id.clone(),
            bytes: published_bytes,
            source_mtime: transcript.source_mtime,
            mode: Some(transcript.mode),
        }),
    };
    // Sidecars travel with the conversation resource. They were scrubbed at
    // capture; the certificate here is the fail-closed publish gate over
    // what actually ships.
    let mut sidecars = Vec::with_capacity(conversation.sidecar_files.len());
    for sidecar in &conversation.sidecar_files {
        let sidecar_file = sidecar_files.remove(&sidecar.logical_path).ok_or_else(|| {
            format!(
                "captured conversation '{}' lost sidecar '{}'",
                resource_id, sidecar.logical_path
            )
        })?;
        let sidecar_logical = mallard_domain::cloud_conversation_sidecar_path(
            &action.provider,
            &result_thread_id,
            &sidecar.sidecar_kind,
            &sidecar.relative_path,
        )?;
        let sidecar_bytes = redaction_run
            .certify_wire_document(sidecar_file.bytes)
            .map_err(|error| {
                format!(
                    "conversation '{}' sidecar '{}': {error}",
                    resource_id, sidecar.logical_path
                )
            })?;
        sidecars.push((
            sidecar_logical,
            PublishedFile::Captured(CapturedBundleFile {
                resource_id: resource_id.clone(),
                bytes: sidecar_bytes.into_bytes(),
                source_mtime: sidecar_file.source_mtime,
                mode: Some(sidecar_file.mode),
            }),
        ));
    }
    for (key, normalized, bytes, source_mtime) in child_payloads {
        let logical_path = mallard_domain::cloud_subagent_transcript_path(
            &action.provider,
            &result_thread_id,
            &key,
        )?;
        thread.files.push(mallard_domain::ConversationFileRef {
            logical_path: logical_path.clone(),
            role: ConversationFileRole::SubagentTranscript {
                child_key: key,
                normalized,
            },
        });
        let previous = previous_manifest
            .and_then(|manifest| manifest.scope(&scope_key))
            .and_then(|scope| scope.files.get(&logical_path));
        let placement = PublishedFile::from_child_capture(
            CapturedBundleFile {
                resource_id: resource_id.clone(),
                bytes,
                source_mtime,
                mode: Some(transcript.mode),
            },
            previous,
        );
        sidecars.push((logical_path, placement));
    }
    let provider_thread_id = conversation
        .source_thread_id
        .clone()
        .ok_or_else(|| "captured conversation lacks a provider session id".to_string())?;
    // The after-state this publication commits: the wire column accepts
    // the artifact's wire tail, the local column pins the reconstructed
    // local value the review verified. For providers without a
    // standalone artifact the two columns carry one shared value.
    // Candidate and accepted-at identifiers are placeholders until the
    // engine patches them at HeadAdvanced from the fused publish result.
    let published_tail = artifact
        .as_ref()
        .map(|artifact| artifact.portable_tail.clone())
        .or_else(|| claude_wire.as_ref().map(|wire| wire.wire_tail.clone()))
        .ok_or_else(|| {
            format!(
                "conversation Push action '{}' has no publishable tail",
                action.action_id
            )
        })?;
    let accepted_local_tail = seeded.observed_tail.clone();
    let operation_id = ConversationOperationId::parse(generated_named_id("operation")?)?;
    let checkpoint = ConversationCheckpoint {
        accepted_subagents,
        generation: 0,
        accepted: Some(mallard_domain::AcceptedConversationVersion {
            artifact_sha256: artifact_sha256.clone(),
            accepted_at_commit_id: action.pins.revision.commit_id.clone(),
            accepted_at_manifest_sha256: action.pins.revision.manifest_sha256.clone(),
            portable_tail: published_tail.clone(),
        }),
        accepted_local_tail: Some(accepted_local_tail.clone()),
        observed_tail: accepted_local_tail.clone(),
        physical: PhysicalMappingState::Ready {
            root_mapping: seeded.mapping.clone(),
            raw_range_pin: RawRangePin {
                start_byte_offset: seeded.mapping.consumed_byte_offset,
                end_byte_offset: seeded.mapping.consumed_byte_offset,
                range_sha256: hex_digest(Sha256::digest([]).as_slice()),
            },
            source_state: transcript
                .source_stamp
                .as_ref()
                .map(jsonl_tail_io::SourceStamp::file_state),
        },
        prefix_witness: seeded.prefix_witness.clone(),
        binding_revision: action.pins.context.binding_revision.unwrap_or(0),
    };
    let operation = ConversationApplyOperation {
        operation_id,
        plan_id: Some(plan_id.clone()),
        plan_action_id: Some(action.action_id.clone()),
        cloud: ConversationCloudAnchor {
            storage_id: storage_id.clone(),
            bundle_id: project.bundle_id.clone(),
            revision: action.pins.revision.bundle_revision,
            commit_id: action.pins.revision.commit_id.clone(),
            manifest_sha256: action.pins.revision.manifest_sha256.clone(),
        },
        host_id: binding.host_id.clone(),
        replica_id: binding.replica_id.clone(),
        local_project_id: binding.local_project_id.clone(),
        provider_profile_id: action.pins.context.provider_profile_id.clone(),
        provider: action.provider.clone(),
        thread_id: local_thread_id,
        // Minted or mapped during this Apply attempt.
        cloud_thread_id: result_thread_id.clone(),
        operation: ConversationApplyKind::CloudPublication(ConversationPublicationApply {
            export_settings_changed: action.pins.export_settings_changed,
            candidate_commit_id: action.pins.revision.commit_id.clone(),
            candidate_manifest_sha256: action.pins.revision.manifest_sha256.clone(),
            artifact_sha256,
            tail_before: action.pins.tail.accepted.clone(),
            tail_after: published_tail,
            planned_relation: action.pins.tail.classification()?,
        }),
        provider_thread_id: Some(provider_thread_id),
        materialization_state: ConversationMaterializationState::Resumable,
        expected_host_identity_revision: action.pins.context.host_identity_revision,
        expected_bindings_document_revision: action.pins.context.bindings_document_revision,
        expected_binding_revision: action.pins.context.binding_revision,
        expected_profile_revision: action.pins.context.profile_revision,
        expected_project_binding_revision: action.pins.context.project_binding_revision,
        targets: Vec::new(),
        created_at: updated_at,
        updated_at,
    };
    let mut path_origins = artifact
        .map(|artifact| artifact.path_origins)
        .unwrap_or(claude_path_origins);
    path_origins.merge(&child_origins)?;
    if let Some(tree) = &captured_tree {
        tree.verify_scope()?;
    }
    if let Some(children) = &captured_claude_children {
        children.verify_scope()?;
    }
    let total: u64 = captured_sources
        .values()
        .map(|(bytes, _)| bytes.len() as u64)
        .sum();
    if total > provider_capture::MAX_CAPTURE_BYTES {
        return Err("Codex tree exceeds capture limit".into());
    }
    if let Some(tree) = &captured_tree {
        let lookup = child_lookup.ok_or("Codex selection inventory is missing")?;
        lookup.verify_current(
            operation
                .provider_thread_id
                .as_deref()
                .ok_or("Codex source identity is missing")?,
            &captured_transcript_source(&conversation)?,
        )?;
        tree.verify_current(lookup)?;
    }
    for (path, (_, stamp)) in &captured_sources {
        if captured_tree.is_some() && path != &captured_transcript_source(&conversation)? {
            continue;
        }
        stamp
            .verify(path)
            .map_err(|_| owned_subagents::PUSH_CHANGED.to_string())?;
    }
    Ok(ConversationPublication {
        path_origins,
        cloud_thread_id: result_thread_id,
        thread,
        descriptor,
        logical_path,
        transcript: transcript_placement,
        sidecars,
        checkpoint,
        operation,
    })
}

/// Commit one built publication into its scope. Infallible by construction:
/// every check ran in the builder, so a committed thread can no longer fail
/// the batch.
fn commit_conversation_publication(
    scope: &mut ScopePublishInput,
    publication: ConversationPublication,
) -> (ConversationCheckpoint, ConversationApplyOperation) {
    let ConversationPublication {
        path_origins: _,
        cloud_thread_id,
        thread,
        descriptor,
        logical_path,
        transcript,
        sidecars,
        checkpoint,
        operation,
    } = publication;
    if let Some(old_thread) = scope.conversations.insert(cloud_thread_id.clone(), thread) {
        for file in old_thread.files {
            scope.retained_files.remove(&file.logical_path);
            scope.captured_files.remove(&file.logical_path);
        }
        scope.resources.remove(&old_thread.resource_id);
    }
    let resource_id = descriptor.resource_id.clone();
    scope.resources.insert(resource_id.clone(), descriptor);
    match transcript {
        PublishedFile::Retained(entry) => {
            scope.retained_files.insert(logical_path, entry);
        }
        PublishedFile::Captured(file) => {
            scope.retained_files.remove(&logical_path);
            scope.captured_files.insert(logical_path, file);
        }
    }
    for (sidecar_path, file) in sidecars {
        match file {
            PublishedFile::Retained(entry) => {
                scope.retained_files.insert(sidecar_path, entry);
            }
            PublishedFile::Captured(file) => {
                scope.captured_files.insert(sidecar_path, file);
            }
        }
    }
    scope.tombstones.retain(|_, tombstone| {
        !matches!(
            PortableResourceRegistry::production().tombstone_target(&tombstone.target),
            Ok(Some(TombstoneTargetPrimitive::ConversationThread { thread_id }))
                if thread_id == cloud_thread_id
        )
    });
    scope.recipe.entries.insert(
        resource_id.clone(),
        RecipeEntry {
            resource_id,
            apply_policy: contracts::safe_file(),
            required: false,
        },
    );
    (checkpoint, operation)
}

#[allow(clippy::too_many_arguments)]
fn build_publish_request(
    repository: &LocalStateRepository,
    plan_id: &PlanId,
    storage_id: &StorageId,
    project: &LocalProjectRegistration,
    binding: &ProjectBinding,
    homes: &BTreeMap<ProviderKey, String>,
    recipe: &BundleRecipe,
    mut captured: provider_capture::CapturedResources,
    previous: Option<&BundleSnapshot>,
    expected_head: PublishExpectation,
    actions: &[ConversationPlanAction],
    mut prepared_codex: PreparedCodexPublications,
    updated_at: u64,
    credential_redaction_enabled: bool,
) -> Result<
    (
        PublishBundleRequest,
        Vec<ConversationApplyOperation>,
        ConversationPublicationState,
        Vec<PushThreadFailure>,
    ),
    String,
> {
    let (origin_host_token, origin_replica_token) =
        repository.derive_origin_tokens(&project.bundle_id, &binding.replica_id)?;
    let published_by = PortableOrigin {
        origin_host_token,
        origin_replica_token,
        shared_label: repository
            .load_or_create_host_identity()?
            .local_display_name
            .as_deref()
            .map(str::trim)
            .filter(|label| !label.is_empty())
            .map(str::to_string),
    };
    let previous_manifest = previous.map(|snapshot| &snapshot.manifest);
    let captured_descriptors = provider_capture::domain_resources(&captured)?;
    // Conversation resources never travel through the generic file path:
    // strip them from the flat selection before scope reconciliation and add
    // the reviewed conversation set per provider scope below.
    let conversation_capture_ids = captured
        .conversations
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    let mut generic_recipe = recipe.clone();
    generic_recipe
        .entries
        .retain(|resource_id, _| !conversation_capture_ids.contains(resource_id.as_str()));
    if let Some(previous_manifest) = previous_manifest {
        let previous_conversation_resources = previous_manifest
            .all_conversations()
            .map(|(_, _, thread)| thread.resource_id.clone())
            .collect::<BTreeSet<_>>();
        generic_recipe
            .entries
            .retain(|resource_id, _| !previous_conversation_resources.contains(resource_id));
    }
    let generic_descriptors = captured_descriptors
        .iter()
        .filter(|(resource_id, _)| generic_recipe.entries.contains_key(*resource_id))
        .map(|(resource_id, descriptor)| (resource_id.clone(), descriptor.clone()))
        .collect::<BTreeMap<_, _>>();
    let recipes_by_scope =
        split_recipe_by_scope(&generic_recipe, &generic_descriptors, previous_manifest)?;

    let document = repository.load_conversation_bindings()?;
    let domain_captured = &captured_descriptors;
    let mut writable_scopes: BTreeMap<SyncScopeKey, ScopePublishInput> = BTreeMap::new();
    let mut reviewed_scope_pins: BTreeMap<SyncScopeKey, (u64, String)> = BTreeMap::new();
    for scope_key in writable_scopes_for_binding(binding) {
        let previous_scope =
            previous_manifest.and_then(|manifest| manifest.scope(&scope_key).cloned());
        reviewed_scope_pins.insert(
            scope_key.clone(),
            previous_scope
                .as_ref()
                .map(|scope| (scope.revision, scope.content_sha256.clone()))
                .unwrap_or_else(absent_scope_pin),
        );
        let mut scope_recipe = recipes_by_scope
            .get(&scope_key)
            .cloned()
            .unwrap_or_else(|| BundleRecipe {
                schema_version: recipe.schema_version,
                revision: recipe.revision,
                entries: BTreeMap::new(),
            });
        preserve_unchanged_scope_recipe_revision(
            &mut scope_recipe,
            previous_scope.as_ref().map(|scope| &scope.recipe),
        );
        let scope_descriptors = generic_descriptors
            .iter()
            .filter(|(resource_id, _)| scope_recipe.entries.contains_key(*resource_id))
            .map(|(resource_id, descriptor)| (resource_id.clone(), descriptor.clone()))
            .collect::<BTreeMap<_, _>>();
        mallard_infrastructure::bundle_engine::align_recipe_policies(
            &mut scope_recipe,
            &scope_descriptors,
        );
        let (mut resources, mut retained_files, mut directories, mut tombstones) =
            mallard_infrastructure::bundle_engine::reconcile_scope_content(
                PortableResourceRegistry::production(),
                &scope_key,
                &scope_recipe,
                &scope_descriptors,
                &captured,
                previous_scope.as_ref(),
                updated_at,
            )?;
        let mut captured_files = BTreeMap::new();
        for captured_file in captured.files.values() {
            if !scope_recipe
                .entries
                .contains_key(&ResourceId::parse(captured_file.resource_id.clone())?)
            {
                continue;
            }
            let logical_path = LogicalPath::parse(captured_file.logical_path.clone())?;
            let resource_id = ResourceId::parse(captured_file.resource_id.clone())?;
            let digest = captured_file.bytes.sha256();
            let can_retain = retained_files.get(&logical_path).is_some_and(|entry| {
                entry.resource_id == resource_id
                    && entry.sha256 == digest
                    && entry.size == captured_file.bytes.len() as u64
                    && entry.source_mtime == captured_file.source_mtime
                    && entry.mode == Some(captured_file.mode)
            });
            if !can_retain {
                // Provider-scope files were scrubbed at capture; the
                // certificate here is the fail-closed publish gate over
                // what actually ships. Project-scope content is not
                // redacted material.
                let bytes = if matches!(scope_key, SyncScopeKey::Provider(_)) {
                    credential_redaction::shared()
                        .begin_run()
                        .with_enabled(credential_redaction_enabled)
                        .certify_wire_document(captured_file.bytes.clone())
                        .map_err(|error| {
                            format!(
                                "resource '{}' file '{}': {error}",
                                resource_id, logical_path
                            )
                        })?
                        .into_bytes()
                } else {
                    captured_file.bytes.clone()
                };
                retained_files.remove(&logical_path);
                captured_files.insert(
                    logical_path,
                    CapturedBundleFile {
                        resource_id,
                        bytes,
                        source_mtime: captured_file.source_mtime,
                        mode: Some(captured_file.mode),
                    },
                );
            }
        }
        for captured_directory in captured.directories.values() {
            if !scope_recipe
                .entries
                .contains_key(&ResourceId::parse(captured_directory.resource_id.clone())?)
            {
                continue;
            }
            let logical_path = LogicalPath::parse(captured_directory.logical_path.clone())?;
            directories.insert(
                logical_path,
                BundleDirectoryEntry {
                    resource_id: ResourceId::parse(captured_directory.resource_id.clone())?,
                    mode: Some(captured_directory.mode),
                    source_mtime: captured_directory.source_mtime,
                },
            );
        }
        let conversations = previous_scope
            .as_ref()
            .map(|scope| scope.conversations.clone())
            .unwrap_or_default();
        let captured_with = match &scope_key {
            SyncScopeKey::Provider(provider) => captured_with_for_provider(provider),
            SyncScopeKey::Project => CapturedWith {
                app_version: env!("CARGO_PKG_VERSION").to_string(),
                provider_versions: BTreeMap::new(),
                codec_versions: BTreeMap::new(),
            },
        };
        // Carry previous conversation content: resources, files, and
        // conversation tombstones stay unless an approved action changes
        // them below.
        if let Some(previous_scope) = &previous_scope {
            for thread in previous_scope.conversations.values() {
                if let Some(descriptor) = previous_scope.resources.get(&thread.resource_id) {
                    resources.insert(thread.resource_id.clone(), descriptor.clone());
                }
                for file in &thread.files {
                    if let Some(entry) = previous_scope.files.get(&file.logical_path) {
                        retained_files.insert(file.logical_path.clone(), entry.clone());
                    }
                }
            }
            for (key, tombstone) in &previous_scope.tombstones {
                if matches!(
                    PortableResourceRegistry::production().tombstone_target(&tombstone.target),
                    Ok(Some(TombstoneTargetPrimitive::ConversationThread { .. }))
                ) {
                    tombstones.insert(key.clone(), tombstone.clone());
                }
            }
        }
        writable_scopes.insert(
            scope_key,
            ScopePublishInput {
                recipe: scope_recipe,
                captured_with,
                conversations,
                resources,
                retained_files,
                captured_files,
                directories,
                tombstones,
            },
        );
    }

    // Apply the reviewed conversation actions inside their provider scopes.
    // Each thread builds in isolation and commits into its scope only after
    // its last fallible step: a thread that fails leaves its scope exactly
    // as the previous manifest had it and joins `failures` with its message,
    // while every other thread publishes.
    let reviewed_config = repository.load_config()?;
    let mut operations = Vec::new();
    let mut indexed_failures = Vec::new();
    let mut planned_origins = BTreeMap::new();
    let mut planned_checkpoints: BTreeMap<ConversationOperationId, ConversationCheckpoint> =
        BTreeMap::new();
    let mut resolved_cloud_ids: BTreeSet<CloudThreadId> = BTreeSet::new();
    let child_lookup = homes
        .get(&ProviderKey::parse("codex")?)
        .map(|home| RolloutLookup::new(Path::new(home)));
    let context = ConversationPublicationContext {
        child_lookup: child_lookup.as_ref(),
        repository,
        plan_id,
        storage_id,
        project,
        binding,
        homes,
        previous_manifest,
        domain_captured,
        document: &document,
        reviewed_config: &reviewed_config,
        published_by: &published_by,
        updated_at,
    };
    let mut jobs = Vec::with_capacity(actions.len());
    for action in actions {
        let scope_key = SyncScopeKey::Provider(action.provider.clone());
        let scope = writable_scopes.get(&scope_key).ok_or_else(|| {
            format!(
                "conversation Push action '{}' targets unbound provider '{}'",
                action.action_id, action.provider,
            )
        })?;
        conversation_action_row_key(action).ok_or_else(|| {
            format!(
                "conversation Push action '{}' names no reportable resource",
                action.action_id,
            )
        })?;
        let previous = action
            .cloud_thread_id
            .as_ref()
            .and_then(|id| scope.conversations.get(id))
            .cloned();
        jobs.push((
            action,
            previous,
            take_captured_conversation_for_action(&mut captured, action),
            action
                .source_resource_id
                .as_ref()
                .and_then(|id| prepared_codex.remove(id)),
        ));
    }
    let workers = provider_capture::bounded_refresh_workers(jobs.len());
    let mut batch_error = None;
    // A job reserves the bytes its builder holds while it runs: the captured
    // transcript and sidecars, plus its retained Codex history. Reservations
    // end when the builder returns. Review snapshots have an aggregate byte
    // bound; the worker cap bounds concurrent projection and redaction caches. Results
    // arrive in completion order: the state below is keyed by operation id,
    // and the failures are put back into action order after the loop.
    mallard_infrastructure::bounded_preparation::for_each_prepared(
        jobs,
        workers,
        mallard_infrastructure::bounded_preparation::PREPARATION_BYTE_BUDGET,
        |(_, _, source, _)| {
            source
                .as_ref()
                .map(|(conversation, transcript, sidecars)| {
                    let captured = sidecars
                        .values()
                        .fold(transcript.bytes.len() as u64, |size, file| {
                            size.saturating_add(file.bytes.len() as u64)
                        });
                    if conversation.provider.as_str() == "codex" {
                        captured.saturating_add(
                            mallard_infrastructure::codex_history_graph::declared_history_bytes(
                                &transcript.bytes,
                            ),
                        )
                    } else {
                        captured
                    }
                })
                .unwrap_or(0)
        },
        |(action, previous, source, prepared)| {
            Ok(build_conversation_publication_or_refusal(
                context,
                action,
                previous,
                source?,
                prepared,
                &mut credential_redaction::shared()
                    .begin_run()
                    .with_enabled(action.pins.credential_redaction_enabled),
            ))
        },
        |index, outcome| {
            if batch_error.is_some() {
                return;
            }
            let action = &actions[index];
            let outcome = outcome
                .map_err(PublicationRefusal::from)
                .and_then(|built| built);
            let outcome = outcome.and_then(|publication| -> Result<(), PublicationRefusal> {
                if !resolved_cloud_ids.insert(publication.cloud_thread_id.clone()) {
                    batch_error = Some(format!(
                        "conversation Push batch resolves cloud thread '{}' twice; nothing was published",
                        publication.cloud_thread_id,
                    ));
                    return Ok(());
                }
                let owner = PathOriginsOwner::for_project(
                    binding, &action.pins.context.provider_profile_id,
                    publication.operation.provider_thread_id.as_deref()
                        .ok_or("publication has no provider ID")?,
                );
                let path_origins_ref = repository.store_path_origins(owner, &publication.path_origins)?;
                let scope = writable_scopes.get_mut(&SyncScopeKey::Provider(action.provider.clone()))
                    .expect("the scope was checked before preparation");
                let (checkpoint, operation) = commit_conversation_publication(scope, publication);
                planned_origins.insert(operation.operation_id.clone(), path_origins_ref);
                planned_checkpoints.insert(operation.operation_id.clone(), checkpoint);
                operations.push(operation);
                Ok(())
            });
            if let Err(refusal) = outcome {
                indexed_failures.push((
                    index,
                    PushThreadFailure {
                        resource_id: conversation_action_row_key(action)
                            .expect("the resource was checked before preparation"),
                        message: refusal.message,
                        edited_since_acceptance: action
                            .thread_id
                            .clone()
                            .filter(|_| refusal.edited_since_acceptance)
                            .map(|thread_id| (action.provider.clone(), thread_id)),
                    },
                ));
            }
        },
    );
    if let Some(error) = batch_error {
        return Err(error);
    }
    indexed_failures.sort_by_key(|(index, _)| *index);
    let failures = indexed_failures
        .into_iter()
        .map(|(_, failure)| failure)
        .collect::<Vec<_>>();
    // Build one final state for all sessions that will publish.
    operations.sort_by(|left, right| left.operation_id.cmp(&right.operation_id));
    let mut running = reviewed_config.clone();
    let mut running_bindings = document.clone();
    for operation in &operations {
        let checkpoint = planned_checkpoints
            .get(&operation.operation_id)
            .cloned()
            .ok_or_else(|| "planned conversation checkpoint disappeared".to_string())?;
        let path_origins_ref = planned_origins
            .get(&operation.operation_id)
            .ok_or("planned path origins disappeared")?
            .clone();

        let layout = RootTailLayout {
            codec: checkpoint.observed_tail.codec.clone(),
            partition_kind: checkpoint.observed_tail.partition_kind,
            start_record_count: checkpoint.observed_tail.start_record_count,
        };
        match running_bindings.bindings.iter_mut().find(|row| {
            row.host_id == operation.host_id
                && row.replica_id == operation.replica_id
                && row.local_project_id == operation.local_project_id
                && row.provider_profile_id == operation.provider_profile_id
                && row.thread_id == operation.thread_id
        }) {
            Some(row) => {
                row.path_origins_ref = Some(path_origins_ref.clone());
                row.provider_thread_id = operation.provider_thread_id.clone();
                row.materialization_state = ConversationMaterializationState::Resumable;
                // A first CreateCloud commits the freshly minted mapping; a
                // mapped Publish rewrites the same value it already carries.
                row.cloud_thread_id = Some(operation.cloud_thread_id.clone());
                if row.root_tail_layout.is_none() {
                    row.root_tail_layout = Some(layout);
                }
                row.revision = row.revision.saturating_add(1);
                row.updated_at = updated_at;
            }
            None => running_bindings.bindings.push(LocalConversationBinding {
                installed_end: None,
                installed_absent_subagents: Default::default(),
                pulled_children_excluded: false,
                installed_subagents: Default::default(),
                path_origins_ref: Some(path_origins_ref),
                host_id: operation.host_id.clone(),
                replica_id: operation.replica_id.clone(),
                local_project_id: operation.local_project_id.clone(),
                provider_profile_id: operation.provider_profile_id.clone(),
                thread_id: operation.thread_id.clone(),
                cloud_thread_id: Some(operation.cloud_thread_id.clone()),
                forked_from: None,
                preserved: None,
                root_tail_layout: Some(layout),
                provider_thread_id: operation.provider_thread_id.clone(),
                materialization_state: ConversationMaterializationState::Resumable,
                revision: 0,
                created_at: updated_at,
                updated_at,
            }),
        }
        let scope = SyncScopeKey::Provider(operation.provider.clone());
        let link = running
            .links
            .iter_mut()
            .find(|link| {
                link.local_project_id == operation.local_project_id
                    && link.storage_id == operation.cloud.storage_id
            })
            .ok_or_else(|| "conversation Push requires a registered storage link".to_string())?;
        let threads = link.conversation_checkpoints.entry(scope).or_default();
        let generation = threads
            .get(&operation.thread_id)
            .map(|existing| existing.generation.saturating_add(1))
            .unwrap_or(0);
        let mut checkpoint = checkpoint;
        checkpoint.generation = generation;
        threads.insert(operation.thread_id.clone(), checkpoint);
    }
    running.revision = running.revision.saturating_add(1);
    running_bindings.revision = running_bindings.revision.saturating_add(1);
    let publication_state = ConversationPublicationState {
        sync_config_before: reviewed_config,
        sync_config_after: running,
        bindings_before: document,
        bindings_after: running_bindings,
    };
    // Every carried conversation stays selected in its scope's recipe.
    for scope in writable_scopes.values_mut() {
        for thread in scope.conversations.values() {
            scope.recipe.entries.insert(
                thread.resource_id.clone(),
                RecipeEntry {
                    resource_id: thread.resource_id.clone(),
                    apply_policy: contracts::safe_file(),
                    required: false,
                },
            );
        }
    }
    Ok((
        PublishBundleRequest {
            git_history: None,
            identity: BundleIdentity {
                bundle_id: project.bundle_id.clone(),
                display_name: project.display_name.clone(),
                kind: BundleKind::Project,
                repository_fingerprint: project.repository_fingerprint.clone(),
            },
            published_by_origin: published_by,
            writable_scopes,
            reviewed_scope_pins,
            expected_head,
            updated_at,
        },
        operations,
        publication_state,
        failures,
    ))
}

fn cloud_publication_from_snapshot(snapshot: &BundleSnapshot) -> ConversationCloudPublication {
    ConversationCloudPublication {
        revision: snapshot.head.revision,
        commit_id: snapshot.head.commit_id.clone(),
        manifest_sha256: snapshot.head.manifest_sha256.clone(),
    }
}

/// Prove every provider thread can be committed to its reviewed binding
/// before immutable publication and the record write.  The binding
/// document's global uniqueness check remains the final invariant, but it is
/// too late to discover an ownership conflict after the cloud commit.
fn validate_cloud_publication_binding_owners(
    bindings: &[LocalConversationBinding],
    operations: &[ConversationApplyOperation],
) -> Result<(), String> {
    let mut owners = BTreeMap::new();
    for binding in bindings {
        let Some(provider_thread_id) = binding.provider_thread_id.as_ref() else {
            continue;
        };
        owners.insert(
            (
                binding.host_id.clone(),
                binding.provider_profile_id.clone(),
                provider_thread_id.clone(),
            ),
            (
                binding.replica_id.clone(),
                binding.local_project_id.clone(),
                binding.thread_id.clone(),
            ),
        );
    }
    for operation in operations {
        let Some(provider_thread_id) = operation.provider_thread_id.as_deref() else {
            continue;
        };
        let owner_key = (
            operation.host_id.clone(),
            operation.provider_profile_id.clone(),
            provider_thread_id.to_string(),
        );
        let target = (
            operation.replica_id.clone(),
            operation.local_project_id.clone(),
            operation.thread_id.clone(),
        );
        if owners
            .get(&owner_key)
            .is_some_and(|current| current != &target)
        {
            return Err(
                "conversation Push cannot publish because a selected provider thread belongs to another local project registration; re-register that project before pushing"
                    .to_string(),
            );
        }
        owners.insert(owner_key, target);
    }
    Ok(())
}

struct ReviewedPublishOutcome {
    /// What the engine stored or compared to; nothing when every selected
    /// conversation failed to build on an empty stream.
    publication: Option<PublishedBundle>,
    /// Selected conversations the request could not build; nothing of
    /// theirs was published.
    failures: Vec<PushThreadFailure>,
}

#[allow(clippy::too_many_arguments)]
fn publish_reviewed(
    repository: &LocalStateRepository,
    engine: &StorageEngine,
    storage_id: &StorageId,
    project: &LocalProjectRegistration,
    binding: &ProjectBinding,
    recipe: &BundleRecipe,
    captured: provider_capture::CapturedResources,
    observed: Option<(
        BundleSnapshot,
        mallard_infrastructure::bundle_engine::HeadToken,
    )>,
    selected_actions: Vec<ConversationPlanAction>,
    prepared_codex: PreparedCodexPublications,
    updated_at: u64,
    on_progress: &mut dyn FnMut(FetchProgress),
    on_phase: &mut dyn FnMut(&str, Duration),
    credential_redaction_enabled: bool,
    git_history: Option<mallard_domain::GitHistorySnapshot>,
) -> Result<ReviewedPublishOutcome, String> {
    let phase_started = Instant::now();
    set_cloud_project_origin(engine, project, binding)?;
    let previous = observed.as_ref().map(|(snapshot, _)| snapshot);
    let expected_head = observed
        .as_ref()
        .map(|(snapshot, token)| {
            PublishExpectation::Match(Box::new(snapshot.clone()), token.clone())
        })
        .unwrap_or(PublishExpectation::Absent);
    let plan_id = PlanId::parse(generated_named_id("apply")?)?;
    on_phase("build conversation actions", phase_started.elapsed());
    let phase_started = Instant::now();
    let resolved_binding = resolve_project_binding(repository, binding)?;
    let (mut request, operations, publication_state, failures) = build_publish_request(
        repository,
        &plan_id,
        storage_id,
        project,
        binding,
        &resolved_binding.homes,
        recipe,
        captured,
        previous,
        expected_head,
        &selected_actions,
        prepared_codex,
        updated_at,
        credential_redaction_enabled,
    )?;
    let git_history_review_token = git_history
        .as_ref()
        .map(project_activity::git_history_review_token)
        .transpose()?;
    request.git_history = git_history;
    let verify_git = || -> Result<(), String> {
        if let Some(token) = &git_history_review_token {
            project_activity::verify_git_history_review(Path::new(&binding.project_root), token)?;
        }
        Ok(())
    };
    validate_cloud_publication_binding_owners(
        &publication_state.bindings_before.bindings,
        &operations,
    )?;
    on_phase("build publish request", phase_started.elapsed());
    let phase_started = Instant::now();
    if operations.is_empty() {
        // A failed conversation selection must not create an empty first revision.
        // Ordinary resource captures still use the normal publication path.
        if previous.is_none()
            && request.writable_scopes.values().all(|scope| {
                scope.captured_files.is_empty()
                    && scope.directories.is_empty()
                    && scope.conversations.is_empty()
                    && scope.tombstones.is_empty()
            })
        {
            return Ok(ReviewedPublishOutcome {
                publication: None,
                failures,
            });
        }
        verify_git()?;
        let outcome = engine.publish_with_progress(request, on_progress, on_phase)?;
        return Ok(ReviewedPublishOutcome {
            publication: Some(outcome),
            failures,
        });
    }
    let publish_outcome = std::cell::RefCell::new(None);
    apply_conversation_cloud_publications_locked(
        repository,
        operations,
        publication_state,
        || {
            verify_git()?;
            let outcome = engine.publish_with_progress(request, on_progress, &mut *on_phase)?;
            let publication = cloud_publication_from_snapshot(outcome.snapshot());
            *publish_outcome.borrow_mut() = Some(outcome);
            Ok(publication)
        },
    )?;
    on_phase(
        "publish conversations and receipts",
        phase_started.elapsed(),
    );
    let outcome = publish_outcome
        .into_inner()
        .ok_or_else(|| "conversation publication produced no bundle result".to_string())?;
    Ok(ReviewedPublishOutcome {
        publication: Some(outcome),
        failures,
    })
}

#[cfg(test)]
#[allow(clippy::too_many_arguments)]
fn push_bundle_reviewed_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
    requested_recipe: BundleRecipe,
    mut project_content_review: ProjectContentPushReview,
    on_progress: &mut dyn FnMut(FetchProgress),
) -> Result<ProjectOperationResult, String> {
    // Older content-review fixtures do not exercise the Git review. Supply
    // that new approval from their temporary repository, as the UI now does.
    if project_content_review.git_history_review_token.is_none() {
        let state = repository.load_project_state_snapshot()?;
        if let (Some(project), Some(binding)) = (
            state.config.project(local_project_id),
            state.bindings.active_for(local_project_id),
        ) {
            project_content_review.git_history_review_token =
                capture_binding_git_history(&state.config, storage_id, project, binding)?
                    .as_ref()
                    .map(project_activity::git_history_review_token)
                    .transpose()?;
        }
    }
    push_bundle_reviewed_with_progress(
        repository,
        local_project_id,
        storage_id,
        requested_recipe,
        project_content_review,
        on_progress,
        &mut |_, _| {},
    )
}

/// The comparison that offered an edited session read it through its
/// cursor, which never saw the edit. Forget the file state that cursor was
/// saved from: a cursor without one is not used, so the next comparison
/// reads the session in full and finds the edit itself. Everything that
/// was accepted stays saved.
fn stop_using_cursors_of_edited_sessions(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
    failures: &[PushThreadFailure],
) -> Result<(), String> {
    let edited = failures
        .iter()
        .filter_map(|failure| failure.edited_since_acceptance.as_ref())
        .collect::<Vec<_>>();
    if edited.is_empty() {
        return Ok(());
    }
    repository
        .transact_config(|config| {
            let Some(link) = config.links.iter_mut().find(|link| {
                &link.local_project_id == local_project_id && &link.storage_id == storage_id
            }) else {
                return Ok::<_, String>(ConfigMutation::Unchanged(()));
            };
            let mut stopped = false;
            for (provider, thread_id) in &edited {
                let Some(checkpoint) = link
                    .conversation_checkpoints
                    .get_mut(&SyncScopeKey::Provider(provider.clone()))
                    .and_then(|threads| threads.get_mut(thread_id))
                else {
                    continue;
                };
                if let PhysicalMappingState::Ready { source_state, .. } = &mut checkpoint.physical {
                    if source_state.take().is_some() {
                        checkpoint.generation = checkpoint.generation.saturating_add(1);
                        stopped = true;
                    }
                }
            }
            Ok(if stopped {
                ConfigMutation::Changed(())
            } else {
                ConfigMutation::Unchanged(())
            })
        })
        .map_err(config_transaction_error)?;
    Ok(())
}

/// Result-row state for a selected conversation the Push could not publish.
const PUSH_RESULT_FAILED: &str = "failed";
/// Result-row state for a selected conversation a Pull has to resolve first.
const PUSH_RESULT_HELD: &str = "held";

/// One result row per selected conversation the Push did not publish, keyed
/// by the review's resource id: a thread that failed to build carries its
/// build error; a thread the apply-time review withheld carries the review's
/// reason, as `held` when a Pull resolves it and as `failed` otherwise.
/// Up-to-date threads and rows the review never produced (suppressed
/// aliases, discovery-blocked sources) were never pushable and add nothing.
fn conversation_push_results(
    selected: &BTreeSet<ResourceId>,
    actioned: &BTreeSet<ResourceId>,
    entries: &[ThreadSyncEntry],
    failures: Vec<PushThreadFailure>,
) -> Vec<OperationResourceResult> {
    let mut results = failures
        .into_iter()
        .map(|failure| OperationResourceResult {
            resource_id: failure.resource_id,
            state: PUSH_RESULT_FAILED.to_string(),
            message: Some(failure.message),
        })
        .collect::<Vec<_>>();
    for resource_id in selected {
        if actioned.contains(resource_id)
            || results
                .iter()
                .any(|result| &result.resource_id == resource_id)
        {
            continue;
        }
        let Some(entry) = entries
            .iter()
            .find(|entry| &entry.resource_id == resource_id)
        else {
            continue;
        };
        let decision = &entry.push_decision;
        if decision.action == ConversationReviewAction::NoChanges {
            continue;
        }
        let held = matches!(
            decision.action,
            ConversationReviewAction::RequirePull | ConversationReviewAction::RequirePullMetadata
        ) || decision.blocker == Some(ConversationBlocker::DetachedRequiresPull);
        let message = decision
            .blocked_reason
            .clone()
            .or_else(|| entry.status_detail.clone())
            .unwrap_or_else(|| {
                if held {
                    "Storage has changes this Push did not include. Pull first, then push again."
                        .to_string()
                } else {
                    "This conversation was not pushable when the Push ran.".to_string()
                }
            });
        results.push(OperationResourceResult {
            resource_id: resource_id.clone(),
            state: if held {
                PUSH_RESULT_HELD
            } else {
                PUSH_RESULT_FAILED
            }
            .to_string(),
            message: Some(message),
        });
    }
    results
}

#[allow(clippy::too_many_arguments)]
/// The user's verb for a push onto the selected version that did not
/// finish (CAS-free plan, section 13): write the record its claim holds,
/// once, and report with the sentences of the Push review. Nothing runs it
/// by itself, and nothing local moves: the user compares again afterwards.
pub(super) fn finish_unfinished_push(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<(), String> {
    let _host_operation = repository.acquire_host_operation()?;
    let state = repository.load_project_state_snapshot()?;
    let config = &state.config;
    let project = config
        .project(local_project_id)
        .cloned()
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
    let link = require_project_link(config, &project, storage_id)?.clone();
    let (storage, engine) =
        storage_engine_from_state(repository, config, &state.bindings, storage_id)?;
    engine
        .finish_unfinished_push(&link.bundle_id)
        .map_err(|error| unfinished_push_sentence(&storage.name, error))
}

pub(super) fn push_bundle_reviewed_with_progress(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
    requested_recipe: BundleRecipe,
    project_content_review: ProjectContentPushReview,
    on_progress: &mut dyn FnMut(FetchProgress),
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<ProjectOperationResult, String> {
    requested_recipe.validate_machine_local()?;
    let phase_started = Instant::now();
    let _host_operation = repository.acquire_host_operation()?;
    let settings = mallard_infrastructure::app_settings::load_app_settings(repository)?;
    let credential_redaction_enabled = settings.credential_redaction_enabled;
    if credential_redaction_enabled != project_content_review.credential_redaction_enabled {
        return Err("Credential redaction changed after review. Review Push again.".into());
    }
    let state = repository.load_project_state_snapshot()?;
    let config = &state.config;
    let project = config
        .project(local_project_id)
        .cloned()
        .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
    let link = require_project_link(&config, &project, storage_id)?.clone();
    let stored_destination_recipe = link.recipe.clone();
    let expected_preference_revision = link.project_content_preferences.revision;
    let binding = state
        .bindings
        .active_for(local_project_id)
        .cloned()
        .ok_or_else(|| {
            format!(
                "project '{}' is not mapped on this machine",
                local_project_id
            )
        })?;
    on_phase("load config and binding", phase_started.elapsed());
    let phase_started = Instant::now();
    // One provider walk feeds byte capture and the apply-time review. A
    // Push with a review token also walks the project content.
    let wants_project_content = project_content_review.review_token.is_some();
    let eligibility = project_file_sync_eligibility(&binding);
    if wants_project_content && eligibility.state != ProjectFileSyncEligibilityState::Eligible {
        return Err(eligibility.reason);
    }
    let resolved = resolve_project_binding_from_state(&state.bindings, &binding)?;
    let git_history = capture_binding_git_history(config, storage_id, &project, &binding)?;
    let actual_git_token = git_history
        .as_ref()
        .map(project_activity::git_history_review_token)
        .transpose()?;
    if actual_git_token != project_content_review.git_history_review_token {
        return Err("Git history changed after review. Review Push again.".into());
    }
    let mut capture_request = capture_request_for_resolved_binding_from_state(
        repository.root(),
        config,
        &state.bindings,
        &resolved,
    )?;
    capture_request.include_project_content = wants_project_content;
    let (discovery, views) =
        provider_capture::discover_sessions(provider_registry(), &capture_request)?;
    let discovered = discovery.project_inventory();
    on_phase("discover local state", phase_started.elapsed());
    let phase_started = Instant::now();
    let (storage, engine) =
        storage_engine_from_state(repository, config, &state.bindings, storage_id)?;
    // Apply starts: list the stream and select. Everything below is checked
    // and built against this freshly selected publication, and the record
    // names it as its parent.
    let (observation, _) = observe_linked_bundle(repository, &engine, &link)?;
    let mainline = observation.mainline;
    let observed = observation.current;
    let remote_project_content = observed
        .as_ref()
        .map(|(snapshot, _)| project_content_versions(&snapshot.manifest))
        .transpose()?
        .unwrap_or_default();
    on_phase("inspect remote head", phase_started.elapsed());
    let phase_started = Instant::now();
    let mut push_recipe = requested_recipe;
    remove_excluded_codex_subagents_from_recipe(
        &mut push_recipe,
        discovery.excluded_subagent_resource_ids(),
    );
    let saved_project_content_entries = stored_destination_recipe
        .as_ref()
        .map(|recipe| {
            recipe
                .entries
                .iter()
                .filter(|(resource_id, _)| {
                    mallard_domain::is_project_content_resource_id(resource_id)
                })
                .map(|(resource_id, entry)| (resource_id.clone(), entry.clone()))
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_default();
    for resource_id in &project_content_review.removal_ids {
        if !saved_project_content_entries.contains_key(resource_id) {
            return Err(format!(
                "project-content removal '{}' is not currently stored for this destination",
                resource_id
            ));
        }
        if push_recipe.entries.contains_key(resource_id) {
            return Err(format!(
                "project-content removal '{}' is also selected for publication",
                resource_id
            ));
        }
    }
    for (resource_id, entry) in &saved_project_content_entries {
        if remote_project_content.contains_key(resource_id)
            && !push_recipe.entries.contains_key(resource_id)
            && !project_content_review.removal_ids.contains(resource_id)
        {
            push_recipe
                .entries
                .insert(resource_id.clone(), entry.clone());
        }
    }

    let requested_project_content_ids = push_recipe
        .entries
        .keys()
        .filter(|resource_id| mallard_domain::is_project_content_resource_id(resource_id))
        .cloned()
        .collect::<BTreeSet<_>>();
    let project_content_selection_changed = requested_project_content_ids
        != saved_project_content_entries
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>()
        || !project_content_review.removal_ids.is_empty();
    on_phase("reconcile selection and recipe", phase_started.elapsed());
    let mut phase_started = Instant::now();
    let mut reviewed_inventory = None;
    if let Some(review_token) = project_content_review.review_token.as_deref() {
        // The freshness check derives from the same walk instant and the same
        // observed publication as the capture and the record's parent below.
        let inventory = build_project_files_inventory(
            local_project_id,
            storage_id,
            &project,
            &link,
            &binding,
            eligibility.clone(),
            &engine,
            observed.as_ref().map(|(snapshot, _)| snapshot),
            &mainline,
            Some(&discovery),
        )?;
        if inventory.review_token.as_deref() != Some(review_token) {
            return Err(
                "project files changed after Scan; rescan and review them before pushing"
                    .to_string(),
            );
        }
        let entries_by_id = inventory
            .entries
            .iter()
            .map(|entry| (entry.descriptor.resource_id.clone(), entry))
            .collect::<BTreeMap<_, _>>();
        for resource_id in requested_project_content_ids.clone() {
            let entry = entries_by_id.get(&resource_id).ok_or_else(|| {
                format!(
                    "selected project-content resource '{}' was not in the reviewed scan",
                    resource_id
                )
            })?;
            if entry.blocked_reason.is_some() {
                return Err(format!(
                    "selected project-content resource '{}' is blocked",
                    resource_id
                ));
            }
            if !entry.local_present && !saved_project_content_entries.contains_key(&resource_id) {
                return Err(format!(
                    "new project-content resource '{}' disappeared after review",
                    resource_id
                ));
            }
            if let Some(warning_digest) = &entry.warning_digest {
                if entry.local_present
                    && !project_content_review
                        .acknowledged_warning_digests
                        .contains(warning_digest)
                {
                    return Err(format!(
                        "project-content warning for '{}' requires explicit acknowledgement",
                        entry.relative_path
                    ));
                }
            }
            if entry.entry_type == ProjectContentEntryType::File && entry.local_present {
                for ancestor in project_content_ancestor_paths(&entry.relative_path) {
                    let required = inventory.entries.iter().find(|candidate| {
                        candidate.entry_type == ProjectContentEntryType::Directory
                            && candidate.relative_path == ancestor
                    });
                    let required = required.ok_or_else(|| {
                        format!(
                            "selected file '{}' lacks reviewed directory '{}'",
                            entry.relative_path, ancestor
                        )
                    })?;
                    let required_id = required.descriptor.resource_id.clone();
                    push_recipe
                        .entries
                        .entry(required_id.clone())
                        .or_insert(RecipeEntry {
                            resource_id: required_id,
                            apply_policy: contracts::explicit_review(),
                            required: true,
                        });
                }
            }
        }
        for removed_directory in project_content_review.removal_ids.iter().filter_map(|id| {
            entries_by_id
                .get(id)
                .filter(|entry| entry.entry_type == ProjectContentEntryType::Directory)
        }) {
            if inventory.entries.iter().any(|candidate| {
                candidate.storage_present
                    && candidate
                        .relative_path
                        .starts_with(&format!("{}/", removed_directory.relative_path))
                    && push_recipe
                        .entries
                        .contains_key(&candidate.descriptor.resource_id)
            }) {
                return Err(format!(
                    "directory '{}' cannot be removed while stored descendants remain selected",
                    removed_directory.relative_path
                ));
            }
        }
        reviewed_inventory = Some(inventory);
        on_phase("verify reviewed project files", phase_started.elapsed());
        phase_started = Instant::now();
    } else if project_content_selection_changed {
        return Err(
            "Scan and review Project files before changing stored project content".to_string(),
        );
    }

    push_recipe.validate()?;
    push_recipe.revision = match &stored_destination_recipe {
        Some(current) if current.entries == push_recipe.entries => current.revision,
        Some(current) => current.revision.saturating_add(1),
        None => 1,
    };
    let capture = provider_capture::capture_recipe_from_discovery(
        provider_registry(),
        &capture_request,
        &discovery,
        &push_recipe,
        credential_redaction_enabled,
    )?;
    on_phase("capture selected payloads", phase_started.elapsed());
    let destination_status = classify_push_destination(
        observed.as_ref().map(|(snapshot, _)| snapshot),
        &mainline,
        &link,
        &binding,
    );
    if let Some(error) = push_destination_error(&destination_status) {
        return Err(error);
    }
    let pushed_at = now_secs();
    let selected_conversations = discovered
        .resources
        .iter()
        .filter(|candidate| {
            kind_primitive(&candidate.kind) == Some(ResourceKindPrimitive::Conversation)
                && push_recipe.entries.contains_key(
                    &ResourceId::parse(candidate.resource_id.clone()).unwrap_or_else(|_| {
                        unreachable!("discovery produced an invalid resource id")
                    }),
                )
        })
        .map(|candidate| ResourceId::parse(candidate.resource_id.clone()))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let review_started = Instant::now();
    let no_pins = BTreeMap::new();
    let review = match observed.as_ref().map(|(snapshot, _)| snapshot) {
        Some(snapshot) => {
            let mut bytes = engine.byte_source(snapshot, None);
            thread_review(
                repository,
                Some(snapshot),
                &mainline,
                &mut bytes,
                &views,
                &capture,
                &no_pins,
                &resolved,
                Some(storage_id),
                pushed_at,
                pushed_at,
                ReviewPurpose::PushPlan,
                Some(&selected_conversations),
                &settings,
            )?
        }
        None => {
            let mut bytes = EmptyBundleBytes;
            thread_review(
                repository,
                None,
                &mainline,
                &mut bytes,
                &views,
                &capture,
                &no_pins,
                &resolved,
                Some(storage_id),
                pushed_at,
                pushed_at,
                ReviewPurpose::PushPlan,
                Some(&selected_conversations),
                &settings,
            )?
        }
    };
    on_phase("review selected conversations", review_started.elapsed());
    let ThreadReview {
        entries: reviewed_entries,
        push_actions: mut selected_actions,
        prepared_codex,
        provider_errors,
        ..
    } = review;
    if let Some((provider, message)) = provider_errors.into_iter().next() {
        return Err(format!(
            "{} conversation apply failed: {}",
            provider, message
        ));
    }
    let stale_children = reviewed_entries
        .iter()
        .filter(|entry| selected_conversations.contains(&entry.resource_id))
        .filter(|entry| {
            let expected = project_content_review
                .subagent_selections
                .get(&entry.resource_id)
                .cloned()
                .unwrap_or_default();
            expected.keys != entry.subagent_selection.keys
                || expected.omitted != entry.subagent_selection.omitted
                || expected.wire_children != entry.subagent_selection.wire_children
        })
        .map(|entry| PushThreadFailure {
            resource_id: entry.resource_id.clone(),
            message: owned_subagents::PUSH_CHANGED.into(),
            edited_since_acceptance: None,
        })
        .collect::<Vec<_>>();
    selected_actions.retain(|action| {
        !stale_children
            .iter()
            .any(|failure| action.source_resource_id.as_ref() == Some(&failure.resource_id))
    });
    let actioned_resources = selected_actions
        .iter()
        .filter_map(|action| action.source_resource_id.clone())
        .collect::<BTreeSet<_>>();
    let mut publish_outcome = publish_reviewed(
        repository,
        &engine,
        storage_id,
        &project,
        &binding,
        &push_recipe,
        capture,
        observed,
        selected_actions,
        prepared_codex,
        pushed_at,
        on_progress,
        &mut *on_phase,
        credential_redaction_enabled,
        git_history,
    )
    .map_err(|error| unfinished_push_sentence(&storage.name, error))?;
    stop_using_cursors_of_edited_sessions(
        repository,
        local_project_id,
        storage_id,
        &publish_outcome.failures,
    )?;
    publish_outcome.failures.extend(stale_children);
    let thread_results = conversation_push_results(
        &selected_conversations,
        &actioned_resources,
        &reviewed_entries,
        publish_outcome.failures,
    );
    let phase_started = Instant::now();
    let Some(publication) = publish_outcome.publication else {
        return Ok(ProjectOperationResult {
            success: false,
            message: "Nothing published".into(),
            operation_id: None,
            resources_changed: Some(0),
            revision: None,
            results: thread_results,
        });
    };
    let was_published = publication.stored();
    // A stored publication is the selected one: a push whose record ranked
    // behind another computer's failed above, before any base moved.
    let published_snapshot = publication.into_snapshot();
    let revision = published_snapshot.head.revision;
    let commit_id = published_snapshot.head.commit_id.clone();
    let manifest_size = published_snapshot.head.manifest_size;
    let manifest_sha256 = published_snapshot.head.manifest_sha256.clone();
    let expected_project_revision = project.revision;
    let expected_project_recipe_revision = project.recipe.revision;
    let bundle_id = project.bundle_id.clone();
    // Advance a base for every writable scope that published — and only for
    // those. Viewed, unbound, and unknown scopes never move.
    let published_scope_coordinates = published_snapshot.manifest.scope_coordinates();
    let writable_scopes = writable_scopes_for_binding(&binding);
    let published_repository_base = RepositoryBase {
        revision,
        commit_id: commit_id.clone(),
        manifest_sha256: manifest_sha256.clone(),
        manifest_size,
    };
    let cloud_repository = cloud_repository_in_use(&engine, &bundle_id)?;
    repository.mutate_config(|config| {
        let current = config
            .projects
            .iter_mut()
            .find(|current| current.local_project_id == *local_project_id)
            .ok_or_else(|| "project was removed while publishing".to_string())?;
        if current.revision != expected_project_revision
            || current.recipe.revision != expected_project_recipe_revision
            || current.bundle_id != bundle_id
        {
            return Err(
"project recipe changed while publishing; the push was stored, refresh before pushing again"
                    .to_string(),
            );
        }
        save_cloud_pin(config, storage_id, &bundle_id, cloud_repository.as_ref());
        let current = config
            .projects
            .iter_mut()
            .find(|current| current.local_project_id == *local_project_id)
            .ok_or_else(|| "project was removed while publishing".to_string())?;
        {
            let current_link = config
                .links
                .iter_mut()
                .find(|link| {
                    link.local_project_id == *local_project_id && link.storage_id == *storage_id
                })
                .ok_or_else(|| "project storage link was removed while publishing".to_string())?;
            for scope in &writable_scopes {
                let last_pull_at = current_link
                    .scope_bases
                    .get(scope)
                    .and_then(|base| base.last_pull_at);
                match published_scope_coordinates.get(scope) {
                    Some((scope_revision, scope_sha256)) => {
                        current_link.scope_bases.insert(
                            scope.clone(),
                            ScopeBase {
                                scope: scope.clone(),
                                scope_revision: *scope_revision,
                                scope_sha256: scope_sha256.clone(),
                                reviewed_in: published_repository_base.clone(),
                                binding_revision: binding.revision,
                                last_pull_at,
                                last_push_at: Some(pushed_at),
                            },
                        );
                    }
                    None => {
                        current_link.scope_bases.remove(scope);
                    }
                }
            }
            drop_stale_scope_bases(current_link, &mainline, &published_repository_base);
        }
        let current_link = config
            .links
            .iter_mut()
            .find(|link| {
                link.local_project_id == *local_project_id && link.storage_id == *storage_id
            })
            .ok_or_else(|| "project storage link was removed while publishing".to_string())?;
        if current_link.recipe != stored_destination_recipe
            || current_link.project_content_preferences.revision != expected_preference_revision
        {
            return Err(
"project-file choices changed while publishing; the push was stored, refresh before pushing again"
                    .to_string(),
            );
        }
        current_link.recipe = Some(push_recipe.clone());
        if let Some(inventory) = &reviewed_inventory {
            let previous_exclusions = current_link
                .project_content_preferences
                .excluded_resource_ids
                .clone();
            let mut exclusions = previous_exclusions.clone();
            for entry in &inventory.entries {
                if !entry.local_present || entry.entry_type == ProjectContentEntryType::Blocked {
                    continue;
                }
                if push_recipe
                    .entries
                    .contains_key(&entry.descriptor.resource_id)
                {
                    exclusions.remove(&entry.descriptor.resource_id);
                } else {
                    exclusions.insert(entry.descriptor.resource_id.clone());
                }
            }
            exclusions.extend(project_content_review.removal_ids.iter().cloned());
            if exclusions != previous_exclusions {
                current_link.project_content_preferences.revision = current_link
                    .project_content_preferences
                    .revision
                    .saturating_add(1);
                current_link
                    .project_content_preferences
                    .excluded_resource_ids = exclusions;
            }
            current_link.project_content_preferences.validate()?;
        }
        current.revision = current.revision.saturating_add(1);
        current.updated_at = pushed_at;
        Ok(())
    })?;
    on_phase("persist push receipts and config", phase_started.elapsed());
    let state = if was_published { "synced" } else { "unchanged" };
    let mut results = published_snapshot
        .manifest
        .all_resources()
        .map(|(resource_id, _)| OperationResourceResult {
            resource_id: resource_id.clone(),
            state: state.to_string(),
            message: None,
        })
        .collect::<Vec<_>>();
    let resources_changed = Some(if was_published { results.len() } else { 0 });
    let failed = thread_results
        .iter()
        .filter(|result| result.state == PUSH_RESULT_FAILED)
        .count();
    results.extend(thread_results);
    let sessions = |count: usize| if count == 1 { "session" } else { "sessions" };
    let message = match (was_published, failed) {
        (true, 0) => format!("Published version {}", revision),
        (true, failed) => format!(
            "Published version {} — {} {} not pushed",
            revision,
            failed,
            sessions(failed)
        ),
        (false, 0) => format!("Already up to date — version {}", revision),
        (false, failed) => format!("Nothing published — {} {} failed", failed, sessions(failed)),
    };
    Ok(ProjectOperationResult {
        // A Push succeeds when every selected thread it could act on was
        // published; a failed thread is reported, never hidden.
        success: failed == 0,
        message,
        operation_id: Some(commit_id),
        resources_changed,
        revision: Some(revision),
        results,
    })
}

pub(super) fn plan_bundle_restore_with_progress(
    repository: &LocalStateRepository,
    storage_id: &StorageId,
    bundle_id: &BundleId,
    binding: &ProjectBinding,
    _on_progress: &mut dyn FnMut(FetchProgress),
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<RestorePlan, String> {
    let phase_started = Instant::now();
    let _host_operation = repository.acquire_host_operation()?;
    let state = repository.load_project_state_snapshot()?;
    let resolved = require_current_binding_from_state(&state.bindings, binding)?;
    let binding = resolved.binding.clone();
    if &binding.bundle_id != bundle_id {
        return Err("binding and requested bundle IDs differ".to_string());
    }
    let config = &state.config;
    let (_, engine) = storage_engine_from_state(repository, config, &state.bindings, storage_id)?;
    if config.project(&binding.local_project_id).is_none() {
        return Err(format!(
            "unknown local project '{}'",
            binding.local_project_id
        ));
    }
    let link = project_link(&config, &binding.local_project_id, storage_id)
        .cloned()
        .ok_or_else(|| "project is not linked to this storage".to_string())?;
    let (observation, remote_continuity) = observe_linked_bundle(repository, &engine, &link)?;
    let mainline = observation.mainline;
    let Some((snapshot, _)) = observation.current else {
        // A computer that holds a base for this storage synced with it
        // before: the storage was cleared, and the standing notice already
        // says to push again. Without a base the storage is one this
        // computer never used, and the text opens the chooser of the
        // projects it does hold.
        if !link.scope_bases.is_empty() {
            let (_, storage_name, _) =
                project_storage_log_context(repository, &binding.local_project_id, storage_id);
            return Err(format!("There is nothing to pull from {storage_name}."));
        }
        return Err(format!("bundle '{}' does not exist", bundle_id));
    };
    on_phase("inspect remote head and manifest", phase_started.elapsed());
    let phase_started = Instant::now();
    let identity = &state.host_identity;
    if identity.host_id != binding.host_id {
        return Err("host identity changed while preparing the Pull review".to_string());
    }
    // Reviewed-base content digests decide which diverged project files must
    // preserve their local bytes as a visible copy. A stale or unavailable
    // base yields an empty map, which fails closed to preservation.
    let project_content_bases = project_content_base_content_digests(
        &engine,
        bundle_id,
        &link,
        &mainline,
        &snapshot.manifest,
    );
    let mut plan = engine.build_restore_plan_from_snapshot(
        provider_registry(),
        &snapshot,
        &binding,
        &resolved.homes,
        &project_content_bases,
        now_secs(),
        identity.revision,
    )?;
    plan.remote_continuity = Some(remote_continuity);
    on_phase("build file restore plan", phase_started.elapsed());
    if !resolved.homes.is_empty() {
        let phase_started = Instant::now();
        let mut byte_source = engine.byte_source(&snapshot, None);
        let capture_request = capture_request_for_resolved_binding_from_state(
            repository.root(),
            config,
            &state.bindings,
            &resolved,
        )?;
        let (_discovery, views) =
            provider_capture::discover_sessions(provider_registry(), &capture_request)?;
        let review = thread_review(
            repository,
            Some(&snapshot),
            &mainline,
            &mut byte_source,
            &views,
            &provider_capture::CapturedResources::default(),
            &BTreeMap::new(),
            &resolved,
            Some(&plan.storage_id),
            plan.created_at,
            plan.created_at,
            ReviewPurpose::Observe,
            None,
            &AppSettings::default(),
        )?;
        plan.conversation_actions.clear();
        plan.conversation_review = review
            .entries
            .into_iter()
            .filter(|entry| entry.pull_decision.action != ConversationReviewAction::NoChanges)
            .map(|entry| {
                let local_thread_id = entry
                    .local_present
                    .then(|| {
                        parse_conversation_resource_id(entry.conversation_resource_id.as_str())
                    })
                    .transpose()?
                    .map(|(_, thread_id)| thread_id);
                let action_id = entry
                    .pull_decision
                    .action
                    .planned_action()
                    .map(|_| ActionId::parse(generated_named_id("selection")?))
                    .transpose()?;
                let thread = entry
                    .cloud_thread_id
                    .as_ref()
                    .and_then(|id| snapshot.manifest.find_conversation(id))
                    .map(|(_, thread)| thread);
                // The comparison priced the stored thread from this same
                // manifest; the row carries that number only when its
                // action installs the bytes.
                let source_size = pull_action_installs_bytes(entry.pull_decision.action)
                    .then_some(entry.pull_bytes)
                    .flatten();
                let stored_ended_at = thread.and_then(|thread| thread.last_message_at());
                Ok(ConversationReviewRow {
                    stored_without_credential_redaction: thread
                        .and_then(|thread| thread.wire_redaction.as_ref())
                        .is_some_and(|stamp| {
                            stamp.codec == credential_redaction::REDACTION_OFF_CODEC_V1
                        }),
                    provider: entry.provider,
                    thread_id: local_thread_id,
                    cloud_thread_id: entry.cloud_thread_id,
                    resource_id: entry.resource_id,
                    action: entry.pull_decision.action,
                    blocker: entry.pull_decision.blocker,
                    blocked_reason: entry.pull_decision.blocked_reason,
                    action_id,
                    display_title: (entry.display_name != entry.thread_id)
                        .then_some(entry.display_name),
                    source_size,
                    stored_ended_at,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        on_phase("compare conversations", phase_started.elapsed());
    }
    let phase_started = Instant::now();
    plan.project_content_eligibility = Some(project_file_sync_eligibility(&binding));
    plan.validate_review()?;
    on_phase("finalize review", phase_started.elapsed());
    Ok(plan)
}

struct RestoreApplyBuild {
    plan: RestorePlan,
    session_views: Vec<provider_capture::LocalSessionView>,
    captured: provider_capture::CapturedResources,
}

/// Build fresh executable pins after the user starts Apply. The comparison
/// object is only an approval anchor and is never executed or persisted.
fn build_restore_plan_for_apply(
    repository: &LocalStateRepository,
    review: &RestorePlan,
    resolved: &ResolvedBinding,
    engine: &StorageEngine,
    snapshot: &BundleSnapshot,
    mainline: &Mainline,
    selected_conversations: &BTreeSet<ResourceId>,
    byte_source: &mut dyn BundleBytes,
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<RestoreApplyBuild, String> {
    let binding = &resolved.binding;
    let state = repository.load_project_state_snapshot()?;
    let config = &state.config;
    let link = project_link(&config, &binding.local_project_id, &review.storage_id)
        .cloned()
        .ok_or_else(|| "project is not linked to this storage".to_string())?;
    let identity = &state.host_identity;
    if identity.host_id != binding.host_id {
        return Err("host identity changed before Pull apply".to_string());
    }

    let phase_started = Instant::now();
    let project_content_bases = project_content_base_content_digests(
        engine,
        &review.bundle_id,
        &link,
        mainline,
        &snapshot.manifest,
    );
    let mut plan = engine.build_restore_plan_from_snapshot(
        provider_registry(),
        snapshot,
        binding,
        &resolved.homes,
        &project_content_bases,
        now_secs(),
        identity.revision,
    )?;
    plan.remote_continuity = review.remote_continuity.clone();
    plan.project_content_eligibility = Some(project_file_sync_eligibility(binding));
    on_phase("build apply plan", phase_started.elapsed());

    if selected_conversations.is_empty() {
        return Ok(RestoreApplyBuild {
            plan,
            session_views: Vec::new(),
            captured: provider_capture::CapturedResources::default(),
        });
    }

    let phase_started = Instant::now();
    let capture_request = capture_request_for_resolved_binding_from_state(
        repository.root(),
        config,
        &state.bindings,
        resolved,
    )?;
    let (discovery, session_views) =
        provider_capture::discover_sessions(provider_registry(), &capture_request)?;
    let local_selection = discovery
        .project_inventory()
        .resources
        .into_iter()
        .filter_map(|candidate| {
            ResourceId::parse(candidate.resource_id.clone())
                .ok()
                .filter(|resource_id| selected_conversations.contains(resource_id))
                .map(|_| candidate.resource_id)
        })
        .collect::<BTreeSet<_>>();
    let captured = provider_capture::capture_from_discovery(
        provider_registry(),
        &capture_request,
        &discovery,
        &local_selection,
        false, // Pull captures local evidence without an outgoing transform.
    )?;
    on_phase("capture selected conversations", phase_started.elapsed());

    let phase_started = Instant::now();
    let review_actions = thread_review(
        repository,
        Some(snapshot),
        mainline,
        byte_source,
        &session_views,
        &captured,
        &BTreeMap::new(),
        resolved,
        Some(&plan.storage_id),
        plan.created_at,
        plan.expires_at,
        ReviewPurpose::PullPlan,
        Some(selected_conversations),
        &AppSettings::default(),
    )?;
    if let Some((provider, message)) = review_actions.provider_errors.into_iter().next() {
        return Err(format!(
            "{} conversation apply failed: {}",
            provider, message
        ));
    }
    plan.conversation_actions = review_actions.pull_actions;
    plan.conversation_review = review_actions.pull_review;
    on_phase("build conversation actions", phase_started.elapsed());
    plan.validate()?;
    Ok(RestoreApplyBuild {
        plan,
        session_views,
        captured,
    })
}

#[derive(Clone)]
struct PreparedPullConversation {
    action: ConversationPlanAction,
    cloud_transcript: VerifiedBody,
    cloud_file_sha256: String,
    cloud_forked_from: Option<CloudThreadId>,
    cloud_preserved: Option<PreservedProvenance>,
    cloud_display_title: Option<String>,
    cloud_wire_redaction: Option<mallard_domain::ConversationWireRedaction>,
    cloud_wire_path_map: Option<mallard_domain::ConversationWirePathMap>,
    cloud_updated_at: u64,
    /// The cloud row's sidecars, fetched and manifest-verified at prepare;
    /// apply plans their targets under the destination identity and
    /// installs them beside the transcript.
    cloud_sidecars: Vec<PreparedPullSidecar>,
    cloud_subagents: BTreeMap<SubagentKey, (VerifiedBody, SubagentContentState)>,
    /// The bound local session's discovery display name, when one exists —
    /// the keep-both marker's base-title input, captured at prepare because
    /// apply runs no discovery of its own.
    local_display_name: Option<String>,
    /// The source selected at capture, never a path derived from cloud data.
    local_source_path: Option<PathBuf>,
}

/// One sidecar of a cloud conversation row: its kind and kind-relative
/// path (the adapter derives the destination name from these) and the
/// verified object body, a temp file until apply reads it.
#[derive(Clone)]
struct PreparedPullSidecar {
    sidecar_kind: String,
    relative_path: String,
    body: VerifiedBody,
}

#[derive(Clone, Debug)]
struct SelectedPullConversation {
    action: ConversationPlanAction,
}

fn captured_local_conversation_for_action<'a>(
    action: &ConversationPlanAction,
    binding: &ProjectBinding,
    document: &mallard_domain::ConversationBindings,
    captured: &'a provider_capture::CapturedResources,
) -> Option<&'a provider_capture::CapturedConversation> {
    // Metadata-only actions neither read nor write the local transcript:
    // their stale-pin guard covers everything except the local file, so
    // review never captures them and apply derives no local digest.
    if action.action == ConversationPlanActionType::AdoptCloudMetadata {
        return None;
    }
    let provider_thread_id = document
        .bindings
        .iter()
        .find(|candidate| {
            candidate.host_id == binding.host_id
                && candidate.replica_id == binding.replica_id
                && candidate.local_project_id == binding.local_project_id
                && candidate.provider_profile_id == action.pins.context.provider_profile_id
                && Some(&candidate.thread_id) == action.thread_id.as_ref()
        })
        .and_then(|candidate| candidate.provider_thread_id.as_deref());
    provider_thread_id.and_then(|provider_thread_id| {
        captured.conversations.values().find(|conversation| {
            conversation.provider == action.provider
                && conversation.source_thread_id.as_deref() == Some(provider_thread_id)
        })
    })
}

struct PreparedPullConversationFailure {
    action: ConversationPlanAction,
    /// What the receipt prints.
    message: String,
    /// The precise reason behind a one-sentence receipt, for the log.
    detail: Option<String>,
}

/// Prepare every approved conversation action. Shared-state loads are
/// fatal, but each action prepares independently: one stale or unreadable
/// thread becomes a per-thread failure receipt instead of blocking the
/// other approved threads.
#[allow(clippy::type_complexity)]
fn prepare_pull_conversation_actions(
    repository: &LocalStateRepository,
    resolved: &ResolvedBinding,
    snapshot: &BundleSnapshot,
    bytes: &mut dyn BundleBytes,
    actions: &[SelectedPullConversation],
    session_views: &[provider_capture::LocalSessionView],
    captured: &provider_capture::CapturedResources,
    storage_id: &StorageId,
    now: u64,
) -> Result<
    (
        Vec<PreparedPullConversation>,
        Vec<PreparedPullConversationFailure>,
        Vec<provider_capture::LocalSessionView>,
    ),
    String,
> {
    if actions.is_empty() {
        return Ok((Vec::new(), Vec::new(), Vec::new()));
    }
    let binding = &resolved.binding;
    let state = repository.load_project_activity_state_snapshot()?;
    let document = &state.conversation_bindings;
    let machine = &state.bindings;
    let identity = &state.host_identity;
    // One batched prefetch covers every approved in-policy transcript and
    // sidecar; the per-action bounded reads below are then verified cache
    // hits. A transfer failure ends this Apply attempt. Oversized files are
    // rejected before transfer.
    let payload_paths = actions
        .iter()
        .filter_map(|selected| {
            selected
                .action
                .cloud_thread_id
                .as_ref()
                .and_then(|cloud_thread_id| snapshot.manifest.find_conversation(cloud_thread_id))
        })
        .flat_map(|(_, thread)| {
            thread
                .files
                .iter()
                .filter(|file| {
                    matches!(
                        file.role,
                        ConversationFileRole::Transcript
                            | ConversationFileRole::Sidecar { .. }
                            | ConversationFileRole::SubagentTranscript { .. }
                    )
                })
                .map(|file| file.logical_path.clone())
        })
        .filter(|path| {
            snapshot
                .manifest
                .find_file(path)
                .is_some_and(|(_, entry)| entry.size <= conversation_file_limit_bytes())
        })
        .collect::<Vec<_>>();
    bytes.prefetch(&payload_paths)?;
    let mut prepared = Vec::with_capacity(actions.len());
    let mut failures = Vec::new();
    let prepare_one = |selected: &SelectedPullConversation,
                       bytes: &mut dyn BundleBytes|
     -> Result<PreparedPullConversation, String> {
        let action = &selected.action;
        // A local counterpart whose capture failed cannot pin a target: the
        // thread fails with the capture's own error.
        if let Some(message) = action
            .source_resource_id
            .as_ref()
            .and_then(|resource_id| captured.failed_conversations.get(resource_id.as_str()))
        {
            return Err(format!("local capture failed: {message}"));
        }
        let cloud_thread_id = action.cloud_thread_id.as_ref().ok_or_else(|| {
            "conversation Pull action lacks its reviewed cloud thread id".to_string()
        })?;
        let (_, thread) = snapshot
            .manifest
            .find_conversation(cloud_thread_id)
            .ok_or_else(|| {
                format!(
                    "reviewed cloud conversation '{}' disappeared",
                    cloud_thread_id
                )
            })?;
        let transcript_ref = thread
            .files
            .iter()
            .find(|file| file.role == ConversationFileRole::Transcript)
            .ok_or_else(|| {
                format!(
                    "cloud conversation '{}' lacks a transcript",
                    cloud_thread_id
                )
            })?;
        let cloud_file_sha256 = snapshot
            .manifest
            .find_file(&transcript_ref.logical_path)
            .ok_or_else(|| {
                format!(
                    "cloud conversation '{}' transcript is absent from the manifest",
                    cloud_thread_id
                )
            })?
            .1
            .sha256
            .clone();
        let cloud_transcript = bytes.body(&transcript_ref.logical_path)?;
        if cloud_transcript.size() > conversation_file_limit_bytes() {
            return Err("cloud conversation transcript exceeds its read limit".to_string());
        }
        // Wire content is verified once in the bounded preparation worker.
        let lineage_digest = Some(thread.lineage_digest.clone());
        let semantic_digest = Some(thread.semantic_digest.clone());
        let local_binding = document.bindings.iter().find(|candidate| {
            candidate.host_id == binding.host_id
                && candidate.replica_id == binding.replica_id
                && candidate.local_project_id == binding.local_project_id
                && candidate.provider_profile_id == action.pins.context.provider_profile_id
                && Some(&candidate.thread_id) == action.thread_id.as_ref()
        });
        let profile = machine
            .profiles
            .iter()
            .find(|profile| profile.profile_id == action.pins.context.provider_profile_id)
            .ok_or_else(|| "reviewed provider profile disappeared".to_string())?;
        let local_view = local_binding
            .and_then(|row| row.provider_thread_id.as_deref())
            .and_then(|provider_thread_id| {
                session_views.iter().find(|view| {
                    view.provider == action.provider
                        && view.provider_thread_id == provider_thread_id
                })
            });
        let local_capture =
            captured_local_conversation_for_action(action, binding, document, captured);
        let local_source_path = local_capture.map(captured_transcript_source).transpose()?;
        let local_target = local_capture
            .and_then(|conversation| captured.files.get(&conversation.transcript_logical_path))
            .map(|file| TargetExpectation::Sha256(file.bytes.sha256().to_string()))
            .unwrap_or(TargetExpectation::Absent);
        let provider_state = action
            .pins
            .target
            .provider_state
            .iter()
            .map(|target| {
                // Transcript pins come from capture. The one live source
                // check runs inside the per-thread apply below.
                let current =
                    if local_source_path.as_deref() == Some(Path::new(&target.target_path)) {
                        local_target.clone()
                    } else {
                        bounded_file_expectation(Path::new(&target.target_path))?
                    };
                Ok(ProviderStateExpectation {
                    target_path: target.target_path.clone(),
                    expectation: current,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        let (scope_revision, scope_sha256) = provider_scope_pin(Some(snapshot), &action.provider);
        let live_checkpoint_generation = state
            .config
            .links
            .iter()
            .find(|link| {
                link.local_project_id == binding.local_project_id && &link.storage_id == storage_id
            })
            .and_then(|link| {
                link.conversation_checkpoints
                    .get(&SyncScopeKey::Provider(action.provider.clone()))
            })
            .and_then(|threads| {
                action
                    .thread_id
                    .as_ref()
                    .and_then(|thread_id| threads.get(thread_id))
            })
            .map(|checkpoint| checkpoint.generation);
        let context = ConversationApplyContext {
            now,
            pins: ConversationActionPins {
                subagent_selection: Default::default(),
                credential_redaction_enabled: thread.wire_redaction.as_ref().is_none_or(|stamp| {
                    stamp.codec != credential_redaction::REDACTION_OFF_CODEC_V1
                }),
                export_settings_changed: false,
                context: ConversationContextPins {
                    host_id: binding.host_id.clone(),
                    replica_id: binding.replica_id.clone(),
                    local_project_id: binding.local_project_id.clone(),
                    provider_profile_id: action.pins.context.provider_profile_id.clone(),
                    host_identity_revision: identity.revision,
                    profile_revision: profile.revision,
                    project_binding_revision: binding.revision,
                    bindings_document_revision: document.revision,
                    binding_revision: local_binding.map(|binding| binding.revision),
                },
                revision: ConversationRevisionPins {
                    bundle_revision: snapshot.head.revision,
                    commit_id: snapshot.head.commit_id.clone(),
                    manifest_sha256: snapshot.head.manifest_sha256.clone(),
                    scope_revision,
                    scope_sha256,
                },
                tail: ConversationTailPins {
                    subagents: action.pins.tail.subagents.clone(),
                    subagents_omitted: action.pins.tail.subagents_omitted,
                    local_only_subagents_kept: action.pins.tail.local_only_subagents_kept,
                    missing_local_subagents: action.pins.tail.missing_local_subagents.clone(),
                    accepted: action.pins.tail.accepted.clone(),
                    accepted_local: action.pins.tail.accepted_local.clone(),
                    local: action.pins.tail.local.clone(),
                    cloud: action.pins.tail.cloud.clone(),
                    checkpoint_generation: live_checkpoint_generation,
                    // Match the executable action to the manifest here. The
                    // preparation worker verifies the bytes against these pins.
                    lineage_digest,
                    semantic_digest,
                    raw_range: action.pins.tail.raw_range.clone(),
                },
                target: ConversationTargetPins {
                    local: local_target,
                    provider_state,
                },
                codec: thread.lineage_codec.clone(),
                expires_at: action.pins.expires_at,
            },
        };
        validate_conversation_action_pins(action, &context).map_err(|pin| {
            // The receipt prints one sentence whatever pin noticed the
            // change; the pin's name follows on its own line, for the log.
            format!(
                "{CONVERSATION_CHANGED}\nconversation Pull action '{}' is stale at {:?}",
                action.action_id, pin
            )
        })?;
        // Sidecars are wire-form at capture and carry no path map: the
        // manifest digest verified on fetch is their whole integrity check,
        // and the row's redaction stamp (verified with the transcript at
        // prepare) covers them.
        let mut cloud_sidecars = Vec::new();
        for (sidecar_kind, relative_path) in conversation_sidecar_refs(&action.provider, thread)? {
            let logical_path = mallard_domain::cloud_conversation_sidecar_path(
                &action.provider,
                cloud_thread_id,
                &sidecar_kind,
                &relative_path,
            )?;
            let body = bytes.body(&logical_path)?;
            if body.size() > conversation_file_limit_bytes() {
                return Err(format!(
                    "cloud conversation sidecar '{}' exceeds its read limit",
                    relative_path
                ));
            }
            cloud_sidecars.push(PreparedPullSidecar {
                sidecar_kind,
                relative_path,
                body,
            });
        }
        let mut cloud_subagents = BTreeMap::new();
        let mut total_bytes = cloud_transcript.size();
        for file in &thread.files {
            if let ConversationFileRole::SubagentTranscript {
                child_key,
                normalized,
            } = &file.role
            {
                let body = bytes.body(&file.logical_path)?;
                total_bytes = total_bytes
                    .checked_add(body.size())
                    .ok_or("cloud tree size overflow")?;
                if body.size() > conversation_file_limit_bytes()
                    || total_bytes > provider_capture::MAX_CAPTURE_BYTES
                {
                    return Err("cloud tree exceeds capture limits".into());
                }
                cloud_subagents.insert(child_key.clone(), (body, normalized.clone()));
            }
        }
        let local_display_name = local_view.map(|view| view.descriptor.display_name.clone());
        Ok(PreparedPullConversation {
            action: action.clone(),
            cloud_transcript,
            cloud_file_sha256,
            cloud_forked_from: thread.forked_from.clone(),
            cloud_preserved: thread.preserved.clone(),
            cloud_display_title: thread.display_title.clone(),
            cloud_wire_redaction: thread.wire_redaction.clone(),
            cloud_wire_path_map: thread.wire_path_map.clone(),
            cloud_updated_at: thread.updated_at,
            cloud_sidecars,
            cloud_subagents,
            local_display_name,
            local_source_path,
        })
    };
    for selected in actions {
        match prepare_one(selected, bytes) {
            Ok(conversation) => prepared.push(conversation),
            Err(message) => {
                let (message, detail) = match message.split_once('\n') {
                    Some((sentence, precise)) if sentence == CONVERSATION_CHANGED => {
                        (sentence.to_string(), Some(precise.to_string()))
                    }
                    _ => (message, None),
                };
                failures.push(PreparedPullConversationFailure {
                    action: selected.action.clone(),
                    message,
                    detail,
                })
            }
        }
    }
    Ok((prepared, failures, session_views.to_vec()))
}

/// A per-thread conversation failure keeps its receipt so successful sibling
/// actions stay applied and the result reports every failed action.
fn failed_conversation_receipt(
    action: &ConversationPlanAction,
    message: String,
    applied_at: u64,
) -> Result<ApplyReceipt, String> {
    // Cloud-only failures that predate minting carry the cloud resource
    // id review always records as `source_resource_id` for cloud rows.
    let resource_id = conversation_action_row_key(action).ok_or_else(|| {
        format!(
            "conversation action '{}' names no reportable resource",
            action.action_id
        )
    })?;
    Ok(failed_conversation_receipt_for(
        &action.action_id,
        resource_id,
        message,
        applied_at,
    ))
}

/// The failure receipt for a reviewed selection that never became an
/// apply-time action, keyed by the review's own ids.
fn failed_conversation_receipt_for(
    action_id: &ActionId,
    resource_id: ResourceId,
    message: String,
    applied_at: u64,
) -> ApplyReceipt {
    ApplyReceipt {
        action_id: action_id.clone(),
        resource_id,
        action_type: RestoreActionType::MaterializeConversation,
        logical_path: None,
        source_sha256: None,
        target_path: None,
        target_sha256_after: None,
        status: ActionStatus::Failed,
        applied_at,
        error: Some(message),
        conversation: None,
    }
}

struct NativeCodexRename {
    home: PathBuf,
    row: CodexIndexRowSpec,
}

// Presentation only: all file writes and acceptance changes finish first.
// Codex appends to the index, which would stale later actions in the batch.
fn rename_committed_codex_titles(
    repository: &LocalStateRepository,
    requests: Vec<NativeCodexRename>,
) {
    for request in requests {
        #[cfg(not(test))]
        let outcome = mallard_infrastructure::providers::codex::naming::rename(
            &request.home,
            &request.row.provider_thread_id,
            &request.row.thread_name,
        );
        #[cfg(test)]
        let outcome = pull_test_support::rename(
            &request.home,
            &request.row.provider_thread_id,
            &request.row.thread_name,
        );
        if outcome.is_err() {
            use mallard_infrastructure::activity_log::{
                ActivityLogContext, ActivityLogEntry, ActivityLogStore, ActivityLogType,
            };
            if let Ok(log) = ActivityLogStore::from_repository(repository) {
                let _ = log.append(&ActivityLogEntry::new(
                    ActivityLogType::Pull,
                    "warn",
                    "pull.codex_title_update_failed",
                    "Codex title update failed. The completed conversation import is unchanged.",
                    None,
                    ActivityLogContext::default(),
                ));
            }
        }
    }
}

/// One reviewed Codex session-index row rewrite. `replace_existing` marks an
/// identity that already owns index rows (MaterializeCloud's destination,
/// keep-both's preserved rename): its existing rows are dropped and one current
/// row is appended. Fresh identities reject collisions instead.
struct CodexIndexRowSpec {
    provider_thread_id: String,
    thread_name: String,
    updated_at: u64,
    replace_existing: bool,
}

/// Decode a portable Codex title through the same path codec as its
/// transcript before the title enters machine-local provider state. The
/// round-trip gate also rejects a cloud title that already contains the
/// destination root: accepting that collision would capture unrelated text
/// into the reserved wire namespace on the next Push.
/// Read the local Codex session index and build its reviewed replacement,
/// rewriting one row per spec. Returns no payload for an empty spec list: a
/// titleless task leaves provider presentation metadata untouched.
fn codex_index_payload(
    path: &Path,
    rows: &[CodexIndexRowSpec],
) -> Result<(TargetExpectation, Option<Vec<u8>>), String> {
    let expectation = bounded_file_expectation(path)?;
    if rows.is_empty() {
        return Ok((expectation, None));
    }
    let bytes = match &expectation {
        TargetExpectation::Absent => Vec::new(),
        TargetExpectation::Sha256(_) => fs::read(path)
            .map_err(|error| format!("read Codex session index '{}': {error}", path.display()))?,
    };
    let mut output = Vec::with_capacity(bytes.len().saturating_add(256 * rows.len()));
    for raw in bytes.split_inclusive(|byte| *byte == b'\n') {
        let line = raw.strip_suffix(b"\n").unwrap_or(raw);
        let line = line.strip_suffix(b"\r").unwrap_or(line);
        if line.is_empty() {
            output.extend_from_slice(raw);
            continue;
        }
        let value: serde_json::Value = serde_json::from_slice(line)
            .map_err(|_| "Codex session index contains malformed JSON".to_string())?;
        let id = value
            .get("id")
            .or_else(|| value.get("session_id"))
            .and_then(serde_json::Value::as_str);
        if let Some(spec) = rows
            .iter()
            .find(|spec| id == Some(spec.provider_thread_id.as_str()))
        {
            if !spec.replace_existing {
                return Err("reserved Codex provider ID is already indexed".to_string());
            }
            continue;
        }
        output.extend_from_slice(raw);
    }
    if !output.is_empty() && !output.ends_with(b"\n") {
        output.push(b'\n');
    }
    for spec in rows {
        let updated_at = Utc
            .timestamp_opt(spec.updated_at as i64, 0)
            .single()
            .ok_or_else(|| "cloud conversation timestamp is out of range".to_string())?
            .format("%Y-%m-%dT%H:%M:%S%.6fZ")
            .to_string();
        let mut row = serde_json::to_vec(&serde_json::json!({
            "id": spec.provider_thread_id,
            "thread_name": spec.thread_name,
            "updated_at": updated_at,
        }))
        .map_err(|error| format!("serialize Codex session index row: {error}"))?;
        row.push(b'\n');
        output.extend(row);
    }
    Ok((expectation, Some(output)))
}

/// Check the captured source once. A change fails this action; an external
/// write after this read is allowed to go undetected. Never retry the read.
fn read_pull_conversation_source(
    path: &Path,
    expected: &TargetExpectation,
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<Vec<u8>, String> {
    let started = Instant::now();
    let result = jsonl_tail_io::read_bounded(path).and_then(|bytes| {
        mallard_infrastructure::sync_metrics::record_bytes_hashed(path, bytes.len() as u64);
        let actual = TargetExpectation::Sha256(hex_digest(Sha256::digest(&bytes).as_slice()));
        if &actual != expected {
            return Err("conversation source bytes changed after review".to_string());
        }
        Ok(bytes)
    });
    on_phase("check local conversation", started.elapsed());
    result
}

// The receipt dwarfs the checkpoint by design; boxing it would ripple
// through every caller for no behavioral gain.
/// Apply one prepared materializing Pull action. Reconstruct the verified
/// cloud graph once and check the captured local source once before
/// installation. Metadata-only actions never reach this function.
#[allow(clippy::too_many_arguments)]
fn apply_prepared_pull_conversation(
    state: &mut LockedConversationPull<'_>,
    plan: &RestorePlan,
    resolved: &ResolvedBinding,
    snapshot: &BundleSnapshot,
    prepared: PreparedPullConversation,
    transcript: PreparedPullTranscript,
    children: Vec<owned_subagents::InstalledChildPayload>,
    destination_provider_thread_id: String,
    expected_bindings_document_revision: u64,
    applied_at: u64,
    native_renames: &mut Vec<NativeCodexRename>,
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<ApplyReceipt, String> {
    let binding = &resolved.binding;
    let cloud_provider_thread_id = transcript.cloud_provider_thread_id.clone();
    let action = prepared.action;
    let current = state.current()?;
    let document_before = &current.conversation_bindings;
    let config_before = &current.config;
    if document_before.revision != expected_bindings_document_revision {
        return Err("conversation bindings changed during Pull apply".to_string());
    }
    let live_binding = document_before.bindings.iter().find(|candidate| {
        candidate.host_id == binding.host_id
            && candidate.replica_id == binding.replica_id
            && candidate.local_project_id == binding.local_project_id
            && candidate.provider_profile_id == action.pins.context.provider_profile_id
            && Some(&candidate.thread_id) == action.thread_id.as_ref()
    });
    if live_binding.map(|binding| binding.revision) != action.pins.context.binding_revision {
        return Err("conversation binding changed after review".to_string());
    }
    let cloud_thread_id = action
        .cloud_thread_id
        .clone()
        .ok_or_else(|| "conversation Pull action lacks its reviewed cloud thread id".to_string())?;
    // A mapped local thread must still map to the reviewed cloud row; a
    // mismatch in either direction is a hard failure, never an adoption.
    if let Some(live_binding) = live_binding {
        if action.action != ConversationPlanActionType::CreateLocal
            && live_binding.cloud_thread_id.as_ref() != Some(&cloud_thread_id)
        {
            return Err(
                "conversation cloud mapping changed after review; refresh and pull again"
                    .to_string(),
            );
        }
    }
    if !action.pins.tail.missing_local_subagents.is_empty() {
        action.pins.tail.validate_missing_child_recovery()?;
        let row = live_binding.ok_or("missing-child recovery lost its binding")?;
        let parent = row
            .provider_thread_id
            .as_deref()
            .ok_or("recovery parent identity is missing")?;
        let main = prepared
            .local_source_path
            .as_ref()
            .ok_or("recovery parent path is missing")?;
        let home = Path::new(resolved.home(&action.provider)?);
        let mut source_ids = BTreeMap::new();
        if action
            .pins
            .tail
            .missing_local_subagents
            .iter()
            .any(|key| !row.installed_subagents.contains_key(key))
        {
            let bytes = jsonl_tail_io::read_bounded(main)?;
            if action.provider.as_str() == "claude" {
                let mut links = claude_subagents::ChildLinks::new();
                claude_subagents::analyze_main(&bytes, parent, &mut links)?;
                source_ids.extend(links.into_iter().map(|(id, key)| (key, id)));
            } else {
                source_ids.extend(
                    codex_subagents::creation_references(&bytes, row.installed_end)?
                        .into_iter()
                        .map(|(id, key)| Ok((SubagentKey::parse(key)?, id)))
                        .collect::<Result<BTreeMap<_, _>, String>>()?,
                );
            }
        }
        for key in &action.pins.tail.missing_local_subagents {
            let id = row
                .installed_subagents
                .get(key)
                .map(|child| &child.provider_thread_id)
                .or_else(|| source_ids.get(key))
                .ok_or("missing child identity cannot be verified")?;
            let present = if action.provider.as_str() == "claude" {
                let path = claude_subagents::child_path(main, parent, id)?;
                claude_subagents::child_exists(
                    &path,
                    main.parent().ok_or("parent directory is missing")?,
                )?
            } else {
                RolloutLookup::new(home).find_current(id)?.is_some()
            };
            if present {
                return Err("Missing child returned after review. Review Pull again.".into());
            }
        }
    }
    let live_provider_thread_id =
        live_binding.and_then(|binding| binding.provider_thread_id.as_deref());
    if action.action == ConversationPlanActionType::MaterializeCloud
        && live_provider_thread_id.is_none()
    {
        return Err(
            "conversation cloud update lost its provider identity after review".to_string(),
        );
    }
    let adapter = provider_registry().require(&action.provider)?;
    let reconstructs_graph = adapter.reconstructs_rollout_graph();
    let cloud_tail = action
        .pins
        .tail
        .cloud
        .clone()
        .ok_or_else(|| "conversation Pull action lacks its pinned cloud tail".to_string())?;
    // Resolve the destination provider identity here, at apply (D2). Codex
    // can create a physical history_base child at any time, so every Codex
    // cloud update is copy-on-write under a freshly minted alias; other
    // providers replace in place under the row's existing provider id.
    // CreateLocal and KeepBoth's remote branch always mint.
    let materialize_in_place =
        action.action == ConversationPlanActionType::MaterializeCloud && !reconstructs_graph;
    let materialize_relocated =
        action.action == ConversationPlanActionType::MaterializeCloud && reconstructs_graph;
    if materialize_in_place
        && live_provider_thread_id != Some(destination_provider_thread_id.as_str())
    {
        return Err("conversation destination identity changed during preparation".to_string());
    }
    // Resolve the local thread identity: CreateLocal derives it from the
    // freshly minted provider id (one uniform rule — the first identity is
    // the derivation of the first provider alias); every other action
    // operates on the reviewed local thread.
    let local_thread_id = match &action.thread_id {
        Some(thread_id) => thread_id.clone(),
        None => {
            if action.action != ConversationPlanActionType::CreateLocal {
                return Err("conversation Pull action lacks its local thread id".to_string());
            }
            initial_conversation_thread_id(
                &binding.bundle_id,
                &action.provider,
                &destination_provider_thread_id,
            )?
        }
    };
    let relocation_source_provider_thread_id = action.source_resource_id.as_ref().and_then(|id| {
        let (source_provider, _) = id.as_str().split_once(':')?;
        (source_provider == action.provider.as_str())
            .then(|| provider_session_id_from_resource(id.as_str()))
            .flatten()
    });
    if materialize_relocated && relocation_source_provider_thread_id != live_provider_thread_id {
        return Err("conversation relocation source identity changed after review".to_string());
    }
    // KeepBoth identities and display facts are minted here (D2/D9): the
    // preserved ThreadId, the provenance ordinal over the pinned snapshot's
    // provider scope plus the live bindings document, and the marker title.
    let keep_both_minted = if action.action == ConversationPlanActionType::KeepBoth {
        let scoped_bindings = document_before
            .bindings
            .iter()
            .filter(|row| {
                row.host_id == binding.host_id
                    && row.replica_id == binding.replica_id
                    && row.local_project_id == binding.local_project_id
                    && row.provider_profile_id == action.pins.context.provider_profile_id
            })
            .collect::<Vec<_>>();
        // Max+1 over every provenance record naming this origin — cloud
        // space against cloud space on both inputs. Concurrent keep-boths of
        // the same origin on other devices can still mint a duplicate
        // ordinal, which is accepted: the device label disambiguates.
        let next_ordinal = snapshot
            .manifest
            .provider_scope(&action.provider)
            .into_iter()
            .flat_map(|scope| scope.conversations.values())
            .filter_map(|thread| thread.preserved.as_ref())
            .chain(
                scoped_bindings
                    .iter()
                    .filter_map(|row| row.preserved.as_ref()),
            )
            .filter(|preserved| preserved.preserved_from == cloud_thread_id)
            .map(|preserved| preserved.ordinal)
            .max()
            .unwrap_or(0)
            .saturating_add(1);
        let identity = &current.host_identity;
        let device_label = match identity
            .local_display_name
            .as_deref()
            .map(str::trim)
            .filter(|label| !label.is_empty())
        {
            Some(label) => label.to_string(),
            None => {
                let (origin_host_token, _) =
                    state.derive_origin_tokens(&binding.bundle_id, &binding.replica_id)?;
                fallback_origin_host_label(&origin_host_token)
            }
        };
        let base_title = prepared
            .local_display_name
            .clone()
            .filter(|name| {
                !name.trim().is_empty() && Some(name.as_str()) != live_provider_thread_id
            })
            .or_else(|| {
                prepared.cloud_display_title.clone().filter(|title| {
                    !title.trim().is_empty() && title.as_str() != cloud_provider_thread_id.as_str()
                })
            });
        Some(KeepBothApply {
            preserved_thread_id: ThreadId::parse(generated_named_id("thread")?)?,
            remote_provider_thread_id: destination_provider_thread_id.clone(),
            preserved: PreservedProvenance {
                preserved_from: cloud_thread_id.clone(),
                ordinal: next_ordinal,
            },
            preserved_display_title: compose_preserved_title(
                base_title.as_deref(),
                next_ordinal,
                &device_label,
            ),
        })
    } else {
        None
    };

    let PreparedPullTranscript {
        child_references,
        transcript: verified_transcript,
        path_origins,
        layout: imported_layout,
        checkpoint,
        ..
    } = transcript;
    let path_origins_ref = state.store_path_origins(
        PathOriginsOwner::for_project(
            binding,
            &action.pins.context.provider_profile_id,
            &destination_provider_thread_id,
        ),
        &path_origins,
    )?;
    let installed_bytes = verified_transcript.bytes().clone();
    let PullTranscriptCheckpoint {
        prefix_witness,
        artifact_sha256,
        accepted_local_tail,
        lineage_digest: staged_lineage_digest,
        semantic_digest: staged_semantic_digest,
        last_canonical_message_id,
        last_synthetic_turn_id,
        next_synthetic_turn_ordinal,
    } = checkpoint;
    let phase_started = Instant::now();

    // Role assignment for the reviewed targets comes from the adapter's
    // declared index path. Non-Codex MaterializeCloud updates replace their
    // reviewed target; every Codex MaterializeCloud, CreateLocal, and
    // KeepBoth consumes a reviewed absent target.
    let index_path = (adapter.index_fragment_limit() > 0)
        .then(|| {
            resolved
                .home(&action.provider)
                .map(|home| Path::new(home).join("session_index.jsonl"))
        })
        .transpose()?;
    let is_index_target = |target: &ProviderStateExpectation| {
        index_path
            .as_ref()
            .is_some_and(|path| Path::new(&target.target_path) == path.as_path())
    };
    let replace_existing = materialize_in_place;
    // Every provider file of this materialization — the transcript and each
    // sidecar the cloud row carries — is planned through the adapter under
    // the destination identity. An in-place update keeps its reviewed
    // transcript pin as the existing path and takes every target's
    // expectation from the reviewed pins; a minted identity's destinations
    // must all be Absent — an occupied path fails this action only (the
    // engine's no-clobber commit is the last-line guard).
    let reviewed_transcript_target = materialize_in_place
        .then(|| {
            action
                .pins
                .target
                .provider_state
                .iter()
                .find(|target| !is_index_target(target))
                .cloned()
                .ok_or_else(|| "conversation Pull action lacks a transcript target".to_string())
        })
        .transpose()?;
    let sidecar_refs = prepared
        .cloud_sidecars
        .iter()
        .map(|sidecar| (sidecar.sidecar_kind.clone(), sidecar.relative_path.clone()))
        .collect::<Vec<_>>();
    let provider_home = resolved.home(&action.provider)?;
    let planned = adapter.materialization_targets(
        &mallard_infrastructure::providers::MaterializationTargetRequest {
            provider_home: Path::new(provider_home),
            project_root: &binding.project_root,
            provider_session_id: &destination_provider_thread_id,
            source_provider_session_id: Some(cloud_provider_thread_id.as_str()),
            existing_transcript_path: reviewed_transcript_target
                .as_ref()
                .map(|target| Path::new(&target.target_path)),
            sidecars: &sidecar_refs,
            planned_at: applied_at,
        },
    )?;
    if action.provider.as_str() == "claude" && !materialize_in_place {
        let main = planned
            .iter()
            .find(|target| target.role == ConversationFileRole::Transcript)
            .ok_or("Claude parent target is missing")?;
        let namespace = main
            .target_path
            .parent()
            .ok_or("Claude parent directory is missing")?
            .join(&destination_provider_thread_id);
        match fs::symlink_metadata(&namespace) {
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(format!("read child namespace: {error}")),
            Ok(_) => return Err("destination parent child namespace is occupied".into()),
        }
    }
    let expectation_for = |target: &mallard_infrastructure::providers::PlannedProviderTarget|
     -> Result<TargetExpectation, String> {
        if materialize_in_place {
            let target_path = target.target_path.to_string_lossy();
            action
                .pins
                .target
                .provider_state
                .iter()
                .find(|pin| pin.target_path == target_path.as_ref())
                .map(|pin| pin.expectation.clone())
                .ok_or_else(|| {
                    format!(
                        "conversation target '{}' was not reviewed",
                        target.target_path.display()
                    )
                })
        } else if bounded_file_expectation(&target.target_path)? != TargetExpectation::Absent {
            Err(format!(
                "conversation destination '{}' is already occupied",
                target.target_path.display()
            ))
        } else {
            Ok(TargetExpectation::Absent)
        }
    };
    // Payload order is commit order: sidecars first, the transcript last,
    // so a failure mid-commit leaves inert extra attachments rather than a
    // resumable transcript without them.
    let mut targets = Vec::with_capacity(planned.len() + children.len() + 1);
    let mut installed_subagents = BTreeMap::new();
    let mut accepted_subagents = BTreeMap::new();
    for child in &children {
        let target_path = adapter.child_transcript_target(
            &mallard_infrastructure::providers::MaterializationTargetRequest {
                provider_home: Path::new(provider_home),
                project_root: &binding.project_root,
                provider_session_id: &destination_provider_thread_id,
                source_provider_session_id: None,
                existing_transcript_path: reviewed_transcript_target
                    .as_ref()
                    .map(|target| Path::new(&target.target_path)),
                sidecars: &[],
                planned_at: applied_at,
            },
            child.provider_thread_id(),
        )?;
        let known_child = materialize_in_place
            .then(|| live_binding)
            .flatten()
            .and_then(|row| row.installed_subagents.get(child.key()));
        if known_child.is_some_and(|known| known.provider_thread_id != child.provider_thread_id()) {
            return Err("installed child identity changed".into());
        }
        // An update in place replaces a child under the state it was
        // reviewed in: one that a Pull installed, or one that the provider
        // wrote here and the local transcript refers to. Any other target
        // must be free.
        let reviewed = materialize_in_place
            .then(|| {
                action
                    .pins
                    .target
                    .provider_state
                    .iter()
                    .find(|pin| Path::new(&pin.target_path) == target_path)
            })
            .flatten();
        let expected = match reviewed {
            Some(pin) => pin.expectation.clone(),
            None if known_child.is_some() => {
                return Err("existing child target was not reviewed".into())
            }
            None => {
                if bounded_file_expectation(&target_path)? != TargetExpectation::Absent {
                    return Err("child destination is occupied".into());
                }
                TargetExpectation::Absent
            }
        };
        installed_subagents.insert(
            child.key().clone(),
            mallard_domain::InstalledSubagent {
                provider_thread_id: child.provider_thread_id().to_string(),
                installed_end: child.bytes().len() as u64,
            },
        );
        targets.push(ConversationTargetPayload {
            target_path: target_path,
            role: ConversationFileRole::SubagentTranscript {
                child_key: child.key().clone(),
                normalized: child.accepted().normalized.clone(),
            },
            expected,
            index_rows: vec![],
            bytes: child.bytes().clone(),
        });
        accepted_subagents.insert(child.key().clone(), child.accepted().clone());
    }
    let mut installed_absent_subagents = child_references.absent(&installed_subagents);
    // An update in place finds the children that the provider wrote on
    // this computer: no Pull brought them, as a transcript or as a
    // reference without one, and their transcripts are here. The stored
    // session may hold none of them. They stay children all the same.
    if let (Some(main), Some(row)) = (&reviewed_transcript_target, live_binding) {
        let main = Path::new(&main.target_path);
        let directory = main.parent().ok_or("parent directory is missing")?;
        let mut absent = BTreeSet::new();
        for agent in installed_absent_subagents {
            let came_with_a_pull = row.installed_absent_subagents.contains(&agent)
                || row
                    .installed_subagents
                    .values()
                    .any(|child| child.provider_thread_id == agent);
            let child =
                claude_subagents::child_path(main, &destination_provider_thread_id, &agent)?;
            if came_with_a_pull || !claude_subagents::child_exists(&child, directory)? {
                absent.insert(agent);
            }
        }
        installed_absent_subagents = absent;
    }
    let mut transcript_target = None;
    let mut sidecar_bodies = prepared.cloud_sidecars.iter();
    for target in &planned {
        let expected = expectation_for(target)?;
        match &target.role {
            ConversationFileRole::Transcript => {
                if transcript_target.is_some() {
                    return Err("provider planned more than one transcript destination".to_string());
                }
                transcript_target = Some(ProviderStateExpectation {
                    target_path: target.target_path.to_string_lossy().into_owned(),
                    expectation: expected,
                });
            }
            ConversationFileRole::Sidecar { .. } => {
                let sidecar = sidecar_bodies.next().ok_or_else(|| {
                    "provider planned more sidecars than the cloud row carries".to_string()
                })?;
                let bytes = sidecar.body.read_bounded(
                    conversation_file_limit_bytes(),
                    "cloud conversation sidecar",
                )?;
                targets.push(ConversationTargetPayload {
                    target_path: target.target_path.clone(),
                    role: target.role.clone(),
                    expected,
                    index_rows: vec![],
                    bytes: bytes.into(),
                });
            }
            ConversationFileRole::ProviderIndexFragment
            | ConversationFileRole::SubagentTranscript { .. } => {
                return Err("provider planned an unsupported session file".to_string());
            }
        }
    }
    if sidecar_bodies.next().is_some() {
        return Err("provider planned fewer sidecars than the cloud row carries".to_string());
    }
    let transcript_target = transcript_target
        .ok_or_else(|| "provider planned no transcript destination".to_string())?;
    targets.push(ConversationTargetPayload {
        target_path: PathBuf::from(&transcript_target.target_path),
        role: ConversationFileRole::Transcript,
        expected: transcript_target.expectation.clone(),
        index_rows: vec![],
        bytes: installed_bytes.clone(),
    });
    let mut committed_renames = Vec::new();
    if let Some(index_target) = action
        .pins
        .target
        .provider_state
        .iter()
        .find(|target| is_index_target(target))
    {
        let index_path = PathBuf::from(&index_target.target_path);
        let mut index_specs = Vec::new();
        if let Some(keep_both) = &keep_both_minted {
            // The preserved copy keeps the original provider session id; its
            // rename carries the marker title minted above. The id comes
            // from the revision-pinned bindings document, so a moved binding
            // forces a stale replan instead of renaming the wrong session.
            let preserved_provider_thread_id = document_before
                .bindings
                .iter()
                .find(|row| {
                    row.host_id == binding.host_id
                        && row.replica_id == binding.replica_id
                        && row.local_project_id == binding.local_project_id
                        && row.provider_profile_id == action.pins.context.provider_profile_id
                        && row.thread_id == local_thread_id
                })
                .and_then(|row| row.provider_thread_id.clone())
                .ok_or_else(|| {
                    "conversation keep-both requires a bound provider session".to_string()
                })?;
            index_specs.push(CodexIndexRowSpec {
                provider_thread_id: preserved_provider_thread_id,
                thread_name: keep_both.preserved_display_title.clone(),
                updated_at: applied_at,
                replace_existing: true,
            });
        }
        // A real title is one a user could have set: unnamed captures
        // publish the provider thread ID as their display title.
        let cloud_title = prepared
            .cloud_display_title
            .as_deref()
            .map(str::trim)
            .filter(|title| !title.is_empty() && *title != cloud_provider_thread_id.as_str());
        let cloud_title = cloud_title
            .map(|title| {
                adapter.decode_portable_display_title(
                    title,
                    &binding.project_root,
                    &binding.canonical_project_root,
                )
            })
            .transpose()?;
        if let Some(cloud_title) = cloud_title {
            index_specs.push(CodexIndexRowSpec {
                provider_thread_id: destination_provider_thread_id.clone(),
                thread_name: cloud_title,
                updated_at: prepared.cloud_updated_at,
                replace_existing,
            });
        }
        let index_rows = index_specs
            .iter()
            .map(|spec| spec.provider_thread_id.clone())
            .collect::<Vec<_>>();
        let (expected, bytes) = codex_index_payload(&index_path, &index_specs)?;
        let home = PathBuf::from(resolved.home(&action.provider)?);
        committed_renames.extend(index_specs.into_iter().map(|row| NativeCodexRename {
            home: home.clone(),
            row,
        }));
        if let Some(bytes) = bytes {
            targets.push(ConversationTargetPayload {
                target_path: index_path,
                role: ConversationFileRole::ProviderIndexFragment,
                expected,
                index_rows,
                bytes: bytes.into(),
            });
        }
    }

    // The exact whole-document after-states this operation commits.
    let mut document_after = document_before.clone();
    let mut config_after = config_before.clone();
    let scope = SyncScopeKey::Provider(action.provider.clone());
    let checked_source = if matches!(
        action.action,
        ConversationPlanActionType::MaterializeCloud | ConversationPlanActionType::KeepBoth
    ) {
        let source_path = prepared
            .local_source_path
            .as_deref()
            .ok_or_else(|| "conversation Pull lacks its captured local source".to_string())?;
        if materialize_in_place && source_path != Path::new(&transcript_target.target_path) {
            return Err(
                "conversation replacement target differs from its captured source".to_string(),
            );
        }
        Some(read_pull_conversation_source(
            source_path,
            &action.pins.target.local,
            on_phase,
        )?)
    } else {
        None
    };
    let retained_source_checkpoint = if materialize_relocated {
        let old_provider_thread_id = live_provider_thread_id
            .ok_or_else(|| "conversation relocation lost its source provider id".to_string())?;
        let retained_thread_id = retained_conversation_thread_id(
            &binding.bundle_id,
            &action.provider,
            &local_thread_id,
            old_provider_thread_id,
        )?;
        if document_before.bindings.iter().any(|row| {
            row.host_id == binding.host_id
                && row.replica_id == binding.replica_id
                && row.local_project_id == binding.local_project_id
                && row.provider_profile_id == action.pins.context.provider_profile_id
                && row.thread_id == retained_thread_id
        }) {
            return Err(
                "conversation retained-source identity collides with an existing binding"
                    .to_string(),
            );
        }
        let mut checkpoint = config_before
            .links
            .iter()
            .find(|link| {
                link.local_project_id == binding.local_project_id
                    && link.storage_id == plan.storage_id
            })
            .and_then(|link| link.conversation_checkpoints.get(&scope))
            .and_then(|threads| threads.get(&local_thread_id))
            .cloned()
            .ok_or_else(|| {
                "conversation relocation lacks its reviewed source checkpoint".to_string()
            })?;
        let PhysicalMappingState::Ready {
            root_mapping,
            raw_range_pin,
            ..
        } = &mut checkpoint.physical
        else {
            return Err("conversation relocation source checkpoint is detached".to_string());
        };
        if root_mapping.provider_thread_id != old_provider_thread_id {
            return Err(
                "conversation relocation source checkpoint names another provider id".to_string(),
            );
        }
        if prepared.local_source_path.as_deref() != Some(Path::new(&root_mapping.root_path)) {
            return Err("conversation source checkpoint names another path".to_string());
        }
        let source_bytes = checked_source
            .as_deref()
            .expect("relocated transcript passed the source check");
        if root_mapping.source_file_size != source_bytes.len() as u64
            || root_mapping.consumed_byte_offset > source_bytes.len() as u64
        {
            return Err(
                "conversation relocation source checkpoint disagrees with its file".to_string(),
            );
        }
        raw_range_pin.start_byte_offset = 0;
        raw_range_pin.end_byte_offset = root_mapping.consumed_byte_offset;
        raw_range_pin.range_sha256 = hex_digest(
            Sha256::digest(&source_bytes[..root_mapping.consumed_byte_offset as usize]).as_slice(),
        );
        checkpoint.accepted = None;
        checkpoint.accepted_local_tail = None;
        checkpoint.accepted_subagents.clear();
        checkpoint.generation = checkpoint.generation.saturating_add(1);
        checkpoint.binding_revision = 0;
        Some((retained_thread_id, checkpoint))
    } else {
        None
    };
    // Only an in-place replacement needs these bytes for its backup. A
    // relocated source has already supplied its checkpoint; KeepBoth leaves
    // its source in place. Drop both of those buffers here.
    let checked_transcript = checked_source.filter(|_| materialize_in_place);
    let installed_mapping = |bytes: &[u8]| -> mallard_domain::RootPhysicalMapping {
        let consumed = bytes.len() as u64;
        let window = consumed.min(4_096);
        mallard_domain::RootPhysicalMapping {
            provider_thread_id: destination_provider_thread_id.clone(),
            root_path: transcript_target.target_path.clone(),
            source_file_size: consumed,
            consumed_byte_offset: consumed,
            consumed_record_ordinal: bytes.iter().filter(|byte| **byte == b'\n').count() as u64,
            probe_window_len: window,
            probe_window_sha256: hex_digest(
                Sha256::digest(&bytes[(consumed - window) as usize..]).as_slice(),
            ),
            last_canonical_message_id: last_canonical_message_id.clone(),
            last_synthetic_turn_id: last_synthetic_turn_id.clone(),
            next_synthetic_turn_ordinal,
        }
    };
    let accepted_checkpoint = ConversationCheckpoint {
        accepted_subagents,
        generation: 0,
        accepted: Some(mallard_domain::AcceptedConversationVersion {
            artifact_sha256: artifact_sha256.clone(),
            accepted_at_commit_id: action.pins.revision.commit_id.clone(),
            accepted_at_manifest_sha256: action.pins.revision.manifest_sha256.clone(),
            portable_tail: cloud_tail.clone(),
        }),
        accepted_local_tail: Some(accepted_local_tail.clone()),
        observed_tail: accepted_local_tail.clone(),
        physical: PhysicalMappingState::Ready {
            root_mapping: installed_mapping(&installed_bytes),
            raw_range_pin: RawRangePin {
                start_byte_offset: installed_bytes.len() as u64,
                end_byte_offset: installed_bytes.len() as u64,
                range_sha256: hex_digest(Sha256::digest([]).as_slice()),
            },
            // The file is installed after this after-state is fixed, so
            // there is no file state to save: the next comparison reads
            // the installed transcript in full.
            source_state: None,
        },
        prefix_witness,
        binding_revision: 0,
    };
    {
        let find_row = |document: &mut mallard_domain::ConversationBindings,
                        thread_id: &ThreadId|
         -> Option<usize> {
            document.bindings.iter().position(|row| {
                row.host_id == binding.host_id
                    && row.replica_id == binding.replica_id
                    && row.local_project_id == binding.local_project_id
                    && row.provider_profile_id == action.pins.context.provider_profile_id
                    && &row.thread_id == thread_id
            })
        };
        match (&action.action, &keep_both_minted) {
            (ConversationPlanActionType::KeepBoth, Some(keep_both)) => {
                // The binding move: the existing alias and its unchanged
                // layout transfer to the preserved thread, whose cloud
                // mapping clears — an ordinary local-only thread whose later
                // push mints a fresh cloud id. The tracked thread keeps its
                // local id and mapping and imports the verified remote
                // layout under fresh identities. No rollout byte changes.
                let index = find_row(&mut document_after, &local_thread_id).ok_or_else(|| {
                    "conversation keep-both requires an existing binding".to_string()
                })?;
                let row = &mut document_after.bindings[index];
                row.thread_id = keep_both.preserved_thread_id.clone();
                row.cloud_thread_id = None;
                row.forked_from = None;
                row.preserved = Some(keep_both.preserved.clone());
                row.revision = row.revision.saturating_add(1);
                row.updated_at = applied_at;
                // The re-created origin row restores the published cloud
                // provenance: an origin that is itself a preserved copy
                // keeps its marker on every device.
                document_after.bindings.push(LocalConversationBinding {
                    installed_end: Some(installed_bytes.len() as u64),
                    installed_absent_subagents: installed_absent_subagents.clone(),
                    pulled_children_excluded: false,
                    installed_subagents: installed_subagents.clone(),
                    path_origins_ref: Some(path_origins_ref.clone()),
                    host_id: binding.host_id.clone(),
                    replica_id: binding.replica_id.clone(),
                    local_project_id: binding.local_project_id.clone(),
                    provider_profile_id: action.pins.context.provider_profile_id.clone(),
                    thread_id: local_thread_id.clone(),
                    cloud_thread_id: Some(cloud_thread_id.clone()),
                    forked_from: None,
                    preserved: prepared.cloud_preserved.clone(),
                    root_tail_layout: Some(imported_layout.clone()),
                    provider_thread_id: Some(destination_provider_thread_id.clone()),
                    materialization_state: ConversationMaterializationState::Resumable,
                    revision: 0,
                    created_at: applied_at,
                    updated_at: applied_at,
                });
            }
            (ConversationPlanActionType::MaterializeCloud, None) => {
                let index = find_row(&mut document_after, &local_thread_id).ok_or_else(|| {
                    "conversation materialization requires an existing binding".to_string()
                })?;
                let row = &mut document_after.bindings[index];
                row.installed_end = Some(installed_bytes.len() as u64);
                row.installed_subagents = installed_subagents.clone();
                row.installed_absent_subagents = installed_absent_subagents.clone();
                row.path_origins_ref = Some(path_origins_ref.clone());
                row.provider_thread_id = Some(destination_provider_thread_id.clone());
                row.root_tail_layout = Some(imported_layout.clone());
                row.materialization_state = ConversationMaterializationState::Resumable;
                row.revision = row.revision.saturating_add(1);
                row.updated_at = applied_at;
            }
            (ConversationPlanActionType::CreateLocal, None) => {
                document_after.bindings.push(LocalConversationBinding {
                    installed_end: Some(installed_bytes.len() as u64),
                    installed_absent_subagents: installed_absent_subagents.clone(),
                    pulled_children_excluded: false,
                    installed_subagents: installed_subagents.clone(),
                    path_origins_ref: Some(path_origins_ref.clone()),
                    host_id: binding.host_id.clone(),
                    replica_id: binding.replica_id.clone(),
                    local_project_id: binding.local_project_id.clone(),
                    provider_profile_id: action.pins.context.provider_profile_id.clone(),
                    thread_id: local_thread_id.clone(),
                    cloud_thread_id: Some(cloud_thread_id.clone()),
                    forked_from: prepared.cloud_forked_from.clone(),
                    preserved: prepared.cloud_preserved.clone(),
                    root_tail_layout: Some(imported_layout.clone()),
                    provider_thread_id: Some(destination_provider_thread_id.clone()),
                    materialization_state: ConversationMaterializationState::Resumable,
                    revision: 0,
                    created_at: applied_at,
                    updated_at: applied_at,
                });
            }
            _ => {
                return Err(
                    "conversation Pull apply received a non-materializing action".to_string(),
                );
            }
        }
    }
    document_after.revision = document_after.revision.saturating_add(1);
    {
        let link = config_after
            .links
            .iter_mut()
            .find(|link| {
                link.local_project_id == binding.local_project_id
                    && link.storage_id == plan.storage_id
            })
            .ok_or_else(|| "conversation Pull requires a registered storage link".to_string())?;
        let threads = link
            .conversation_checkpoints
            .entry(scope.clone())
            .or_default();
        if let Some((retained_thread_id, retained_checkpoint)) = retained_source_checkpoint {
            if threads.contains_key(&retained_thread_id) {
                return Err("conversation retained-source checkpoint already exists".to_string());
            }
            threads.insert(retained_thread_id, retained_checkpoint);
        }
        // Read before Keep both moves the checkpoint away: the thread keeps
        // its id, so its checkpoint continues the numbering. A generation
        // that started again would let an observation of the file that was
        // moved answer for the file that was installed.
        let generation = threads
            .get(&local_thread_id)
            .map(|existing| existing.generation.saturating_add(1))
            .unwrap_or(0);
        if let Some(keep_both) = &keep_both_minted {
            // Re-key the destination's checkpoint to the preserved thread as
            // local-only observed state: observed tail, mapping, and witness
            // survive; the accepted pin and accepted physical end clear.
            if let Some(mut moved) = threads.remove(&local_thread_id) {
                moved.accepted = None;
                moved.accepted_local_tail = None;
                moved.accepted_subagents.clear();
                moved.generation = moved.generation.saturating_add(1);
                moved.binding_revision = moved.binding_revision.saturating_add(1);
                threads.insert(keep_both.preserved_thread_id.clone(), moved);
            }
        }
        let mut checkpoint = accepted_checkpoint.clone();
        checkpoint.generation = generation;
        threads.insert(local_thread_id.clone(), checkpoint);
        // The base takes the scope coordinates of the reviewed publication.
        // The scope counter is a per-branch number, so nothing orders by it.
        link.scope_bases.entry(scope.clone()).and_modify(|base| {
            base.scope_revision = action.pins.revision.scope_revision;
            base.scope_sha256 = action.pins.revision.scope_sha256.clone();
            base.reviewed_in = RepositoryBase {
                revision: action.pins.revision.bundle_revision,
                commit_id: action.pins.revision.commit_id.clone(),
                manifest_sha256: action.pins.revision.manifest_sha256.clone(),
                manifest_size: base.reviewed_in.manifest_size.max(1),
            };
            base.last_pull_at = Some(applied_at);
        });
    }
    config_after.revision = config_after.revision.saturating_add(1);
    on_phase("build local after-states", phase_started.elapsed());

    let operation = ConversationApplyOperation {
        operation_id: ConversationOperationId::parse(generated_named_id("operation")?)?,
        plan_id: Some(plan.plan_id.clone()),
        plan_action_id: Some(action.action_id.clone()),
        cloud: ConversationCloudAnchor {
            storage_id: plan.storage_id.clone(),
            bundle_id: plan.bundle_id.clone(),
            revision: action.pins.revision.bundle_revision,
            commit_id: action.pins.revision.commit_id.clone(),
            manifest_sha256: action.pins.revision.manifest_sha256.clone(),
        },
        host_id: binding.host_id.clone(),
        replica_id: binding.replica_id.clone(),
        local_project_id: binding.local_project_id.clone(),
        provider_profile_id: action.pins.context.provider_profile_id.clone(),
        provider: action.provider.clone(),
        // Every identity below was minted or resolved in this Apply attempt.
        thread_id: local_thread_id.clone(),
        cloud_thread_id: cloud_thread_id.clone(),
        operation: ConversationApplyKind::ProviderMaterialization(
            ConversationMaterializationApply {
                planned_relation: action.pins.tail.classification()?,
                accepted_tail_after: cloud_tail,
                // The engine's verify_provider_payload hashes the staged
                // **local** target bytes, so these pins are the decode
                // build's local digests (§3.2 form ledger); the manifest's
                // wire digests were verified at prepare.
                pinned_lineage_digest: staged_lineage_digest,
                pinned_semantic_digest: staged_semantic_digest,
                keep_both: keep_both_minted,
                expected_config_revision: config_before.revision,
                sync_config_after: config_after,
                bindings_after: document_after,
            },
        ),
        provider_thread_id: Some(destination_provider_thread_id),
        materialization_state: ConversationMaterializationState::Resumable,
        expected_host_identity_revision: action.pins.context.host_identity_revision,
        // Earlier approved actions in this Pull can advance the shared
        // document. Match the exact rolling revision this action replaces.
        expected_bindings_document_revision,
        expected_binding_revision: action.pins.context.binding_revision,
        expected_profile_revision: action.pins.context.profile_revision,
        expected_project_binding_revision: action.pins.context.project_binding_revision,
        targets: Vec::new(),
        created_at: applied_at,
        updated_at: applied_at,
    };
    let install_started = Instant::now();
    let receipt = apply_conversation_materialization_locked(
        state,
        ConversationMaterializationRequest {
            operation,
            targets,
            transcript: verified_transcript,
            subagents: children,
            checked_transcript,
        },
    )?;
    native_renames.extend(committed_renames);
    on_phase("stage and commit conversation", install_started.elapsed());
    Ok(ApplyReceipt {
        action_id: action.action_id.clone(),
        // Receipts stay in the local id space: the operation's resolved
        // local thread, minted above for CreateLocal.
        resource_id: conversation_resource_id(&action.provider, &local_thread_id)?,
        action_type: RestoreActionType::MaterializeConversation,
        logical_path: None,
        source_sha256: Some(prepared.cloud_file_sha256.clone()),
        target_path: Some(transcript_target.target_path.clone()),
        target_sha256_after: receipt.local_file_sha256_after.clone(),
        status: ActionStatus::Applied,
        applied_at,
        error: None,
        conversation: Some(receipt),
    })
}

fn approved_pull_conversation_resources(
    review: &RestorePlan,
    approved: &BTreeSet<ActionId>,
) -> BTreeSet<ResourceId> {
    review
        .conversation_review
        .iter()
        .filter(|row| {
            row.action_id
                .as_ref()
                .is_some_and(|action_id| approved.contains(action_id))
        })
        .map(|row| row.resource_id.clone())
        .collect()
}

/// An approved conversation row the apply-time review no longer offers as
/// the reviewed action. It fails on its own receipt while every other
/// approved row applies.
struct UnalignedPullSelection {
    action_id: ActionId,
    resource_id: ResourceId,
    message: String,
}

fn validate_pull_approval(
    review: &RestorePlan,
    approved_action_ids: &[ActionId],
    now: u64,
) -> Result<BTreeSet<ActionId>, String> {
    review.validate_review()?;
    if now < review.created_at || now > review.expires_at {
        return Err(REVIEW_EXPIRED.to_string());
    }
    let mut approved = BTreeSet::new();
    for action_id in approved_action_ids {
        if !approved.insert(action_id.clone()) {
            return Err(format!(
                "restore selection '{}' was approved more than once",
                action_id
            ));
        }
    }
    let known = review
        .actions
        .iter()
        .map(|action| action.action_id.clone())
        .chain(
            review
                .conversation_review
                .iter()
                .filter_map(|row| row.action_id.clone()),
        )
        .collect::<BTreeSet<_>>();
    if let Some(unknown) = approved
        .iter()
        .find(|action_id| !known.contains(*action_id))
    {
        return Err(format!(
            "restore selection '{}' is not in the comparison",
            unknown
        ));
    }

    Ok(approved)
}

/// File IDs include the resource, path, and action type and remain stable.
/// Transfer conversation selection IDs by resource and action type. Return
/// approved conversation rows that no longer match.
fn align_pull_apply_selections(
    review: &RestorePlan,
    approved: &BTreeSet<ActionId>,
    plan: &mut RestorePlan,
) -> Result<Vec<UnalignedPullSelection>, String> {
    for reviewed in review
        .actions
        .iter()
        .filter(|action| approved.contains(&action.action_id))
    {
        if !plan
            .actions
            .iter()
            .any(|candidate| candidate.action_id == reviewed.action_id)
        {
            return Err(format!(
                "resource '{}' changed after comparison",
                reviewed.resource_id
            ));
        }
    }

    let mut unaligned = Vec::new();
    for reviewed in review.conversation_review.iter().filter(|row| {
        row.action_id
            .as_ref()
            .is_some_and(|action_id| approved.contains(action_id))
    }) {
        let expected_action = reviewed
            .action
            .planned_action()
            .ok_or_else(|| format!("conversation '{}' is not selectable", reviewed.resource_id))?;
        let candidate = plan.conversation_actions.iter_mut().find(|candidate| {
            conversation_action_row_key(candidate).as_ref() == Some(&reviewed.resource_id)
                && candidate.action == expected_action
        });
        let Some(candidate) = candidate else {
            // The thread moved between Compare and Apply: the apply-time
            // review offers a different action, or none. The apply-time
            // row's own reason wins when it has one.
            let message = plan
                .conversation_review
                .iter()
                .find(|row| row.resource_id == reviewed.resource_id)
                .and_then(|row| row.blocked_reason.clone())
                .unwrap_or_else(|| {
                    "This conversation changed after the comparison. Compare again.".to_string()
                });
            unaligned.push(UnalignedPullSelection {
                action_id: reviewed
                    .action_id
                    .clone()
                    .expect("selected conversation row has an id"),
                resource_id: reviewed.resource_id.clone(),
                message,
            });
            continue;
        };
        candidate.action_id = reviewed
            .action_id
            .clone()
            .expect("selected conversation row has an id");
        if let Some(row) = plan
            .conversation_review
            .iter_mut()
            .find(|row| row.resource_id == reviewed.resource_id && row.action == reviewed.action)
        {
            row.action_id = reviewed.action_id.clone();
        }
    }
    plan.validate()?;
    Ok(unaligned)
}

/// The refusal of a Pull whose review no longer matches the storage: the
/// pinned version lost a race, the storage was cleared, or this computer
/// synced past the pin from another window. The review's error banner prints
/// it with its "Compare again" button (PLAN_PULL_PINNED_VERSION.md, T3 to T5
/// and T11).
pub const REVIEW_SUPERSEDED: &str = "The storage changed since this review. Compare again.";

/// The refusal of a review older than its one-day validity (T6).
pub const REVIEW_EXPIRED: &str = "This review is older than a day. Compare again.";

/// The receipt of a ticked session that changed on this computer since the
/// review, whatever pin noticed it (T7). The pin's own name goes to the log.
pub const CONVERSATION_CHANGED: &str =
    "This conversation changed after the comparison. Compare again.";

/// The version a review pinned, read for its apply: one listing of the
/// stream, the pinned version looked up on the selected chain, and its
/// record and manifest read by name. A newer version pushed on top does not
/// matter, because the pinned bytes are the same. The Pull is refused when
/// the pinned version is on no selected chain (it lost a race, or the
/// storage was cleared, with or without a push since), when its manifest is
/// not the reviewed one, and when a usable base of this link already names
/// a later version, because this computer synced past the pin from another
/// window and applying it would move its bases backwards
/// (PLAN_PULL_PINNED_VERSION.md, section 4.1).
fn pinned_version_for_apply(
    repository: &LocalStateRepository,
    review: &RestorePlan,
    binding: &ProjectBinding,
) -> Result<(StorageEngine, BundleSnapshot, Mainline), String> {
    let (_, engine) = storage_engine(repository, &review.storage_id)?;
    let (mainline, _) = engine.select(&review.bundle_id)?;
    let Some(pinned) = mainline
        .names()
        .iter()
        .find(|name| name.revision() == review.revision && name.commit_id() == review.commit_id)
    else {
        return Err(REVIEW_SUPERSEDED.to_string());
    };
    let config = repository.load_config()?;
    let synced_past = project_link(&config, &binding.local_project_id, &review.storage_id)
        .into_iter()
        .flat_map(|link| repository_bases(link))
        .any(|base| {
            base.revision > review.revision && mainline.contains(base.revision, &base.commit_id)
        });
    if synced_past {
        return Err(REVIEW_SUPERSEDED.to_string());
    }
    let (snapshot, _) = engine.snapshot_at(&review.bundle_id, pinned)?;
    if snapshot.head.manifest_sha256 != review.manifest_sha256 {
        return Err(REVIEW_SUPERSEDED.to_string());
    }
    Ok((engine, snapshot, mainline))
}

/// Test control over the instants around step 4 of a Pull apply, the batched
/// download of the ticked sessions, for tests that reach the storage only
/// through the whole service: what another computer does in that instant.
#[cfg(test)]
mod pull_test_support {
    use std::{cell::RefCell, path::Path};

    type Rename = Box<dyn FnMut(&Path, &str, &str) -> Result<(), String>>;
    thread_local! {
        static RENAME: RefCell<Option<Rename>> = const { RefCell::new(None) };
    }

    pub fn set_rename(rename: Option<Rename>) {
        RENAME.with(|slot| *slot.borrow_mut() = rename);
    }

    pub(super) fn rename(home: &Path, id: &str, title: &str) -> Result<(), String> {
        RENAME.with(|slot| match slot.borrow_mut().as_mut() {
            Some(rename) => rename(home, id, title),
            None => Ok(()), // Unit tests never launch the installed provider.
        })
    }

    thread_local! {
        static BEFORE_DOWNLOAD: RefCell<Option<Box<dyn FnOnce()>>> = const { RefCell::new(None) };
        static AFTER_DOWNLOAD: RefCell<Option<Box<dyn FnOnce()>>> = const { RefCell::new(None) };
    }

    /// Run `action` once on this thread, right before the next Pull apply
    /// downloads its sessions.
    pub fn before_conversation_download(action: impl FnOnce() + 'static) {
        BEFORE_DOWNLOAD.with(|slot| *slot.borrow_mut() = Some(Box::new(action)));
    }

    /// Run `action` once on this thread, right after the next Pull apply
    /// downloaded its sessions and before it installs them.
    pub fn after_conversation_download(action: impl FnOnce() + 'static) {
        AFTER_DOWNLOAD.with(|slot| *slot.borrow_mut() = Some(Box::new(action)));
    }

    pub(super) fn run_before_download() {
        if let Some(action) = BEFORE_DOWNLOAD.with(|slot| slot.borrow_mut().take()) {
            action();
        }
    }

    pub(super) fn run_after_download() {
        if let Some(action) = AFTER_DOWNLOAD.with(|slot| slot.borrow_mut().take()) {
            action();
        }
    }
}

pub(super) fn apply_bundle_restore_with_progress(
    repository: &LocalStateRepository,
    review: &RestorePlan,
    approved_action_ids: Vec<ActionId>,
    on_progress: &mut dyn FnMut(FetchProgress),
    on_phase: &mut dyn FnMut(&str, Duration),
) -> Result<RestoreResult, String> {
    let phase_started = Instant::now();
    let _host_operation = repository.acquire_host_operation()?;
    let approved_set = validate_pull_approval(review, &approved_action_ids, now_secs())?;
    let resolved = current_binding_for_restore_plan(repository, review)?;
    let binding = resolved.binding.clone();
    let selected_conversations = approved_pull_conversation_resources(review, &approved_set);
    let (engine, snapshot, mainline) = pinned_version_for_apply(repository, review, &binding)?;
    // Keep verified payloads alive across planning, preparation, and file apply,
    // even when the selected content exceeds the shared cache capacity.
    let mut byte_source = engine.byte_source(&snapshot, Some(on_progress));
    let RestoreApplyBuild {
        mut plan,
        session_views,
        captured,
    } = build_restore_plan_for_apply(
        repository,
        review,
        &resolved,
        &engine,
        &snapshot,
        &mainline,
        &selected_conversations,
        &mut byte_source,
        on_phase,
    )?;
    let unaligned = align_pull_apply_selections(review, &approved_set, &mut plan)?;
    let unaligned_ids = unaligned
        .iter()
        .map(|selection| selection.action_id.clone())
        .collect::<BTreeSet<_>>();
    let aligned_action_ids = approved_set.difference(&unaligned_ids).cloned().collect();
    let (approved, approved_conversation_actions) =
        split_approved_restore_actions(aligned_action_ids, &plan)?;
    let approves_project_content = plan.actions.iter().any(|action| {
        approved.contains(&action.action_id)
            && matches!(
                &action.kind,
                RestoreActionKind::WriteProjectFile { .. }
                    | RestoreActionKind::EnsureProjectDirectory { .. }
                    | RestoreActionKind::DeleteProjectFile { .. }
                    | RestoreActionKind::DeleteProjectDirectory { .. }
            )
    });
    if approves_project_content {
        let eligibility = project_file_sync_eligibility(&binding);
        if eligibility.state != ProjectFileSyncEligibilityState::Eligible {
            return Err(eligibility.reason);
        }
    }
    // The whole selection, priced from the pinned manifest, before the first
    // write. The review refused past this limit already; rechecking here is
    // what makes the limit a contract rather than a courtesy of the meter.
    let pull_bytes = pull_bytes_of_selection(
        &snapshot.manifest,
        &plan,
        &approved,
        approved_conversation_actions.iter().map(|selected| {
            (
                selected.action.action,
                selected.action.cloud_thread_id.as_ref(),
            )
        }),
    )?;
    if pull_bytes > provider_capture::MAX_CAPTURE_BYTES {
        return Err(pull_limit_sentence(
            pull_bytes,
            provider_capture::MAX_CAPTURE_BYTES,
        ));
    }
    let applied_at = now_secs();
    on_phase("prepare apply", phase_started.elapsed());
    let phase_started = Instant::now();
    // Metadata-only adoptions never download payloads. The whole batch is one
    // revisioned config transaction.
    let (metadata_actions, materializing_actions): (Vec<_>, Vec<_>) = approved_conversation_actions
        .into_iter()
        .partition(|selected| {
            selected.action.action == ConversationPlanActionType::AdoptCloudMetadata
        });
    let mut conversation_receipts = Vec::new();
    for selection in unaligned {
        conversation_receipts.push(failed_conversation_receipt_for(
            &selection.action_id,
            selection.resource_id,
            selection.message,
            applied_at,
        ));
    }
    let metadata_plan_actions = metadata_actions
        .iter()
        .map(|selected| selected.action.clone())
        .collect::<Vec<_>>();
    match adopt_cloud_metadata_actions(repository, &plan, &metadata_plan_actions, applied_at) {
        Ok(receipts) => conversation_receipts.extend(receipts),
        // The transaction itself failed during validation or persistence:
        // no adoption was committed, and every action reports the one
        // operation-level error instead of claiming per-thread success.
        Err(message) => {
            for action in &metadata_plan_actions {
                conversation_receipts.push(failed_conversation_receipt(
                    action,
                    message.clone(),
                    applied_at,
                )?);
            }
        }
    }
    #[cfg(test)]
    pull_test_support::run_before_download();
    // Step 4 reads the storage. When it cannot be read, the work ends here:
    // no ticked session is installed, every ticked session and file is not
    // pulled, and what step 3 saved stays (PLAN_PULL_PINNED_VERSION.md,
    // section 4.3).
    let downloaded = prepare_pull_conversation_actions(
        repository,
        &resolved,
        &snapshot,
        &mut byte_source,
        &materializing_actions,
        &session_views,
        &captured,
        &plan.storage_id,
        applied_at,
    );
    #[cfg(test)]
    pull_test_support::run_after_download();
    let (prepared_conversations, prepare_failures, session_views, mut stopped) = match downloaded {
        Ok((prepared, failures, views)) => (prepared, failures, views, None),
        Err(reason) => (Vec::new(), Vec::new(), session_views, Some(reason)),
    };
    on_phase("prepare conversations", phase_started.elapsed());
    if stopped.is_some() {
        for selected in &materializing_actions {
            conversation_receipts.push(failed_conversation_receipt(
                &selected.action,
                NOT_PULLED.to_string(),
                applied_at,
            )?);
        }
    }
    for failure in prepare_failures {
        if let Some(detail) = &failure.detail {
            on_phase(
                &format!("a session changed after the comparison: {detail}"),
                std::time::Duration::ZERO,
            );
        }
        conversation_receipts.push(failed_conversation_receipt(
            &failure.action,
            failure.message,
            applied_at,
        )?);
    }
    // The apply-time occupied set for minted provider identities: the
    // prepare capture's session views, every binding row's provider id, and
    // (inside the mint) ids minted earlier in this batch. Allocation
    // exhaustion fails the action, never retries silently.
    // Keep only the expected revisions across CPU preparation. Settings and
    // state readers must be able to acquire the persistence lock while the
    // bounded workers run or the consumer waits for the next finished result.
    let initial_state = repository.load_project_activity_state_snapshot()?;
    let initial_bindings = &initial_state.conversation_bindings;
    let mut expected_config_revision = initial_state.config.revision;
    let mut occupied_provider_ids = session_views
        .iter()
        .map(|view| view.provider_thread_id.clone())
        .chain(
            initial_bindings
                .bindings
                .iter()
                .filter_map(|row| row.provider_thread_id.clone()),
        )
        .collect::<BTreeSet<String>>();
    // Threads settle independently. Successful actions advance the shared
    // bindings document, so the next already-reviewed action chains from the
    // revision this batch just committed instead of invalidating itself.
    let mut expected_bindings_document_revision = prepared_conversations
        .first()
        .map(|prepared| prepared.action.pins.context.bindings_document_revision);
    let jobs = prepared_conversations
        .iter()
        .map(|prepared| {
            if prepared.action.provider.as_str() == "codex" {
                let destinations = mallard_infrastructure::codex_thread_allocator::allocate_codex_thread_ids_local(
                    prepared.cloud_subagents.len() + 1, &|id| occupied_provider_ids.contains(id))
                    .map(|batch| {
                        let mut ids = batch.into_iter();
                        let main = ids.next().expect("allocated main");
                        occupied_provider_ids.insert(main.clone());
                        let mut map = BTreeMap::from([(codex_subagents::PORTABLE_MAIN_ID.to_string(), main.clone())]);
                        for (key, id) in prepared.cloud_subagents.keys().zip(ids) {
                            occupied_provider_ids.insert(id.clone());
                            map.insert(codex_subagents::portable_child_id(key), id);
                        }
                        (main, map)
                    });
                return (prepared.clone(), destinations);
            }
            let action = &prepared.action;
            let destination = provider_registry()
                .require(&action.provider)
                .and_then(|adapter| {
                    if action.action == ConversationPlanActionType::MaterializeCloud
                        && !adapter.reconstructs_rollout_graph()
                    {
                        initial_bindings
                            .bindings
                            .iter()
                            .find(|row| {
                                row.host_id == binding.host_id
                                    && row.replica_id == binding.replica_id
                                    && row.local_project_id == binding.local_project_id
                                    && row.provider_profile_id
                                        == action.pins.context.provider_profile_id
                                    && Some(&row.thread_id) == action.thread_id.as_ref()
                            })
                            .and_then(|row| row.provider_thread_id.clone())
                            .ok_or_else(|| {
                                "conversation cloud update lost its provider identity".to_string()
                            })
                    } else {
                        mint_provider_thread_id(adapter, &mut occupied_provider_ids)
                    }
                });
            (prepared.clone(), destination.map(|id| (id, BTreeMap::new())))
        })
        .collect::<Vec<_>>();
    drop(initial_state);
    let workers = provider_capture::bounded_refresh_workers(jobs.len());
    let mut selected = prepared_conversations
        .into_iter()
        .map(Some)
        .collect::<Vec<_>>();
    let mut indexed_receipts = Vec::new();
    let mut native_renames = Vec::new();
    let preparation_started = Instant::now();
    // A job reserves the cloud transcript and child rollout bytes it reads
    // while it runs. Results arrive in completion order: every install
    // re-reads the shared revisions under the lock, and the receipts are put
    // back into action order after the loop.
    let bounds = mallard_infrastructure::bounded_preparation::for_each_prepared(
        jobs,
        workers,
        mallard_infrastructure::bounded_preparation::PREPARATION_BYTE_BUDGET,
        |(prepared, _)| {
            prepared
                .cloud_subagents
                .values()
                .fold(prepared.cloud_transcript.size(), |size, (body, _)| {
                    size.saturating_add(body.size())
                })
        },
        |(prepared, destination)| {
            let (destination, identities) = destination?;
            let cloud_bytes = prepared.cloud_transcript.read_bounded(
                conversation_file_limit_bytes(),
                "cloud conversation transcript",
            )?;
            let action = &prepared.action;
            let cloud_tail = action
                .pins
                .tail
                .cloud
                .as_ref()
                .ok_or("conversation Pull action lacks its pinned cloud tail")?;
            let mut transcript =
                mallard_infrastructure::pull_transcript::prepare_pull_transcript_with_identities(
                    provider_registry().require(&action.provider)?,
                    &cloud_bytes,
                    &PullTranscriptRequest {
                        cloud_thread_id: action
                            .cloud_thread_id
                            .as_ref()
                            .ok_or("conversation Pull lacks its cloud id")?
                            .as_str(),
                        cloud_tail,
                        cloud_wire_redaction: prepared.cloud_wire_redaction.as_ref(),
                        cloud_wire_path_map: prepared.cloud_wire_path_map.as_ref(),
                        lineage_digest: action.pins.tail.lineage_digest.as_deref(),
                        semantic_digest: action.pins.tail.semantic_digest.as_deref(),
                        destination_provider_thread_id: &destination,
                        project_root: &binding.project_root,
                        canonical_project_root: &binding.canonical_project_root,
                    },
                    &identities,
                )?;
            let children_started = Instant::now();
            let children = prepared
                .cloud_subagents
                .iter()
                .map(|(key, (body, normalized))| {
                    Ok((
                        key.clone(),
                        (
                            body.read_bounded(
                                conversation_file_limit_bytes(),
                                "cloud child rollout",
                            )?,
                            normalized.clone(),
                        ),
                    ))
                })
                .collect::<Result<BTreeMap<_, _>, String>>()?;
            let children = transcript.child_references.prepare(
                &children,
                &identities,
                &transcript.cloud_provider_thread_id,
                &destination,
                &binding.project_root,
                (binding.canonical_project_root != binding.project_root)
                    .then_some(binding.canonical_project_root.as_str()),
                &mut credential_redaction::shared()
                    .run_from_stamp(prepared.cloud_wire_redaction.as_ref())?,
            )?;
            for child in &children {
                transcript.path_origins.merge(child.origins())?;
            }
            Ok((
                transcript,
                destination,
                children,
                children_started.elapsed(),
            ))
        },
        |index, result| {
            let prepared = selected[index]
                .take()
                .expect("prepared action consumed once");
            let action = prepared.action.clone();
            let resource = conversation_action_row_key(&action)
                .map(|resource_id| resource_id.to_string())
                .unwrap_or_else(|| action.action_id.to_string());
            let phase_started = Instant::now();
            let expected_revision = expected_bindings_document_revision
                .unwrap_or(action.pins.context.bindings_document_revision);
            let outcome = result.and_then(|(transcript, destination, children, children_elapsed)| {
                on_phase("prepare child transcripts", children_elapsed);
                on_phase(
                    &format!("verify cloud transcript {resource}"),
                    transcript.wire_verification_elapsed,
                );
                on_phase(
                    &format!("reconstruct transcript {resource}"),
                    transcript.reconstruction_elapsed,
                );
                on_phase(
                    &format!("verify output transcript {resource}"),
                    transcript.output_verification_elapsed,
                );
                on_phase(
                    &format!(
                        "prepare transcript {resource} ({} source bytes, {} output bytes, {} semantic analyses)",
                        transcript.input_bytes,
                        transcript.transcript.bytes().len(),
                        transcript.analysis_work.passes,
                    ),
                    transcript.elapsed,
                );
                // Reload under the lock only when a prepared result is ready
                // to install. Never accept an intervening config write as the
                // next before-state of this already-approved batch.
                let mut pull_state = repository.lock_conversation_pull()?;
                if pull_state.current()?.config.revision != expected_config_revision {
                    return Err("sync config changed during Pull apply".to_string());
                }
                let outcome = apply_prepared_pull_conversation(
                    &mut pull_state,
                    &plan,
                    &resolved,
                    &snapshot,
                    prepared,
                    transcript,
                    children,
                    destination,
                    expected_revision,
                    applied_at,
                    &mut native_renames,
                    on_phase,
                );
                // A write error may follow a successful file replacement.
                // Reload and validate the durable documents under this same
                // lock, then let other sessions use the resulting revisions.
                let state_write_failed = pull_state.current().is_err();
                if state_write_failed {
                    if let Err(error) = pull_state.reload_after_failed_commit() {
                        return Err(format!("{}; reload Pull state: {error}",
                            outcome.as_ref().unwrap_err()));
                    }
                }
                if outcome.is_ok() || state_write_failed {
                    let current = pull_state.current()?;
                    expected_config_revision = current.config.revision;
                    expected_bindings_document_revision =
                        Some(current.conversation_bindings.revision);
                }
                outcome
            });
            let receipt = match outcome {
                Ok(receipt) => receipt,
                Err(message) => failed_conversation_receipt(&action, message, applied_at)
                    .expect("validated action has a receipt identity"),
            };
            indexed_receipts.push((index, receipt));
            on_phase(
                &format!("apply conversation {resource}"),
                phase_started.elapsed(),
            );
        },
    );
    on_phase(
        &format!(
            "prepare and install conversations (peak {} jobs, {} source bytes)",
            bounds.peak_jobs, bounds.peak_source_bytes
        ),
        preparation_started.elapsed(),
    );
    indexed_receipts.sort_by_key(|(index, _)| *index);
    conversation_receipts.extend(indexed_receipts.into_iter().map(|(_, receipt)| receipt));
    let phase_started = Instant::now();
    let mut applied = if stopped.is_some() {
        unreached_apply_result(&plan, &approved, applied_at, None)
    } else {
        let applied = engine.apply_restore_plan_lazy(
            &snapshot,
            &mut byte_source,
            &binding,
            &resolved.homes,
            &plan,
            &approved,
            &repository.backups_dir()?,
            applied_at,
        )?;
        stopped = applied.stopped.clone();
        applied
    };
    on_phase("restore files and provider data", phase_started.elapsed());
    let phase_started = Instant::now();
    applied.receipts.extend(conversation_receipts);
    if let Some(record) = repository
        .load_materializations()?
        .records
        .into_iter()
        .find(|record| record.plan_id == plan.plan_id)
    {
        let recorded = applied
            .receipts
            .iter()
            .map(|receipt| receipt.action_id.clone())
            .collect::<BTreeSet<_>>();
        applied.receipts.extend(
            record
                .receipts
                .into_iter()
                .filter(|receipt| !recorded.contains(&receipt.action_id)),
        );
    }
    let files_complete = reviewed_files_complete(&applied.receipts, &BTreeSet::new());
    let status = if files_complete {
        MaterializationStatus::Complete
    } else {
        MaterializationStatus::Partial
    };
    let record = MaterializationRecord {
        materialization_id: MaterializationId::parse(generated_named_id("materialization")?)?,
        plan_id: plan.plan_id.clone(),
        host_id: binding.host_id.clone(),
        replica_id: binding.replica_id.clone(),
        local_project_id: binding.local_project_id.clone(),
        storage_id: plan.storage_id.clone(),
        bundle_id: plan.bundle_id.clone(),
        revision: plan.revision,
        commit_id: plan.commit_id.clone(),
        manifest_sha256: plan.manifest_sha256.clone(),
        binding_revision: binding.revision,
        status,
        applied_at,
        receipts: applied.receipts.clone(),
    };
    repository.mutate_materializations(|_, materializations| {
        if let Some(current) = materializations
            .records
            .iter_mut()
            .find(|current| current.plan_id == record.plan_id)
        {
            if current.host_id != record.host_id
                || current.replica_id != record.replica_id
                || current.local_project_id != record.local_project_id
                || current.storage_id != record.storage_id
                || current.bundle_id != record.bundle_id
                || current.revision != record.revision
                || current.commit_id != record.commit_id
                || current.manifest_sha256 != record.manifest_sha256
                || current.binding_revision != record.binding_revision
            {
                return Err("restore receipts disagree on their reviewed Apply scope".to_string());
            }
            let existing_action_ids = current
                .receipts
                .iter()
                .map(|receipt| receipt.action_id.clone())
                .collect::<BTreeSet<_>>();
            current.receipts.extend(
                record
                    .receipts
                    .iter()
                    .filter(|receipt| !existing_action_ids.contains(&receipt.action_id))
                    .cloned(),
            );
            current.status = record.status;
            current.applied_at = current.applied_at.max(record.applied_at);
            return Ok(());
        }
        materializations.records.push(record);
        Ok(())
    })?;
    let overall_success = !applied
        .receipts
        .iter()
        .any(|receipt| matches!(receipt.status, ActionStatus::Failed | ActionStatus::Blocked));
    if files_complete {
        let cloud_repository = cloud_repository_in_use(&engine, &plan.bundle_id)?;
        repository.mutate_config(|config| {
            save_cloud_pin(
                config,
                &plan.storage_id,
                &plan.bundle_id,
                cloud_repository.as_ref(),
            );
            let project = config
                .projects
                .iter_mut()
                .find(|project| project.local_project_id == binding.local_project_id)
                .ok_or_else(|| "bound project was removed while applying restore".to_string())?;
            let _ = project;
            {
                let link = config
                    .links
                    .iter_mut()
                    .find(|link| {
                        link.local_project_id == binding.local_project_id
                            && link.storage_id == plan.storage_id
                    })
                    .ok_or_else(|| {
                        "project storage link was removed while applying restore".to_string()
                    })?;
                let reviewed_in = RepositoryBase {
                    revision: plan.revision,
                    commit_id: plan.commit_id.clone(),
                    manifest_sha256: plan.manifest_sha256.clone(),
                    manifest_size: snapshot.head.manifest_size,
                };
                // Pull advances only the approved bound scopes: the project
                // scope plus each bound provider's scope, exactly as the
                // review presented them. Unbound and unknown scopes never
                // move.
                for scope in writable_scopes_for_binding(&binding) {
                    let previous = link.scope_bases.get(&scope).cloned();
                    let last_push_at = previous.as_ref().and_then(|base| base.last_push_at);
                    let previous_pull_at = previous.as_ref().and_then(|base| base.last_pull_at);
                    match snapshot.manifest.scope(&scope) {
                        Some(remote) => {
                            link.scope_bases.insert(
                                scope.clone(),
                                ScopeBase {
                                    scope: scope.clone(),
                                    scope_revision: remote.revision,
                                    scope_sha256: remote.content_sha256.clone(),
                                    reviewed_in: reviewed_in.clone(),
                                    binding_revision: binding.revision,
                                    last_pull_at: successful_pull_timestamp(
                                        previous_pull_at,
                                        applied_at,
                                        overall_success,
                                    ),
                                    last_push_at,
                                },
                            );
                        }
                        None => {
                            link.scope_bases.remove(&scope);
                        }
                    }
                }
                drop_stale_scope_bases(link, &mainline, &reviewed_in);
            }
            let link = config
                .links
                .iter_mut()
                .find(|link| {
                    link.local_project_id == binding.local_project_id
                        && link.storage_id == plan.storage_id
                })
                .ok_or_else(|| {
                    "project storage link was removed while applying Pull".to_string()
                })?;
            link.recipe = Some(machine_local_recipe_from_manifest(&snapshot.manifest)?);
            project.revision = project.revision.saturating_add(1);
            project.updated_at = applied_at;
            Ok(())
        })?;
    }
    on_phase(
        "persist restore receipts and config",
        phase_started.elapsed(),
    );
    let offers_started = Instant::now();
    let applied_action_ids = applied
        .receipts
        .iter()
        .filter(|receipt| receipt.status == ActionStatus::Applied)
        .map(|receipt| receipt.action_id.clone())
        .collect::<Vec<_>>();
    let not_pulled_action_ids = applied
        .receipts
        .iter()
        .filter(|receipt| {
            receipt.status == ActionStatus::Failed && receipt.error.as_deref() == Some(NOT_PULLED)
        })
        .map(|receipt| receipt.action_id.clone())
        .collect::<Vec<_>>();
    let failed_actions = applied
        .receipts
        .iter()
        .filter(|receipt| matches!(receipt.status, ActionStatus::Failed | ActionStatus::Blocked))
        .filter(|receipt| !not_pulled_action_ids.contains(&receipt.action_id))
        .map(|receipt| FailedAction {
            action_id: receipt.action_id.clone(),
            display_name: None,
            message: receipt
                .error
                .clone()
                .unwrap_or_else(|| "Action was not materialized".to_string()),
        })
        .collect::<Vec<_>>();
    let preserved_threads = applied
        .receipts
        .iter()
        .filter_map(|receipt| {
            receipt.conversation.as_ref().and_then(|conversation| {
                conversation.preserved_thread_id.as_ref().map(|preserved| {
                    // The marker title is minted at Apply and reaches the UI
                    // through the receipt, never through Compare.
                    let preserved_display_title = conversation
                        .preserved_display_title
                        .clone()
                        .ok_or_else(|| {
                            "applied keep-both receipt lacks its minted marker title".to_string()
                        })?;
                    Ok(PreservedThreadResult {
                        action_id: receipt.action_id.clone(),
                        original_thread_id: conversation.thread_id.clone(),
                        preserved_thread_id: preserved.clone(),
                        preserved_display_title,
                    })
                })
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    let success = overall_success;
    // A stopped Pull says so first: what it installed stays, what it did not
    // reach is not pulled, and the areas are not marked as reviewed. A
    // missing object names no cause: the storage was cleared, or a folder
    // that a sync product replicates has not received it yet.
    let stopped = stopped.map(|reason| {
        if reason == VERSION_INCOMPLETE {
            let (_, storage_name, _) = project_storage_log_context(
                repository,
                &binding.local_project_id,
                &plan.storage_id,
            );
            format!("Part of this version is missing from {storage_name}. Compare again.")
        } else {
            reason
        }
    });
    let message = if let Some(stopped) = &stopped {
        stopped.clone()
    } else if success {
        format!("Applied {} restore actions", applied_action_ids.len())
    } else {
        format!(
            "Applied {} actions; {} require attention",
            applied_action_ids.len(),
            failed_actions.len()
        )
    };
    let (readiness, readiness_error) =
        match bundle_readiness_for_snapshot(repository, &resolved, &snapshot) {
            Ok(readiness) => (Some(readiness), None),
            Err(error) => (None, Some(error)),
        };
    let result = RestoreResult {
        success,
        message,
        readiness,
        readiness_error,
        plan_id: Some(plan.plan_id),
        reviewed_base_advanced: Some(files_complete),
        applied_action_ids,
        failed_actions,
        preserved_threads,
        // Every committed conversation materialization may leave a running
        // provider app unaware of the thread until its next rescan; each
        // bound provider's adapter decides whether to offer a follow-up.
        after_pull_actions: applied
            .receipts
            .iter()
            .find_map(|receipt| receipt.conversation.as_ref())
            .map(|receipt| {
                resolved
                    .homes
                    .iter()
                    .filter_map(|(provider, home)| {
                        provider_registry().get(provider).and_then(|adapter| {
                            adapter.after_pull_offer(&receipt.operation_id, Some(Path::new(home)))
                        })
                    })
                    .collect()
            })
            .unwrap_or_default(),
        stopped,
        not_pulled_action_ids,
    };
    on_phase("build after-Pull offers", offers_started.elapsed());
    on_phase("persist receipts and finalize", phase_started.elapsed());
    let rename_started = Instant::now();
    rename_committed_codex_titles(repository, native_renames);
    on_phase("update Codex titles", rename_started.elapsed());
    Ok(result)
}

/// Collapse a config transaction failure to the repository's error string.
/// Batch closures report per-item outcomes as data, so both arms carry the
/// same operation-level message type.
fn config_transaction_error(error: ConfigTransactionError<String>) -> String {
    match error {
        ConfigTransactionError::Mutation(message)
        | ConfigTransactionError::Persistence(message) => message,
    }
}

/// Apply every approved metadata-only adoption in one revisioned config
/// transaction: each accepts its verified cloud value into the destination
/// checkpoint and advances the scope base. A stale or missing thread fails
/// its own receipt without rejecting valid siblings; the document is written
/// once when at least one adoption applied, and a transaction failure
/// commits nothing.
fn adopt_cloud_metadata_actions(
    repository: &LocalStateRepository,
    plan: &RestorePlan,
    actions: &[ConversationPlanAction],
    applied_at: u64,
) -> Result<Vec<ApplyReceipt>, String> {
    if actions.is_empty() {
        return Ok(Vec::new());
    }
    struct PreparedAdoption {
        local_thread_id: ThreadId,
        cloud_tail: PortableConversationTail,
        accepted_local_tail: PortableConversationTail,
        resource_id: ResourceId,
    }
    // Action-local fields are validated before the transaction; a prepared
    // slot of `Err` is already that action's failed outcome.
    let prepared =
        actions
            .iter()
            .map(|action| {
                // Adopt actions always operate on a registered local thread (D5).
                let local_thread_id = action
                    .thread_id
                    .clone()
                    .ok_or_else(|| "conversation adoption lacks its local thread id".to_string())?;
                let cloud_tail = action.pins.tail.cloud.clone().ok_or_else(|| {
                    "conversation adoption lacks its pinned cloud tail".to_string()
                })?;
                // The local column accepts the reviewed local observation:
                // adoption runs only on Sync relations, where classification
                // proved it equivalent to the accepted cloud value in its own
                // form.
                let accepted_local_tail = action.pins.tail.local.clone().ok_or_else(|| {
                    "conversation adoption lacks its pinned local tail".to_string()
                })?;
                let resource_id = conversation_resource_id(&action.provider, &local_thread_id)?;
                Ok(PreparedAdoption {
                    local_thread_id,
                    cloud_tail,
                    accepted_local_tail,
                    resource_id,
                })
            })
            .collect::<Vec<Result<PreparedAdoption, String>>>();
    let (outcomes, _) = repository
        .transact_config(|config| {
            let mut changed = false;
            let mut outcomes: Vec<Result<ResourceId, String>> = Vec::with_capacity(actions.len());
            for (action, prepared) in actions.iter().zip(&prepared) {
                let outcome = (|| {
                    let prepared = prepared.as_ref().map_err(Clone::clone)?;
                    let scope = SyncScopeKey::Provider(action.provider.clone());
                    let link = config
                        .links
                        .iter_mut()
                        .find(|link| {
                            link.local_project_id == action.pins.context.local_project_id
                                && link.storage_id == plan.storage_id
                        })
                        .ok_or_else(|| {
                            "conversation adoption requires a registered storage link".to_string()
                        })?;
                    let checkpoint = link
                        .conversation_checkpoints
                        .get_mut(&scope)
                        .and_then(|threads| threads.get_mut(&prepared.local_thread_id))
                        .ok_or_else(|| {
                            "conversation adoption requires an existing destination checkpoint"
                                .to_string()
                        })?;
                    if Some(checkpoint.generation) != action.pins.tail.checkpoint_generation {
                        return Err(
                            "conversation adoption checkpoint advanced after review; refresh \
                             and pull again"
                                .to_string(),
                        );
                    }
                    let accepted = mallard_domain::AcceptedConversationVersion {
                        artifact_sha256: checkpoint
                            .accepted
                            .as_ref()
                            .map(|accepted| accepted.artifact_sha256.clone())
                            .unwrap_or_else(|| hex_digest(Sha256::digest([]).as_slice())),
                        accepted_at_commit_id: action.pins.revision.commit_id.clone(),
                        accepted_at_manifest_sha256: action.pins.revision.manifest_sha256.clone(),
                        portable_tail: prepared.cloud_tail.clone(),
                    };
                    checkpoint.accepted = Some(accepted);
                    checkpoint.accepted_local_tail = Some(prepared.accepted_local_tail.clone());
                    checkpoint.observed_tail = prepared.accepted_local_tail.clone();
                    checkpoint.generation = checkpoint.generation.saturating_add(1);
                    link.scope_bases.entry(scope).and_modify(|base| {
                        base.scope_revision = action.pins.revision.scope_revision;
                        base.scope_sha256 = action.pins.revision.scope_sha256.clone();
                        base.reviewed_in = RepositoryBase {
                            revision: action.pins.revision.bundle_revision,
                            commit_id: action.pins.revision.commit_id.clone(),
                            manifest_sha256: action.pins.revision.manifest_sha256.clone(),
                            manifest_size: base.reviewed_in.manifest_size.max(1),
                        };
                        base.last_pull_at = Some(applied_at);
                    });
                    Ok(prepared.resource_id.clone())
                })();
                changed |= outcome.is_ok();
                outcomes.push(outcome);
            }
            if changed {
                Ok::<_, String>(ConfigMutation::Changed(outcomes))
            } else {
                Ok(ConfigMutation::Unchanged(outcomes))
            }
        })
        .map_err(config_transaction_error)?;
    actions
        .iter()
        .zip(outcomes)
        .map(|(action, outcome)| match outcome {
            Ok(resource_id) => Ok(ApplyReceipt {
                action_id: action.action_id.clone(),
                resource_id,
                action_type: RestoreActionType::MaterializeConversation,
                logical_path: None,
                source_sha256: None,
                target_path: None,
                target_sha256_after: None,
                status: ActionStatus::Applied,
                applied_at,
                error: None,
                conversation: None,
            }),
            Err(message) => failed_conversation_receipt(action, message, applied_at),
        })
        .collect()
}

pub(super) fn committed_conversation_receipt(
    repository: &LocalStateRepository,
    operation_id: &ConversationOperationId,
) -> Result<mallard_domain::ConversationApplyReceipt, String> {
    let materializations = repository.load_materializations()?;
    materializations
        .records
        .iter()
        .flat_map(|record| record.receipts.iter())
        .filter(|receipt| receipt.status == ActionStatus::Applied)
        .find_map(|receipt| {
            receipt
                .conversation
                .clone()
                .filter(|conversation| &conversation.operation_id == operation_id)
        })
        .ok_or_else(|| "committed conversation receipt was not found".to_string())
}

fn successful_pull_timestamp(
    previous: Option<u64>,
    applied_at: u64,
    overall_success: bool,
) -> Option<u64> {
    overall_success.then_some(applied_at).or(previous)
}

/// Load the exact storage snapshot approved by a Pull review. Dependency and
/// readiness support must never discover a different linked storage on their
/// own, because each storage advances its bundle revisions independently.
/// Load the plan's binding and re-inspect the bundle head it pins. This is
/// deliberately metadata-only — supporting views (dependencies, readiness)
/// must never download payload objects.
/// Whether this apply may advance the reviewed recipe base to its plan's
/// revision. Declining a project-content decision (`Skipped`) settles the
/// review, a `Manual` keep-local receipt is itself the decision, and a
/// declined conversation materialization is the Claude spelling of an
/// unapproved typed Codex action (which never produces a receipt): the
/// thread stays in storage, Push carries it forward by reference, and the
/// next Pull re-offers it. Only a skipped `WriteFile`/`MergeFile` leaves
/// reviewed generic content behind that the baseline must not move past.
/// An empty receipt set is a completed review of nothing: the
/// acknowledge-only Pull that advances the baseline without materializing
/// anything.
fn reviewed_files_complete(
    receipts: &[ApplyReceipt],
    kept_local_conversation_actions: &BTreeSet<ActionId>,
) -> bool {
    receipts.iter().all(|receipt| match receipt.action_type {
        RestoreActionType::WriteProjectFile
        | RestoreActionType::EnsureProjectDirectory
        | RestoreActionType::DeleteProjectFile
        | RestoreActionType::DeleteProjectDirectory
        | RestoreActionType::MaterializeConversation
        | RestoreActionType::PublishConversation => {
            matches!(
                receipt.status,
                ActionStatus::Applied | ActionStatus::Skipped
            )
        }
        RestoreActionType::WriteFile | RestoreActionType::MergeFile => {
            receipt.status == ActionStatus::Applied
        }
        RestoreActionType::Manual => {
            receipt.status == ActionStatus::Applied
                || (receipt.status == ActionStatus::Skipped
                    && kept_local_conversation_actions.contains(&receipt.action_id))
        }
    })
}

/// Read current setup state. This query does not authorize an Apply.
pub(super) fn get_restore_readiness_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Result<BundleReadiness, String> {
    let state = repository.load_project_state_snapshot()?;
    let binding = state
        .bindings
        .active_for(local_project_id)
        .ok_or_else(|| "project has no active binding".to_string())?;
    if project_link(&state.config, local_project_id, storage_id).is_none() {
        return Err("project is not linked to this storage".to_string());
    }
    let resolved = resolve_project_binding_from_state(&state.bindings, binding)?;
    let (_, engine) =
        storage_engine_from_state(repository, &state.config, &state.bindings, storage_id)?;
    let snapshot = engine.inspect(&binding.bundle_id)?;
    bundle_readiness_for_snapshot(repository, &resolved, &snapshot)
}

fn bundle_readiness_for_snapshot(
    repository: &LocalStateRepository,
    resolved: &ResolvedBinding,
    snapshot: &BundleSnapshot,
) -> Result<BundleReadiness, String> {
    let binding = &resolved.binding;
    let head = &snapshot.head;
    let bundle_id = &head.bundle_id;
    let materialization = repository
        .load_materializations()?
        .records
        .into_iter()
        .rev()
        .find(|record| {
            record.host_id == binding.host_id
                && record.replica_id == binding.replica_id
                && record.bundle_id == *bundle_id
                && record.revision == head.revision
                && record.manifest_sha256 == head.manifest_sha256
                && record.binding_revision == binding.revision
                && record.status != MaterializationStatus::Detached
        });
    let mut issues = Vec::new();
    // Provider-home readiness is informational per provider scope: an
    // unbound provider's remote sessions stay view-only rather than
    // blocking anything.
    for (provider, scope) in snapshot.manifest.provider_scopes() {
        let needs_home = !scope.conversations.is_empty() || !scope.resources.is_empty();
        add_provider_home_issue(
            &mut issues,
            provider.clone(),
            needs_home,
            resolved.homes.get(provider).map(String::as_str),
        );
    }
    if snapshot.manifest.all_files().next().is_some() {
        match materialization.as_ref() {
            None => issues.push(BundleReadinessIssue {
                issue_id: "restore-files".to_string(),
                category: "project_files".to_string(),
                title: "Pull has not been applied yet".to_string(),
                detail: Some(
                    "Open the Pull review and apply the changes you want on this machine."
                        .to_string(),
                ),
                severity: "warning".to_string(),
                provider: None,
                resource_id: None,
                action: Some("plan_restore".to_string()),
            }),
            Some(record) if record.status == MaterializationStatus::Partial => {
                add_partial_materialization_issues(&mut issues, record, snapshot);
            }
            Some(_) => {}
        }
    }
    let blocked = issues.iter().any(|issue| issue.severity == "error");
    Ok(BundleReadiness {
        bundle_id: bundle_id.clone(),
        state: if blocked {
            "blocked"
        } else if issues.is_empty() {
            "ready"
        } else {
            "needs_setup"
        }
        .to_string(),
        issues,
        generated_at: now_secs(),
    })
}

fn add_partial_materialization_issues(
    issues: &mut Vec<BundleReadinessIssue>,
    materialization: &MaterializationRecord,
    snapshot: &BundleSnapshot,
) {
    let unresolved = materialization
        .receipts
        .iter()
        .filter(|receipt| receipt.status != ActionStatus::Applied)
        .collect::<Vec<_>>();

    let manual_conversations = unresolved
        .iter()
        .filter(|receipt| receipt.action_type == RestoreActionType::Manual)
        .filter(|receipt| {
            snapshot
                .manifest
                .find_resource(&receipt.resource_id)
                .is_some_and(|(_, resource)| {
                    kind_primitive(&resource.kind) == Some(ResourceKindPrimitive::Conversation)
                })
        })
        .map(|receipt| receipt.resource_id.clone())
        .collect::<BTreeSet<_>>();
    if !manual_conversations.is_empty() {
        let count = manual_conversations.len();
        let resource_id = (count == 1)
            .then(|| manual_conversations.iter().next().cloned())
            .flatten();
        let provider = resource_id
            .as_ref()
            .and_then(|resource_id| snapshot.manifest.find_resource(resource_id))
            .and_then(|(_, resource)| resource.provider.clone());
        issues.push(BundleReadinessIssue {
            issue_id: "conversation-conflicts".to_string(),
            category: "sessions".to_string(),
            title: if count == 1 {
                "1 conversation conflict still needs manual resolution".to_string()
            } else {
                format!("{count} conversation conflicts still need manual resolution")
            },
            detail: Some(
                "The other selected changes were restored. The conflicted local conversation was left unchanged."
                    .to_string(),
            ),
            severity: "warning".to_string(),
            provider,
            resource_id,
            action: Some("resolve_conflict".to_string()),
        });
    }

    let incomplete_project_data = unresolved
        .iter()
        .filter(|receipt| {
            if receipt.action_type == RestoreActionType::Manual {
                return !manual_conversations.contains(&receipt.resource_id);
            }
            match receipt.action_type {
                RestoreActionType::WriteFile
                | RestoreActionType::MergeFile
                | RestoreActionType::MaterializeConversation
                | RestoreActionType::PublishConversation => true,
                RestoreActionType::WriteProjectFile
                | RestoreActionType::EnsureProjectDirectory
                | RestoreActionType::DeleteProjectFile
                | RestoreActionType::DeleteProjectDirectory => {
                    matches!(receipt.status, ActionStatus::Failed | ActionStatus::Blocked)
                }
                RestoreActionType::Manual => false,
            }
        })
        .copied()
        .collect::<Vec<&ApplyReceipt>>();
    if !incomplete_project_data.is_empty() {
        let resource_ids = incomplete_project_data
            .iter()
            .map(|receipt| receipt.resource_id.clone())
            .collect::<BTreeSet<_>>();
        let count = resource_ids.len();
        let failed = incomplete_project_data
            .iter()
            .any(|receipt| matches!(receipt.status, ActionStatus::Failed | ActionStatus::Blocked));
        issues.push(BundleReadinessIssue {
            issue_id: "restore-project-data".to_string(),
            category: "project_files".to_string(),
            title: if count == 1 {
                "1 project data change was left unchanged".to_string()
            } else {
                format!("{count} project data changes were left unchanged")
            },
            detail: Some(if failed {
                "Review the technical result, fix the reported problem, and try Pull again."
                    .to_string()
            } else {
                "Review this change separately before applying it on this machine.".to_string()
            }),
            severity: if failed { "error" } else { "warning" }.to_string(),
            provider: None,
            resource_id: (count == 1)
                .then(|| resource_ids.iter().next().cloned())
                .flatten(),
            action: Some("review_restore".to_string()),
        });
    }
}

/// One active binding together with its resolved provider homes. Machine
/// state persists profile IDs; commands resolve homes per operation through
/// the profile catalog and never store them on the binding.
#[derive(Clone, Debug)]
pub(crate) struct ResolvedBinding {
    pub binding: ProjectBinding,
    pub homes: BTreeMap<ProviderKey, String>,
}

impl ResolvedBinding {
    fn home(&self, provider: &ProviderKey) -> Result<&str, String> {
        self.homes.get(provider).map(String::as_str).ok_or_else(|| {
            format!(
                "provider '{}' is not bound with a readable profile on this machine",
                provider
            )
        })
    }
}

/// Every publication a scope base of this link was reviewed in. Global
/// history continuity checks each of them against the selected chain;
/// per-scope continuity is classified against each scope base separately.
fn repository_bases(link: &ProjectStorageLink) -> impl Iterator<Item = &RepositoryBase> {
    link.scope_bases.values().map(|base| &base.reviewed_in)
}

/// Remove every scope base that was reviewed in a publication off the
/// selected chain. A Push and a Pull call this in the transaction that saves
/// their new bases: `saved` is the publication those name, and `mainline` is
/// the chain it was built on or read from. Comparisons already read a stale
/// base as absent; removing it here is what ends the cleared-storage notice,
/// and only an action of the user does it, never a refresh.
fn drop_stale_scope_bases(
    link: &mut ProjectStorageLink,
    mainline: &Mainline,
    saved: &RepositoryBase,
) {
    link.scope_bases.retain(|_, base| {
        base.reviewed_in.commit_id == saved.commit_id
            || mainline.contains(base.reviewed_in.revision, &base.reviewed_in.commit_id)
    });
}

/// The newest publication any scope base of this link was reviewed in: the
/// base the status views print and reload.
fn repository_base_from_link(link: &ProjectStorageLink) -> Option<RepositoryBase> {
    repository_bases(link)
        .max_by_key(|reviewed| reviewed.revision)
        .cloned()
}

fn project_link<'a>(
    config: &'a SyncConfig,
    local_project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Option<&'a ProjectStorageLink> {
    config
        .links
        .iter()
        .find(|link| &link.local_project_id == local_project_id && &link.storage_id == storage_id)
}

#[cfg(test)]
fn require_current_binding(
    repository: &LocalStateRepository,
    supplied: &ProjectBinding,
) -> Result<ResolvedBinding, String> {
    let bindings = repository.load_bindings()?;
    require_current_binding_from_state(&bindings, supplied)
}

fn require_current_binding_from_state(
    bindings: &MachineProjectState,
    supplied: &ProjectBinding,
) -> Result<ResolvedBinding, String> {
    if supplied.state != BindingState::Active {
        return Err("project binding is not active".to_string());
    }
    let current = bindings
        .bindings
        .iter()
        .find(|binding| {
            binding.host_id == supplied.host_id && binding.replica_id == supplied.replica_id
        })
        .ok_or_else(|| "project binding is not registered on this machine".to_string())?;
    if current != supplied {
        return Err("project binding changed; refresh before continuing".to_string());
    }
    resolve_project_binding_from_state(bindings, current)
}

pub(super) fn resolve_project_binding(
    repository: &LocalStateRepository,
    binding: &ProjectBinding,
) -> Result<ResolvedBinding, String> {
    let state = repository.load_bindings()?;
    resolve_project_binding_from_state(&state, binding)
}

fn resolve_project_binding_from_state(
    state: &MachineProjectState,
    binding: &ProjectBinding,
) -> Result<ResolvedBinding, String> {
    let homes = resolve_profile_paths_from_state(state, &binding.profile_ids)?;
    let resolved = ResolvedBinding {
        binding: binding.clone(),
        homes,
    };
    resolved.binding.validate_structure()?;
    Ok(resolved)
}

pub(super) fn current_binding_for_restore_plan(
    repository: &LocalStateRepository,
    plan: &RestorePlan,
) -> Result<ResolvedBinding, String> {
    let state = repository.load_project_state_snapshot()?;
    let identity = &state.host_identity;
    if identity.host_id != plan.host_id || identity.revision != plan.expected_host_identity_revision
    {
        return Err("restore plan's host identity changed after planning".to_string());
    }
    let binding = state
        .bindings
        .bindings
        .iter()
        .find(|binding| {
            binding.host_id == plan.host_id
                && binding.replica_id == plan.replica_id
                && binding.state == BindingState::Active
        })
        .ok_or_else(|| "restore plan's project binding is no longer active".to_string())?;
    if binding.revision != plan.binding_revision || binding.bundle_id != plan.bundle_id {
        return Err("restore plan's project binding changed after planning".to_string());
    }
    resolve_project_binding_from_state(&state.bindings, binding)
}

/// Every bound provider's declared ways to open the pulled project, in
/// provider display order.
pub(super) fn project_open_commands(resolved: &ResolvedBinding) -> Vec<(String, String)> {
    let mut commands = Vec::new();
    for descriptor in provider_registry().descriptors() {
        let Some(home) = resolved.homes.get(&descriptor.key) else {
            continue;
        };
        let Some(adapter) = provider_registry().get(&descriptor.key) else {
            continue;
        };
        commands.extend(
            adapter
                .project_open_commands(Path::new(home), &resolved.binding.project_root)
                .into_iter()
                .map(|command| (command.label, command.command)),
        );
    }
    commands
}

fn split_approved_restore_actions(
    mut approved: BTreeSet<ActionId>,
    plan: &RestorePlan,
) -> Result<(BTreeSet<ActionId>, Vec<SelectedPullConversation>), String> {
    let plan_action_ids = plan
        .actions
        .iter()
        .map(|action| action.action_id.clone())
        .chain(
            plan.conversation_actions
                .iter()
                .map(|action| action.action_id.clone()),
        )
        .collect::<BTreeSet<_>>();
    if let Some(unknown) = approved
        .iter()
        .find(|action_id| !plan_action_ids.contains(*action_id))
    {
        return Err(format!(
            "restore action '{}' is not in the Pull review",
            unknown
        ));
    }
    let mut selected_conversations = Vec::new();
    for action in &plan.conversation_actions {
        if !approved.contains(&action.action_id) {
            continue;
        }
        if !is_selectable_pull_conversation_action(action) {
            return Err(format!(
                "conversation Pull action '{}' cannot be selected",
                action.action_id
            ));
        }
        approved.remove(&action.action_id);
        selected_conversations.push(SelectedPullConversation {
            action: action.clone(),
        });
    }
    Ok((approved, selected_conversations))
}

fn add_provider_home_issue(
    issues: &mut Vec<BundleReadinessIssue>,
    provider: ProviderKey,
    required: bool,
    home: Option<&str>,
) {
    if !required {
        return;
    }
    let valid = home.is_some_and(|path| {
        fs::symlink_metadata(path)
            .is_ok_and(|metadata| metadata.is_dir() && !metadata.file_type().is_symlink())
    });
    if valid {
        return;
    }
    let name = provider_name(&provider);
    issues.push(BundleReadinessIssue {
        issue_id: format!("provider-home-{}", provider),
        category: "conversations".to_string(),
        title: format!("{} home is not mapped", name),
        detail: Some(format!(
            "Choose an existing {} home before restoring provider state.",
            name
        )),
        severity: "error".to_string(),
        provider: Some(provider),
        resource_id: None,
        action: Some("edit_binding".to_string()),
    });
}

#[cfg(test)]
fn capture_request_for_binding(
    repository: &LocalStateRepository,
    binding: &ProjectBinding,
) -> Result<CaptureRequest, String> {
    let state = repository.load_project_state_snapshot()?;
    let resolved = resolve_project_binding_from_state(&state.bindings, binding)?;
    capture_request_for_resolved_binding_from_state(
        repository.root(),
        &state.config,
        &state.bindings,
        &resolved,
    )
}

fn capture_request_for_resolved_binding_from_state(
    repository_root: &Path,
    config: &SyncConfig,
    bindings: &MachineProjectState,
    resolved: &ResolvedBinding,
) -> Result<CaptureRequest, String> {
    let binding = &resolved.binding;
    if bindings.active_for(&binding.local_project_id) != Some(binding)
        || resolved.homes.iter().any(|(provider, home)| {
            !bindings.profiles.iter().any(|profile| {
                binding.profile_ids.get(provider) == Some(&profile.profile_id)
                    && &profile.provider == provider
                    && &profile.canonical_path == home
            })
        })
    {
        return Err("project binding changed; refresh before continuing".to_string());
    }
    let resolved_project = fs_canonicalize(Path::new(&binding.project_root))?;
    if resolved_project != binding.canonical_project_root {
        return Err("project binding resolves to a different checkout".to_string());
    }
    // Nested bound projects are separate directory projects. Exact-home
    // ownership keeps their sessions out with no exclusion list, but their
    // trees must still stay out of this project's content capture.
    let nested_binding_roots: Vec<PathBuf> = bindings
        .bindings
        .iter()
        .filter(|other| {
            other.state == BindingState::Active && other.replica_id != binding.replica_id
        })
        .map(|other| PathBuf::from(&other.canonical_project_root))
        .filter(|root| root.starts_with(&resolved_project) && root != &resolved_project)
        .collect();
    let mut request = CaptureRequest {
        project_root: resolved_project,
        provider_homes: resolved
            .homes
            .iter()
            .map(|(provider, home)| (provider.clone(), PathBuf::from(home)))
            .collect(),
        include_project_content: false,
        excluded_content_roots: nested_binding_roots,
    };
    request
        .excluded_content_roots
        .push(repository_root.to_path_buf());
    request.excluded_content_roots.extend(
        configured_local_storage_roots(config)?
            .into_iter()
            .map(|(_, root)| root),
    );
    for home in resolved.homes.values() {
        request.excluded_content_roots.push(PathBuf::from(home));
    }
    Ok(request)
}

pub(super) fn repository_fingerprint(project_root: &Path) -> Option<String> {
    origin_url(project_root).map(|url| repository_fingerprint_from_remote_url(&url))
}

/// The `origin` remote's URL as `.git/config` spells it, read without
/// running Git; none when the folder has no readable config of its own.
pub(super) fn origin_url(project_root: &Path) -> Option<String> {
    let config_path = project_root.join(".git/config");
    let metadata = fs::symlink_metadata(&config_path).ok()?;
    if !metadata.is_file() || metadata.file_type().is_symlink() || metadata.len() > 1024 * 1024 {
        return None;
    }
    let contents = fs::read_to_string(config_path).ok()?;
    let mut in_origin = false;
    for line in contents.lines() {
        let line = line.trim();
        if line.starts_with('[') {
            in_origin = line.eq_ignore_ascii_case("[remote \"origin\"]");
            continue;
        }
        if in_origin {
            let Some((key, value)) = line.split_once('=') else {
                continue;
            };
            if key.trim().eq_ignore_ascii_case("url") {
                return Some(value.trim().to_string());
            }
        }
    }
    None
}

pub(super) fn repository_fingerprint_from_remote_url(value: &str) -> String {
    let sanitized = strip_url_userinfo(value.trim());
    let canonical_github = project_activity::normalize_github_repository_url(value);
    let canonical = canonical_github.as_deref().unwrap_or(&sanitized);
    repository_url_fingerprint(canonical)
}

fn repository_url_fingerprint(value: &str) -> String {
    let digest = Sha256::digest(value.as_bytes());
    hex_digest(&digest)
}

fn strip_url_userinfo(value: &str) -> String {
    let Some((scheme, remainder)) = value.split_once("://") else {
        return value.to_string();
    };
    let authority_end = remainder.find('/').unwrap_or(remainder.len());
    let authority = &remainder[..authority_end];
    let Some(at) = authority.rfind('@') else {
        return value.to_string();
    };
    format!("{}://{}", scheme, &remainder[at + 1..])
}

fn require_project_link<'a>(
    config: &'a SyncConfig,
    project: &LocalProjectRegistration,
    storage_id: &StorageId,
) -> Result<&'a ProjectStorageLink, String> {
    config
        .links
        .iter()
        .find(|link| {
            link.local_project_id == project.local_project_id
                && &link.storage_id == storage_id
                && link.bundle_id == project.bundle_id
        })
        .ok_or_else(|| {
            format!(
                "project '{}' is not linked to storage '{}'",
                project.local_project_id, storage_id
            )
        })
}

pub(super) fn storage_engine(
    repository: &LocalStateRepository,
    storage_id: &StorageId,
) -> Result<(StorageConfig, StorageEngine), String> {
    let state = repository.load_project_state_snapshot()?;
    storage_engine_from_state(repository, &state.config, &state.bindings, storage_id)
}

fn storage_engine_from_state(
    repository: &LocalStateRepository,
    config: &SyncConfig,
    machine: &MachineProjectState,
    storage_id: &StorageId,
) -> Result<(StorageConfig, StorageEngine), String> {
    let storage = config
        .storages
        .iter()
        .find(|storage| &storage.id == storage_id)
        .cloned()
        .ok_or_else(|| format!("unknown storage '{}'", storage_id))?;
    validate_config_storage_isolation(repository, config, &machine.bindings, &machine.profiles)?;
    let store = ConfiguredObjectStore::shared(&storage)?;
    if let Some(cloud) = store.managed_cloud() {
        for link in config
            .links
            .iter()
            .filter(|link| link.storage_id == *storage_id)
        {
            cloud.set_pin(&link.bundle_id, link.managed_cloud_repository_id.as_deref())?;
        }
    }
    let engine = engine_for_storage_config(&storage)?;
    Ok((storage, engine))
}

/// Attach an engine to the process-shared store for one storage
/// configuration; the marker was verified when that store was opened.
fn engine_for_storage_config(storage: &StorageConfig) -> Result<StorageEngine, String> {
    Ok(
        BundleEngine::open(ConfiguredObjectStore::shared(storage)?, storage.id.clone())?
            .with_object_cache(ObjectCache::global()),
    )
}

/// Every configured storage that occupies a machine-local directory, with
/// that directory, resolved through its adapter. A storage whose provider is
/// unavailable in this build claims no local root.
fn configured_local_storage_roots(
    config: &SyncConfig,
) -> Result<Vec<(&StorageConfig, PathBuf)>, String> {
    let registry = StorageProviderRegistry::production();
    let mut roots = Vec::new();
    for storage in &config.storages {
        if let Some(root) = storage_local_root(registry, storage)? {
            roots.push((storage, root));
        }
    }
    Ok(roots)
}

fn validate_config_storage_isolation(
    repository: &LocalStateRepository,
    config: &SyncConfig,
    bindings: &[ProjectBinding],
    profiles: &[ProviderProfile],
) -> Result<(), String> {
    let repository_root = prospective_canonical(repository.root())?;
    let mut local_roots = Vec::<(&StorageConfig, PathBuf)>::new();
    for (storage, configured_root) in configured_local_storage_roots(config)? {
        let root = prospective_canonical(&configured_root)?;
        if paths_overlap(&root, &repository_root) {
            return Err(format!(
                "local storage '{}' overlaps Mallard application data",
                storage.name
            ));
        }
        for (other, other_root) in &local_roots {
            if paths_overlap(&root, other_root) {
                return Err(format!(
                    "local storages '{}' and '{}' overlap",
                    storage.name, other.name
                ));
            }
        }
        for binding in bindings
            .iter()
            .filter(|binding| binding.state == BindingState::Active)
        {
            let target = prospective_canonical(Path::new(&binding.canonical_project_root))?;
            if paths_overlap(&root, &target) {
                return Err(format!(
                    "local storage '{}' overlaps project root '{}'",
                    storage.name,
                    target.display()
                ));
            }
        }
        for profile in profiles {
            let target = prospective_canonical(Path::new(&profile.canonical_path))?;
            if paths_overlap(&root, &target) {
                return Err(format!(
                    "local storage '{}' overlaps {} profile '{}'",
                    storage.name,
                    provider_name(&profile.provider),
                    target.display()
                ));
            }
        }
        local_roots.push((storage, root));
    }
    Ok(())
}

fn prospective_canonical(path: &Path) -> Result<PathBuf, String> {
    if !path.is_absolute()
        || path.components().any(|component| {
            matches!(
                component,
                std::path::Component::CurDir | std::path::Component::ParentDir
            )
        })
    {
        return Err(format!(
            "path '{}' is not absolute and clean",
            path.display()
        ));
    }
    let mut cursor = path.to_path_buf();
    let mut missing = Vec::new();
    loop {
        match fs::symlink_metadata(&cursor) {
            Ok(_) => {
                let mut resolved = fs::canonicalize(&cursor)
                    .map_err(|error| format!("resolve '{}': {}", cursor.display(), error))?;
                for component in missing.iter().rev() {
                    resolved.push(component);
                }
                return Ok(resolved);
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                let name = cursor.file_name().ok_or_else(|| {
                    format!("cannot resolve prospective path '{}'", path.display())
                })?;
                missing.push(name.to_os_string());
                cursor = cursor
                    .parent()
                    .ok_or_else(|| format!("'{}' has no existing ancestor", path.display()))?
                    .to_path_buf();
            }
            Err(error) => {
                return Err(format!("inspect '{}': {}", cursor.display(), error));
            }
        }
    }
}

pub(super) fn get_project_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
) -> Result<Option<ProjectDetail>, String> {
    let snapshot = repository.load_project_state_snapshot()?;
    let config = snapshot.config;
    let Some(project) = config.project(local_project_id).cloned() else {
        return Ok(None);
    };
    let links = config
        .links
        .into_iter()
        .filter(|link| &link.local_project_id == local_project_id)
        .collect();
    let binding = snapshot.bindings.for_project(local_project_id).cloned();
    let materializations = snapshot
        .materializations
        .records
        .into_iter()
        .filter(|record| &record.local_project_id == local_project_id)
        .collect();
    Ok(Some(ProjectDetail {
        project,
        links,
        binding,
        materializations,
    }))
}

/// Keep the shared repository name for the first local project and add the
/// first available numeric suffix only when that visible name is already in
/// use on this machine.
fn deduplicated_local_alias(
    display_name: &str,
    existing: &[LocalProjectRegistration],
) -> Result<Option<String>, String> {
    let display_name = display_name.trim();
    let taken: BTreeSet<&str> = existing
        .iter()
        .map(|project| {
            project
                .local_alias
                .as_deref()
                .unwrap_or(&project.display_name)
                .trim()
        })
        .collect();

    if !taken.contains(display_name) {
        return Ok(None);
    }

    let mut counter = 2u64;
    loop {
        let candidate = format!("{display_name} ({counter})");
        if candidate.len() > 1_024 {
            return Err(
                "project name is too long to make unique; shorten it before finishing setup"
                    .to_string(),
            );
        }
        if !taken.contains(candidate.as_str()) {
            return Ok(Some(candidate));
        }
        counter = counter
            .checked_add(1)
            .ok_or_else(|| "too many local projects share this name".to_string())?;
    }
}

fn cloud_link_id(storage: &StorageConfig, bundle: &BundleId) -> Result<Option<String>, String> {
    let store = ConfiguredObjectStore::shared(storage)?;
    store
        .managed_cloud()
        .map(|cloud| cloud.resolve_repository(bundle))
        .transpose()
}

/// The Mallard Cloud repository a Push or a Pull read and wrote: the link's
/// pin, or what stands in for a pin that answered gone. `None` on any other
/// storage. It costs no request: the operation has already resolved it.
fn cloud_repository_in_use(
    engine: &StorageEngine,
    bundle: &BundleId,
) -> Result<Option<String>, String> {
    match engine.store().managed_cloud() {
        Some(cloud) => cloud.repository_in_use(bundle),
        None => Ok(None),
    }
}

/// Save the repository an operation used as the pin of every link of that
/// storage and bundle, in the transaction that saves the operation's bases.
/// A Push onto a repository that was gone created another, and a Pull read
/// the one another computer created: from here on the link names it. Only a
/// Push and a Pull do this; a refresh saves nothing.
fn save_cloud_pin(
    config: &mut SyncConfig,
    storage_id: &StorageId,
    bundle: &BundleId,
    repository: Option<&String>,
) {
    let Some(repository) = repository else {
        return;
    };
    for link in config
        .links
        .iter_mut()
        .filter(|link| link.storage_id == *storage_id && link.bundle_id == *bundle)
    {
        link.managed_cloud_repository_id = Some(repository.clone());
    }
}

fn cloud_status_for(
    config: &SyncConfig,
    project_id: &LocalProjectId,
    storage_id: &StorageId,
) -> Option<mallard_infrastructure::managed_cloud::client::ManagedCloudStatus> {
    let link = config
        .links
        .iter()
        .find(|link| &link.local_project_id == project_id && &link.storage_id == storage_id)?;
    link.managed_cloud_repository_id.as_ref()?;
    let storage = config
        .storages
        .iter()
        .find(|storage| &storage.id == storage_id)?;
    let store = ConfiguredObjectStore::shared(storage).ok()?;
    store.managed_cloud()?.status(&link.bundle_id)
}

pub(super) fn save_project_link_with_repository(
    repository: &LocalStateRepository,
    request: SaveProjectLinkRequest,
) -> Result<ProjectStorageLink, String> {
    // Registration claim before the config mutation (D1): creating a link
    // makes the bundle discoverable in the storage immediately, and a
    // storage that cannot be written fails the link here instead of at the
    // first push. Re-saving an existing link changes only user intent and
    // publishes nothing; a project with no active binding has no replica to
    // stamp the claim with and stays discoverable through sibling detection.
    let managed_cloud_repository_id = {
        let config = repository.load_config()?;
        let project = config
            .project(&request.local_project_id)
            .cloned()
            .ok_or_else(|| format!("unknown local project '{}'", request.local_project_id))?;
        let storage = config
            .storages
            .iter()
            .find(|storage| storage.id == request.storage_id)
            .cloned()
            .ok_or_else(|| format!("unknown storage '{}'", request.storage_id))?;
        let link_exists = config.links.iter().any(|existing| {
            existing.local_project_id == request.local_project_id
                && existing.storage_id == request.storage_id
        });
        if !link_exists {
            if let Some(binding) = repository
                .load_bindings()?
                .active_for(&request.local_project_id)
            {
                publish_registration_claim(repository, &storage, &project, &binding)?;
                cloud_link_id(&storage, &project.bundle_id)?
            } else {
                None
            }
        } else {
            config
                .links
                .iter()
                .find(|link| {
                    link.local_project_id == request.local_project_id
                        && link.storage_id == request.storage_id
                })
                .and_then(|link| link.managed_cloud_repository_id.clone())
        }
    };
    repository.mutate_config(|config| {
        let bundle_id = config
            .project(&request.local_project_id)
            .ok_or_else(|| format!("unknown local project '{}'", request.local_project_id))?
            .bundle_id
            .clone();
        if !config
            .storages
            .iter()
            .any(|storage| storage.id == request.storage_id)
        {
            return Err(format!("unknown storage '{}'", request.storage_id));
        }
        if let Some(existing) = config.links.iter_mut().find(|existing| {
            existing.local_project_id == request.local_project_id
                && existing.storage_id == request.storage_id
        }) {
            // The request edits only user intent. Destination-specific review
            // state belongs to the existing link and is dropped only by unlink.
            existing.pinned = request.pinned;
            return Ok(existing.clone());
        }
        let link = ProjectStorageLink {
            managed_cloud_repository_id: managed_cloud_repository_id.clone(),
            local_project_id: request.local_project_id.clone(),
            storage_id: request.storage_id.clone(),
            bundle_id,
            recipe: None,
            scope_bases: BTreeMap::new(),
            project_content_preferences: Default::default(),
            conversation_checkpoints: BTreeMap::new(),
            pinned: request.pinned,
            created_at: now_secs(),
        };
        config.links.push(link.clone());
        Ok(link)
    })
}

pub(super) fn connect_project_to_remote_bundle_with_repository(
    repository: &LocalStateRepository,
    request: ConnectProjectBundleRequest,
) -> Result<ProjectDetail, String> {
    let _host_operation = repository.acquire_host_operation()?;
    connect_project_to_remote_bundle_guarded(repository, request)
}

fn connect_project_to_remote_bundle_guarded(
    repository: &LocalStateRepository,
    request: ConnectProjectBundleRequest,
) -> Result<ProjectDetail, String> {
    let config = repository.load_config()?;
    let project = config
        .project(&request.local_project_id)
        .cloned()
        .ok_or_else(|| format!("unknown local project '{}'", request.local_project_id))?;
    if project.bundle_id != request.expected_bundle_id {
        return Err(format!(
            "project bundle changed (expected '{}', current '{}')",
            request.expected_bundle_id, project.bundle_id
        ));
    }
    if !config
        .storages
        .iter()
        .any(|storage| storage.id == request.storage_id)
    {
        return Err(format!("unknown storage '{}'", request.storage_id));
    }
    if project.bundle_id == request.bundle_id {
        save_project_link_with_repository(
            repository,
            SaveProjectLinkRequest {
                local_project_id: request.local_project_id.clone(),
                storage_id: request.storage_id,
                pinned: request.pinned,
            },
        )?;
        return get_project_with_repository(repository, &request.local_project_id)?
            .ok_or_else(|| "project disappeared while linking storage".to_string());
    }

    let other_links = config
        .links
        .iter()
        .filter(|link| {
            link.local_project_id == request.local_project_id
                && link.storage_id != request.storage_id
        })
        .count();
    if other_links > 0 {
        return Err(
            "cannot change bundle identity while the project is linked to another storage; unlink the other storage first"
                .to_string(),
        );
    }
    if repository
        .load_materializations()?
        .records
        .iter()
        .any(|record| record.local_project_id == request.local_project_id)
    {
        return Err(
            "cannot change bundle identity after project resources were materialized".to_string(),
        );
    }
    let (_, engine) = storage_engine(repository, &request.storage_id)?;
    let remote = engine.inspect(&request.bundle_id)?;
    let remote_fingerprint = remote.manifest.bundle.repository_fingerprint.clone();
    if let (Some(local), Some(remote)) = (
        project.repository_fingerprint.as_deref(),
        remote_fingerprint.as_deref(),
    ) {
        if local != remote && !request.allow_repository_mismatch {
            return Err("remote bundle belongs to a different repository".to_string());
        }
    } else if project.repository_fingerprint.is_some() && !request.allow_repository_mismatch {
        return Err("remote bundle does not declare a repository fingerprint".to_string());
    }
    // A pure registration claim (empty revision-1 manifest) may be
    // abandoned: nothing was ever published under it, so connecting away
    // loses nothing — that is how a split-brain twin converges. Any content
    // keeps the refusal; genuine divergence is resolved by pull/Keep Both,
    // never by connect.
    if let Some(snapshot) = engine.inspect_optional(&project.bundle_id)? {
        if !snapshot.manifest.is_registration_only() {
            return Err(
                "the current bundle already exists in this storage; refusing to abandon published history"
                    .to_string(),
            );
        }
    }

    let machine = repository.load_bindings()?;
    let active_binding = machine.active_for(&request.local_project_id).cloned();
    if let Some(binding) = &active_binding {
        validate_binding_request(
            repository,
            &SaveProjectBindingRequest {
                local_project_id: request.local_project_id.clone(),
                project_root: binding.project_root.clone(),
                profile_ids: binding.profile_ids.clone(),
                expected_revision: None,
            },
        )?;
    }
    let remote_recipe = machine_local_recipe_from_manifest(&remote.manifest)?;
    let new_bundle_id = request.bundle_id.clone();
    let storage = config
        .storages
        .iter()
        .find(|storage| storage.id == request.storage_id)
        .ok_or("Storage is unavailable")?;
    let managed_cloud_repository_id = cloud_link_id(storage, &new_bundle_id)?;
    repository.mutate_project_bundle(&request.local_project_id, config.revision, |config| {
        let project = config
            .projects
            .iter_mut()
            .find(|project| project.local_project_id == request.local_project_id)
            .ok_or_else(|| "project was removed while connecting the remote bundle".to_string())?;
        if project.bundle_id != request.expected_bundle_id {
            return Err("project bundle changed while connecting remote storage".to_string());
        }
        project.bundle_id = new_bundle_id.clone();
        project.recipe = remote_recipe.clone();
        if project.repository_fingerprint.is_none()
            || (request.allow_repository_mismatch && remote_fingerprint.is_some())
        {
            project.repository_fingerprint = remote_fingerprint.clone();
        }
        project.revision = project.revision.saturating_add(1);
        project.updated_at = now_secs();
        for link in config
            .links
            .iter_mut()
            .filter(|link| link.local_project_id == request.local_project_id)
        {
            link.bundle_id = new_bundle_id.clone();
            link.managed_cloud_repository_id = managed_cloud_repository_id.clone();
            link.recipe = None;
            link.pinned = request.pinned;
        }
        if !config.links.iter().any(|link| {
            link.local_project_id == request.local_project_id
                && link.storage_id == request.storage_id
        }) {
            config.links.push(ProjectStorageLink {
                managed_cloud_repository_id: managed_cloud_repository_id.clone(),
                local_project_id: request.local_project_id.clone(),
                storage_id: request.storage_id.clone(),
                bundle_id: new_bundle_id.clone(),
                recipe: None,
                scope_bases: BTreeMap::new(),
                project_content_preferences: Default::default(),
                conversation_checkpoints: BTreeMap::new(),
                pinned: request.pinned,
                created_at: now_secs(),
            });
        }
        Ok(())
    })?;
    get_project_with_repository(repository, &request.local_project_id)?
        .ok_or_else(|| "project disappeared after connecting remote storage".to_string())
}

pub(super) fn save_project_binding_with_repository(
    repository: &LocalStateRepository,
    request: SaveProjectBindingRequest,
) -> Result<ProjectBinding, String> {
    let _host_operation = repository.acquire_host_operation()?;
    save_project_binding_guarded(repository, request)
}

fn save_project_binding_guarded(
    repository: &LocalStateRepository,
    request: SaveProjectBindingRequest,
) -> Result<ProjectBinding, String> {
    let validated = validate_binding_request(repository, &request)?;
    let host_id = repository.load_or_create_host_identity()?.host_id;
    let binding = repository.mutate_bindings(|config, bindings| {
        let project = config
            .project(&request.local_project_id)
            .ok_or_else(|| format!("unknown local project '{}'", request.local_project_id))?;
        let position = bindings
            .bindings
            .iter()
            .position(|binding| binding.local_project_id == request.local_project_id);
        let (replica_id, revision) = match position {
            Some(index) => {
                let current = &bindings.bindings[index];
                let expected = request.expected_revision.ok_or_else(|| {
                    "expected_revision is required when changing a binding".to_string()
                })?;
                if expected != current.revision {
                    return Err(format!(
                        "project binding changed (expected version {}, current {})",
                        expected, current.revision
                    ));
                }
                // Profile paths are immutable in the catalog, so pinning the
                // profile IDs pins each agent home while still allowing a
                // checkout path remap.
                if current.state == BindingState::Active
                    && current.profile_ids != request.profile_ids
                {
                    return Err(AGENT_HOME_LOCKED_MESSAGE.to_string());
                }
                (
                    current.replica_id.clone(),
                    current.revision.saturating_add(1),
                )
            }
            None => {
                if request.expected_revision.is_some() {
                    return Err("new binding must not provide expected_revision".to_string());
                }
                (ReplicaId::parse(generated_named_id("replica")?)?, 0)
            }
        };
        let next = ProjectBinding {
            host_id: host_id.clone(),
            replica_id,
            local_project_id: request.local_project_id.clone(),
            bundle_id: project.bundle_id.clone(),
            project_root: request.project_root.clone(),
            canonical_project_root: validated.clone(),
            profile_ids: request.profile_ids.clone(),
            state: BindingState::Active,
            revision,
            updated_at: now_secs(),
        };
        next.validate_structure()?;
        match position {
            Some(index) => bindings.bindings[index] = next.clone(),
            None => bindings.bindings.push(next.clone()),
        }
        Ok(next)
    })?;

    // A remap never erases history, but materializations produced for an
    // older binding revision are detached and cannot satisfy a new plan.
    repository.mutate_materializations(|_, materializations| {
        for record in &mut materializations.records {
            if record.host_id == binding.host_id
                && record.replica_id == binding.replica_id
                && record.binding_revision != binding.revision
                && record.status != MaterializationStatus::Detached
            {
                record.status = MaterializationStatus::Detached;
            }
        }
        Ok(())
    })?;
    Ok(binding)
}

/// First active binding (excluding `exclude`) that already claims one of the
/// requested provider profiles for this checkout. Project identity is
/// (canonical root, provider profile): the same folder with a different
/// config is a separate project, only a shared profile is a collision.
fn root_profile_collision<'a>(
    machine: &'a MachineProjectState,
    exclude: Option<&LocalProjectId>,
    canonical_root: &str,
    profile_ids: &BTreeMap<ProviderKey, LocalProviderProfileId>,
) -> Option<(&'a ProjectBinding, ProviderKey)> {
    let folded = canonical_root.to_lowercase();
    machine
        .bindings
        .iter()
        .filter(|binding| binding.state == BindingState::Active)
        .filter(|binding| exclude != Some(&binding.local_project_id))
        .filter(|binding| binding.canonical_project_root.to_lowercase() == folded)
        .find_map(|binding| {
            profile_ids.iter().find_map(|(provider, profile_id)| {
                binding
                    .profile_ids
                    .values()
                    .any(|used| used == profile_id)
                    .then_some((binding, provider.clone()))
            })
        })
}

/// Select the one current project identity that setup is replacing.
///
/// Removing a project deliberately detaches its machine-local replica instead
/// of erasing conversation identity.  Re-registering that exact
/// (checkout, bundle, provider profiles) tuple must therefore reactivate the
/// detached replica; minting a second replica would make the retained provider
/// thread bindings look like a second owner.
fn detached_binding_for_reregistration(
    machine: &MachineProjectState,
    config: &SyncConfig,
    host_id: &HostId,
    bundle_id: &BundleId,
    canonical_root: &str,
    profile_ids: &BTreeMap<ProviderKey, LocalProviderProfileId>,
) -> Result<Option<ProjectBinding>, String> {
    let matches = machine
        .bindings
        .iter()
        .filter(|binding| binding.state == BindingState::Detached)
        .filter(|binding| &binding.host_id == host_id)
        .filter(|binding| &binding.bundle_id == bundle_id)
        .filter(|binding| {
            binding
                .canonical_project_root
                .eq_ignore_ascii_case(canonical_root)
        })
        .filter(|binding| &binding.profile_ids == profile_ids)
        .filter(|binding| config.project(&binding.local_project_id).is_none())
        .cloned()
        .collect::<Vec<_>>();
    match matches.as_slice() {
        [] => Ok(None),
        [binding] => Ok(Some(binding.clone())),
        _ => Err(
            "multiple detached registrations match this project; repair local project state before finishing setup"
                .to_string(),
        ),
    }
}

/// Visible label for collision messages: the machine-local alias when one
/// exists, else the shared display name, else the raw id.
fn project_label(config: &SyncConfig, id: &LocalProjectId) -> String {
    config
        .project(id)
        .map(|project| {
            project
                .local_alias
                .clone()
                .unwrap_or_else(|| project.display_name.clone())
        })
        .unwrap_or_else(|| id.to_string())
}

/// Validate a binding request and return the canonical project root.
fn validate_binding_request(
    repository: &LocalStateRepository,
    request: &SaveProjectBindingRequest,
) -> Result<String, String> {
    validate_absolute_clean_path("project root", &request.project_root)?;
    let profile_paths = resolve_profile_paths(repository, &request.profile_ids)?;
    let metadata = fs_metadata_no_final_symlink(Path::new(&request.project_root))?;
    if !metadata.is_dir() {
        return Err(format!(
            "project root '{}' is not a directory",
            request.project_root
        ));
    }
    let canonical = fs_canonicalize(Path::new(&request.project_root))?;
    let repository_root = prospective_canonical(repository.root())?;
    if paths_overlap(&canonical, &repository_root) {
        return Err(format!(
            "project root '{}' overlaps Mallard app data '{}'",
            canonical.display(),
            repository_root.display()
        ));
    }
    let config = repository.load_config()?;
    let local_stores = configured_local_storage_roots(&config)?
        .into_iter()
        .map(|(storage, root)| {
            prospective_canonical(&root).map(|path| (storage.name.as_str(), path))
        })
        .collect::<Result<Vec<_>, _>>()?;
    for (storage_name, storage_path) in &local_stores {
        if paths_overlap(&canonical, storage_path) {
            return Err(format!(
                "project root '{}' overlaps local storage '{}'",
                canonical.display(),
                storage_name
            ));
        }
    }
    let mut provider_roots: Vec<PathBuf> = Vec::new();
    for (provider, path) in &profile_paths {
        let label = format!("{} profile", provider_name(provider));
        let path = prospective_canonical(Path::new(path))?;
        if paths_overlap(&path, &repository_root) {
            return Err(format!(
                "{} '{}' overlaps Mallard app data",
                label,
                path.display()
            ));
        }
        if paths_overlap(&path, &canonical) {
            return Err(format!(
                "{} '{}' overlaps the project root",
                label,
                path.display()
            ));
        }
        for (storage_name, storage_path) in &local_stores {
            if paths_overlap(&path, storage_path) {
                return Err(format!(
                    "{} '{}' overlaps local storage '{}'",
                    label,
                    path.display(),
                    storage_name
                ));
            }
        }
        if provider_roots
            .iter()
            .any(|other| paths_overlap(&path, other))
        {
            return Err("selected provider homes must not overlap".to_string());
        }
        provider_roots.push(path);
    }
    let machine = repository.load_bindings()?;
    if let Some((other, provider)) = root_profile_collision(
        &machine,
        Some(&request.local_project_id),
        &canonical.to_string_lossy(),
        &request.profile_ids,
    ) {
        return Err(format!(
            "'{}' already uses this {} config for this folder; pick a different config",
            project_label(&config, &other.local_project_id),
            provider_name(&provider)
        ));
    }
    Ok(canonical.to_string_lossy().into_owned())
}

fn detach_project_binding_guarded(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
) -> Result<bool, String> {
    let detached_scope = repository.mutate_bindings(|_, bindings| {
        let Some(binding) = bindings.bindings.iter_mut().find(|binding| {
            &binding.local_project_id == local_project_id && binding.state == BindingState::Active
        }) else {
            return Ok(None);
        };
        binding.state = BindingState::Detached;
        binding.revision = binding.revision.saturating_add(1);
        binding.updated_at = now_secs();
        Ok(Some((binding.host_id.clone(), binding.replica_id.clone())))
    })?;
    let Some((host_id, replica_id)) = detached_scope else {
        return Ok(false);
    };
    repository.mutate_materializations(|_, materializations| {
        for record in &mut materializations.records {
            if record.host_id == host_id && record.replica_id == replica_id {
                record.status = MaterializationStatus::Detached;
            }
        }
        Ok(())
    })?;
    Ok(true)
}

/// Sets or clears the machine-local alias.  The synced `display_name` stays
/// untouched so a rename here never propagates to the remote bundle or other
/// replicas.
pub(super) fn rename_local_project_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
    local_alias: Option<String>,
    expected_revision: u64,
) -> Result<LocalProjectRegistration, String> {
    let alias = local_alias
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    repository.mutate_config(|config| {
        let project = config
            .projects
            .iter_mut()
            .find(|project| &project.local_project_id == local_project_id)
            .ok_or_else(|| format!("unknown local project '{}'", local_project_id))?;
        if project.revision != expected_revision {
            return Err(format!(
                "project changed (expected version {}, current {})",
                expected_revision, project.revision
            ));
        }
        project.local_alias = alias;
        project.revision = project.revision.saturating_add(1);
        project.updated_at = now_secs();
        project.validate()?;
        Ok(project.clone())
    })
}

pub(super) fn remove_local_project_with_repository(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
) -> Result<bool, String> {
    let _host_operation = repository.acquire_host_operation()?;
    remove_local_project_guarded(repository, local_project_id)
}

fn remove_local_project_guarded(
    repository: &LocalStateRepository,
    local_project_id: &LocalProjectId,
) -> Result<bool, String> {
    if repository
        .load_config()?
        .project(local_project_id)
        .is_none()
    {
        return Ok(false);
    }
    // Detach local application state before removing the registration.  A
    // crash between files leaves a valid unbound project, never an active
    // binding to an unknown project.
    let _ = detach_project_binding_guarded(repository, local_project_id)?;
    repository.mutate_materializations(|_, materializations| {
        for record in &mut materializations.records {
            if &record.local_project_id == local_project_id {
                record.status = MaterializationStatus::Detached;
            }
        }
        Ok(())
    })?;
    repository.mutate_config(|config| {
        config
            .projects
            .retain(|project| &project.local_project_id != local_project_id);
        config
            .links
            .retain(|link| &link.local_project_id != local_project_id);
        Ok(true)
    })
}

// ---------------------------------------------------------------------------
// Project setup drafts and transactional finalization
// ---------------------------------------------------------------------------

#[derive(Serialize, Clone, Debug)]
pub struct SetupDraftSummary {
    pub draft_id: SetupDraftId,
    pub display_name: String,
    pub project_root: String,
    pub updated_at: u64,
    pub revision: u64,
    /// `draft` when every referenced record still exists; `attention` when a
    /// referenced profile or storage disappeared since the draft was saved.
    pub status: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub last_error: Option<String>,
}

#[derive(Serialize, Clone, Debug)]
pub struct SetupDraftList {
    pub drafts: Vec<SetupDraftSummary>,
    #[serde(default)]
    pub warnings: Vec<String>,
}

#[derive(Serialize, Clone, Debug)]
pub struct CreateSetupDraftResult {
    pub draft: ProjectSetupDraft,
    /// True when an existing draft for the same canonical folder was resumed
    /// instead of creating a duplicate.
    pub resumed: bool,
}

/// What setup would make of one folder, answered without writing anything:
/// the verdict the Folder field shows while a path is typed.
#[derive(Serialize, Clone, Debug, PartialEq, Eq)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum ProjectFolderProbe {
    /// Not an absolute path free of `.` and `..` parts.
    Invalid { message: String },
    /// Nothing exists at the path.
    Missing,
    /// Something is there but cannot be resolved, such as a folder that
    /// cannot be read.
    Unreadable { message: String },
    /// A file; `parent` is the folder that holds it.
    NotADirectory { parent: Option<String> },
    /// The folder is Mallard's own data folder or lies inside it, or, with
    /// `contains`, holds it.
    MallardData { contains: bool },
    /// A folder setup accepts.
    Folder {
        canonical_path: String,
        is_git_repository: bool,
        /// The draft already started for this folder: setting up resumes it.
        #[serde(skip_serializing_if = "Option::is_none")]
        existing_draft_id: Option<SetupDraftId>,
        /// Projects already bound to this folder. Another can still be set
        /// up here with a different agent profile.
        existing_project_ids: Vec<LocalProjectId>,
    },
}

/// One folder recent sessions ran in, and what choosing it would do.
#[derive(Serialize, Clone, Debug)]
pub struct AgentFolder {
    /// The folder as the sessions recorded it.
    pub path: String,
    pub providers: Vec<ProviderKey>,
    /// Unix seconds of the newest session file that named the folder.
    pub last_active: u64,
    /// The Folder field's verdict, except that Git is read from a `.git`
    /// entry on the folder or above it instead of by running Git per row.
    pub probe: ProjectFolderProbe,
}

#[derive(Serialize, Clone, Debug)]
pub struct AgentFolderList {
    pub folders: Vec<AgentFolder>,
}

/// The most folders the list offers, newest first.
const MAX_AGENT_FOLDERS: usize = 50;

/// A folder setup refuses: the field's verdict, and the sentence
/// `create_setup_draft` returns for it.
struct ProjectFolderRefusal {
    probe: ProjectFolderProbe,
    message: String,
}

/// The checks every way into setup makes before a folder is used, in the
/// order `create_setup_draft` has always made them.
fn resolve_project_folder(
    repository: &LocalStateRepository,
    project_root: &str,
) -> Result<PathBuf, ProjectFolderRefusal> {
    if let Err(message) = validate_absolute_clean_path("project root", project_root) {
        return Err(ProjectFolderRefusal {
            probe: ProjectFolderProbe::Invalid {
                message: message.clone(),
            },
            message,
        });
    }
    let canonical = match fs::canonicalize(project_root) {
        Ok(canonical) => canonical,
        Err(error) => {
            let probe = if matches!(
                error.kind(),
                std::io::ErrorKind::NotFound | std::io::ErrorKind::NotADirectory
            ) {
                ProjectFolderProbe::Missing
            } else {
                ProjectFolderProbe::Unreadable {
                    message: error.to_string(),
                }
            };
            return Err(ProjectFolderRefusal {
                probe,
                message: format!("resolve '{}': {}", project_root, error),
            });
        }
    };
    if !canonical.is_dir() {
        return Err(ProjectFolderRefusal {
            probe: ProjectFolderProbe::NotADirectory {
                parent: canonical
                    .parent()
                    .map(|parent| parent.to_string_lossy().into_owned()),
            },
            message: format!("project root '{}' is not a directory", project_root),
        });
    }
    let repository_root =
        prospective_canonical(repository.root()).map_err(|message| ProjectFolderRefusal {
            probe: ProjectFolderProbe::Unreadable {
                message: message.clone(),
            },
            message,
        })?;
    if paths_overlap(&canonical, &repository_root) {
        return Err(ProjectFolderRefusal {
            probe: ProjectFolderProbe::MallardData {
                contains: canonical != repository_root && repository_root.starts_with(&canonical),
            },
            message: "project root overlaps Mallard application data".to_string(),
        });
    }
    Ok(canonical)
}

/// What each folder already is on this machine, loaded once: the draft
/// started there and the projects bound to it.
struct ProjectFolderIndex {
    drafts: Vec<(String, SetupDraftId)>,
    bindings: Vec<(String, LocalProjectId)>,
}

impl ProjectFolderIndex {
    fn load(
        repository: &LocalStateRepository,
        machine: &MachineProjectState,
    ) -> Result<Self, String> {
        let (drafts, _) = repository.list_setup_drafts()?;
        Ok(Self {
            drafts: drafts
                .into_iter()
                .map(|draft| (draft.canonical_project_root, draft.draft_id))
                .collect(),
            bindings: machine
                .bindings
                .iter()
                .filter(|binding| binding.state == BindingState::Active)
                .map(|binding| {
                    (
                        binding.canonical_project_root.to_lowercase(),
                        binding.local_project_id.clone(),
                    )
                })
                .collect(),
        })
    }

    /// Drafts match the canonical folder exactly, as `create_setup_draft`
    /// resumes them; bindings match it case-insensitively, as setup reserves
    /// their profiles.
    fn folder(&self, canonical: &Path, is_git_repository: bool) -> ProjectFolderProbe {
        let canonical_path = canonical.to_string_lossy().into_owned();
        let folded = canonical_path.to_lowercase();
        let existing_project_ids: BTreeSet<LocalProjectId> = self
            .bindings
            .iter()
            .filter(|(root, _)| *root == folded)
            .map(|(_, project_id)| project_id.clone())
            .collect();
        ProjectFolderProbe::Folder {
            existing_draft_id: self
                .drafts
                .iter()
                .find(|(root, _)| *root == canonical_path)
                .map(|(_, draft_id)| draft_id.clone()),
            existing_project_ids: existing_project_ids.into_iter().collect(),
            canonical_path,
            is_git_repository,
        }
    }
}

pub(super) fn probe_project_folder_with_repository(
    repository: &LocalStateRepository,
    project_root: &str,
) -> Result<ProjectFolderProbe, String> {
    let canonical = match resolve_project_folder(repository, project_root) {
        Ok(canonical) => canonical,
        Err(refusal) => return Ok(refusal.probe),
    };
    let machine = repository.load_bindings()?;
    let index = ProjectFolderIndex::load(repository, &machine)?;
    Ok(index.folder(&canonical, project_activity::is_git_work_tree(&canonical)))
}

/// The same verdict without running Git: Git is read from a `.git` entry on
/// the folder or above, as the recent-folder list reads it. For a probe that
/// runs per keystroke where Git may not be installed — on macOS, running the
/// `/usr/bin/git` stub offers to install the developer tools.
pub(super) fn probe_project_folder_without_git(
    repository: &LocalStateRepository,
    project_root: &str,
) -> Result<ProjectFolderProbe, String> {
    let canonical = match resolve_project_folder(repository, project_root) {
        Ok(canonical) => canonical,
        Err(refusal) => return Ok(refusal.probe),
    };
    let machine = repository.load_bindings()?;
    let index = ProjectFolderIndex::load(repository, &machine)?;
    Ok(index.folder(&canonical, has_git_entry(&canonical)))
}

/// The folders the newest sessions of every registered profile ran in, each
/// with the verdict choosing it would get. Each provider bounds its own read
/// (`SessionAdapter::recent_session_homes`); a profile that cannot be read
/// adds nothing.
pub(super) fn list_agent_folders_with_repository(
    repository: &LocalStateRepository,
) -> Result<AgentFolderList, String> {
    let machine = repository.load_bindings()?;
    let mut sightings: BTreeMap<PathBuf, (BTreeSet<ProviderKey>, u64)> = BTreeMap::new();
    for profile in &machine.profiles {
        let Some(adapter) = provider_registry().get(&profile.provider) else {
            continue;
        };
        let Ok(homes) = adapter.recent_session_homes(Path::new(&profile.path)) else {
            continue;
        };
        for sighting in homes {
            let (providers, last_active) = sightings.entry(sighting.home).or_default();
            providers.insert(profile.provider.clone());
            *last_active = (*last_active).max(sighting.last_active);
        }
    }
    let index = ProjectFolderIndex::load(repository, &machine)?;
    // Two recorded spellings of one folder (a link and its target) are one
    // row, keyed by where they resolve.
    let mut folders: BTreeMap<String, AgentFolder> = BTreeMap::new();
    for (home, (providers, last_active)) in sightings {
        let recorded = home.to_string_lossy().into_owned();
        let probe = match resolve_project_folder(repository, &recorded) {
            Ok(canonical) => index.folder(&canonical, has_git_entry(&canonical)),
            Err(refusal) => refusal.probe,
        };
        let key = match &probe {
            ProjectFolderProbe::Folder { canonical_path, .. } => canonical_path.clone(),
            _ => recorded.clone(),
        };
        let folder = folders.entry(key).or_insert_with(|| AgentFolder {
            path: recorded,
            providers: Vec::new(),
            last_active: 0,
            probe,
        });
        for provider in providers {
            if !folder.providers.contains(&provider) {
                folder.providers.push(provider);
            }
        }
        folder.providers.sort();
        folder.last_active = folder.last_active.max(last_active);
    }
    let mut folders: Vec<AgentFolder> = folders.into_values().collect();
    folders.sort_by(|left, right| {
        right
            .last_active
            .cmp(&left.last_active)
            .then_with(|| left.path.cmp(&right.path))
    });
    folders.truncate(MAX_AGENT_FOLDERS);
    Ok(AgentFolderList { folders })
}

/// Whether a `.git` entry sits on the folder or above it: the list's cheap
/// stand-in for `git rev-parse`, which the typed probe still runs.
fn has_git_entry(folder: &Path) -> bool {
    folder
        .ancestors()
        .any(|ancestor| fs::symlink_metadata(ancestor.join(".git")).is_ok())
}

#[derive(Serialize, Clone, Debug)]
pub struct SetupSectionStatus {
    pub section: String,
    pub state: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message: Option<String>,
}

#[derive(Serialize, Clone, Debug)]
pub struct SetupDraftInspection {
    pub draft: ProjectSetupDraft,
    pub sections: Vec<SetupSectionStatus>,
    pub can_finalize: bool,
}

pub(super) fn list_setup_drafts_with_repository(
    repository: &LocalStateRepository,
) -> Result<SetupDraftList, String> {
    let (drafts, warnings) = repository.list_setup_drafts()?;
    let config = repository.load_config()?;
    let machine = repository.load_bindings()?;
    let summaries = drafts
        .into_iter()
        .map(|draft| {
            let status = if draft_references_are_present(&draft, &config, &machine) {
                "draft"
            } else {
                "attention"
            };
            SetupDraftSummary {
                status: status.to_string(),
                draft_id: draft.draft_id,
                display_name: draft.display_name,
                project_root: draft.project_root,
                updated_at: draft.updated_at,
                revision: draft.revision,
                last_error: draft.last_error,
            }
        })
        .collect();
    Ok(SetupDraftList {
        drafts: summaries,
        warnings,
    })
}

fn draft_references_are_present(
    draft: &ProjectSetupDraft,
    config: &SyncConfig,
    machine: &MachineProjectState,
) -> bool {
    let profiles_present = draft.profiles.values().all(|selection| match selection {
        DraftProfileSelection::Existing { profile_id } => machine
            .profiles
            .iter()
            .any(|profile| &profile.profile_id == profile_id),
        DraftProfileSelection::Pending { .. } => true,
    });
    let storage_present = match &draft.storage {
        Some(DraftStorageSelection { storage_id }) => config
            .storages
            .iter()
            .any(|storage| &storage.id == storage_id),
        _ => true,
    };
    profiles_present && storage_present
}

fn suggested_project_name(project_root: &Path) -> String {
    project_activity::discover_github_repository_url(project_root)
        .and_then(|url| url.rsplit('/').next().map(str::to_owned))
        .unwrap_or_else(|| {
            project_root
                .file_name()
                .and_then(|name| name.to_str())
                .filter(|name| !name.trim().is_empty())
                .unwrap_or("Project")
                .to_string()
        })
}

pub(super) fn create_setup_draft_with_repository(
    repository: &LocalStateRepository,
    project_root: &str,
) -> Result<CreateSetupDraftResult, String> {
    let canonical =
        resolve_project_folder(repository, project_root).map_err(|refusal| refusal.message)?;
    let canonical_text = canonical.to_string_lossy().into_owned();
    let (existing, _) = repository.list_setup_drafts()?;
    if let Some(found) = existing
        .into_iter()
        .find(|draft| draft.canonical_project_root == canonical_text)
    {
        return Ok(CreateSetupDraftResult {
            draft: found,
            resumed: true,
        });
    }

    ensure_default_provider_profiles(repository)?;
    let machine = repository.load_bindings()?;
    let config = repository.load_config()?;
    // Profiles already claimed by an active project on this exact folder are
    // taken: the composite project key (root, profile) reserves them, so a
    // second setup here must use a different config.
    let claimed_profiles: BTreeSet<&LocalProviderProfileId> = machine
        .bindings
        .iter()
        .filter(|binding| binding.state == BindingState::Active)
        .filter(|binding| {
            binding.canonical_project_root.to_lowercase() == canonical_text.to_lowercase()
        })
        .flat_map(|binding| binding.profile_ids.values())
        .collect();
    // Preselect every provider the registry marks a setup default, each from
    // its own single unambiguous unclaimed profile. Registration-driven: a
    // provider with no profile on this machine, or with more than one to
    // choose between, stays unselected rather than guessing, and any
    // preselection can be turned off before finishing.
    let mut profiles = BTreeMap::new();
    for descriptor in provider_registry().descriptors() {
        if !descriptor.setup_default {
            continue;
        }
        let mut candidates = machine
            .profiles
            .iter()
            .filter(|profile| profile.provider == descriptor.key)
            .filter(|profile| !claimed_profiles.contains(&profile.profile_id));
        if let (Some(only), None) = (candidates.next(), candidates.next()) {
            profiles.insert(
                descriptor.key.clone(),
                DraftProfileSelection::Existing {
                    profile_id: only.profile_id.clone(),
                },
            );
        }
    }
    // The storage a new draft starts on: the first by preference — Mallard
    // Cloud, then the other clouds, then local folders, which is the
    // registry's display rank — and by name among equals. "None yet" stays
    // one click away on the setup page; a provider this build does not
    // register is never the default.
    let descriptors = storage_provider_descriptors();
    let rank_of = |provider: &StorageProviderKey| {
        descriptors
            .iter()
            .find(|descriptor| &descriptor.key == provider)
            .map(|descriptor| descriptor.display_rank)
    };
    let storage = config
        .storages
        .iter()
        .filter_map(|storage| rank_of(&storage.provider).map(|rank| (rank, storage)))
        .min_by(|left, right| {
            left.0
                .cmp(&right.0)
                .then_with(|| left.1.name.cmp(&right.1.name))
        })
        .map(|(_, storage)| DraftStorageSelection {
            storage_id: storage.id.clone(),
        });
    let display_name = suggested_project_name(&canonical);
    let now = now_secs();
    let draft = ProjectSetupDraft {
        schema: SETUP_DRAFT_SCHEMA,
        draft_id: SetupDraftId::parse(generated_named_id("draft")?)?,
        local_project_id: LocalProjectId::parse(generated_named_id("project")?)?,
        new_bundle_id: BundleId::generate()?,
        project_root: project_root.to_string(),
        canonical_project_root: canonical_text,
        display_name,
        repository_fingerprint: repository_fingerprint(&canonical),
        profiles,
        storage,
        repository: DraftRepositoryChoice::New,
        revision: 0,
        created_at: now,
        updated_at: now,
        last_error: None,
    };
    let saved = repository.save_setup_draft(draft)?;
    Ok(CreateSetupDraftResult {
        draft: saved,
        resumed: false,
    })
}

pub(super) fn update_setup_draft_with_repository(
    repository: &LocalStateRepository,
    submitted: ProjectSetupDraft,
) -> Result<ProjectSetupDraft, String> {
    let stored = repository
        .load_setup_draft(&submitted.draft_id)?
        .ok_or_else(|| format!("setup draft '{}' does not exist", submitted.draft_id))?;
    validate_absolute_clean_path("project root", &submitted.project_root)?;
    let canonical = fs_canonicalize(Path::new(&submitted.project_root))?;
    if !canonical.is_dir() {
        return Err(format!(
            "project root '{}' is not a directory",
            submitted.project_root
        ));
    }
    // A new folder gets a new suggestion unless this edit also supplies an
    // explicit name. Subsequent edits to Name remain the user's choice.
    let display_name = if canonical.to_string_lossy() != stored.canonical_project_root
        && submitted.repository == DraftRepositoryChoice::New
        && submitted.display_name == stored.display_name
    {
        suggested_project_name(&canonical)
    } else {
        submitted.display_name
    };
    // Editable fields come from the client; identity, timestamps, and derived
    // path facts stay server-owned.
    let draft = ProjectSetupDraft {
        schema: SETUP_DRAFT_SCHEMA,
        draft_id: stored.draft_id,
        local_project_id: stored.local_project_id,
        new_bundle_id: stored.new_bundle_id,
        project_root: submitted.project_root,
        canonical_project_root: canonical.to_string_lossy().into_owned(),
        display_name,
        repository_fingerprint: repository_fingerprint(&canonical),
        profiles: submitted.profiles,
        storage: submitted.storage,
        repository: submitted.repository,
        revision: submitted.revision,
        created_at: stored.created_at,
        updated_at: now_secs(),
        last_error: stored.last_error,
    };
    repository.save_setup_draft(draft)
}

pub(super) fn discard_setup_draft_with_repository(
    repository: &LocalStateRepository,
    draft_id: &SetupDraftId,
) -> Result<bool, String> {
    if repository.load_setup_transaction(draft_id)?.is_some() {
        return Err(
            "a finalization for this draft is still recovering; retry Finish setup first"
                .to_string(),
        );
    }
    repository.delete_setup_draft(draft_id)
}

/// Resolve each draft profile selection to the concrete provider home path,
/// plus the profile record to create when the selection is still pending.
struct ResolvedDraftProfiles {
    paths: BTreeMap<ProviderKey, String>,
    profile_ids: BTreeMap<ProviderKey, LocalProviderProfileId>,
    pending_records: Vec<ProviderProfile>,
}

fn resolve_draft_profiles(
    repository: &LocalStateRepository,
    draft: &ProjectSetupDraft,
) -> Result<ResolvedDraftProfiles, String> {
    if draft.profiles.is_empty() {
        return Err("choose at least one local provider profile".to_string());
    }
    let machine = repository.load_bindings()?;
    let now = now_secs();
    let mut resolved = ResolvedDraftProfiles {
        paths: BTreeMap::new(),
        profile_ids: BTreeMap::new(),
        pending_records: Vec::new(),
    };
    for (provider, selection) in &draft.profiles {
        match selection {
            DraftProfileSelection::Existing { profile_id } => {
                let profile = machine
                    .profiles
                    .iter()
                    .find(|profile| &profile.profile_id == profile_id)
                    .ok_or_else(|| format!("unknown provider profile '{}'", profile_id))?;
                if &profile.provider != provider {
                    return Err(format!(
                        "{} cannot use {} profile '{}'",
                        provider_name(provider),
                        provider_name(&profile.provider),
                        profile.display_name
                    ));
                }
                let (available, readable, _, error) = inspect_provider_profile(profile);
                if !available || !readable {
                    return Err(error.unwrap_or_else(|| {
                        format!(
                            "{} profile '{}' is not readable",
                            provider_name(provider),
                            profile.path
                        )
                    }));
                }
                resolved
                    .paths
                    .insert(provider.clone(), profile.path.clone());
                resolved
                    .profile_ids
                    .insert(provider.clone(), profile.profile_id.clone());
            }
            DraftProfileSelection::Pending { path, display_name } => {
                let probe = probe_provider_profile_with_repository(repository, provider, path)?;
                if !probe.readable {
                    return Err(format!(
                        "{} profile '{}' is not readable",
                        provider_name(provider),
                        probe.resolved_path
                    ));
                }
                if let Some(profile_id) = probe.existing_profile_id {
                    resolved.paths.insert(provider.clone(), probe.resolved_path);
                    resolved.profile_ids.insert(provider.clone(), profile_id);
                    continue;
                }
                let profile = ProviderProfile {
                    profile_id: LocalProviderProfileId::parse(generated_named_id("profile")?)?,
                    provider: provider.clone(),
                    display_name: if display_name.trim().is_empty() {
                        probe.suggested_name
                    } else {
                        display_name.trim().to_string()
                    },
                    path: probe.resolved_path.clone(),
                    canonical_path: probe.canonical_path,
                    provider_config: mallard_domain::AgentProviderConfig::version_1(),
                    revision: 0,
                    created_at: now,
                    updated_at: now,
                };
                profile.validate_structure()?;
                resolved.paths.insert(provider.clone(), probe.resolved_path);
                resolved
                    .profile_ids
                    .insert(provider.clone(), profile.profile_id.clone());
                resolved.pending_records.push(profile);
            }
        }
    }
    Ok(resolved)
}

fn resolve_draft_storage(
    repository: &LocalStateRepository,
    draft: &ProjectSetupDraft,
) -> Result<Option<StorageConfig>, String> {
    match &draft.storage {
        None => Ok(None),
        Some(DraftStorageSelection { storage_id }) => {
            let config = repository.load_config()?;
            let storage = config
                .storages
                .iter()
                .find(|storage| &storage.id == storage_id)
                .cloned()
                .ok_or_else(|| format!("unknown storage '{}'", storage_id))?;
            Ok(Some(storage))
        }
    }
}

fn repository_fingerprints_require_acknowledgement(
    remote: Option<&str>,
    local: Option<&str>,
) -> bool {
    remote != local
}

pub(super) fn inspect_setup_draft_with_repository(
    repository: &LocalStateRepository,
    draft_id: &SetupDraftId,
) -> Result<SetupDraftInspection, String> {
    let mut draft = repository
        .load_setup_draft(draft_id)?
        .ok_or_else(|| format!("setup draft '{}' does not exist", draft_id))?;
    let local_repository_fingerprint =
        repository_fingerprint(Path::new(&draft.canonical_project_root));
    draft
        .repository_fingerprint
        .clone_from(&local_repository_fingerprint);
    let mut sections = Vec::new();
    let mut blocked = false;

    // Project folder.
    let project_state = match fs_canonicalize(Path::new(&draft.project_root)) {
        Ok(canonical) if canonical.to_string_lossy() == draft.canonical_project_root => {
            SetupSectionStatus {
                section: "project".to_string(),
                state: "ready".to_string(),
                message: None,
            }
        }
        Ok(_) => SetupSectionStatus {
            section: "project".to_string(),
            state: "blocked".to_string(),
            message: Some(
                "The folder now resolves to a different location; choose it again.".to_string(),
            ),
        },
        Err(error) => SetupSectionStatus {
            section: "project".to_string(),
            state: "blocked".to_string(),
            message: Some(format!("Project folder is unavailable: {}", error)),
        },
    };
    blocked |= project_state.state == "blocked";
    sections.push(project_state);

    // Profiles and their isolation from the project and Mallard-owned paths.
    match resolve_draft_profiles(repository, &draft) {
        Ok(resolved) => {
            match validate_setup_paths(repository, &draft.project_root, &resolved.paths) {
                Ok(_) => {
                    sections.push(SetupSectionStatus {
                        section: "profiles".to_string(),
                        state: "ready".to_string(),
                        message: None,
                    });
                }
                Err(error) => {
                    blocked = true;
                    sections.push(SetupSectionStatus {
                        section: "profiles".to_string(),
                        state: "blocked".to_string(),
                        message: Some(error),
                    });
                }
            }
        }
        Err(error) => {
            blocked = true;
            sections.push(SetupSectionStatus {
                section: "profiles".to_string(),
                state: "blocked".to_string(),
                message: Some(error),
            });
        }
    }

    // Storage.
    match resolve_draft_storage(repository, &draft) {
        Ok(Some(_)) => sections.push(SetupSectionStatus {
            section: "storage".to_string(),
            state: "ready".to_string(),
            message: None,
        }),
        Ok(None) => sections.push(SetupSectionStatus {
            section: "storage".to_string(),
            state: "attention".to_string(),
            message: Some(
                "No storage linked; the project will not sync until one is added.".to_string(),
            ),
        }),
        Err(error) => {
            blocked = true;
            sections.push(SetupSectionStatus {
                section: "storage".to_string(),
                state: "blocked".to_string(),
                message: Some(error),
            });
        }
    }

    // Repository choice.
    let repository_state = match &draft.repository {
        DraftRepositoryChoice::New => SetupSectionStatus {
            section: "repository".to_string(),
            state: "ready".to_string(),
            message: None,
        },
        DraftRepositoryChoice::Existing {
            storage_id,
            repository_fingerprint: remote_fingerprint,
            mismatch_acknowledged,
            ..
        } => {
            let selected_storage_id = draft
                .storage
                .as_ref()
                .map(|selection| selection.storage_id.clone());
            if selected_storage_id.as_ref() != Some(storage_id) {
                SetupSectionStatus {
                    section: "repository".to_string(),
                    state: "blocked".to_string(),
                    message: Some(
                        "The chosen remote repo lives in a different storage than the one selected."
                            .to_string(),
                    ),
                }
            } else if repository_fingerprints_require_acknowledgement(
                remote_fingerprint.as_deref(),
                local_repository_fingerprint.as_deref(),
            ) && !mismatch_acknowledged
            {
                SetupSectionStatus {
                    section: "repository".to_string(),
                    state: "blocked".to_string(),
                    message: Some(
                        "The remote repo is not verified to match this folder's Git remote; acknowledge this to continue."
                            .to_string(),
                    ),
                }
            } else {
                SetupSectionStatus {
                    section: "repository".to_string(),
                    state: "ready".to_string(),
                    message: Some(
                        "The remote repo is revalidated against storage during Finish setup."
                            .to_string(),
                    ),
                }
            }
        }
    };
    blocked |= repository_state.state == "blocked";
    sections.push(repository_state);

    Ok(SetupDraftInspection {
        can_finalize: !blocked,
        draft,
        sections,
    })
}

fn build_setup_transaction(
    repository: &LocalStateRepository,
    draft: &ProjectSetupDraft,
) -> Result<SetupTransaction, String> {
    let host_id = repository.load_or_create_host_identity()?.host_id;
    let canonical = fs_canonicalize(Path::new(&draft.project_root))?;
    if canonical.to_string_lossy() != draft.canonical_project_root {
        return Err(
            "the project folder moved since this draft was saved; choose it again".to_string(),
        );
    }
    let resolved_profiles = resolve_draft_profiles(repository, draft)?;
    validate_setup_paths(repository, &draft.project_root, &resolved_profiles.paths)?;
    // Pending selections resolve to existing profile ids when their path is
    // already cataloged, so an id-level collision check covers both kinds.
    // Excluding the draft's own project keeps finalize retries idempotent.
    let machine = repository.load_bindings()?;
    if let Some((other, provider)) = root_profile_collision(
        &machine,
        Some(&draft.local_project_id),
        &draft.canonical_project_root,
        &resolved_profiles.profile_ids,
    ) {
        let config = repository.load_config()?;
        return Err(format!(
            "'{}' already syncs this folder with that {} config; open it instead or pick a different config",
            project_label(&config, &other.local_project_id),
            provider_name(&provider)
        ));
    }
    let resolved_storage = resolve_draft_storage(repository, draft)?;
    let local_fingerprint = repository_fingerprint(&canonical);

    // Finalization revalidates remote repositories: the bundle must exist and
    // the user must acknowledge fingerprint mismatches.
    let (bundle_id, display_name, fingerprint, recipe) = match &draft.repository {
        DraftRepositoryChoice::New => (
            draft.new_bundle_id.clone(),
            draft.display_name.clone(),
            local_fingerprint,
            BundleRecipe::default(),
        ),
        DraftRepositoryChoice::Existing {
            storage_id,
            bundle_id,
            mismatch_acknowledged,
            ..
        } => {
            let storage = resolved_storage
                .as_ref()
                .filter(|resolved| &resolved.id == storage_id)
                .ok_or_else(|| {
                    "the chosen remote repo lives in a different storage than the one selected"
                        .to_string()
                })?;
            let engine = engine_for_storage_config(storage)?;
            let snapshot = engine.inspect(bundle_id)?;
            let machine_local_recipe = machine_local_recipe_from_manifest(&snapshot.manifest)?;
            let remote_fingerprint = snapshot.manifest.bundle.repository_fingerprint.clone();
            if repository_fingerprints_require_acknowledgement(
                remote_fingerprint.as_deref(),
                local_fingerprint.as_deref(),
            ) && !mismatch_acknowledged
            {
                return Err(
                    "the remote repo is not verified to match this folder's Git remote; acknowledge the mismatch first"
                        .to_string(),
                );
            }
            (
                bundle_id.clone(),
                snapshot.manifest.bundle.display_name.clone(),
                remote_fingerprint.or(local_fingerprint),
                machine_local_recipe,
            )
        }
    };

    let config = repository.load_config()?;
    let detached = detached_binding_for_reregistration(
        &machine,
        &config,
        &host_id,
        &bundle_id,
        &draft.canonical_project_root,
        &resolved_profiles.profile_ids,
    )?;
    let local_project_id = detached
        .as_ref()
        .map(|binding| binding.local_project_id.clone())
        .unwrap_or_else(|| draft.local_project_id.clone());
    let now = now_secs();
    let project = LocalProjectRegistration {
        local_project_id: local_project_id.clone(),
        bundle_id: bundle_id.clone(),
        display_name,
        local_alias: None,
        repository_fingerprint: fingerprint,
        recipe,
        revision: 0,
        created_at: now,
        updated_at: now,
    };
    project.validate()?;

    let links = resolved_storage
        .as_ref()
        .map(|resolved| ProjectStorageLink {
            managed_cloud_repository_id: None,
            local_project_id: local_project_id.clone(),
            storage_id: resolved.id.clone(),
            bundle_id: bundle_id.clone(),
            recipe: None,
            scope_bases: BTreeMap::new(),
            project_content_preferences: Default::default(),
            conversation_checkpoints: BTreeMap::new(),
            pinned: true,
            created_at: now,
        })
        .into_iter()
        .collect();

    let binding = match detached {
        Some(previous) => ProjectBinding {
            host_id: previous.host_id,
            replica_id: previous.replica_id,
            local_project_id,
            bundle_id,
            project_root: draft.project_root.clone(),
            canonical_project_root: draft.canonical_project_root.clone(),
            profile_ids: resolved_profiles.profile_ids.clone(),
            state: BindingState::Active,
            revision: previous.revision.saturating_add(1),
            updated_at: now,
        },
        None => ProjectBinding {
            host_id: host_id.clone(),
            replica_id: ReplicaId::parse(generated_named_id("replica")?)?,
            local_project_id,
            bundle_id,
            project_root: draft.project_root.clone(),
            canonical_project_root: draft.canonical_project_root.clone(),
            profile_ids: resolved_profiles.profile_ids.clone(),
            state: BindingState::Active,
            revision: 0,
            updated_at: now,
        },
    };
    binding.validate_structure()?;

    let transaction = SetupTransaction {
        schema: SETUP_TRANSACTION_SCHEMA,
        draft_id: draft.draft_id.clone(),
        draft_revision: draft.revision,
        created_at: now,
        host_id,
        replica_id: binding.replica_id.clone(),
        profiles: resolved_profiles.pending_records,
        project,
        links,
        binding,
    };
    transaction.validate()?;

    // Prove prospective isolation before anything is written: the new records
    // must not overlap application data, local storages, or each other.
    let prospective_config = repository.load_config()?;
    let machine = repository.load_bindings()?;
    let mut prospective_profiles = machine.profiles.clone();
    prospective_profiles.extend(transaction.profiles.iter().cloned());
    let mut prospective_bindings = machine.bindings.clone();
    match prospective_bindings
        .iter()
        .position(|binding| binding.replica_id == transaction.binding.replica_id)
    {
        Some(index) => prospective_bindings[index] = transaction.binding.clone(),
        None => prospective_bindings.push(transaction.binding.clone()),
    }
    validate_config_storage_isolation(
        repository,
        &prospective_config,
        &prospective_bindings,
        &prospective_profiles,
    )?;
    Ok(transaction)
}

/// Apply a setup transaction's records in dependency order, skipping records
/// that already exist so every retry reconciles instead of duplicating.
fn apply_setup_transaction(
    repository: &LocalStateRepository,
    transaction: &SetupTransaction,
) -> Result<(), String> {
    let _host_operation = repository.acquire_host_operation()?;
    transaction.validate()?;
    let identity = repository.load_or_create_host_identity()?;
    if transaction.host_id != identity.host_id {
        return Err(
            "setup transaction belongs to a different host; review the draft again".to_string(),
        );
    }

    // 1. Provider profiles (machine state; no dependency on config).
    let profile_id_map = repository.mutate_bindings(|_, machine| {
        let mut map: BTreeMap<LocalProviderProfileId, LocalProviderProfileId> = BTreeMap::new();
        for profile in &transaction.profiles {
            if machine
                .profiles
                .iter()
                .any(|existing| existing.profile_id == profile.profile_id)
            {
                continue;
            }
            if let Some(existing) = machine.profiles.iter().find(|existing| {
                existing.provider == profile.provider
                    && existing.canonical_path == profile.canonical_path
            }) {
                // Someone created the same profile concurrently; reconcile to
                // the surviving record instead of failing on overlap.
                map.insert(profile.profile_id.clone(), existing.profile_id.clone());
                continue;
            }
            machine.profiles.push(profile.clone());
        }
        Ok(map)
    })?;

    // 2. Project and links (one atomic config mutation).
    repository.mutate_config(|config| {
        if config
            .project(&transaction.project.local_project_id)
            .is_none()
        {
            let mut project = transaction.project.clone();
            if project.local_alias.is_none() {
                project.local_alias =
                    deduplicated_local_alias(&project.display_name, &config.projects)?;
            }
            config.projects.push(project);
        }
        for link in &transaction.links {
            if !config.links.iter().any(|existing| {
                existing.local_project_id == link.local_project_id
                    && existing.storage_id == link.storage_id
            }) {
                config.links.push(link.clone());
            }
        }
        Ok(())
    })?;

    // 3. Machine binding (requires the project to exist in config).
    let mut expected_binding = transaction.binding.clone();
    for profile_id in expected_binding.profile_ids.values_mut() {
        if let Some(mapped) = profile_id_map.get(profile_id) {
            *profile_id = mapped.clone();
        }
    }
    repository.mutate_bindings(|_, machine| {
        if let Some(index) = machine
            .bindings
            .iter()
            .position(|binding| binding.local_project_id == expected_binding.local_project_id)
        {
            let existing = &machine.bindings[index];
            if existing == &expected_binding {
                return Ok(());
            }
            let reactivates_detached = existing.state == BindingState::Detached
                && expected_binding.state == BindingState::Active
                && existing.host_id == expected_binding.host_id
                && existing.replica_id == expected_binding.replica_id
                && existing.bundle_id == expected_binding.bundle_id
                && existing.profile_ids == expected_binding.profile_ids
                && existing
                    .canonical_project_root
                    .eq_ignore_ascii_case(&expected_binding.canonical_project_root)
                && expected_binding.revision == existing.revision.saturating_add(1);
            if reactivates_detached {
                machine.bindings[index] = expected_binding.clone();
                return Ok(());
            }
            return Err(
                "setup transaction conflicts with a different host or project replica".to_string(),
            );
        }
        machine.bindings.push(expected_binding.clone());
        Ok(())
    })?;

    // Confirm both documents contain the expected records before the caller
    // removes the transaction.
    let config = repository.load_config()?;
    if config
        .project(&transaction.project.local_project_id)
        .is_none()
    {
        return Err("project registration did not persist".to_string());
    }
    let persisted_binding = repository
        .load_bindings()?
        .bindings
        .into_iter()
        .find(|binding| binding.local_project_id == transaction.project.local_project_id);
    if persisted_binding.as_ref() != Some(&expected_binding) {
        return Err("project binding did not persist".to_string());
    }
    Ok(())
}

/// True when any of the transaction's records already landed in a document.
fn setup_transaction_partially_applied(
    repository: &LocalStateRepository,
    transaction: &SetupTransaction,
) -> Result<bool, String> {
    let config = repository.load_config()?;
    if config
        .project(&transaction.project.local_project_id)
        .is_some()
    {
        return Ok(true);
    }
    let machine = repository.load_bindings()?;
    if machine
        .bindings
        .iter()
        .any(|binding| binding.local_project_id == transaction.project.local_project_id)
    {
        return Ok(true);
    }
    if transaction.profiles.iter().any(|profile| {
        machine
            .profiles
            .iter()
            .any(|existing| existing.profile_id == profile.profile_id)
    }) {
        return Ok(true);
    }
    Ok(false)
}

/// Complete or clean up interrupted finalizations.  Runs before the shell's
/// first project listing and before every finalize, so a crash between the
/// config and binding writes heals on the next app start.
pub(crate) fn recover_setup_state(repository: &LocalStateRepository) -> Vec<String> {
    let (transactions, mut warnings) = match repository.list_setup_transactions() {
        Ok(listed) => listed,
        Err(error) => return vec![format!("setup recovery unavailable: {}", error)],
    };
    for transaction in transactions {
        match repository.load_or_create_host_identity() {
            Ok(identity) if identity.host_id != transaction.host_id => {
                let project_exists = repository.load_config().ok().is_some_and(|config| {
                    config
                        .project(&transaction.project.local_project_id)
                        .is_some()
                });
                if let Err(error) = repository.delete_setup_transaction(&transaction.draft_id) {
                    warnings.push(error);
                    continue;
                }
                if project_exists {
                    if let Err(error) = repository.delete_setup_draft(&transaction.draft_id) {
                        warnings.push(error);
                    }
                    warnings.push(format!(
                        "setup for draft '{}' was retained as a detached project after host registration; review its local binding",
                        transaction.draft_id
                    ));
                } else {
                    let message =
                        "host identity changed during setup; review the draft and finish again";
                    record_draft_error(repository, &transaction.draft_id, message);
                    warnings.push(format!(
                        "setup for draft '{}' must be reviewed again because the host identity changed",
                        transaction.draft_id
                    ));
                }
                continue;
            }
            Ok(_) => {}
            Err(error) => {
                warnings.push(format!(
                    "setup for draft '{}' cannot verify host identity: {}",
                    transaction.draft_id, error
                ));
                continue;
            }
        }
        match apply_setup_transaction(repository, &transaction) {
            Ok(()) => {
                if let Err(error) = repository.delete_setup_transaction(&transaction.draft_id) {
                    warnings.push(error);
                    continue;
                }
                if let Err(error) = repository.delete_setup_draft(&transaction.draft_id) {
                    warnings.push(error);
                }
            }
            Err(error) => match setup_transaction_partially_applied(repository, &transaction) {
                // Nothing landed; return to the draft state and keep the
                // reason on the draft instead of wedging future finalizes.
                Ok(false) => {
                    if let Err(delete_error) =
                        repository.delete_setup_transaction(&transaction.draft_id)
                    {
                        warnings.push(delete_error);
                    }
                    record_draft_error(repository, &transaction.draft_id, &error);
                    warnings.push(format!(
                        "setup for draft '{}' was rolled back: {}",
                        transaction.draft_id, error
                    ));
                }
                _ => warnings.push(format!(
                    "setup for draft '{}' is incomplete and will retry: {}",
                    transaction.draft_id, error
                )),
            },
        }
    }
    warnings
}

fn record_draft_error(repository: &LocalStateRepository, draft_id: &SetupDraftId, error: &str) {
    let Ok(Some(mut draft)) = repository.load_setup_draft(draft_id) else {
        return;
    };
    let mut message: String = error.chars().filter(|c| !c.is_control()).collect();
    message.truncate(4_000);
    draft.last_error = Some(message);
    let _ = repository.save_setup_draft(draft);
}

pub(super) fn finalize_project_setup_with_repository(
    repository: &LocalStateRepository,
    draft_id: &SetupDraftId,
    expected_revision: u64,
) -> Result<ProjectDetail, String> {
    // Complete anything interrupted first; this may finish this very draft.
    let recovery_warnings = recover_setup_state(repository);
    let Some(draft) = repository.load_setup_draft(draft_id)? else {
        return Err(format!(
            "setup draft '{}' does not exist (it may have just finished; refresh the project list)",
            draft_id
        ));
    };
    if let Some(warning) = recovery_warnings
        .iter()
        .find(|warning| warning.contains(draft_id.as_str()))
    {
        return Err(warning.clone());
    }
    if draft.revision != expected_revision {
        return Err(format!(
            "setup draft changed (expected version {}, current {})",
            expected_revision, draft.revision
        ));
    }

    let result = (|| {
        let mut transaction = build_setup_transaction(repository, &draft)?;
        // Registration claim before any local record exists (D1): a storage
        // that cannot be written fails Finish with nothing to recover, and
        // an adopted existing repo already has a head so the claim no-ops.
        if let Some(link) = transaction.links.first() {
            let storage = repository
                .load_config()?
                .storages
                .iter()
                .find(|storage| storage.id == link.storage_id)
                .cloned()
                .ok_or_else(|| format!("unknown storage '{}'", link.storage_id))?;
            publish_registration_claim(
                repository,
                &storage,
                &transaction.project,
                &transaction.binding,
            )?;
        }
        for link in &mut transaction.links {
            let config = repository.load_config()?;
            let storage = config
                .storages
                .iter()
                .find(|storage| storage.id == link.storage_id)
                .ok_or("Storage is unavailable")?;
            link.managed_cloud_repository_id = cloud_link_id(storage, &link.bundle_id)?;
        }
        repository.save_setup_transaction(&transaction)?;
        apply_setup_transaction(repository, &transaction).map(|()| transaction)
    })();
    let transaction = match result {
        Ok(transaction) => transaction,
        Err(error) => {
            record_draft_error(repository, draft_id, &error);
            return Err(error);
        }
    };
    repository.delete_setup_transaction(draft_id)?;
    repository.delete_setup_draft(draft_id)?;
    get_project_with_repository(repository, &transaction.project.local_project_id)?
        .ok_or_else(|| "project disappeared after setup".to_string())
}

fn paths_overlap(left: &Path, right: &Path) -> bool {
    left == right || left.starts_with(right) || right.starts_with(left)
}

fn fs_metadata_no_final_symlink(path: &Path) -> Result<std::fs::Metadata, String> {
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|error| format!("inspect '{}': {}", path.display(), error))?;
    if metadata.file_type().is_symlink() {
        // Binding spelling may itself be a symlink because provider cwd
        // identity uses the spelling.  Follow it only after proving the final
        // component is a link; canonical containment is stored separately.
        std::fs::metadata(path).map_err(|error| format!("follow '{}': {}", path.display(), error))
    } else {
        Ok(metadata)
    }
}

fn fs_profile_metadata(path: &Path) -> Result<std::fs::Metadata, String> {
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|error| format!("inspect provider profile '{}': {}", path.display(), error))?;
    if metadata.file_type().is_symlink() {
        return Err(format!(
            "provider profile '{}' cannot be a symlink; choose the resolved directory",
            path.display()
        ));
    }
    Ok(metadata)
}

pub(super) fn fs_canonicalize(path: &Path) -> Result<PathBuf, String> {
    let canonical = std::fs::canonicalize(path)
        .map_err(|error| format!("resolve '{}': {}", path.display(), error))?;
    Ok(strip_windows_verbatim_prefix(canonical))
}

/// `std::fs::canonicalize` on Windows returns verbatim paths (`\\?\C:\…`).
/// Bindings, the path-map root grammar, and provider `cwd` fields all use
/// the ordinary drive spelling, so strip the prefix for plain drive paths.
#[cfg(windows)]
fn strip_windows_verbatim_prefix(path: PathBuf) -> PathBuf {
    use std::path::{Component, Prefix};
    match path.components().next() {
        Some(Component::Prefix(prefix)) => match prefix.kind() {
            Prefix::VerbatimDisk(drive) => {
                let mut plain = PathBuf::from(format!("{}:\\", drive as char));
                plain.extend(path.components().skip(2));
                plain
            }
            _ => path,
        },
        _ => path,
    }
}

#[cfg(not(windows))]
fn strip_windows_verbatim_prefix(path: PathBuf) -> PathBuf {
    path
}

