    #[test]
    fn fetch_started_messages_preserve_direction_and_byte_formatting() {
        assert_eq!(
            format_fetch_started_message(true, 3, 1_200_000, "Shared"),
            "↑  Uploading 3 objects (1.2 MB) to Shared"
        );
        assert_eq!(
            format_fetch_started_message(false, 3, 1_200_000, "Shared"),
            "↓  Downloading 3 objects (1.2 MB) from Shared"
        );
    }

    #[test]
    fn unchanged_scope_recipe_preserves_remote_revision_after_pull() {
        let generic_resource_id = ResourceId::parse("codex:memory").unwrap();
        let generic_entry = RecipeEntry {
            resource_id: generic_resource_id.clone(),
            apply_policy: contracts::safe_file(),
            required: false,
        };
        let conversation_resource_id = conversation_resource_id(
            &codex_key(),
            &ThreadId::parse("thread-recipe-revision").unwrap(),
        )
        .unwrap();
        let conversation_entry = RecipeEntry {
            resource_id: conversation_resource_id.clone(),
            apply_policy: contracts::merge(),
            required: false,
        };

        let mut previous = BundleRecipe {
            revision: 7,
            ..BundleRecipe::default()
        };
        previous
            .entries
            .insert(generic_resource_id.clone(), generic_entry.clone());
        previous
            .entries
            .insert(conversation_resource_id, conversation_entry);

        let mut unchanged = BundleRecipe::default();
        unchanged
            .entries
            .insert(generic_resource_id.clone(), generic_entry);
        preserve_unchanged_scope_recipe_revision(&mut unchanged, Some(&previous));
        assert_eq!(unchanged.revision, 7);

        let mut changed = BundleRecipe::default();
        changed.entries.insert(
            generic_resource_id.clone(),
            RecipeEntry {
                resource_id: generic_resource_id,
                apply_policy: contracts::explicit_review(),
                required: false,
            },
        );
        preserve_unchanged_scope_recipe_revision(&mut changed, Some(&previous));
        assert_eq!(changed.revision, 0);
    }

    #[test]
    fn observation_worker_outcome_preserves_errors_and_rejects_missing_slots() {
        let thread_id = ThreadId::parse("thread-worker-test").unwrap();
        let mut failed = std::sync::OnceLock::new();
        assert!(failed
            .set(Err("sentinel observation error".to_string()))
            .is_ok());
        assert_eq!(
            take_observation_outcome(&thread_id, &mut failed)
                .err()
                .as_deref(),
            Some("sentinel observation error")
        );

        let mut missing = std::sync::OnceLock::new();
        assert_eq!(
            take_observation_outcome(&thread_id, &mut missing)
                .err()
                .as_deref(),
            Some("thread observation worker produced no outcome for thread 'thread-worker-test'")
        );
    }

    #[test]
    fn packaged_cli_is_resolved_beside_the_desktop_executable() {
        let temp = tempfile::tempdir().unwrap();
        let desktop = temp.path().join(if cfg!(windows) {
            "mallard.exe"
        } else {
            "mallard"
        });
        let cli = temp.path().join(if cfg!(windows) {
            "mallard-cli.exe"
        } else {
            "mallard-cli"
        });
        std::fs::write(&desktop, b"desktop").unwrap();
        std::fs::write(&cli, b"cli").unwrap();

        assert_eq!(
            packaged_cli_path(&desktop).unwrap(),
            cli.canonicalize().unwrap()
        );
        std::fs::remove_file(&cli).unwrap();
        assert!(packaged_cli_path(&desktop)
            .unwrap_err()
            .contains("not available"));
    }

    #[cfg(unix)]
    #[test]
    fn packaged_cli_path_rejects_a_sibling_symlink() {
        use std::os::unix::fs::symlink;

        let temp = tempfile::tempdir().unwrap();
        let desktop = temp.path().join("mallard");
        let outside = temp.path().join("outside-cli");
        let cli = temp.path().join("mallard-cli");
        std::fs::write(&desktop, b"desktop").unwrap();
        std::fs::write(&outside, b"outside").unwrap();
        symlink(&outside, &cli).unwrap();

        assert!(packaged_cli_path(&desktop)
            .unwrap_err()
            .contains("not available"));
    }

    #[test]
    fn every_registered_cli_launcher_is_terminal_safe() {
        // Both shipped agents launch; anything registered stays a bare
        // program name the login shell resolves, never a path or shell text.
        let mut launchable = 0;
        for descriptor in provider_registry().descriptors() {
            let Some(launcher) = descriptor.cli_launcher else {
                continue;
            };
            launchable += 1;
            assert!(
                launcher
                    .program
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_'),
                "{}: program {:?}",
                descriptor.display_name,
                launcher.program,
            );
            assert!(!launcher.display_name.trim().is_empty());
        }
        assert!(launchable >= 2, "claude and codex both ship launchers");
        for key in ["claude", "codex"] {
            let key = ProviderKey::parse(key).expect("static provider key");
            assert!(provider_registry()
                .require(&key)
                .unwrap()
                .descriptor()
                .cli_launcher
                .is_some());
        }
    }

    #[test]
    fn codex_portable_display_title_decodes_tokens_and_preserves_literals() {
        use mallard_infrastructure::providers::SessionAdapter as _;
        let adapter = mallard_infrastructure::providers::codex::CodexAdapter::new();
        let root = "/tmp/mallard-target-project";
        let title =
            "Open /__mallard_root__/b;/src/main.rs; keep /tmp/project1_external/outside.txt";
        assert_eq!(
            adapter
                .decode_portable_display_title(title, root, root)
                .unwrap(),
            "Open /tmp/mallard-target-project/src/main.rs; keep /tmp/project1_external/outside.txt"
        );
        assert!(adapter
            .decode_portable_display_title(
                "Keep /__mallard_root___external/outside.txt",
                root,
                root
            )
            .is_err());
        assert_eq!(
            adapter
                .decode_portable_display_title(
                    "Already mentions /tmp/mallard-target-project/src/main.rs",
                    root,
                    root
                )
                .unwrap(),
            "Already mentions /tmp/mallard-target-project/src/main.rs"
        );
    }

    #[test]
    fn codex_index_payload_writes_provider_schema_rows_only_for_titled_threads() {
        let temp = tempfile::tempdir().unwrap();
        let index_path = temp.path().join("session_index.jsonl");

        let (expectation, bytes) = codex_index_payload(&index_path, &[]).unwrap();
        assert_eq!(expectation, TargetExpectation::Absent);
        assert!(bytes.is_none(), "titleless threads write no index row");

        let named = |name: &str, replace_existing: bool| CodexIndexRowSpec {
            provider_thread_id: "thread-new".to_string(),
            thread_name: name.to_string(),
            updated_at: 1_784_332_800,
            replace_existing,
        };
        let (_, bytes) = codex_index_payload(&index_path, &[named("Named", false)]).unwrap();
        let row: serde_json::Value =
            serde_json::from_slice(bytes.unwrap().trim_ascii_end()).unwrap();
        assert_eq!(
            row,
            serde_json::json!({
                "id": "thread-new",
                "thread_name": "Named",
                "updated_at": "2026-07-18T00:00:00.000000Z",
            })
        );

        std::fs::write(
            &index_path,
            "{\"id\":\"thread-new\",\"thread_name\":\"Old\",\"updated_at\":\"2026-01-01T00:00:00.000000Z\"}\n",
        )
        .unwrap();
        assert!(codex_index_payload(&index_path, &[named("Named", false)])
            .unwrap_err()
            .contains("already indexed"));
        // A keep-both rewrite carries two rows in one payload: the preserved
        // rename replaces the existing row while the fresh destination row
        // appends alongside it.
        let (_, replacement) = codex_index_payload(
            &index_path,
            &[
                named("Updated", true),
                CodexIndexRowSpec {
                    provider_thread_id: "thread-destination".to_string(),
                    thread_name: "Cloud".to_string(),
                    updated_at: 1_784_332_800,
                    replace_existing: false,
                },
            ],
        )
        .unwrap();
        let rows = replacement
            .unwrap()
            .split(|byte| *byte == b'\n')
            .filter(|line| !line.is_empty())
            .map(|line| serde_json::from_slice::<serde_json::Value>(line).unwrap())
            .collect::<Vec<_>>();
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0]["id"], "thread-new");
        assert_eq!(rows[0]["thread_name"], "Updated");
        assert_eq!(rows[1]["id"], "thread-destination");
        assert_eq!(rows[1]["thread_name"], "Cloud");
    }

    #[test]
    fn host_sensitive_workflows_share_the_host_operation_lock() {
        let temp = tempfile::tempdir().unwrap();
        let repo = LocalStateRepository::from_home_dir(temp.path()).unwrap();
        let guard = repo.acquire_host_operation().unwrap();
        let request = SaveProjectBindingRequest {
            local_project_id: LocalProjectId::parse("project-a").unwrap(),
            project_root: temp.path().join("project").to_string_lossy().into_owned(),
            profile_ids: BTreeMap::new(),
            expected_revision: None,
        };
        assert!(save_project_binding_with_repository(&repo, request)
            .unwrap_err()
            .contains("host-sensitive operation"));
        assert!(inspect_project_files_with_repository(
            &repo,
            &LocalProjectId::parse("project-a").unwrap(),
            &StorageId::parse("storage-a").unwrap(),
        )
        .unwrap_err()
        .contains("host-sensitive operation"));
        assert!(remove_project_link_with_repository(
            &repo,
            &LocalProjectId::parse("project-a").unwrap(),
            &StorageId::parse("storage-a").unwrap(),
        )
        .unwrap_err()
        .contains("host-sensitive operation"));
        assert!(prepare_push_review_with_repository(
            &repo,
            &LocalProjectId::parse("project-a").unwrap(),
            &StorageId::parse("storage-a").unwrap(),
        )
        .unwrap_err()
        .contains("host-sensitive operation"));
        // Binding detach is guarded too. Its own command is gone, so the arm
        // names the live entry point that still performs the mutation:
        // `remove_local_project_with_repository` -> `remove_local_project_guarded`
        // -> `detach_project_binding_guarded`.
        assert!(remove_local_project_with_repository(
            &repo,
            &LocalProjectId::parse("project-a").unwrap()
        )
        .unwrap_err()
        .contains("host-sensitive operation"));
        drop(guard);
    }

    /// Remove one bundle from a local-folder storage the way a clear does:
    /// its records first, which unpublishes it, then its manifests and objects.
    fn wipe_remote_bundle(storage_root: &Path, bundle_id: &BundleId) {
        let repositories = storage_root.join(".mallard/v1/repositories");
        std::fs::remove_dir_all(repositories.join("_commits").join(bundle_id.as_str())).unwrap();
        std::fs::remove_dir_all(repositories.join(bundle_id.as_str())).unwrap();
    }

    /// The commit at depth `revision` of fixture branch `branch`. Branch 0 is
    /// the history this replica reviewed; any other branch shares nothing
    /// with it, like a recreated stream or a sibling that was selected.
    fn continuity_commit(revision: u64, branch: u64) -> String {
        format!("commit-{branch:012x}{revision:012x}")
    }

    /// The selected chain of a stream whose publications 1 to `tip` are all
    /// on `branch`.
    fn continuity_mainline(tip: u64, branch: u64) -> Mainline {
        let mut names = Vec::<mallard_domain::RecordName>::new();
        for revision in 1..=tip {
            let token = mallard_domain::PublicationToken::new(
                continuity_commit(revision, branch),
                format!("{:064x}", branch * 1_000 + revision),
            )
            .unwrap();
            let parent = names.last().map(|parent| parent.token().clone());
            names.push(mallard_domain::RecordName::new(revision, token, parent, revision).unwrap());
        }
        Mainline::select(names)
    }

    fn continuity_head_on(revision: u64, manifest_sha256: &str, branch: u64) -> BundleHead {
        BundleHead {
            schema_version: mallard_domain::BUNDLE_SCHEMA,
            bundle_id: BundleId::parse("0123456789abcdef0123456789abcdef").unwrap(),
            kind: BundleKind::Project,
            revision,
            commit_id: continuity_commit(revision, branch),
            manifest_key: format!("_manifests/{}.json", revision),
            manifest_size: 1,
            manifest_sha256: manifest_sha256.to_string(),
            updated_at: revision,
        }
    }

    fn continuity_head(revision: u64, manifest_sha256: &str) -> BundleHead {
        continuity_head_on(revision, manifest_sha256, 0)
    }

    fn continuity_repository_base(revision: u64, manifest_sha256: &str) -> RepositoryBase {
        RepositoryBase {
            revision,
            commit_id: continuity_commit(revision, 0),
            manifest_sha256: manifest_sha256.to_string(),
            manifest_size: 1,
        }
    }

    fn continuity_scope_base(
        scope: SyncScopeKey,
        scope_revision: u64,
        scope_sha256: &str,
        reviewed_in: RepositoryBase,
        binding_revision: u64,
    ) -> ScopeBase {
        ScopeBase {
            scope,
            scope_revision,
            scope_sha256: scope_sha256.to_string(),
            reviewed_in,
            binding_revision,
            last_pull_at: None,
            last_push_at: Some(99),
        }
    }

    fn continuity_link(bases: Vec<ScopeBase>) -> ProjectStorageLink {
        ProjectStorageLink {
            managed_cloud_repository_id: None,
            local_project_id: LocalProjectId::parse("project-a").unwrap(),
            storage_id: StorageId::parse("storage-a").unwrap(),
            bundle_id: BundleId::parse("0123456789abcdef0123456789abcdef").unwrap(),
            recipe: None,
            scope_bases: bases
                .into_iter()
                .map(|base| (base.scope.clone(), base))
                .collect(),
            conversation_checkpoints: BTreeMap::new(),
            project_content_preferences: ProjectContentPreferences::default(),
            pinned: false,
            created_at: 1,
        }
    }

    /// A binding whose only bound provider is Codex, so the writable scopes
    /// are exactly `project` and `provider:codex`.
    fn continuity_binding(revision: u64) -> ProjectBinding {
        ProjectBinding {
            host_id: HostId::parse("1".repeat(32)).unwrap(),
            replica_id: ReplicaId::parse("replica-a").unwrap(),
            local_project_id: LocalProjectId::parse("project-a").unwrap(),
            bundle_id: BundleId::parse("0123456789abcdef0123456789abcdef").unwrap(),
            project_root: "/tmp/project-a".to_string(),
            canonical_project_root: "/tmp/project-a".to_string(),
            profile_ids: BTreeMap::from([(
                ProviderKey::parse("codex").unwrap(),
                LocalProviderProfileId::parse("profile-codex").unwrap(),
            )]),
            state: BindingState::Active,
            revision,
            updated_at: 1,
        }
    }

    fn continuity_snapshot(
        head: BundleHead,
        scopes: Vec<(SyncScopeKey, u64, &str)>,
    ) -> BundleSnapshot {
        let manifest = BundleManifest {
            git_history: None,
            schema_version: mallard_domain::BUNDLE_SCHEMA,
            revision: head.revision,
            commit_id: head.commit_id.clone(),
            updated_at: head.updated_at,
            bundle: BundleIdentity {
                bundle_id: head.bundle_id.clone(),
                display_name: "Continuity".to_string(),
                kind: BundleKind::Project,
                repository_fingerprint: None,
            },
            published_by_origin: PortableOrigin {
                origin_host_token: OriginHostToken::parse("a".repeat(64)).unwrap(),
                origin_replica_token: OriginReplicaToken::parse("b".repeat(64)).unwrap(),
                shared_label: None,
            },
            scopes: scopes
                .into_iter()
                .map(|(scope, revision, content_sha256)| {
                    (
                        scope,
                        BundleScope {
                            revision,
                            content_sha256: content_sha256.to_string(),
                            recipe: BundleRecipe::default(),
                            captured_with: CapturedWith::default(),
                            conversations: BTreeMap::new(),
                            resources: BTreeMap::new(),
                            files: BTreeMap::new(),
                            directories: BTreeMap::new(),
                            tombstones: BTreeMap::new(),
                        },
                    )
                })
                .collect(),
        };
        BundleSnapshot {
            storage_id: StorageId::parse("storage-a").unwrap(),
            head,
            manifest,
            fetched_at: 1,
        }
    }

    /// The Push gate, one assertion per storage-area row of the plan (A1 to
    /// A7) plus the binding overlay. A cleared or recreated history is no
    /// state of its own: its bases are stale, and the same rows decide.
    #[test]
    fn push_destination_is_decided_by_the_writable_scopes_alone() {
        let digest_a = "a".repeat(64);
        let digest_b = "b".repeat(64);
        let scope_c = "c".repeat(64);
        let scope_d = "d".repeat(64);
        let scope_e = "e".repeat(64);
        let codex_scope = SyncScopeKey::Provider(ProviderKey::parse("codex").unwrap());
        let claude_scope = SyncScopeKey::Provider(ProviderKey::parse("claude").unwrap());
        let binding = continuity_binding(7);
        // The reviewed link: the codex scope was reviewed at scope revision 1
        // (digest c) inside repository revision 3 (manifest digest a).
        let reviewed = continuity_link(vec![continuity_scope_base(
            codex_scope.clone(),
            1,
            &scope_c,
            continuity_repository_base(3, &digest_a),
            7,
        )]);
        let empty = continuity_link(vec![]);
        let nothing = Mainline::default();
        let on_base = continuity_mainline(3, 0);
        let current = continuity_snapshot(
            continuity_head(3, &digest_a),
            vec![(codex_scope.clone(), 1, &scope_c)],
        );

        // A1: nothing stored, nothing reviewed.
        assert_eq!(
            classify_push_destination(None, &nothing, &empty, &binding),
            PushDestinationStatus::Ready { revision: None }
        );
        // A3: the storage was cleared and nobody pushed since. The bases are
        // stale, every writable scope is a first publication target, and the
        // Push writes the stream's first record. No unlink, no reset.
        assert_eq!(
            classify_push_destination(None, &nothing, &reviewed, &binding),
            PushDestinationStatus::Ready { revision: None }
        );
        // A4: remote data in a writable scope that this replica never
        // reviewed blocks with the exact blocking scope named.
        assert_eq!(
            classify_push_destination(Some(&current), &on_base, &empty, &binding),
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteWithoutBase,
                remote_revision: 3,
                base_revision: None,
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );
        // Binding-revision mismatch is push policy: a base reviewed under an
        // older binding cannot authorize this Push.
        assert_eq!(
            classify_push_destination(Some(&current), &on_base, &reviewed, &continuity_binding(8)),
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::BindingChanged,
                remote_revision: 3,
                base_revision: Some(3),
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );
        // A5, usable base: the freshly selected publication is the one this
        // replica is based on.
        assert_eq!(
            classify_push_destination(Some(&current), &on_base, &reviewed, &binding),
            PushDestinationStatus::Ready { revision: Some(3) }
        );
        // A5, stale base: the stream was cleared and pushed again, and the
        // writable scope holds exactly the reviewed content. Identity decides
        // the history, and content decides the scope.
        assert_eq!(
            classify_push_destination(
                Some(&continuity_snapshot(
                    continuity_head_on(3, &digest_b, 1),
                    vec![(codex_scope.clone(), 1, &scope_c)],
                )),
                &continuity_mainline(3, 1),
                &reviewed,
                &binding,
            ),
            PushDestinationStatus::Ready { revision: Some(3) }
        );
        // A6: a descendant of the base in which the codex scope changed: a
        // true advance of a writable scope, so this Push needs a Pull first.
        let advanced = classify_push_destination(
            Some(&continuity_snapshot(
                continuity_head(4, &digest_b),
                vec![(codex_scope.clone(), 2, &scope_d)],
            )),
            &continuity_mainline(4, 0),
            &reviewed,
            &binding,
        );
        assert_eq!(
            advanced,
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteAdvanced,
                remote_revision: 4,
                base_revision: Some(3),
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );
        // A descendant in which only an unbound provider scope changed: the
        // repository advanced but no writable scope did, so a Codex-only
        // binding publishes on the new selection and carries the Claude
        // change without pulling it (D6).
        assert_eq!(
            classify_push_destination(
                Some(&continuity_snapshot(
                    continuity_head(4, &digest_b),
                    vec![
                        (codex_scope.clone(), 1, &scope_c),
                        (claude_scope.clone(), 5, &scope_e),
                    ],
                )),
                &continuity_mainline(4, 0),
                &reviewed,
                &binding,
            ),
            PushDestinationStatus::Ready { revision: Some(4) }
        );
        // A7: the stream was cleared and another computer pushed other
        // content into a writable scope. However far ahead its revision is,
        // the base is not on the selected chain, so the scope reads as never
        // reviewed here and a Pull comes first.
        let recreated = classify_push_destination(
            Some(&continuity_snapshot(
                continuity_head_on(4, &digest_b, 1),
                vec![(codex_scope.clone(), 2, &scope_d)],
            )),
            &continuity_mainline(4, 1),
            &reviewed,
            &binding,
        );
        assert_eq!(
            recreated,
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteWithoutBase,
                remote_revision: 4,
                base_revision: None,
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );
        // The stream was recreated by a computer that wrote only into scopes
        // this binding does not write: every writable scope is A3, and the
        // Push is open without a Pull.
        assert_eq!(
            classify_push_destination(
                Some(&continuity_snapshot(
                    continuity_head_on(2, &digest_b, 1),
                    vec![(claude_scope.clone(), 1, &scope_e)],
                )),
                &continuity_mainline(2, 1),
                &reviewed,
                &binding,
            ),
            PushDestinationStatus::Ready { revision: Some(2) }
        );
        // Several scope bases, one of them stale: each scope is decided by
        // its own base. The stale project base is A3, the codex base is A5.
        let mut stranded_base = continuity_repository_base(2, &digest_a);
        stranded_base.commit_id = continuity_commit(2, 9);
        let stranded = continuity_link(vec![
            continuity_scope_base(
                codex_scope.clone(),
                1,
                &scope_c,
                continuity_repository_base(3, &digest_a),
                7,
            ),
            continuity_scope_base(SyncScopeKey::Project, 1, &scope_e, stranded_base, 7),
        ]);
        assert_eq!(
            classify_push_destination(Some(&current), &on_base, &stranded, &binding),
            PushDestinationStatus::Ready { revision: Some(3) }
        );

        // No state asks for an unlink or a reset.
        assert_eq!(
            serde_json::to_value(&recreated).unwrap(),
            serde_json::json!({
                "state": "requires_pull",
                "reason": "remote_without_base",
                "remote_revision": 4,
                "blocking_scopes": ["provider:codex"],
            })
        );
        let message = push_destination_error(&recreated).unwrap();
        assert!(message.contains("never been reviewed on this computer"));
        assert!(!message.contains("unlink"));

        let message = push_destination_error(&advanced).unwrap();
        assert!(message.contains("base version 3"));
        assert!(message.contains("remote version 4"));
        assert!(message.contains("provider:codex"));
    }

    #[test]
    fn routine_history_scan_logs_are_throttled_per_project() {
        let mut logged_at = BTreeMap::new();
        assert!(claim_history_scan_log_at(
            &mut logged_at,
            "project-one",
            100,
        ));
        assert!(!claim_history_scan_log_at(
            &mut logged_at,
            "project-one",
            100 + HISTORY_SCAN_LOG_THROTTLE_SECS - 1,
        ));
        assert!(claim_history_scan_log_at(
            &mut logged_at,
            "project-one",
            100 + HISTORY_SCAN_LOG_THROTTLE_SECS,
        ));
        assert!(claim_history_scan_log_at(
            &mut logged_at,
            "project-two",
            101,
        ));
        assert!(!claim_history_scan_log_at(
            &mut logged_at,
            "project-one",
            100 + HISTORY_SCAN_LOG_THROTTLE_SECS + 1,
        ));
    }

