    #[test]
    fn clean_push_review_separates_one_divergence_from_local_recipe_resources() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("clean-conversation-recipe-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        let binding =
            bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let first_provider_id = "019fa660-0000-7000-8000-000000000001";
        let second_provider_id = "019fa660-0000-7000-8000-000000000002";
        let sessions = codex_home.join("sessions/2026/07/28");
        std::fs::create_dir_all(&sessions).unwrap();
        let first_path = sessions.join(format!(
            "rollout-2026-07-28T12-00-00-{first_provider_id}.jsonl"
        ));
        let second_path = sessions.join(format!(
            "rollout-2026-07-28T12-01-00-{second_provider_id}.jsonl"
        ));
        std::fs::write(
            &first_path,
            command_test_transcript(
                first_provider_id,
                &project_root,
                &[("first-base", "user", "first base")],
            ),
        )
        .unwrap();
        std::fs::write(
            &second_path,
            command_test_transcript(
                second_provider_id,
                &project_root,
                &[("second-base", "user", "second base")],
            ),
        )
        .unwrap();

        // The first Push persists local capture IDs in the link recipe and
        // portable conversation IDs only in the manifest provider scope.
        push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let initial = engine.inspect(&project.bundle_id).unwrap();
        let first_thread = initial
            .manifest
            .all_conversations()
            .find_map(|(_, thread_id, thread)| {
                (thread.source_thread_id.as_deref() == Some(first_provider_id))
                    .then_some(thread_id.clone())
            })
            .unwrap();
        let second_thread = initial
            .manifest
            .all_conversations()
            .find_map(|(_, thread_id, thread)| {
                (thread.source_thread_id.as_deref() == Some(second_provider_id))
                    .then_some(thread_id.clone())
            })
            .unwrap();
        assert_ne!(first_thread, second_thread);

        let config = repo.load_config().unwrap();
        config
            .project(&project.local_project_id)
            .unwrap()
            .recipe
            .validate_machine_local()
            .unwrap();
        let link_recipe = project_link(&config, &project.local_project_id, &storage_id)
            .unwrap()
            .recipe
            .as_ref()
            .unwrap();
        link_recipe.validate_machine_local().unwrap();
        assert!(link_recipe
            .entries
            .keys()
            .all(|resource_id| { !is_conversation_resource_id(resource_id.as_str()) }));

        // Both local sessions advance. Only the first also advances remotely,
        // producing one real divergence and leaving the second safe to Push.
        std::fs::write(
            &first_path,
            command_test_transcript(
                first_provider_id,
                &project_root,
                &[
                    ("first-base", "user", "first base"),
                    ("first-local", "user", "first local branch"),
                ],
            ),
        )
        .unwrap();
        std::fs::write(
            &second_path,
            command_test_transcript(
                second_provider_id,
                &project_root,
                &[
                    ("second-base", "user", "second base"),
                    ("second-local", "user", "second local change"),
                ],
            ),
        )
        .unwrap();
        let (origin_host_token, origin_replica_token) = repo
            .derive_origin_tokens(&project.bundle_id, &binding.replica_id)
            .unwrap();
        let origin = PortableOrigin {
            origin_host_token,
            origin_replica_token,
            shared_label: None,
        };
        let mut first_remote = ThreadSpec::new(
            first_thread.as_str(),
            first_provider_id,
            command_test_transcript(
                first_provider_id,
                &project_root,
                &[
                    ("first-base", "user", "first base"),
                    ("first-remote", "user", "first remote branch"),
                ],
            ),
            origin.clone(),
            20,
        );
        first_remote.title = "First".to_string();
        let mut second_remote = ThreadSpec::new(
            second_thread.as_str(),
            second_provider_id,
            command_test_transcript(
                second_provider_id,
                &project_root,
                &[("second-base", "user", "second base")],
            ),
            origin.clone(),
            20,
        );
        second_remote.title = "Second".to_string();
        let (_, head_token) = engine.read_head(&project.bundle_id).unwrap().unwrap();
        let remote = engine
            .publish(publish_request(
                project.bundle_id.clone(),
                &[first_remote, second_remote],
                origin,
                20,
                Some(&initial.manifest),
                PublishExpectation::Match(Box::new(initial.clone()), head_token),
            ))
            .unwrap()
            .into_snapshot();
        // The repository head and scope were explicitly reviewed, while the
        // per-thread accepted checkpoint remains the common first-Push base.
        record_reviewed_scope_bases(&repo, &project, &binding, &storage_id, &remote, 20);

        let review =
            prepare_push_review_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        assert_eq!(
            review.destination_status,
            PushDestinationStatus::Ready { revision: Some(3) }
        );
        let comparison = review.thread_comparison.as_ref().unwrap();
        assert_eq!(comparison.counts.diverged, 1);
        assert_eq!(comparison.counts.local, 1);
        let divergent = comparison
            .entries
            .iter()
            .find(|entry| entry.provider_thread_id.as_deref() == Some(first_provider_id))
            .unwrap();
        assert_eq!(divergent.state, ThreadSyncState::Diverged);
        assert_eq!(
            divergent.push_decision.action,
            ConversationReviewAction::RequirePull
        );
        assert!(!divergent.push_decision.selectable);
        let pushable = comparison
            .entries
            .iter()
            .find(|entry| entry.provider_thread_id.as_deref() == Some(second_provider_id))
            .unwrap();
        assert_eq!(pushable.state, ThreadSyncState::LocalAhead);
        assert_eq!(
            pushable.push_decision.action,
            ConversationReviewAction::Publish
        );
        assert!(pushable.push_decision.selectable);

        assert!(review.inventory.resources.iter().all(|resource| {
            !is_conversation_resource_id(resource.descriptor.resource_id.as_str())
        }));
        assert!(review
            .inventory
            .resources
            .iter()
            .all(|resource| { resource.descriptor.kind != contracts::requirement() }));
        review.inventory.recipe.validate_machine_local().unwrap();
    }

    #[test]
    fn production_push_holds_a_divergent_tip_and_pushes_the_rest() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("conversation-push-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        let binding =
            bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let remote_cwd = temp.path().join("remote-project");
        let remote_tip = command_test_transcript(
            "provider-t111",
            &remote_cwd,
            &[
                ("base-user", "user", "base"),
                ("base-agent", "assistant", "answer"),
                ("remote-tip", "user", "remote branch"),
            ],
        );
        let (source, _t1, t11, t111) = publish_three_level_chain(
            &repo,
            &project,
            &binding,
            &storage_id,
            &remote_cwd,
            remote_tip,
        );
        let local_provider_id = "019fa661-49d6-7642-8aee-ebc2ef0929e6";
        let local_tip = command_test_transcript(
            local_provider_id,
            &project_root,
            &[
                ("base-user", "user", "base"),
                ("base-agent", "assistant", "answer"),
                ("local-tip", "user", "local branch"),
            ],
        );
        // The local registration keeps its own machine-local identity; the
        // pairing to the cloud tip lives only in the binding's mapping.
        let local_t111 = ThreadId::parse("thread-local-t111").unwrap();
        let local_path = bind_local_conversation(
            &repo,
            &binding,
            &codex_home,
            &local_t111,
            &t111,
            Some(t11.clone()),
            local_provider_id,
            &local_tip,
            &source,
        );
        // A second, unrelated local-only conversation stays pushable while
        // the divergent tip is held.
        let fresh_provider_id = "019fa661-49d6-7642-8aee-ebc2ef092900";
        let fresh_transcript = command_test_transcript(
            fresh_provider_id,
            &project_root,
            &[("fresh-user", "user", "a brand new local thread")],
        );
        let fresh_path = codex_home.join("sessions/2026/07/28").join(format!(
            "rollout-2026-07-28T12-00-00-{}.jsonl",
            fresh_provider_id
        ));
        std::fs::create_dir_all(fresh_path.parent().unwrap()).unwrap();
        std::fs::write(&fresh_path, &fresh_transcript).unwrap();

        let review =
            prepare_push_review_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        let comparison = review.thread_comparison.as_ref().unwrap();
        let tip = comparison
            .entries
            .iter()
            .find(|entry| entry.cloud_thread_id.as_ref() == Some(&t111))
            .unwrap();
        // S4: the pair has no acceptance, and the stored copy is another
        // branch that adoption cannot prove. Nothing is replaced and nothing
        // is blocked: Push asks for a Pull, and Pull keeps both copies.
        assert_eq!(tip.state, ThreadSyncState::Diverged);
        assert_eq!(
            tip.push_decision.action,
            ConversationReviewAction::RequirePull
        );
        assert_eq!(tip.push_decision.blocker, None);
        assert!(!tip.push_decision.selectable);
        assert_eq!(tip.pull_decision.action, ConversationReviewAction::KeepBoth);
        assert!(tip.pull_decision.selectable);
        let fresh = comparison
            .entries
            .iter()
            .find(|entry| entry.provider_thread_id.as_deref() == Some(fresh_provider_id))
            .unwrap();
        assert_eq!(
            fresh.push_decision.action,
            ConversationReviewAction::CreateCloud
        );
        assert!(fresh.push_decision.selectable);
        assert!(
            !recommended_review_recipe(&review, &storage_id)
                .entries
                .contains_key(&tip.resource_id),
            "a row that needs a Pull must not enter the selected recipe"
        );
        assert!(!repo.root().join("conversation_push_plans").exists());

        // The rest of the project pushes while the divergent tip is held.
        let pushed = push_bundle_reviewed_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
            recommended_review_recipe(&review, &storage_id),
            empty_project_content_review(),
            &mut |_| {},
        )
        .unwrap();
        assert!(pushed.success, "{}", pushed.message);

        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let published = engine.inspect(&project.bundle_id).unwrap();
        let published_scope = published.manifest.provider_scope(&codex_key()).unwrap();
        let source_scope = source.manifest.provider_scope(&codex_key()).unwrap();
        assert_eq!(published_scope.conversations.len(), 4);
        // The divergent thread keeps its cloud version, byte for byte.
        let republished_tip = published_scope.conversations.get(&t111).unwrap();
        let source_tip = source_scope.conversations.get(&t111).unwrap();
        assert_eq!(republished_tip.forked_from, source_tip.forked_from);
        let tip_transcript_path = republished_tip
            .files
            .iter()
            .find(|file| file.role == ConversationFileRole::Transcript)
            .unwrap()
            .logical_path
            .clone();
        assert_eq!(
            published_scope
                .files
                .get(&tip_transcript_path)
                .unwrap()
                .sha256,
            source_scope.files.get(&tip_transcript_path).unwrap().sha256,
        );
        // The local divergent branch was neither pushed nor modified.
        assert_eq!(std::fs::read(&local_path).unwrap(), local_tip);
        assert!(published_scope
            .conversations
            .values()
            .any(|thread| thread.source_thread_id.as_deref() == Some(fresh_provider_id)));
        let bindings = repo.load_conversation_bindings().unwrap();
        let original_binding = bindings
            .bindings
            .iter()
            .find(|candidate| {
                candidate.local_project_id == project.local_project_id
                    && candidate.cloud_thread_id.as_ref() == Some(&t111)
            })
            .unwrap();
        assert_eq!(original_binding.forked_from, Some(t11));
        assert_eq!(
            original_binding.provider_thread_id.as_deref(),
            Some(local_provider_id)
        );
    }

    fn reviewed_project_content_recipe(inventory: &ProjectContentInventory) -> BundleRecipe {
        let mut recipe = BundleRecipe::default();
        for entry in &inventory.entries {
            if entry.local_present && entry.blocked_reason.is_none() && entry.selected_after_scan {
                let resource_id = entry.descriptor.resource_id.clone();
                recipe.entries.insert(
                    resource_id.clone(),
                    RecipeEntry {
                        resource_id,
                        apply_policy: contracts::explicit_review(),
                        required: entry.entry_type == ProjectContentEntryType::Directory,
                    },
                );
            }
        }
        recipe
    }

    #[test]
    fn storage_clear_drops_recipe_only_project_content_and_republishes_sessions() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let catalog =
            CatalogStateRepository::from_home_dir(temp.path().join("catalog-home")).unwrap();
        let storage_id = StorageId::parse("cleared-project-files-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));

        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        std::fs::create_dir_all(&project_root).unwrap();
        std::fs::write(project_root.join("draft.md"), b"first draft\n").unwrap();
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);

        let provider_thread_id = "019fc001-0000-7000-8000-000000000001";
        let child_thread_id = "019fc001-0000-7000-8000-000000000002";
        let grandchild_thread_id = "019fc001-0000-7000-8000-000000000003";
        let local_rollouts = [
            write_owned_rollout(
                &codex_home,
                &project_root,
                provider_thread_id,
                None,
                &[("start-child", child_thread_id)],
            ),
            write_owned_rollout(
                &codex_home,
                &project_root,
                child_thread_id,
                Some(provider_thread_id),
                &[("start-grandchild", grandchild_thread_id)],
            ),
            write_owned_rollout(
                &codex_home,
                &project_root,
                grandchild_thread_id,
                Some(child_thread_id),
                &[],
            ),
        ]
        .map(|path| {
            let bytes = std::fs::read(&path).unwrap();
            (path, bytes)
        });

        let first_files =
            inspect_project_files_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        let old_file_id = first_files
            .entries
            .iter()
            .find(|entry| entry.relative_path == "draft.md")
            .unwrap()
            .descriptor
            .resource_id
            .clone();
        let first_review =
            prepare_push_review_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        let mut first_approval = PushApproval::recommended(&first_review, &storage_id);
        first_approval
            .recipe
            .entries
            .extend(reviewed_project_content_recipe(&first_files).entries);
        first_approval.project_content_review_token = first_files.review_token;
        let first_push = ProjectSyncService::new(&repo)
            .push_reviewed(&project.local_project_id, &storage_id, first_approval)
            .unwrap();
        assert!(first_push.success, "{}", first_push.message);

        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let first_snapshot = engine.inspect(&project.bundle_id).unwrap();
        assert!(first_snapshot
            .manifest
            .scope(&SyncScopeKey::Project)
            .unwrap()
            .resources
            .contains_key(&old_file_id));
        let (_, cloud_thread_id, cloud_thread) = first_snapshot
            .manifest
            .all_conversations()
            .find(|(_, _, thread)| thread.source_thread_id.as_deref() == Some(provider_thread_id))
            .unwrap();
        assert_eq!(
            cloud_thread
                .files
                .iter()
                .filter(|file| matches!(file.role, ConversationFileRole::SubagentTranscript { .. }))
                .count(),
            2
        );
        let store = LocalObjectStore::open(&temp.path().join("store")).unwrap();
        let stored_files = first_snapshot
            .manifest
            .all_files()
            .map(|(_, file)| {
                (
                    repository_object_key(&project.bundle_id, &file.object_key).unwrap(),
                    file.size,
                )
            })
            .collect::<Vec<_>>();
        for (key, size) in &stored_files {
            assert!(store.get_metadata(key, *size).unwrap().is_some());
        }

        std::fs::rename(
            project_root.join("draft.md"),
            project_root.join("renamed.md"),
        )
        .unwrap();
        let expected_config_revision = repo.load_config().unwrap().revision;
        clear_storage_data_with_repositories(
            &repo,
            &catalog,
            &storage_id,
            expected_config_revision,
        )
        .unwrap();
        assert!(engine
            .inspect_optional(&project.bundle_id)
            .unwrap()
            .is_none());
        for (key, size) in &stored_files {
            assert!(store.get_metadata(key, *size).unwrap().is_none());
        }
        for (path, bytes) in &local_rollouts {
            assert_eq!(std::fs::read(path).unwrap(), *bytes);
        }
        let cleared_config = repo.load_config().unwrap();
        assert!(
            project_link(&cleared_config, &project.local_project_id, &storage_id)
                .unwrap()
                .recipe
                .as_ref()
                .unwrap()
                .entries
                .contains_key(&old_file_id)
        );

        let second_files =
            inspect_project_files_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        assert!(second_files
            .entries
            .iter()
            .all(|entry| entry.descriptor.resource_id != old_file_id));
        let new_file_id = second_files
            .entries
            .iter()
            .find(|entry| entry.relative_path == "renamed.md")
            .unwrap()
            .descriptor
            .resource_id
            .clone();
        let second_review =
            prepare_push_review_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        let session = second_review
            .thread_comparison
            .as_ref()
            .unwrap()
            .entries
            .iter()
            .find(|entry| entry.provider_thread_id.as_deref() == Some(provider_thread_id))
            .unwrap();
        assert_eq!(session.state, ThreadSyncState::LocalOnly);
        assert_eq!(session.subagent_selection.keys.len(), 2);
        assert_eq!(
            session.push_decision.action,
            ConversationReviewAction::CreateCloud
        );

        let mut second_approval = PushApproval::recommended(&second_review, &storage_id);
        second_approval
            .recipe
            .entries
            .retain(|resource_id, _| !mallard_domain::is_project_content_resource_id(resource_id));
        second_approval
            .recipe
            .entries
            .extend(reviewed_project_content_recipe(&second_files).entries);
        second_approval.project_content_review_token = second_files.review_token;
        let second_push = ProjectSyncService::new(&repo)
            .push_reviewed(&project.local_project_id, &storage_id, second_approval)
            .unwrap();
        assert!(second_push.success, "{}", second_push.message);

        let republished = engine.inspect(&project.bundle_id).unwrap();
        let project_scope = republished.manifest.scope(&SyncScopeKey::Project).unwrap();
        assert!(project_scope.resources.contains_key(&new_file_id));
        assert!(!project_scope.resources.contains_key(&old_file_id));
        let (_, _, republished_thread) = republished
            .manifest
            .all_conversations()
            .find(|(_, thread_id, thread)| {
                *thread_id == cloud_thread_id
                    && thread.source_thread_id.as_deref() == Some(provider_thread_id)
            })
            .unwrap();
        assert_eq!(
            republished_thread
                .files
                .iter()
                .filter(|file| matches!(file.role, ConversationFileRole::SubagentTranscript { .. }))
                .count(),
            2
        );

        let config = repo.load_config().unwrap();
        let recipe = project_link(&config, &project.local_project_id, &storage_id)
            .unwrap()
            .recipe
            .as_ref()
            .unwrap();
        assert!(recipe.entries.contains_key(&new_file_id));
        assert!(!recipe.entries.contains_key(&old_file_id));
    }

    #[test]
    fn project_content_nested_tree_and_empty_directory_round_trip_then_delete_safely() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("project-files-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));

        let source = register(&repo);
        let source_root = temp.path().join("machine-a/project");
        std::fs::create_dir_all(source_root.join("docs/specs")).unwrap();
        std::fs::create_dir_all(source_root.join("docs/empty")).unwrap();
        std::fs::write(source_root.join("docs/specs/a.md"), b"portable spec\n").unwrap();
        std::fs::write(source_root.join("docs/file_b.md"), b"original b\n").unwrap();
        std::fs::write(source_root.join("excluded.txt"), b"do not publish\n").unwrap();
        bind_and_link_test_replica(
            &repo,
            &source,
            &storage_id,
            &source_root,
            &temp.path().join("machine-a/codex"),
        );

        let scanned =
            inspect_project_files_with_repository(&repo, &source.local_project_id, &storage_id)
                .unwrap();
        assert_eq!(
            scanned.eligibility.state,
            ProjectFileSyncEligibilityState::Eligible
        );
        assert!(scanned
            .entries
            .iter()
            .all(|entry| entry.selected_after_scan));
        let excluded_id = scanned
            .entries
            .iter()
            .find(|entry| entry.relative_path == "excluded.txt")
            .unwrap()
            .descriptor
            .resource_id
            .clone();
        let mut recipe = reviewed_project_content_recipe(&scanned);
        recipe.entries.remove(&excluded_id);
        let selected_ids = recipe.entries.keys().cloned().collect::<BTreeSet<_>>();
        let pushed = push_bundle_reviewed_with_repository(
            &repo,
            &source.local_project_id,
            &storage_id,
            recipe,
            ProjectContentPushReview {
                git_history_review_token: None,
                credential_redaction_enabled: true,
                subagent_selections: BTreeMap::new(),
                review_token: scanned.review_token.clone(),
                removal_ids: BTreeSet::new(),
                acknowledged_warning_digests: BTreeSet::new(),
            },
            &mut |_| {},
        )
        .unwrap();
        assert!(pushed.success, "{}", pushed.message);

        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let first_snapshot = engine.inspect(&source.bundle_id).unwrap();
        let first_project_scope = first_snapshot
            .manifest
            .scope(&SyncScopeKey::Project)
            .unwrap();
        assert!(first_project_scope
            .files
            .contains_key(&mallard_domain::LogicalPath::parse("project/docs/specs/a.md").unwrap()));
        assert!(!first_project_scope
            .files
            .contains_key(&mallard_domain::LogicalPath::parse("project/excluded.txt").unwrap()));
        for directory in ["project/docs", "project/docs/specs", "project/docs/empty"] {
            assert!(first_project_scope
                .directories
                .contains_key(&mallard_domain::LogicalPath::parse(directory).unwrap()));
        }
        let config_after_push = repo.load_config().unwrap();
        let source_link = config_after_push
            .links
            .iter()
            .find(|link| {
                link.local_project_id == source.local_project_id && link.storage_id == storage_id
            })
            .unwrap();
        assert!(source_link
            .project_content_preferences
            .excluded_resource_ids
            .contains(&excluded_id));
        let relinked = save_project_link_with_repository(
            &repo,
            SaveProjectLinkRequest {
                local_project_id: source.local_project_id.clone(),
                storage_id: storage_id.clone(),
                pinned: false,
            },
        )
        .unwrap();
        assert!(relinked
            .project_content_preferences
            .excluded_resource_ids
            .contains(&excluded_id));
        let rescanned =
            inspect_project_files_with_repository(&repo, &source.local_project_id, &storage_id)
                .unwrap();
        let excluded = rescanned
            .entries
            .iter()
            .find(|entry| entry.descriptor.resource_id == excluded_id)
            .unwrap();
        assert!(!excluded.selected_after_scan);
        assert!(!excluded.selected_in_recipe);
        let other_storage_id = StorageId::parse("project-files-other-store").unwrap();
        add_local_storage(&repo, &other_storage_id, &temp.path().join("other-store"));
        save_project_link_with_repository(
            &repo,
            SaveProjectLinkRequest {
                local_project_id: source.local_project_id.clone(),
                storage_id: other_storage_id.clone(),
                pinned: true,
            },
        )
        .unwrap();
        let other_destination_scan = inspect_project_files_with_repository(
            &repo,
            &source.local_project_id,
            &other_storage_id,
        )
        .unwrap();
        assert!(
            other_destination_scan
                .entries
                .iter()
                .find(|entry| entry.descriptor.resource_id == excluded_id)
                .unwrap()
                .selected_after_scan
        );

        let git_race_target = register(&repo);
        let git_race_root = temp.path().join("machine-git-race/project");
        let git_race_binding = bind_and_link_test_replica(
            &repo,
            &git_race_target,
            &storage_id,
            &git_race_root,
            &temp.path().join("machine-git-race/codex"),
        );
        let git_race_plan = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&storage_id, &git_race_target.bundle_id, &git_race_binding)
            .unwrap();
        assert_eq!(
            git_race_plan
                .project_content_eligibility
                .as_ref()
                .unwrap()
                .state,
            ProjectFileSyncEligibilityState::Eligible
        );
        let git = std::process::Command::new("git")
            .arg("init")
            .arg(&git_race_root)
            .output()
            .unwrap();
        assert!(git.status.success());
        let error = ProjectSyncService::new(&repo)
            .apply_bundle_restore(
                &git_race_plan,
                git_race_plan
                    .actions
                    .iter()
                    .map(|action| action.action_id.clone())
                    .collect(),
            )
            .unwrap_err();
        assert!(error.contains("Git"), "{error}");
        assert!(!git_race_root.join("docs/specs/a.md").exists());

        let target = register(&repo);
        let target_root = temp.path().join("machine-b/project");
        let target_binding = bind_and_link_test_replica(
            &repo,
            &target,
            &storage_id,
            &target_root,
            &temp.path().join("machine-b/codex"),
        );
        let restore = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&storage_id, &target.bundle_id, &target_binding)
            .unwrap();
        assert_eq!(
            restore
                .actions
                .iter()
                .filter(|action| matches!(
                    action.kind,
                    RestoreActionKind::EnsureProjectDirectory { .. }
                ))
                .count(),
            3
        );
        assert_eq!(
            restore
                .actions
                .iter()
                .filter(|action| matches!(action.kind, RestoreActionKind::WriteProjectFile { .. }))
                .count(),
            2
        );
        assert!(restore
            .actions
            .iter()
            .all(|action| action.requires_explicit_approval));
        let approved = restore
            .actions
            .iter()
            .map(|action| action.action_id.clone())
            .collect();
        let applied = ProjectSyncService::new(&repo)
            .apply_bundle_restore(&restore, approved)
            .unwrap();
        assert!(applied.success, "{}", applied.message);
        assert_eq!(
            std::fs::read(target_root.join("docs/specs/a.md")).unwrap(),
            b"portable spec\n"
        );
        assert_eq!(
            std::fs::read(target_root.join("docs/file_b.md")).unwrap(),
            b"original b\n"
        );
        assert!(target_root.join("docs/empty").is_dir());

        std::fs::remove_file(source_root.join("docs/specs/a.md")).unwrap();
        std::fs::remove_file(source_root.join("docs/file_b.md")).unwrap();
        std::fs::remove_dir(source_root.join("docs/specs")).unwrap();
        std::fs::remove_dir(source_root.join("docs/empty")).unwrap();
        std::fs::remove_dir(source_root.join("docs")).unwrap();
        let removal_scan =
            inspect_project_files_with_repository(&repo, &source.local_project_id, &storage_id)
                .unwrap();
        assert!(removal_scan
            .entries
            .iter()
            .filter(|entry| selected_ids.contains(&entry.descriptor.resource_id))
            .all(|entry| !entry.local_present));
        let mut removal_recipe = repo
            .load_config()
            .unwrap()
            .links
            .iter()
            .find(|link| {
                link.local_project_id == source.local_project_id && link.storage_id == storage_id
            })
            .and_then(|link| link.recipe.clone())
            .unwrap();
        for resource_id in &selected_ids {
            removal_recipe.entries.remove(resource_id);
        }
        push_bundle_reviewed_with_repository(
            &repo,
            &source.local_project_id,
            &storage_id,
            removal_recipe,
            ProjectContentPushReview {
                git_history_review_token: None,
                credential_redaction_enabled: true,
                subagent_selections: BTreeMap::new(),
                review_token: removal_scan.review_token.clone(),
                removal_ids: selected_ids.clone(),
                acknowledged_warning_digests: BTreeSet::new(),
            },
            &mut |_| {},
        )
        .unwrap();

        let deletion_snapshot = engine.inspect(&source.bundle_id).unwrap();
        assert_eq!(deletion_snapshot.manifest.all_files().count(), 0);
        assert_eq!(deletion_snapshot.manifest.all_directories().count(), 0);
        assert_eq!(
            deletion_snapshot
                .manifest
                .all_tombstones()
                .filter(|(_, _, tombstone)| {
                    tombstone.target.kind.as_str() == contracts::PROJECT_CONTENT_FILE
                })
                .count(),
            2
        );
        assert_eq!(
            deletion_snapshot
                .manifest
                .all_tombstones()
                .filter(|(_, _, tombstone)| {
                    tombstone.target.kind.as_str() == contracts::PROJECT_CONTENT_DIRECTORY
                })
                .count(),
            3
        );

        let deletion_plan = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&storage_id, &target.bundle_id, &target_binding)
            .unwrap();
        assert_eq!(
            deletion_plan
                .actions
                .iter()
                .filter(|action| matches!(action.kind, RestoreActionKind::DeleteProjectFile { .. }))
                .count(),
            2
        );
        assert_eq!(
            deletion_plan
                .actions
                .iter()
                .filter(|action| matches!(
                    action.kind,
                    RestoreActionKind::DeleteProjectDirectory { .. }
                ))
                .count(),
            3
        );
        let approved = deletion_plan
            .actions
            .iter()
            .map(|action| action.action_id.clone())
            .collect();
        std::fs::write(target_root.join("docs/file_b.md"), b"locally changed b\n").unwrap();
        let deleted = ProjectSyncService::new(&repo)
            .apply_bundle_restore(&deletion_plan, approved)
            .unwrap();
        assert!(
            !deleted.success,
            "a changed local file or non-empty directory was removed"
        );
        assert!(!target_root.join("docs/specs/a.md").exists());
        assert_eq!(
            std::fs::read(target_root.join("docs/file_b.md")).unwrap(),
            b"locally changed b\n"
        );
        assert!(target_root.join("docs").is_dir());
        let backup_contains_file = walkdir::WalkDir::new(repo.backups_dir().unwrap())
            .into_iter()
            .filter_map(Result::ok)
            .filter(|entry| entry.file_type().is_file())
            .any(|entry| std::fs::read(entry.path()).ok().as_deref() == Some(b"portable spec\n"));
        assert!(
            backup_contains_file,
            "the deleted file did not receive a recoverable backup"
        );

        std::fs::remove_file(target_root.join("docs/file_b.md")).unwrap();
        let retry = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&storage_id, &target.bundle_id, &target_binding)
            .unwrap();
        let retry_approved = retry
            .actions
            .iter()
            .filter(|action| {
                matches!(
                    action.kind,
                    RestoreActionKind::DeleteProjectDirectory { .. }
                )
            })
            .map(|action| action.action_id.clone())
            .collect();
        let retried = ProjectSyncService::new(&repo)
            .apply_bundle_restore(&retry, retry_approved)
            .unwrap();
        assert!(retried.success, "{}", retried.message);
        assert!(!target_root.join("docs").exists());
    }

    #[test]
    fn initializing_git_after_project_content_review_rejects_push_without_a_head() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("git-race-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));
        let project = register(&repo);
        let project_root = temp.path().join("project");
        std::fs::create_dir_all(&project_root).unwrap();
        std::fs::write(project_root.join("notes.md"), b"notes").unwrap();
        bind_and_link_test_replica(
            &repo,
            &project,
            &storage_id,
            &project_root,
            &temp.path().join("codex"),
        );
        let scanned =
            inspect_project_files_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        assert_eq!(
            scanned.eligibility.state,
            ProjectFileSyncEligibilityState::Eligible
        );
        let git = std::process::Command::new("git")
            .arg("init")
            .arg(&project_root)
            .output()
            .unwrap();
        assert!(git.status.success());
        let error = push_bundle_reviewed_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
            reviewed_project_content_recipe(&scanned),
            ProjectContentPushReview {
                git_history_review_token: None,
                credential_redaction_enabled: true,
                subagent_selections: BTreeMap::new(),
                review_token: scanned.review_token,
                removal_ids: BTreeSet::new(),
                acknowledged_warning_digests: BTreeSet::new(),
            },
            &mut |_| {},
        )
        .unwrap_err();
        assert!(error.contains("Git"), "{error}");
        // The rejected push published nothing: only the link-time
        // registration claim stands in the storage.
        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let snapshot = engine.inspect(&project.bundle_id).unwrap();
        assert!(snapshot.manifest.is_registration_only());
    }

    #[test]
    fn project_content_warning_and_review_tokens_are_bound_to_exact_bytes() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("warning-review-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));
        let project = register(&repo);
        let project_root = temp.path().join("project");
        std::fs::create_dir_all(&project_root).unwrap();
        std::fs::write(project_root.join("notes.txt"), b"sample ghp_test_value_one").unwrap();
        bind_and_link_test_replica(
            &repo,
            &project,
            &storage_id,
            &project_root,
            &temp.path().join("codex"),
        );

        let first =
            inspect_project_files_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        let first_warning = first.entries[0].warning_digest.clone().unwrap();
        let recipe = reviewed_project_content_recipe(&first);
        let missing_ack = push_bundle_reviewed_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
            recipe.clone(),
            ProjectContentPushReview {
                git_history_review_token: None,
                credential_redaction_enabled: true,
                subagent_selections: BTreeMap::new(),
                review_token: first.review_token.clone(),
                removal_ids: BTreeSet::new(),
                acknowledged_warning_digests: BTreeSet::new(),
            },
            &mut |_| {},
        )
        .unwrap_err();
        assert!(missing_ack.contains("acknowledgement"));

        std::fs::write(project_root.join("notes.txt"), b"sample ghp_test_value_two").unwrap();
        let stale = push_bundle_reviewed_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
            recipe,
            ProjectContentPushReview {
                git_history_review_token: None,
                credential_redaction_enabled: true,
                subagent_selections: BTreeMap::new(),
                review_token: first.review_token,
                removal_ids: BTreeSet::new(),
                acknowledged_warning_digests: BTreeSet::from([first_warning.clone()]),
            },
            &mut |_| {},
        )
        .unwrap_err();
        assert!(stale.contains("changed after Scan"), "{stale}");

        let refreshed =
            inspect_project_files_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        let refreshed_warning = refreshed.entries[0].warning_digest.clone().unwrap();
        assert_ne!(first_warning, refreshed_warning);
        let published = push_bundle_reviewed_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
            reviewed_project_content_recipe(&refreshed),
            ProjectContentPushReview {
                git_history_review_token: None,
                credential_redaction_enabled: true,
                subagent_selections: BTreeMap::new(),
                review_token: refreshed.review_token,
                removal_ids: BTreeSet::new(),
                acknowledged_warning_digests: BTreeSet::from([refreshed_warning]),
            },
            &mut |_| {},
        )
        .unwrap();
        assert!(published.success);
        assert_eq!(
            published.message,
            format!("Published version {}", published.revision.unwrap())
        );
    }

    #[test]
    fn diverged_pull_preserves_the_local_project_file_as_a_visible_copy() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("preserve-copy-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));

        // Machine A publishes the reviewed base: a draft and a bystander.
        let source = register(&repo);
        let source_root = temp.path().join("machine-a/project");
        std::fs::create_dir_all(&source_root).unwrap();
        std::fs::write(source_root.join("draft.md"), b"reviewed v1\n").unwrap();
        std::fs::write(source_root.join("stable.md"), b"steady\n").unwrap();
        bind_and_link_test_replica(
            &repo,
            &source,
            &storage_id,
            &source_root,
            &temp.path().join("machine-a/codex"),
        );
        let scanned =
            inspect_project_files_with_repository(&repo, &source.local_project_id, &storage_id)
                .unwrap();
        let pushed = push_bundle_reviewed_with_repository(
            &repo,
            &source.local_project_id,
            &storage_id,
            reviewed_project_content_recipe(&scanned),
            ProjectContentPushReview {
                git_history_review_token: None,
                credential_redaction_enabled: true,
                subagent_selections: BTreeMap::new(),
                review_token: scanned.review_token.clone(),
                removal_ids: BTreeSet::new(),
                acknowledged_warning_digests: BTreeSet::new(),
            },
            &mut |_| {},
        )
        .unwrap();
        assert!(pushed.success, "{}", pushed.message);

        // Machine B pulls the base, then edits the draft locally.
        let target = register(&repo);
        let target_root = temp.path().join("machine-b/project");
        let target_binding = bind_and_link_test_replica(
            &repo,
            &target,
            &storage_id,
            &target_root,
            &temp.path().join("machine-b/codex"),
        );
        let first = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&storage_id, &target.bundle_id, &target_binding)
            .unwrap();
        let applied = ProjectSyncService::new(&repo)
            .apply_bundle_restore(
                &first,
                first
                    .actions
                    .iter()
                    .map(|action| action.action_id.clone())
                    .collect(),
            )
            .unwrap();
        assert!(applied.success, "{}", applied.message);
        assert_eq!(
            std::fs::read(target_root.join("draft.md")).unwrap(),
            b"reviewed v1\n"
        );
        std::fs::write(target_root.join("draft.md"), b"local twist\n").unwrap();

        // Machine A moves the storage side past the base.
        std::fs::write(source_root.join("draft.md"), b"storage v2\n").unwrap();
        let rescanned =
            inspect_project_files_with_repository(&repo, &source.local_project_id, &storage_id)
                .unwrap();
        let repushed = push_bundle_reviewed_with_repository(
            &repo,
            &source.local_project_id,
            &storage_id,
            reviewed_project_content_recipe(&rescanned),
            ProjectContentPushReview {
                git_history_review_token: None,
                credential_redaction_enabled: true,
                subagent_selections: BTreeMap::new(),
                review_token: rescanned.review_token.clone(),
                removal_ids: BTreeSet::new(),
                acknowledged_warning_digests: BTreeSet::new(),
            },
            &mut |_| {},
        )
        .unwrap();
        assert!(repushed.success, "{}", repushed.message);

        // B's next Pull plans the diverged draft with a preservation pin and
        // the untouched bystander without one — the base tells them apart.
        let second = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&storage_id, &target.bundle_id, &target_binding)
            .unwrap();
        let pin_for = |name: &str| {
            second.actions.iter().find_map(|action| match &action.kind {
                RestoreActionKind::WriteProjectFile {
                    logical_path,
                    preserve,
                    ..
                } if logical_path.as_str() == name => Some(preserve.clone()),
                _ => None,
            })
        };
        let draft_pin = pin_for("project/draft.md")
            .expect("draft write action")
            .expect("diverged draft must preserve");
        assert_eq!(
            draft_pin.copy_logical_path.as_str(),
            "project/draft-local-copy.md"
        );
        if let Some(stable_pin) = pin_for("project/stable.md") {
            assert!(stable_pin.is_none(), "fast-forward must not preserve");
        }
        let applied = ProjectSyncService::new(&repo)
            .apply_bundle_restore(
                &second,
                second
                    .actions
                    .iter()
                    .map(|action| action.action_id.clone())
                    .collect(),
            )
            .unwrap();
        assert!(applied.success, "{}", applied.message);
        assert_eq!(
            std::fs::read(target_root.join("draft.md")).unwrap(),
            b"storage v2\n"
        );
        assert_eq!(
            std::fs::read(target_root.join("draft-local-copy.md")).unwrap(),
            b"local twist\n"
        );

        // The copy is ordinary local content: B's next scan offers to push it.
        let target_scan =
            inspect_project_files_with_repository(&repo, &target.local_project_id, &storage_id)
                .unwrap();
        let copy_entry = target_scan
            .entries
            .iter()
            .find(|entry| entry.relative_path == "draft-local-copy.md")
            .expect("copy appears in the next scan");
        assert_eq!(copy_entry.state, "local_only");
        assert!(copy_entry.selected_after_scan);
        let draft_entry = target_scan
            .entries
            .iter()
            .find(|entry| entry.relative_path == "draft.md")
            .unwrap();
        assert_eq!(draft_entry.state, "synced");
    }

    #[test]
    fn project_open_commands_pin_the_checkout_and_assigned_profiles() {
        let binding = ProjectBinding {
            host_id: HostId::parse("00112233445566778899aabbccddeeff").unwrap(),
            replica_id: ReplicaId::parse("replica-test").unwrap(),
            local_project_id: LocalProjectId::parse("project-test").unwrap(),
            bundle_id: BundleId::parse("0123456789abcdef0123456789abcdef").unwrap(),
            project_root: "/tmp/client's project".to_string(),
            canonical_project_root: "/tmp/client's project".to_string(),
            profile_ids: BTreeMap::from([
                (
                    codex_key(),
                    LocalProviderProfileId::parse("profile-codex").unwrap(),
                ),
                (
                    ProviderKey::parse("claude").unwrap(),
                    LocalProviderProfileId::parse("profile-claude").unwrap(),
                ),
            ]),
            state: BindingState::Active,
            revision: 1,
            updated_at: 1,
        };
        let resolved = ResolvedBinding {
            binding,
            homes: BTreeMap::from([
                (codex_key(), "/tmp/custom codex/.codex".to_string()),
                (
                    ProviderKey::parse("claude").unwrap(),
                    "/tmp/custom claude/.claude".to_string(),
                ),
            ]),
        };

        let mut expected = vec![
            (
                "Codex — new",
                "CODEX_HOME='/tmp/custom codex/.codex' codex -C '/tmp/client'\\''s project'"
                    .to_string(),
            ),
            (
                "Codex — resume",
                "CODEX_HOME='/tmp/custom codex/.codex' codex resume -C '/tmp/client'\\''s project'"
                    .to_string(),
            ),
        ];
        let commands = project_open_commands(&resolved);
        // App discovery can omit the launch command. If present, it must
        // pin the same profile and checkout, whatever the install location.
        #[cfg(target_os = "macos")]
        if let Some((_, command)) = commands.iter().find(|(label, _)| label == "Codex app — new") {
            assert!(command.starts_with("'/usr/bin/open' -n -a '"));
            assert!(command.ends_with(
                " --env 'CODEX_HOME=/tmp/custom codex/.codex' 'codex://threads/new?path=%2Ftmp%2Fclient%27s%20project'"
            ));
        }
        #[cfg(any(target_os = "macos", windows))]
        expected.push((
            "Codex app — resume",
            "use Open in Codex (one deep link cannot carry both project and chat)".to_string(),
        ));
        expected.extend([
            (
                "Claude — new",
                "cd '/tmp/client'\\''s project' && CLAUDE_CONFIG_DIR='/tmp/custom claude/.claude' claude"
                    .to_string(),
            ),
            (
                "Claude — resume",
                "cd '/tmp/client'\\''s project' && CLAUDE_CONFIG_DIR='/tmp/custom claude/.claude' claude --resume"
                    .to_string(),
            ),
        ]);
        assert_eq!(
            commands
                .into_iter()
                .filter(|(label, _)| label != "Codex app — new")
                .collect::<Vec<_>>(),
            expected
                .into_iter()
                .map(|(label, command)| (label.to_string(), command))
                .collect::<Vec<_>>(),
            "adapters list their open commands in provider display order"
        );
    }

    #[test]
    fn desktop_assignment_never_overrides_rollout_authoritative_home() {
        let temp = tempfile::tempdir().unwrap();
        let repo =
            LocalStateRepository::from_home_dir(temp.path().join("agent-sync-home")).unwrap();
        let project = register(&repo);
        let project_root = temp.path().join("mallardInternal");
        let foreign_root = temp.path().join("mallard-ai-web");
        let codex_home = temp.path().join(".codex");
        let sessions = codex_home.join("sessions/2026/07/19");
        std::fs::create_dir_all(&project_root).unwrap();
        std::fs::create_dir_all(&foreign_root).unwrap();
        std::fs::create_dir_all(&sessions).unwrap();
        let profile_id = add_profile(&repo, &codex_key(), &codex_home);
        save_project_binding_with_repository(
            &repo,
            SaveProjectBindingRequest {
                local_project_id: project.local_project_id.clone(),
                project_root: project_root.to_string_lossy().into_owned(),
                profile_ids: BTreeMap::from([(codex_key(), profile_id)]),
                expected_revision: None,
            },
        )
        .unwrap();

        let matching_thread = "019f7500-0000-7000-8000-000000000010";
        let foreign_thread = "019f7500-0000-7000-8000-000000000011";
        let matching_path = sessions.join(format!("rollout-{}.jsonl", matching_thread));
        let foreign_path = sessions.join(format!("rollout-{}.jsonl", foreign_thread));
        let project_root_json = serde_json::to_string(project_root.to_str().unwrap()).unwrap();
        let foreign_root_json = serde_json::to_string(foreign_root.to_str().unwrap()).unwrap();
        let matching_source = format!(
            "{{\"type\":\"session_meta\",\"payload\":{{\"id\":\"{}\",\"cwd\":{}}}}}\n",
            matching_thread, project_root_json
        );
        std::fs::write(&matching_path, matching_source.as_bytes()).unwrap();
        let foreign_source = format!(
            "{{\"type\":\"session_meta\",\"payload\":{{\"id\":\"{}\",\"cwd\":{}}}}}\n{{\"type\":\"turn_context\",\"payload\":{{\"cwd\":{}}}}}\n",
            foreign_thread, foreign_root_json, project_root_json
        );
        std::fs::write(&foreign_path, foreign_source.as_bytes()).unwrap();
        std::fs::write(
            codex_home.join(".codex-global-state.json"),
            serde_json::to_vec_pretty(&serde_json::json!({
                "local-projects": {
                    "local-current": {
                        "id": "local-current",
                        "name": "mallardInternal",
                        "rootPaths": [project_root.to_str().unwrap()]
                    },
                    "local-foreign": {
                        "id": "local-foreign",
                        "name": "mallard-ai-web",
                        "rootPaths": [foreign_root.to_str().unwrap()]
                    }
                },
                "thread-project-assignments": {
                    (matching_thread): {
                        "projectId": "local-foreign",
                        "projectKind": "local"
                    },
                    (foreign_thread): {
                        "projectId": "local-current",
                        "projectKind": "local"
                    }
                },
                "thread-writable-roots": {},
                "thread-workspace-root-hints": {}
            }))
            .unwrap(),
        )
        .unwrap();

        let local = load_project_local_read(&repo, &project.local_project_id).unwrap();
        assert!(local
            .views
            .iter()
            .all(|view| view.provider_thread_id != foreign_thread));
        assert!(local
            .discovery
            .project_inventory()
            .resources
            .iter()
            .all(|resource| !resource.resource_id.contains(foreign_thread)));
        let activity = get_project_activity_with_repository(
            &repo,
            &project.local_project_id,
            None,
            None,
            Some(1),
            Some(90),
            false,
        )
        .unwrap();
        assert_eq!(activity.sessions.len(), 1, "{:?}", activity.sessions);
        let matching = activity
            .sessions
            .iter()
            .find(|session| session.provider_session_id.as_deref() == Some(matching_thread))
            .unwrap();
        assert!(matching.sync_blocked_reason.is_none());
        assert!(activity
            .sessions
            .iter()
            .all(|session| { session.provider_session_id.as_deref() != Some(foreign_thread) }));
        assert_eq!(
            std::fs::read(&matching_path).unwrap(),
            matching_source.as_bytes(),
            "Desktop reassignment must not rewrite the rollout"
        );
        assert_eq!(
            std::fs::read(&foreign_path).unwrap(),
            foreign_source.as_bytes(),
            "project assignment must not transfer or rewrite rollout ownership"
        );
    }

