    #[test]
    fn saving_existing_project_link_changes_only_pinned() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let project = register(&repo);
        let storage_id = StorageId::parse("backup").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));
        save_project_link_with_repository(
            &repo,
            SaveProjectLinkRequest {
                local_project_id: project.local_project_id.clone(),
                storage_id: storage_id.clone(),
                pinned: false,
            },
        )
        .unwrap();

        let observed_tail = mallard_domain::compute_portable_conversation_tail(
            TailPartitionKind::WholeThread,
            0,
            &[mallard_domain::CanonicalConversationMessage {
                message_id: mallard_domain::MessageId::parse("message-link-checkpoint").unwrap(),
                parent_message_id: None,
                semantic_fingerprint: "d".repeat(64),
            }],
        )
        .unwrap();
        let checkpoint = ConversationCheckpoint {
            accepted_subagents: Default::default(),
            generation: 5,
            accepted: None,
            accepted_local_tail: None,
            observed_tail,
            physical: PhysicalMappingState::Detached {
                expected_provider_thread_id: "0199a1b2-0000-7000-8000-000000000001".to_string(),
                expected_binding_revision: 8,
            },
            prefix_witness: None,
            binding_revision: 8,
        };
        let excluded_resource_id =
            ResourceId::parse(format!("project:content-file:{}", "e".repeat(64))).unwrap();
        let before = repo
            .mutate_config(|config| {
                let link = config
                    .links
                    .iter_mut()
                    .find(|link| {
                        link.local_project_id == project.local_project_id
                            && link.storage_id == storage_id
                    })
                    .unwrap();
                link.recipe = Some(BundleRecipe {
                    revision: 7,
                    ..BundleRecipe::default()
                });
                link.scope_bases.insert(
                    SyncScopeKey::Project,
                    ScopeBase {
                        scope: SyncScopeKey::Project,
                        scope_revision: 3,
                        scope_sha256: "b".repeat(64),
                        reviewed_in: RepositoryBase {
                            revision: 3,
                            commit_id: "commit-link-state".to_string(),
                            manifest_sha256: "a".repeat(64),
                            manifest_size: 1,
                        },
                        binding_revision: 8,
                        last_pull_at: Some(10),
                        last_push_at: Some(11),
                    },
                );
                link.project_content_preferences.revision = 4;
                link.project_content_preferences
                    .excluded_resource_ids
                    .insert(excluded_resource_id);
                link.conversation_checkpoints.insert(
                    SyncScopeKey::Provider(codex_key()),
                    BTreeMap::from([(
                        ThreadId::parse("thread-link-checkpoint").unwrap(),
                        checkpoint,
                    )]),
                );
                Ok(link.clone())
            })
            .unwrap();
        assert!(!before.conversation_checkpoints.is_empty());

        let updated = save_project_link_with_repository(
            &repo,
            SaveProjectLinkRequest {
                local_project_id: project.local_project_id.clone(),
                storage_id: storage_id.clone(),
                pinned: true,
            },
        )
        .unwrap();
        let mut expected = before;
        expected.pinned = true;
        assert_eq!(updated, expected);

        let persisted = repo
            .load_config()
            .unwrap()
            .links
            .into_iter()
            .find(|link| {
                link.local_project_id == project.local_project_id && link.storage_id == storage_id
            })
            .unwrap();
        assert_eq!(persisted, expected);
        assert!(!persisted.conversation_checkpoints.is_empty());
    }

    #[test]
    fn unlink_removes_the_destination_base_without_deleting_storage_data() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let project = register(&repo);
        let storage_id = StorageId::parse("backup").unwrap();
        let storage_root = temp.path().join("store");
        std::fs::create_dir_all(&storage_root).unwrap();
        let marker = storage_root.join("remote-object");
        std::fs::write(&marker, b"keep").unwrap();

        let mut config = repo.load_config().unwrap();
        config.storages.push(local_storage_config(
            storage_id.clone(),
            "Backup",
            &storage_root,
        ));
        repo.save_config(config).unwrap();
        save_project_link_with_repository(
            &repo,
            SaveProjectLinkRequest {
                local_project_id: project.local_project_id.clone(),
                storage_id: storage_id.clone(),
                pinned: true,
            },
        )
        .unwrap();
        repo.mutate_config(|config| {
            config
                .links
                .iter_mut()
                .find(|link| {
                    link.local_project_id == project.local_project_id
                        && link.storage_id == storage_id
                })
                .unwrap()
                .scope_bases
                .insert(
                    SyncScopeKey::Project,
                    ScopeBase {
                        scope: SyncScopeKey::Project,
                        scope_revision: 1,
                        scope_sha256: "b".repeat(64),
                        reviewed_in: RepositoryBase {
                            revision: 1,
                            commit_id: "commit-1".to_string(),
                            manifest_sha256: "a".repeat(64),
                            manifest_size: 1,
                        },
                        binding_revision: 1,
                        last_pull_at: Some(1),
                        last_push_at: None,
                    },
                );
            Ok(())
        })
        .unwrap();

        assert!(
            remove_project_link_with_repository(&repo, &project.local_project_id, &storage_id,)
                .unwrap()
        );
        let mut config = repo.load_config().unwrap();
        // The reviewed scope bases live on the link, so unlinking removes the
        // machine-local review state with it.
        assert!(config.links.is_empty());
        assert!(marker.exists());

        config.storages.retain(|storage| storage.id != storage_id);
        repo.save_config(config).unwrap();
        assert!(marker.exists());
        assert!(!remove_project_link_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap());
    }

    #[test]
    fn storage_clear_deletes_only_managed_remote_namespaces_and_keeps_configuration() {
        let temp = tempfile::tempdir().unwrap();
        let repo = LocalStateRepository::from_home_dir(temp.path().join("home")).unwrap();
        let catalog =
            CatalogStateRepository::from_home_dir(temp.path().join("catalog-home")).unwrap();
        let storage_id = StorageId::parse("storage-clear").unwrap();
        let storage_root = temp.path().join("storage");
        std::fs::create_dir_all(&storage_root).unwrap();
        let mut config = repo.load_config().unwrap();
        config.storages.push(local_storage_config(
            storage_id.clone(),
            "Clear me",
            &storage_root,
        ));
        let saved = repo.save_config(config).unwrap();
        let store = LocalObjectStore::open(&storage_root).unwrap();
        let repository_key = repository_object_key(
            &BundleId::parse("11111111111111111111111111111111").unwrap(),
            "_manifests/1-commit-a.json",
        )
        .unwrap();
        let library_key =
            library_object_key("library-22222222222222222222222222222222", "_tag.json").unwrap();
        store.put_immutable(&repository_key, b"repository").unwrap();
        store.put_immutable(&library_key, b"library").unwrap();
        std::fs::write(storage_root.join("keep.txt"), b"user data").unwrap();

        let stale =
            clear_storage_data_with_repositories(&repo, &catalog, &storage_id, saved.revision + 1)
                .unwrap_err();
        assert!(stale.contains("storage configuration changed"));
        assert!(store.get_metadata(&repository_key, 64).unwrap().is_some());
        assert!(store.get_metadata(&library_key, 64).unwrap().is_some());

        let result =
            clear_storage_data_with_repositories(&repo, &catalog, &storage_id, saved.revision)
                .unwrap();

        assert_eq!(result.repository_objects_deleted, 1);
        assert_eq!(result.library_objects_deleted, 1);
        assert!(store.get_metadata(&repository_key, 64).unwrap().is_none());
        assert!(store.get_metadata(&library_key, 64).unwrap().is_none());
        assert!(storage_root.join(STORAGE_MARKER_KEY).is_file());
        assert_eq!(
            std::fs::read(storage_root.join("keep.txt")).unwrap(),
            b"user data"
        );
        assert!(repo
            .load_config()
            .unwrap()
            .storages
            .iter()
            .any(|storage| storage.id == storage_id));
    }

    #[test]
    fn unlinked_project_can_adopt_a_matching_remote_bundle_when_storage_is_added_later() {
        let temp = tempfile::tempdir().unwrap();
        let repo = LocalStateRepository::from_home_dir(temp.path().join("home")).unwrap();
        let storage_id = StorageId::parse("shared").unwrap();
        let mut config = repo.load_config().unwrap();
        config.storages.push(local_storage_config(
            storage_id.clone(),
            "Shared",
            &temp.path().join("store"),
        ));
        repo.save_config(config).unwrap();

        let fingerprint = "a".repeat(64);
        let source_bundle = BundleId::parse("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa").unwrap();
        let source = register_local_project_with_repository(
            &repo,
            RegisterLocalProjectRequest {
                display_name: "Project A".to_string(),
                repository_fingerprint: Some(fingerprint.clone()),
                bundle_id: Some(source_bundle.clone()),
            },
        )
        .unwrap();
        let source_root = temp.path().join("project-a");
        let source_codex = temp.path().join("codex-home");
        std::fs::create_dir_all(&source_root).unwrap();
        ensure_test_git_repository(&source, &source_root);
        std::fs::create_dir_all(source_codex.join("sessions/2026/07/18")).unwrap();
        let source_session_id = "019f742a-a206-7932-876c-9db8d8ce575a";
        std::fs::write(
            source_codex
                .join("sessions/2026/07/18")
                .join(format!("rollout-{source_session_id}.jsonl")),
            command_test_transcript(
                source_session_id,
                &source_root,
                &[("message-source", "user", "hello")],
            ),
        )
        .unwrap();
        std::fs::write(
            source_codex.join("session_index.jsonl"),
            format!(
                "{{\"id\":\"{}\",\"thread_name\":\"Source conversation\"}}\n",
                source_session_id
            ),
        )
        .unwrap();
        let profile_id = add_profile(&repo, &codex_key(), &source_codex);
        save_project_binding_with_repository(
            &repo,
            SaveProjectBindingRequest {
                local_project_id: source.local_project_id.clone(),
                project_root: source_root.to_string_lossy().into_owned(),
                profile_ids: BTreeMap::from([(codex_key(), profile_id.clone())]),
                expected_revision: None,
            },
        )
        .unwrap();
        save_project_link_with_repository(
            &repo,
            SaveProjectLinkRequest {
                local_project_id: source.local_project_id.clone(),
                storage_id: storage_id.clone(),
                pinned: true,
            },
        )
        .unwrap();
        push_bundle_with_repository(&repo, &source.local_project_id, &storage_id).unwrap();
        let (_, source_engine) = storage_engine(&repo, &storage_id).unwrap();
        let source_snapshot = source_engine.inspect(&source_bundle).unwrap();
        let portable_conversation_id = source_snapshot
            .manifest
            .all_conversations()
            .next()
            .map(|(_, _, conversation)| conversation.resource_id.clone())
            .expect("source Push publishes its conversation");
        assert!(source_snapshot
            .manifest
            .provider_scope(&codex_key())
            .unwrap()
            .recipe
            .entries
            .contains_key(&portable_conversation_id));

        let other_bundle = BundleId::parse("cccccccccccccccccccccccccccccccc").unwrap();
        let other = register_local_project_with_repository(
            &repo,
            RegisterLocalProjectRequest {
                display_name: "Other repo".to_string(),
                repository_fingerprint: Some("c".repeat(64)),
                bundle_id: Some(other_bundle.clone()),
            },
        )
        .unwrap();
        let other_root = temp.path().join("other-repo");
        std::fs::create_dir_all(&other_root).unwrap();
        ensure_test_git_repository(&other, &other_root);
        save_project_binding_with_repository(
            &repo,
            SaveProjectBindingRequest {
                local_project_id: other.local_project_id.clone(),
                project_root: other_root.to_string_lossy().into_owned(),
                profile_ids: BTreeMap::from([(codex_key(), profile_id.clone())]),
                expected_revision: None,
            },
        )
        .unwrap();
        save_project_link_with_repository(
            &repo,
            SaveProjectLinkRequest {
                local_project_id: other.local_project_id.clone(),
                storage_id: storage_id.clone(),
                pinned: true,
            },
        )
        .unwrap();
        push_bundle_with_repository(&repo, &other.local_project_id, &storage_id).unwrap();

        let available = list_remote_bundle_snapshots_with_repository(&repo, &storage_id).unwrap();
        assert_eq!(available.len(), 2);
        assert!(available.iter().any(|bundle| {
            bundle.bundle_id == source_bundle
                && bundle.repository_fingerprint.as_deref() == Some(fingerprint.as_str())
        }));
        assert!(available
            .iter()
            .any(|bundle| bundle.bundle_id == other_bundle));

        let matches =
            find_remote_bundle_matches_with_repository(&repo, &storage_id, &fingerprint).unwrap();
        assert_eq!(matches.len(), 1);
        assert_eq!(matches[0].bundle_id, source_bundle);

        let local_bundle = BundleId::parse("bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb").unwrap();
        let replica = register_local_project_with_repository(
            &repo,
            RegisterLocalProjectRequest {
                display_name: "Project B".to_string(),
                repository_fingerprint: Some(fingerprint.clone()),
                bundle_id: Some(local_bundle.clone()),
            },
        )
        .unwrap();
        let replica_root = temp.path().join("project-b");
        std::fs::create_dir_all(&replica_root).unwrap();
        ensure_test_git_repository(&replica, &replica_root);
        save_project_binding_with_repository(
            &repo,
            SaveProjectBindingRequest {
                local_project_id: replica.local_project_id.clone(),
                project_root: replica_root.to_string_lossy().into_owned(),
                profile_ids: BTreeMap::from([(codex_key(), profile_id.clone())]),
                expected_revision: None,
            },
        )
        .unwrap();
        // This is the reported failure mode: linking first stores a fresh
        // local-only bundle ID which Pull cannot find remotely.
        save_project_link_with_repository(
            &repo,
            SaveProjectLinkRequest {
                local_project_id: replica.local_project_id.clone(),
                storage_id: storage_id.clone(),
                pinned: true,
            },
        )
        .unwrap();

        let connected = connect_project_to_remote_bundle_with_repository(
            &repo,
            ConnectProjectBundleRequest {
                local_project_id: replica.local_project_id.clone(),
                storage_id: storage_id.clone(),
                bundle_id: source_bundle.clone(),
                expected_bundle_id: local_bundle,
                pinned: true,
                allow_repository_mismatch: false,
            },
        )
        .unwrap();
        assert_eq!(connected.project.bundle_id, source_bundle);
        assert_eq!(connected.links.len(), 1);
        assert_eq!(connected.links[0].bundle_id, connected.project.bundle_id);
        assert!(!connected
            .project
            .recipe
            .entries
            .contains_key(&portable_conversation_id));
        let binding = connected.binding.unwrap();
        assert_eq!(binding.bundle_id, connected.project.bundle_id);
        assert_eq!(binding.project_root, replica_root.to_string_lossy());
        assert_eq!(binding.profile_ids.get(&codex_key()), Some(&profile_id));
        let (_, replica_engine) = storage_engine(&repo, &storage_id).unwrap();
        assert_eq!(
            replica_engine
                .inspect(&connected.project.bundle_id)
                .unwrap()
                .head
                .revision,
            2
        );
        let inventory =
            get_bundle_inventory_with_repository(&repo, &replica.local_project_id).unwrap();
        assert!(inventory.resources.iter().all(|resource| {
            resource.descriptor.resource_id != portable_conversation_id
                || resource.descriptor.kind != contracts::requirement()
        }));
        let comparison = get_project_thread_sync_comparison_with_repository(
            &repo,
            &replica.local_project_id,
            &storage_id,
        )
        .unwrap();
        assert!(comparison.entries.iter().any(|entry| {
            entry.resource_id == portable_conversation_id
                && entry.state == ThreadSyncState::StorageOnly
        }));

        let override_local_bundle = BundleId::parse("dddddddddddddddddddddddddddddddd").unwrap();
        let override_replica = register_local_project_with_repository(
            &repo,
            RegisterLocalProjectRequest {
                display_name: "Explicit repo override".to_string(),
                repository_fingerprint: Some(fingerprint.clone()),
                bundle_id: Some(override_local_bundle.clone()),
            },
        )
        .unwrap();
        let override_root = temp.path().join("override-replica");
        std::fs::create_dir_all(&override_root).unwrap();
        ensure_test_git_repository(&override_replica, &override_root);
        save_project_binding_with_repository(
            &repo,
            SaveProjectBindingRequest {
                local_project_id: override_replica.local_project_id.clone(),
                project_root: override_root.to_string_lossy().into_owned(),
                profile_ids: BTreeMap::from([(codex_key(), profile_id)]),
                expected_revision: None,
            },
        )
        .unwrap();
        save_project_link_with_repository(
            &repo,
            SaveProjectLinkRequest {
                local_project_id: override_replica.local_project_id.clone(),
                storage_id: storage_id.clone(),
                pinned: true,
            },
        )
        .unwrap();

        let rejected = connect_project_to_remote_bundle_with_repository(
            &repo,
            ConnectProjectBundleRequest {
                local_project_id: override_replica.local_project_id.clone(),
                storage_id: storage_id.clone(),
                bundle_id: other_bundle.clone(),
                expected_bundle_id: override_local_bundle.clone(),
                pinned: true,
                allow_repository_mismatch: false,
            },
        )
        .unwrap_err();
        assert!(rejected.contains("different repository"));

        let overridden = connect_project_to_remote_bundle_with_repository(
            &repo,
            ConnectProjectBundleRequest {
                local_project_id: override_replica.local_project_id,
                storage_id,
                bundle_id: other_bundle,
                expected_bundle_id: override_local_bundle,
                pinned: true,
                allow_repository_mismatch: true,
            },
        )
        .unwrap();
        assert_eq!(
            overridden.project.repository_fingerprint.as_deref(),
            Some("cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc")
        );
    }

    #[test]
    fn pull_readiness_uses_the_selected_storage_and_current_revision() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let first_storage_id = StorageId::parse("first-linked-store").unwrap();
        let selected_storage_id = StorageId::parse("selected-pull-store").unwrap();
        let mut config = repo.load_config().unwrap();
        config.storages.extend([
            local_storage_config(
                first_storage_id.clone(),
                "First linked store",
                &temp.path().join("first-store"),
            ),
            local_storage_config(
                selected_storage_id.clone(),
                "Selected Pull store",
                &temp.path().join("selected-store"),
            ),
        ]);
        repo.save_config(config).unwrap();

        let project = register(&repo);
        let project_root = temp.path().join("project");
        std::fs::create_dir_all(&project_root).unwrap();
        let profile_id = add_profile(&repo, &codex_key(), &temp.path().join("codex-home"));
        save_project_binding_with_repository(
            &repo,
            SaveProjectBindingRequest {
                local_project_id: project.local_project_id.clone(),
                project_root: project_root.to_string_lossy().into_owned(),
                profile_ids: BTreeMap::from([(codex_key(), profile_id)]),
                expected_revision: None,
            },
        )
        .unwrap();
        for storage_id in [&first_storage_id, &selected_storage_id] {
            save_project_link_with_repository(
                &repo,
                SaveProjectLinkRequest {
                    local_project_id: project.local_project_id.clone(),
                    storage_id: storage_id.clone(),
                    pinned: true,
                },
            )
            .unwrap();
        }

        // Identical content republishes as a no-op, so each push appends a
        // turn to an owned Codex session first to genuinely advance the
        // revision on its storage.
        let session_id = "019f7500-0000-7000-8000-0000000000aa";
        let sessions = temp.path().join("codex-home/sessions/2026/07/20");
        std::fs::create_dir_all(&sessions).unwrap();
        let rollout = sessions.join(format!("rollout-{}.jsonl", session_id));
        std::fs::write(
            &rollout,
            command_test_transcript(session_id, &project_root, &[]),
        )
        .unwrap();
        let mut turn = 0_usize;
        let mut advance_local_content =
            move || {
                turn += 1;
                std::fs::OpenOptions::new()
                .append(true)
                .open(&rollout)
                .and_then(|mut file| {
                    use std::io::Write as _;
                    let parent_id = (turn > 1).then(|| format!("turn-{}", turn - 1));
                    writeln!(file, "{}", serde_json::json!({
                        "ordinal": turn as u64,
                        "type": "response_item",
                        "payload": {
                            "type": "message",
                            "id": format!("turn-{turn}"),
                            "parent_id": parent_id,
                            "role": "user",
                            "content": [{"type": "input_text", "text": format!("turn {turn}")}],
                        },
                    }))
                })
                .unwrap();
            };
        for _ in 0..2 {
            advance_local_content();
            push_bundle_with_repository(&repo, &project.local_project_id, &first_storage_id)
                .unwrap();
        }
        for _ in 0..3 {
            advance_local_content();
            push_bundle_with_repository(&repo, &project.local_project_id, &selected_storage_id)
                .unwrap();
        }

        let binding = repo
            .load_bindings()
            .unwrap()
            .active_for(&project.local_project_id)
            .cloned()
            .unwrap();
        let restore = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&selected_storage_id, &project.bundle_id, &binding)
            .unwrap();

        assert_eq!(restore.storage_id, selected_storage_id);
        assert_eq!(restore.revision, 4);
        assert_eq!(
            get_restore_readiness_with_repository(
                &repo,
                &project.local_project_id,
                &selected_storage_id
            )
            .unwrap()
            .bundle_id,
            restore.bundle_id
        );

        advance_local_content();
        push_bundle_with_repository(&repo, &project.local_project_id, &selected_storage_id)
            .unwrap();
        assert_eq!(
            get_restore_readiness_with_repository(
                &repo,
                &project.local_project_id,
                &selected_storage_id
            )
            .unwrap()
            .bundle_id,
            restore.bundle_id
        );
    }

    #[test]
    fn push_without_changes_is_a_noop_that_records_the_base() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("noop-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);

        let session_id = "019f7500-0000-7000-8000-0000000000bb";
        let sessions = codex_home.join("sessions/2026/07/21");
        std::fs::create_dir_all(&sessions).unwrap();
        std::fs::write(
            sessions.join(format!("rollout-{}.jsonl", session_id)),
            command_test_transcript(
                session_id,
                &project_root,
                &[("message-noop", "user", "hello")],
            ),
        )
        .unwrap();

        let first =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert!(first.success);
        assert_eq!(first.revision, Some(2));
        assert!(
            first.message.contains("Published version 2"),
            "{}",
            first.message
        );
        let (first_base, first_scopes) =
            reviewed_link_state(&repo, &project.local_project_id, &storage_id);

        let repeat =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert!(repeat.success);
        assert_eq!(repeat.revision, Some(2));
        assert!(
            repeat.message.contains("Already up to date"),
            "{}",
            repeat.message
        );
        assert!(!repeat.results.is_empty());
        assert!(repeat
            .results
            .iter()
            .all(|result| result.state == "unchanged"));
        assert_eq!(repeat.resources_changed, Some(0));

        let (repeat_base, repeat_scopes) =
            reviewed_link_state(&repo, &project.local_project_id, &storage_id);
        assert_eq!(repeat_base.revision, first_base.revision);
        assert_eq!(repeat_base.manifest_sha256, first_base.manifest_sha256);
        let codex_scope = SyncScopeKey::Provider(codex_key());
        assert!(
            repeat_scopes[&codex_scope].last_push_at >= first_scopes[&codex_scope].last_push_at
        );

        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let snapshot = engine.inspect(&project.bundle_id).unwrap();
        assert_eq!(snapshot.head.revision, 2);
        assert_eq!(repeat_base.manifest_size, snapshot.head.manifest_size);
    }

    /// The cloud id every stored session of `snapshot` has, by provider id.
    fn stored_cloud_ids(snapshot: &BundleSnapshot) -> BTreeMap<Option<String>, CloudThreadId> {
        snapshot
            .manifest
            .all_conversations()
            .map(|(_, cloud_id, thread)| (thread.source_thread_id.clone(), cloud_id.clone()))
            .collect()
    }

    /// The comparison row of one local provider session.
    fn comparison_entry<'a>(
        comparison: &'a ThreadSyncComparison,
        provider_thread_id: &str,
    ) -> &'a ThreadSyncEntry {
        comparison
            .entries
            .iter()
            .find(|entry| entry.provider_thread_id.as_deref() == Some(provider_thread_id))
            .unwrap_or_else(|| panic!("no comparison row for '{provider_thread_id}'"))
    }

    /// Story 1, with rows S1 and A3: another computer cleared the storage and
    /// nobody has pushed since. This computer's bases and acceptance name a
    /// history the storage no longer has. They are read as absent and never
    /// deleted by a refresh. Push is open, every session is a new task under
    /// the cloud id it already has, and one Push writes the stream's first
    /// record. No unlink, no reset and no Pull.
    #[test]
    fn a_cleared_storage_is_pushed_again_without_an_unlink_or_a_reset() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("missing-history-store").unwrap();
        let storage_root = temp.path().join("store");
        add_local_storage(&repo, &storage_id, &storage_root);
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let session = "019f7500-0000-7000-8000-0000000000bc";
        write_codex_session(&codex_home, session, &project_root);

        let first =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(first.revision, Some(2));
        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let cloud_ids_before = stored_cloud_ids(
            engine
                .observe(&project.bundle_id)
                .unwrap()
                .snapshot()
                .unwrap(),
        );
        assert_eq!(cloud_ids_before.len(), 1);
        let saved_link = |repo: &LocalStateRepository| {
            let config = repo.load_config().unwrap();
            project_link(&config, &project.local_project_id, &storage_id)
                .unwrap()
                .clone()
        };
        let reviewed = saved_link(&repo);
        assert!(reviewed
            .conversation_checkpoints
            .values()
            .flat_map(BTreeMap::values)
            .all(|checkpoint| checkpoint.accepted.is_some()));

        wipe_remote_bundle(&storage_root, &project.bundle_id);

        // The refresh reports the missing history and decides every row
        // without the stale records. It deletes none of them: a short
        // listing looks the same as a clear.
        let comparison = get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::RemoteMissing { base_revision: 2 }
        );
        let entry = comparison_entry(&comparison, session);
        assert_eq!(entry.push_decision.blocker, None);
        assert_eq!(
            entry.push_decision.action,
            ConversationReviewAction::CreateCloud
        );
        assert_eq!(
            entry.pull_decision.action,
            ConversationReviewAction::ReportLocalOnly
        );
        assert!(comparison
            .scopes
            .iter()
            .all(|scope| scope.continuity == ScopeContinuity::Fresh));
        assert_eq!(saved_link(&repo), reviewed);

        let context =
            prepare_push_review_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        assert_eq!(
            context.destination_status,
            PushDestinationStatus::Ready { revision: None }
        );
        assert_eq!(
            get_push_destination_status_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap(),
            context.destination_status
        );
        assert_eq!(saved_link(&repo).scope_bases, reviewed.scope_bases);

        // One Push recreates the storage: the first record of the new
        // history carries the content, under the cloud id the session had.
        let republished =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert!(republished.success, "{}", republished.message);
        assert_eq!(republished.revision, Some(1));
        let observation = engine.observe(&project.bundle_id).unwrap();
        assert_eq!(observation.mainline.names().len(), 1);
        assert_eq!(
            stored_cloud_ids(observation.snapshot().unwrap()),
            cloud_ids_before
        );

        // The next refresh reads in sync, and no record of the old history
        // is left on the link.
        let settled = get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();
        assert_eq!(
            settled.remote_continuity,
            RemoteContinuity::InSync { revision: 1 }
        );
        assert_eq!(
            comparison_entry(&settled, session).state,
            ThreadSyncState::Synced
        );
        let link = saved_link(&repo);
        assert!(repository_bases(&link).all(|base| observation
            .mainline
            .contains(base.revision, &base.commit_id)));
        assert!(link
            .conversation_checkpoints
            .values()
            .flat_map(BTreeMap::values)
            .filter_map(|checkpoint| checkpoint.accepted.as_ref())
            .all(|accepted| observation
                .mainline
                .contains_commit(&accepted.accepted_at_commit_id)));
    }

    /// A project that is not managed by Git, with `draft.md`, linked to a
    /// local storage. Its files are one storage area, compared against the
    /// manifest the area's base names (PLAN_CLEARED_STORAGE_PUSH_AGAIN.md,
    /// section 2.3). One repository plays both computers: the other one's
    /// Push saves its records on this link, and `restore_scope_bases` puts
    /// this computer's own back.
    struct FilesWorld {
        repo: LocalStateRepository,
        storage_id: StorageId,
        storage_root: PathBuf,
        project: LocalProjectRegistration,
        project_root: PathBuf,
    }

    impl FilesWorld {
        fn new(temp: &tempfile::TempDir, storage: &str) -> Self {
            let repo = repository(temp);
            let storage_id = StorageId::parse(storage).unwrap();
            let storage_root = temp.path().join("store");
            add_local_storage(&repo, &storage_id, &storage_root);
            let project = register(&repo);
            let project_root = temp.path().join("project");
            std::fs::create_dir_all(&project_root).unwrap();
            std::fs::write(project_root.join("draft.md"), b"first draft\n").unwrap();
            bind_and_link_test_replica(
                &repo,
                &project,
                &storage_id,
                &project_root,
                &temp.path().join("codex-home"),
            );
            Self {
                repo,
                storage_id,
                storage_root,
                project,
                project_root,
            }
        }

        fn write(&self, relative_path: &str, bytes: &[u8]) {
            std::fs::write(self.project_root.join(relative_path), bytes).unwrap();
        }

        fn read(&self, relative_path: &str) -> Vec<u8> {
            std::fs::read(self.project_root.join(relative_path)).unwrap()
        }

        /// The files review, as Scan shows it.
        fn files(&self) -> ProjectContentInventory {
            inspect_project_files_with_repository(
                &self.repo,
                &self.project.local_project_id,
                &self.storage_id,
            )
            .unwrap()
        }

        fn state_of(files: &ProjectContentInventory, relative_path: &str) -> String {
            files
                .entries
                .iter()
                .find(|entry| entry.relative_path == relative_path)
                .unwrap_or_else(|| panic!("no files row for '{relative_path}'"))
                .state
                .clone()
        }

        /// Push the scanned files, as the Push review does after a Scan.
        fn push_files(&self) -> ProjectOperationResult {
            let files = self.files();
            let review = prepare_push_review_with_repository(
                &self.repo,
                &self.project.local_project_id,
                &self.storage_id,
            )
            .unwrap();
            let mut approval = PushApproval::recommended(&review, &self.storage_id);
            approval
                .recipe
                .entries
                .extend(reviewed_project_content_recipe(&files).entries);
            approval.project_content_review_token = files.review_token;
            ProjectSyncService::new(&self.repo)
                .push_reviewed(&self.project.local_project_id, &self.storage_id, approval)
                .unwrap()
        }

        fn destination(&self) -> PushDestinationStatus {
            prepare_push_review_with_repository(
                &self.repo,
                &self.project.local_project_id,
                &self.storage_id,
            )
            .unwrap()
            .destination_status
        }

        fn scope_bases(&self) -> BTreeMap<SyncScopeKey, ScopeBase> {
            reviewed_link_state(&self.repo, &self.project.local_project_id, &self.storage_id).1
        }

        fn restore_scope_bases(&self, bases: &BTreeMap<SyncScopeKey, ScopeBase>) {
            self.repo
                .mutate_config(|config| {
                    config
                        .links
                        .iter_mut()
                        .find(|link| {
                            link.local_project_id == self.project.local_project_id
                                && link.storage_id == self.storage_id
                        })
                        .unwrap()
                        .scope_bases = bases.clone();
                    Ok(())
                })
                .unwrap();
        }

        fn pull_plan(&self) -> RestorePlan {
            let binding = self
                .repo
                .load_bindings()
                .unwrap()
                .active_for(&self.project.local_project_id)
                .cloned()
                .unwrap();
            ProjectSyncService::new(&self.repo)
                .plan_bundle_restore(&self.storage_id, &self.project.bundle_id, &binding)
                .unwrap()
        }

        fn pull_everything(&self, plan: &RestorePlan) {
            ProjectSyncService::new(&self.repo)
                .apply_bundle_restore(
                    plan,
                    plan.actions
                        .iter()
                        .map(|action| action.action_id.clone())
                        .collect(),
                )
                .unwrap();
        }

        /// The Pull's write of one project file, and whether it keeps this
        /// computer's version beside it: `Some` is "Replace file · keeps
        /// local copy", `None` a plain write.
        fn file_write(
            plan: &RestorePlan,
            relative_path: &str,
        ) -> Option<mallard_domain::ProjectFilePreservationPin> {
            let logical_path = format!("project/{relative_path}");
            plan.actions
                .iter()
                .find_map(|action| match &action.kind {
                    RestoreActionKind::WriteProjectFile {
                        logical_path: path,
                        preserve,
                        ..
                    } if path.as_str() == logical_path => Some(preserve.clone()),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("the Pull does not write '{relative_path}'"))
        }
    }

    /// Story 1 with project files, rows F1 and A3: another computer cleared
    /// the storage and nobody pushed since. The base of the project's files
    /// names a manifest the storage no longer has. It is read as absent, so
    /// every file is compared by content alone and reads "Only on this
    /// computer": none reads "unknown", nothing warns, Push is open, and one
    /// Push publishes the files. Reading deletes nothing.
    #[test]
    fn a_cleared_storage_with_project_files_reads_them_local_only_and_pushes_them() {
        let temp = tempfile::tempdir().unwrap();
        let world = FilesWorld::new(&temp, "cleared-files-store");
        world.write("notes.md", b"notes\n");
        let first = world.push_files();
        assert_eq!(first.revision, Some(2), "{}", first.message);
        assert!(world
            .files()
            .entries
            .iter()
            .all(|entry| entry.state == "synced"));
        let reviewed_bases = world.scope_bases();

        wipe_remote_bundle(&world.storage_root, &world.project.bundle_id);

        let files = world.files();
        assert_eq!(files.entries.len(), 2);
        for entry in &files.entries {
            assert_eq!(entry.state, "local_only", "{}", entry.relative_path);
            assert!(!entry.base_present, "{}", entry.relative_path);
        }
        assert!(files.warnings.is_empty(), "{:?}", files.warnings);
        assert_eq!(world.scope_bases(), reviewed_bases);
        assert_eq!(
            world.destination(),
            PushDestinationStatus::Ready { revision: None }
        );

        let republished = world.push_files();
        assert_eq!(republished.revision, Some(1), "{}", republished.message);
        let (_, engine) = storage_engine(&world.repo, &world.storage_id).unwrap();
        let stored = engine.inspect(&world.project.bundle_id).unwrap();
        let stored_files = project_content_versions(&stored.manifest)
            .unwrap()
            .values()
            .filter(|version| version.entry_type == ProjectContentEntryType::File)
            .map(|version| version.relative_path.clone())
            .collect::<BTreeSet<_>>();
        assert_eq!(
            stored_files,
            BTreeSet::from(["draft.md".to_string(), "notes.md".to_string()])
        );
        assert!(world
            .files()
            .entries
            .iter()
            .all(|entry| entry.state == "synced"));
    }

    /// Story 2 with project files, rows F3, F4 and A7: another computer
    /// cleared the storage and pushed files again. With the base read as
    /// absent, a file both hold with other content reads "Changed here and
    /// in storage", a file only the storage has reads "Only in storage",
    /// Push asks for a Pull, and the Pull replaces the changed file while
    /// keeping this computer's version beside it.
    #[test]
    fn a_recreated_storage_with_project_files_compares_by_content_and_the_pull_keeps_a_copy() {
        let temp = tempfile::tempdir().unwrap();
        let world = FilesWorld::new(&temp, "recreated-files-store");
        let first = world.push_files();
        assert_eq!(first.revision, Some(2), "{}", first.message);
        let reviewed_bases = world.scope_bases();

        // The other computer: the clear, then other content and one more file.
        wipe_remote_bundle(&world.storage_root, &world.project.bundle_id);
        world.write("draft.md", b"second draft\n");
        world.write("extra.md", b"only in storage\n");
        let recreated = world.push_files();
        assert_eq!(recreated.revision, Some(1), "{}", recreated.message);

        // This computer: its own files, and its records of the cleared history.
        world.write("draft.md", b"first draft\n");
        std::fs::remove_file(world.project_root.join("extra.md")).unwrap();
        world.restore_scope_bases(&reviewed_bases);

        let files = world.files();
        assert_eq!(FilesWorld::state_of(&files, "draft.md"), "diverged");
        assert_eq!(FilesWorld::state_of(&files, "extra.md"), "storage_only");
        assert!(files.entries.iter().all(|entry| entry.state != "unknown"));
        assert!(files.warnings.is_empty(), "{:?}", files.warnings);
        assert!(matches!(
            world.destination(),
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteWithoutBase,
                ..
            }
        ));

        let plan = world.pull_plan();
        let kept = FilesWorld::file_write(&plan, "draft.md").expect("draft.md keeps a local copy");
        assert_eq!(
            kept.copy_logical_path.as_str(),
            "project/draft-local-copy.md"
        );
        assert_eq!(FilesWorld::file_write(&plan, "extra.md"), None);
        world.pull_everything(&plan);
        assert_eq!(world.read("draft.md"), b"second draft\n");
        assert_eq!(world.read("draft-local-copy.md"), b"first draft\n");
        assert_eq!(world.read("extra.md"), b"only in storage\n");
        let after = world.files();
        assert_eq!(FilesWorld::state_of(&after, "draft.md"), "synced");
        assert_eq!(FilesWorld::state_of(&after, "extra.md"), "synced");
        assert_eq!(
            FilesWorld::state_of(&after, "draft-local-copy.md"),
            "local_only"
        );
        assert_eq!(
            world.destination(),
            PushDestinationStatus::Ready { revision: Some(1) }
        );
    }

    /// A readable stale manifest, after an interrupted clear: the clear
    /// deleted the records and stopped before the manifests, and another
    /// computer then pushed a first version with other content. The manifest
    /// this computer's base names can still be read, and judged against it
    /// a file this computer did not change would read "Newer in storage" and
    /// be replaced plainly. The base is off the selected chain, so nothing
    /// reads that manifest: the file reads "Changed here and in storage",
    /// and the Pull keeps a local copy.
    #[test]
    fn a_readable_stale_manifest_after_an_interrupted_clear_judges_no_file() {
        let temp = tempfile::tempdir().unwrap();
        let world = FilesWorld::new(&temp, "interrupted-clear-files-store");
        let first = world.push_files();
        assert_eq!(first.revision, Some(2), "{}", first.message);
        let reviewed_bases = world.scope_bases();

        std::fs::remove_dir_all(
            world
                .storage_root
                .join(".mallard/v1/repositories/_commits")
                .join(world.project.bundle_id.as_str()),
        )
        .unwrap();
        world.write("draft.md", b"second draft\n");
        let recreated = world.push_files();
        assert_eq!(recreated.revision, Some(1), "{}", recreated.message);
        world.write("draft.md", b"first draft\n");
        world.restore_scope_bases(&reviewed_bases);

        // The manifest the base names is still there, and it says that this
        // computer's draft.md is the reviewed one...
        let base = &reviewed_bases[&SyncScopeKey::Project];
        let (_, engine) = storage_engine(&world.repo, &world.storage_id).unwrap();
        let old = engine
            .inspect_manifest_version(
                &world.project.bundle_id,
                base.reviewed_in.revision,
                &base.reviewed_in.commit_id,
                base.reviewed_in.manifest_size,
                &base.reviewed_in.manifest_sha256,
            )
            .unwrap();
        assert_eq!(
            old.scope(&SyncScopeKey::Project)
                .unwrap()
                .files
                .get(&LogicalPath::parse("project/draft.md").unwrap())
                .unwrap()
                .sha256,
            mallard_domain::sha256_hex(b"first draft\n")
        );
        // ...and nothing reads it.
        let files = world.files();
        assert_eq!(FilesWorld::state_of(&files, "draft.md"), "diverged");
        assert!(files.warnings.is_empty(), "{:?}", files.warnings);
        let plan = world.pull_plan();
        assert!(FilesWorld::file_write(&plan, "draft.md").is_some());
    }

    /// A readable stale manifest, for a displaced base: this computer's
    /// second push changed draft.md, and another computer's record on the
    /// version before it, built a second earlier, shows up afterwards. The
    /// manifest of the displaced version can still be read, and judged
    /// against it draft.md would read "Newer in storage" and be replaced
    /// plainly, without the user's choice. The base is off the selected
    /// chain, so nothing reads that manifest: the file reads "Changed here
    /// and in storage", and the Pull keeps this computer's version beside
    /// the stored one.
    #[test]
    fn a_readable_stale_manifest_of_a_displaced_push_judges_no_file() {
        let temp = tempfile::tempdir().unwrap();
        let world = FilesWorld::new(&temp, "displaced-files-store");
        let first = world.push_files();
        assert_eq!(first.revision, Some(2), "{}", first.message);
        world.write("draft.md", b"second draft\n");
        let second = world.push_files();
        assert_eq!(second.revision, Some(3), "{}", second.message);
        let displaced_bases = world.scope_bases();

        let mine = record_names_at(&world.storage_root, &world.project.bundle_id, 3).remove(0);
        plant_rival_publication(
            &world.storage_root,
            &world.project.bundle_id,
            &record_names_at(&world.storage_root, &world.project.bundle_id, 2).remove(0),
            &format!("commit-{}", "e".repeat(24)),
            mine.created_at_ms() - 1_000,
        );
        assert_eq!(
            get_project_thread_sync_comparison_with_repository(
                &world.repo,
                &world.project.local_project_id,
                &world.storage_id,
            )
            .unwrap()
            .remote_continuity,
            RemoteContinuity::Displaced {
                base_revision: 3,
                remote_revision: 3,
                saved_by: SavedBy::Push,
            }
        );
        assert_eq!(world.scope_bases(), displaced_bases);

        // The manifest the base names is still there, and it says that this
        // computer's draft.md is the reviewed one...
        let base = &displaced_bases[&SyncScopeKey::Project];
        let (_, engine) = storage_engine(&world.repo, &world.storage_id).unwrap();
        let old = engine
            .inspect_manifest_version(
                &world.project.bundle_id,
                base.reviewed_in.revision,
                &base.reviewed_in.commit_id,
                base.reviewed_in.manifest_size,
                &base.reviewed_in.manifest_sha256,
            )
            .unwrap();
        assert_eq!(
            old.scope(&SyncScopeKey::Project)
                .unwrap()
                .files
                .get(&LogicalPath::parse("project/draft.md").unwrap())
                .unwrap()
                .sha256,
            mallard_domain::sha256_hex(b"second draft\n")
        );
        // ...and nothing reads it.
        let files = world.files();
        assert_eq!(FilesWorld::state_of(&files, "draft.md"), "diverged");
        assert!(files.warnings.is_empty(), "{:?}", files.warnings);
        let plan = world.pull_plan();
        let kept = FilesWorld::file_write(&plan, "draft.md").expect("draft.md keeps a local copy");
        assert_eq!(
            kept.copy_logical_path.as_str(),
            "project/draft-local-copy.md"
        );
        world.pull_everything(&plan);
        assert_eq!(world.read("draft.md"), b"first draft\n");
        assert_eq!(world.read("draft-local-copy.md"), b"second draft\n");
    }

    /// The record names of one bundle's stream at `revision`, as the storage
    /// folder holds them.
    fn record_names_at(
        storage_root: &Path,
        bundle_id: &BundleId,
        revision: u64,
    ) -> Vec<mallard_domain::RecordName> {
        let stream = storage_root
            .join(".mallard/v1/repositories/_commits")
            .join(bundle_id.as_str());
        let mut names = std::fs::read_dir(stream)
            .unwrap()
            .filter_map(|entry| {
                mallard_domain::RecordName::parse(entry.unwrap().file_name().to_str()?)
            })
            .filter(|name| name.revision() == revision)
            .collect::<Vec<_>>();
        names.sort_by_key(|name| name.file_name());
        names
    }

    /// Another computer's publication on `parent`, or a first publication
    /// when there is none: the content of `content_of` carried byte for byte
    /// under its own commit id, in a record that claims `created_at_ms`.
    fn plant_publication(
        storage_root: &Path,
        bundle_id: &BundleId,
        content_of: &mallard_domain::RecordName,
        parent: Option<&mallard_domain::RecordName>,
        commit_id: &str,
        created_at_ms: u64,
    ) -> mallard_domain::RecordName {
        plant_edited_publication(
            storage_root,
            bundle_id,
            content_of,
            parent,
            commit_id,
            created_at_ms,
            |_| {},
        )
    }

    /// `plant_publication` with the manifest edited before it is written,
    /// for a stored version that says something false about its content.
    fn plant_edited_publication(
        storage_root: &Path,
        bundle_id: &BundleId,
        content_of: &mallard_domain::RecordName,
        parent: Option<&mallard_domain::RecordName>,
        commit_id: &str,
        created_at_ms: u64,
        edit: impl FnOnce(&mut BundleManifest),
    ) -> mallard_domain::RecordName {
        let repositories = storage_root.join(".mallard/v1/repositories");
        let stream = repositories.join("_commits").join(bundle_id.as_str());
        let bundle = repositories.join(bundle_id.as_str());
        // A manifest's bytes are its one canonical serialization, so this
        // one is written from the typed manifest, like any writer's.
        let mut manifest: BundleManifest = serde_json::from_slice(
            &std::fs::read(bundle.join(format!(
                "_manifests/{}-{}.json",
                content_of.revision(),
                content_of.commit_id()
            )))
            .unwrap(),
        )
        .unwrap();
        manifest.revision = parent.map_or(1, |parent| parent.revision() + 1);
        manifest.commit_id = commit_id.to_string();
        edit(&mut manifest);
        let manifest_bytes = serde_json::to_vec(&manifest).unwrap();
        let manifest_key = format!("_manifests/{}-{commit_id}.json", manifest.revision);
        std::fs::write(bundle.join(&manifest_key), &manifest_bytes).unwrap();
        let mut record: serde_json::Value =
            serde_json::from_slice(&std::fs::read(stream.join(content_of.file_name())).unwrap())
                .unwrap();
        let fields = record.as_object_mut().unwrap();
        fields.remove("previous_commit_id");
        fields.remove("previous_record_sha256");
        if let Some(parent) = parent {
            record["previous_commit_id"] = serde_json::json!(parent.commit_id());
            record["previous_record_sha256"] = serde_json::json!(parent.token().record_sha256());
        }
        record["revision"] = serde_json::json!(manifest.revision);
        record["commit_id"] = serde_json::json!(commit_id);
        record["created_at_ms"] = serde_json::json!(created_at_ms);
        record["manifest_key"] = serde_json::json!(manifest_key);
        record["manifest_sha256"] = serde_json::json!(mallard_domain::sha256_hex(&manifest_bytes));
        record["manifest_size"] = serde_json::json!(manifest_bytes.len());
        let record_bytes = serde_json::to_vec(&record).unwrap();
        let name = mallard_domain::RecordName::new(
            manifest.revision,
            mallard_domain::PublicationToken::new(
                commit_id.to_string(),
                mallard_domain::sha256_hex(&record_bytes),
            )
            .unwrap(),
            parent.map(|parent| parent.token().clone()),
            created_at_ms,
        )
        .unwrap();
        std::fs::write(stream.join(name.file_name()), &record_bytes).unwrap();
        name
    }

    /// Another computer's publication on `parent`, carrying the parent's
    /// content: a sibling of whatever this computer publishes on it.
    fn plant_rival_publication(
        storage_root: &Path,
        bundle_id: &BundleId,
        parent: &mallard_domain::RecordName,
        rival_commit: &str,
        created_at_ms: u64,
    ) -> mallard_domain::RecordName {
        plant_publication(
            storage_root,
            bundle_id,
            parent,
            Some(parent),
            rival_commit,
            created_at_ms,
        )
    }

    /// Two computers push on the same version within seconds. The other
    /// one's record ranks first and lands between this push's listing and
    /// its write, so the listing after the write selects it. This push fails
    /// as a whole: no base, checkpoint, binding or receipt moves, the storage
    /// reads as an ordinary advanced one, and the next Push publishes the
    /// same session. Nothing is held and nothing needs a reset.
    #[test]
    fn a_push_that_loses_the_fork_window_fails_whole_and_the_next_push_publishes_it() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("fork-window-store").unwrap();
        let storage_root = temp.path().join("store");
        add_local_storage(&repo, &storage_id, &storage_root);
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let session_path = |session_id: &str| {
            codex_home
                .join("sessions/2026/07/22")
                .join(format!("rollout-{session_id}.jsonl"))
        };
        let accepted_session = "019f7500-0000-7000-8000-0000000000c1";
        write_codex_session(&codex_home, accepted_session, &project_root);
        let first =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(first.revision, Some(2));

        // A second session, first published by the push that loses.
        let new_session = "019f7500-0000-7000-8000-0000000000c2";
        write_codex_session(&codex_home, new_session, &project_root);
        let session_bytes = std::fs::read(session_path(new_session)).unwrap();
        let local_sync_state = || {
            (
                repo.load_config().unwrap(),
                repo.load_conversation_bindings().unwrap(),
                repo.load_materializations().unwrap(),
            )
        };
        let before = local_sync_state();

        // This push's record is built after the version it publishes on, so
        // a rival that claims the millisecond after that version ranks first.
        std::thread::sleep(Duration::from_millis(5));
        let rival_commit = format!("commit-{}", "e".repeat(24));
        use mallard_infrastructure::storage_core::publication::test_support;
        test_support::before_next_record_request({
            let (storage_root, bundle_id) = (storage_root.clone(), project.bundle_id.clone());
            let rival_commit = rival_commit.clone();
            move || {
                let parent = record_names_at(&storage_root, &bundle_id, 2).remove(0);
                plant_rival_publication(
                    &storage_root,
                    &bundle_id,
                    &parent,
                    &rival_commit,
                    parent.created_at_ms() + 1,
                );
            }
        });
        let error =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap_err();
        assert_eq!(
            error,
            mallard_infrastructure::storage_core::publication::REMOTE_CHANGED
        );

        // Nothing local moved, and both records are in the storage.
        assert_eq!(local_sync_state(), before);
        assert_eq!(
            std::fs::read(session_path(new_session)).unwrap(),
            session_bytes
        );
        assert_eq!(
            record_names_at(&storage_root, &project.bundle_id, 3).len(),
            2
        );

        // The base is an ancestor of the selected publication: an ordinary
        // advanced storage. No row is held, and Push is open.
        let comparison = get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::Advanced {
                base_revision: 2,
                remote_revision: 3
            }
        );
        assert_eq!(comparison.entries.len(), 2);
        assert!(comparison
            .entries
            .iter()
            .all(|entry| entry.push_decision.blocker.is_none()));
        assert_eq!(
            get_push_destination_status_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap(),
            PushDestinationStatus::Ready { revision: Some(3) }
        );

        // Pushing again publishes the session on the selected publication.
        let republished =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(republished.revision, Some(4), "{}", republished.message);
        assert!(republished.success);
        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let observation = engine.observe(&project.bundle_id).unwrap();
        assert_eq!(observation.mainline.names()[2].commit_id(), rival_commit);
        assert_eq!(
            observation
                .snapshot()
                .unwrap()
                .manifest
                .all_conversations()
                .count(),
            2
        );
        // The record that was not selected is still in the storage, on no
        // selected chain.
        let kept = record_names_at(&storage_root, &project.bundle_id, 3)
            .into_iter()
            .find(|name| name.commit_id() != rival_commit)
            .unwrap();
        assert!(!observation.mainline.contains(3, kept.commit_id()));
        assert_eq!(
            std::fs::read(session_path(new_session)).unwrap(),
            session_bytes
        );
    }

    /// The one loss that cannot fail the Push: the other computer listed
    /// before this one's record was visible, and its earlier-ranked record
    /// lands after this Push was confirmed. Recovery is a user action: the
    /// next refresh reports the Push `Displaced` and writes nothing, so the
    /// bases and the acceptance it saved are kept and read as absent, and
    /// the standing notice says so. The area that holds the displaced
    /// content was never reviewed on the selected history, so a Pull comes
    /// first; it installs nothing and marks the area reviewed, and the next
    /// Push publishes the same sessions under the same cloud ids.
    #[test]
    fn a_push_outranked_after_it_was_confirmed_reads_displaced_and_is_pushed_again() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("fork-window-store").unwrap();
        let storage_root = temp.path().join("store");
        add_local_storage(&repo, &storage_id, &storage_root);
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let sessions = codex_home.join("sessions/2026/07/22");
        std::fs::create_dir_all(&sessions).unwrap();
        let continued = "019f7500-0000-7000-8000-0000000000d1";
        let created = "019f7500-0000-7000-8000-0000000000d2";
        let session_path = |id: &str| sessions.join(format!("rollout-{id}.jsonl"));
        let write_session = |id: &str, messages: &[(&str, &str, &str)]| {
            std::fs::write(
                session_path(id),
                command_test_transcript(id, &project_root, messages),
            )
            .unwrap();
        };
        let cloud_ids = |snapshot: &BundleSnapshot| {
            snapshot
                .manifest
                .all_conversations()
                .map(|(_, cloud_id, thread)| (thread.source_thread_id.clone(), cloud_id.clone()))
                .collect::<BTreeMap<_, _>>()
        };
        let compare = || {
            get_project_thread_sync_comparison_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap()
        };
        let saved_config = || std::fs::read(repo.config_path()).unwrap();

        // Version 2 holds one session and stays selected for good.
        write_session(continued, &[("base", "user", "base")]);
        let first =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(first.revision, Some(2));

        // That session continues and a second one starts. The Push is
        // confirmed: its record is the only child of version 2.
        write_session(
            continued,
            &[("base", "user", "base"), ("next", "user", "continued here")],
        );
        write_session(created, &[("fresh", "user", "a new session")]);
        let local_bytes = [continued, created].map(|id| std::fs::read(session_path(id)).unwrap());
        let mine =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(mine.revision, Some(3));
        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let pushed = engine.observe(&project.bundle_id).unwrap();
        let pushed_ids = cloud_ids(pushed.snapshot().unwrap());
        assert_eq!(pushed_ids.len(), 2);

        // The other computer's record becomes visible only now: a sibling on
        // version 2, built a second earlier, that changed nothing this
        // computer's scope holds.
        let mine_name = record_names_at(&storage_root, &project.bundle_id, 3).remove(0);
        let rival_commit = format!("commit-{}", "e".repeat(24));
        plant_rival_publication(
            &storage_root,
            &project.bundle_id,
            &record_names_at(&storage_root, &project.bundle_id, 2).remove(0),
            &rival_commit,
            mine_name.created_at_ms() - 1_000,
        );

        // The refresh reports the displaced Push, and the saved state is
        // byte-identical before and after it: no base moved, and no
        // acceptance was forgotten.
        let before = saved_config();
        let comparison = compare();
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::Displaced {
                base_revision: 3,
                remote_revision: 3,
                saved_by: SavedBy::Push,
            }
        );
        assert_eq!(saved_config(), before);
        let config = repo.load_config().unwrap();
        let link = project_link(&config, &project.local_project_id, &storage_id).unwrap();
        assert!(repository_bases(link).all(|base| base.commit_id == mine_name.commit_id()));
        let checkpoints = link
            .conversation_checkpoints
            .values()
            .flat_map(BTreeMap::values)
            .collect::<Vec<_>>();
        assert_eq!(checkpoints.len(), 2);
        assert!(checkpoints.iter().all(|checkpoint| {
            checkpoint
                .accepted
                .as_ref()
                .is_some_and(|accepted| accepted.accepted_at_commit_id == mine_name.commit_id())
        }));

        // The codex area holds this computer's displaced content, which the
        // selected history never had: never reviewed here (A7), so a Pull
        // comes first. The stale acceptance reports no session as
        // synchronized: the sessions are read from their content, the
        // continued one as ahead of the stored version and the new one as a
        // new task under the cloud id it already has.
        let codex_area = |comparison: &ThreadSyncComparison| {
            comparison
                .scopes
                .iter()
                .find(|scope| scope.scope == "provider:codex")
                .expect("the codex area is compared")
                .continuity
                .clone()
        };
        // The area's revision is its own per-branch counter, not the
        // publication's.
        assert_eq!(
            codex_area(&comparison),
            ScopeContinuity::Unreviewed { remote_revision: 1 }
        );
        assert_eq!(comparison.entries.len(), 2);
        let row = |id: &str| comparison_entry(&comparison, id);
        assert_eq!(row(continued).state, ThreadSyncState::LocalAhead);
        assert_eq!(row(created).state, ThreadSyncState::LocalOnly);
        assert_eq!(
            row(continued).push_decision.action,
            ConversationReviewAction::Publish
        );
        assert_eq!(
            row(created).push_decision.action,
            ConversationReviewAction::CreateCloud
        );
        assert_eq!(
            get_push_destination_status_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap(),
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteWithoutBase,
                remote_revision: 3,
                base_revision: None,
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );

        // The Pull review carries the verdict. Applying it installs nothing
        // and marks the area as reviewed on the selected history, which ends
        // the notice.
        let binding = repo
            .load_bindings()
            .unwrap()
            .active_for(&project.local_project_id)
            .cloned()
            .unwrap();
        let plan = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&storage_id, &project.bundle_id, &binding)
            .unwrap();
        assert_eq!(
            plan.remote_continuity,
            Some(RemoteContinuity::Displaced {
                base_revision: 3,
                remote_revision: 3,
                saved_by: SavedBy::Push,
            })
        );
        ProjectSyncService::new(&repo)
            .apply_bundle_restore(
                &plan,
                plan.actions
                    .iter()
                    .map(|action| action.action_id.clone())
                    .collect(),
            )
            .unwrap();
        assert_eq!(
            compare().remote_continuity,
            RemoteContinuity::InSync { revision: 3 }
        );

        // Pushing again publishes both sessions on the selected history,
        // under the cloud ids the displaced Push gave them. The displaced
        // publication stays in the storage, never selected, and nothing
        // local was touched.
        let republished =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(republished.revision, Some(4), "{}", republished.message);
        assert!(republished.success);
        let observation = engine.observe(&project.bundle_id).unwrap();
        assert_eq!(observation.mainline.names()[2].commit_id(), rival_commit);
        assert_eq!(cloud_ids(observation.snapshot().unwrap()), pushed_ids);
        assert_eq!(observation.unselected, [mine_name]);
        let settled = compare();
        assert_eq!(
            settled.remote_continuity,
            RemoteContinuity::InSync { revision: 4 }
        );
        assert!(settled
            .entries
            .iter()
            .all(|entry| entry.push_decision.action == ConversationReviewAction::NoChanges));
        let config = repo.load_config().unwrap();
        let link = project_link(&config, &project.local_project_id, &storage_id).unwrap();
        assert!(link
            .conversation_checkpoints
            .values()
            .flat_map(BTreeMap::values)
            .filter_map(|checkpoint| checkpoint.accepted.as_ref())
            .all(|accepted| observation
                .mainline
                .contains_commit(&accepted.accepted_at_commit_id)));
        assert_eq!(
            [continued, created].map(|id| std::fs::read(session_path(id)).unwrap()),
            local_bytes
        );
    }

    /// The first Push of a project is outranked: the publication both
    /// computers share is the registration, which holds no scope. The base
    /// is kept and read as absent, so the area is a first publication target
    /// again, Push is open, and the session is published again under its
    /// cloud id.
    #[test]
    fn an_outranked_first_push_reads_displaced_and_is_pushed_again() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("fork-window-store").unwrap();
        let storage_root = temp.path().join("store");
        add_local_storage(&repo, &storage_id, &storage_root);
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        write_codex_session(
            &codex_home,
            "019f7500-0000-7000-8000-0000000000bf",
            &project_root,
        );
        let mine =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(mine.revision, Some(2));
        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let pushed = engine.observe(&project.bundle_id).unwrap();
        let pushed_id = pushed
            .snapshot()
            .unwrap()
            .manifest
            .all_conversations()
            .map(|(_, cloud_id, _)| cloud_id.clone())
            .next()
            .unwrap();

        let mine_name = record_names_at(&storage_root, &project.bundle_id, 2).remove(0);
        plant_rival_publication(
            &storage_root,
            &project.bundle_id,
            &record_names_at(&storage_root, &project.bundle_id, 1).remove(0),
            &format!("commit-{}", "e".repeat(24)),
            mine_name.created_at_ms() - 1_000,
        );

        // Revision order would have called this in sync: both are version 2.
        // The refresh reports it displaced and writes nothing.
        let saved_config = || std::fs::read(repo.config_path()).unwrap();
        let before = saved_config();
        let comparison = get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::Displaced {
                base_revision: 2,
                remote_revision: 2,
                saved_by: SavedBy::Push,
            }
        );
        assert_eq!(saved_config(), before);
        assert_eq!(comparison.entries.len(), 1);
        assert_eq!(
            comparison.entries[0].push_decision.action,
            ConversationReviewAction::CreateCloud
        );
        assert_eq!(
            get_push_destination_status_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap(),
            PushDestinationStatus::Ready { revision: Some(2) }
        );
        let republished =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(republished.revision, Some(3), "{}", republished.message);
        let observation = engine.observe(&project.bundle_id).unwrap();
        assert_eq!(
            observation
                .snapshot()
                .unwrap()
                .manifest
                .all_conversations()
                .map(|(_, cloud_id, _)| cloud_id.clone())
                .collect::<Vec<_>>(),
            [pushed_id]
        );
        assert_eq!(
            get_project_thread_sync_comparison_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap()
            .remote_continuity,
            RemoteContinuity::InSync { revision: 3 }
        );
    }

    /// A base the listing cannot connect to the selected chain proves no
    /// lost race: the stream was cleared and another computer pushed again
    /// while an interrupted clear left this computer's record behind. The
    /// link reads `Replaced`, never `Displaced`, and nothing is written.
    #[test]
    fn a_base_left_behind_by_an_interrupted_clear_reads_replaced_not_displaced() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("interrupted-clear-store").unwrap();
        let storage_root = temp.path().join("store");
        add_local_storage(&repo, &storage_id, &storage_root);
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        write_codex_session(
            &codex_home,
            "019f7500-0000-7000-8000-0000000000e1",
            &project_root,
        );
        push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        let before = std::fs::read(repo.config_path()).unwrap();

        // The clear deleted the first record and stopped; another computer
        // then published a first version of its own.
        let old_root = record_names_at(&storage_root, &project.bundle_id, 1).remove(0);
        plant_publication(
            &storage_root,
            &project.bundle_id,
            &old_root,
            None,
            &format!("commit-{}", "c".repeat(24)),
            old_root.created_at_ms() + 60_000,
        );
        std::fs::remove_file(
            storage_root
                .join(".mallard/v1/repositories/_commits")
                .join(project.bundle_id.as_str())
                .join(old_root.file_name()),
        )
        .unwrap();

        let comparison = get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::Replaced {
                base_revision: 2,
                remote_revision: 1
            }
        );
        assert_eq!(std::fs::read(repo.config_path()).unwrap(), before);
    }

    /// Story 2 on one storage area, rows A7 and A5: the storage was cleared
    /// and pushed again with other content. The replica whose bases name the
    /// cleared history reads the area as never reviewed here. It is asked
    /// for a Pull, never for an unlink or a reset, and an ordinary Pull
    /// replaces the stale bases.
    #[test]
    fn a_recreated_storage_asks_for_a_pull_and_the_pull_replaces_the_stale_bases() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("replaced-history-store").unwrap();
        let storage_root = temp.path().join("store");
        add_local_storage(&repo, &storage_id, &storage_root);
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        write_codex_session(
            &codex_home,
            "019f7500-0000-7000-8000-0000000000bd",
            &project_root,
        );

        let first =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(first.revision, Some(2));
        let (pre_wipe_base, pre_wipe_scopes) =
            reviewed_link_state(&repo, &project.local_project_id, &storage_id);

        // The clear, then one more session and a plain Push: the same bundle
        // id, a brand-new history that starts again at version 1.
        wipe_remote_bundle(&storage_root, &project.bundle_id);
        write_codex_session(
            &codex_home,
            "019f7500-0000-7000-8000-0000000000b0",
            &project_root,
        );
        let recreated =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(recreated.revision, Some(1), "{}", recreated.message);
        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let recreated_head = engine.inspect(&project.bundle_id).unwrap().head;
        assert_ne!(recreated_head.commit_id, pre_wipe_base.commit_id);

        // The other replica: same binding, but its recorded bases name the
        // cleared history.
        repo.mutate_config(|config| {
            config
                .links
                .iter_mut()
                .find(|link| {
                    link.local_project_id == project.local_project_id
                        && link.storage_id == storage_id
                })
                .unwrap()
                .scope_bases = pre_wipe_scopes.clone();
            Ok(())
        })
        .unwrap();

        // The Push review asks for a Pull of the area it writes...
        let context =
            prepare_push_review_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        assert_eq!(
            context.destination_status,
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteWithoutBase,
                remote_revision: 1,
                base_revision: None,
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );
        // ...the comparison shown by refresh names the cleared history, which
        // is what the standing notice reads...
        assert_eq!(
            context
                .thread_comparison
                .as_ref()
                .expect("thread comparison")
                .remote_continuity,
            RemoteContinuity::Replaced {
                base_revision: 2,
                remote_revision: 1
            }
        );
        let comparison = get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::Replaced {
                base_revision: 2,
                remote_revision: 1
            }
        );
        assert!(comparison
            .scopes
            .iter()
            .any(|scope| scope.scope == "provider:codex"
                && scope.continuity == ScopeContinuity::Unreviewed { remote_revision: 1 }));
        // ...and the push preflight fails with the same answer.
        let error =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap_err();
        assert!(
            error.contains("never been reviewed on this computer"),
            "got: {error}"
        );
        assert!(error.contains("pull and review"), "got: {error}");
        assert!(!error.contains("unlink"), "got: {error}");

        // The pull plan carries the verdict, and applying it replaces every
        // base of the cleared history.
        let binding = repo
            .load_bindings()
            .unwrap()
            .active_for(&project.local_project_id)
            .cloned()
            .unwrap();
        let plan = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&storage_id, &project.bundle_id, &binding)
            .unwrap();
        assert_eq!(
            plan.remote_continuity,
            Some(RemoteContinuity::Replaced {
                base_revision: 2,
                remote_revision: 1
            })
        );
        ProjectSyncService::new(&repo)
            .apply_bundle_restore(
                &plan,
                plan.actions
                    .iter()
                    .map(|action| action.action_id.clone())
                    .collect(),
            )
            .unwrap();
        assert_eq!(
            get_push_destination_status_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap(),
            PushDestinationStatus::Ready { revision: Some(1) }
        );
        assert_eq!(
            get_project_thread_sync_comparison_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap()
            .remote_continuity,
            RemoteContinuity::InSync { revision: 1 }
        );
        let (_, healed_scopes) = reviewed_link_state(&repo, &project.local_project_id, &storage_id);
        assert!(healed_scopes
            .values()
            .all(|base| base.reviewed_in.commit_id == recreated_head.commit_id));
    }

    /// Two computers on one storage: two local projects of one bundle, each
    /// with its own project folder and its own Codex home.
    struct TwoComputers {
        _temp: tempfile::TempDir,
        repo: LocalStateRepository,
        storage_id: StorageId,
        storage_root: PathBuf,
        bundle_id: BundleId,
        a: TestComputer,
        b: TestComputer,
    }

    struct TestComputer {
        project: LocalProjectRegistration,
        root: PathBuf,
        codex: PathBuf,
        binding: ProjectBinding,
    }

    impl TwoComputers {
        fn new(storage: &str) -> Self {
            Self::with_fingerprint(storage, Some("a".repeat(64)))
        }

        fn with_project_files(storage: &str) -> Self {
            Self::with_fingerprint(storage, None)
        }

        fn with_fingerprint(storage: &str, fingerprint: Option<String>) -> Self {
            let temp = tempfile::tempdir().unwrap();
            let repo = repository(&temp);
            let storage_id = StorageId::parse(storage).unwrap();
            let storage_root = temp.path().join("store");
            add_local_storage(&repo, &storage_id, &storage_root);
            let bundle_id = BundleId::parse("5eaf00d5eaf00d5eaf00d5eaf00d5eaf").unwrap();
            let computer = |name: &str| {
                let project = register_local_project_with_repository(
                    &repo,
                    RegisterLocalProjectRequest {
                        display_name: format!("Project on {name}"),
                        repository_fingerprint: fingerprint.clone(),
                        bundle_id: Some(bundle_id.clone()),
                    },
                )
                .unwrap();
                let root = temp.path().join(format!("project-{name}"));
                let codex = temp.path().join(format!("codex-{name}"));
                let binding =
                    bind_and_link_test_replica(&repo, &project, &storage_id, &root, &codex);
                TestComputer {
                    project,
                    root,
                    codex,
                    binding,
                }
            };
            let a = computer("a");
            let b = computer("b");
            Self {
                _temp: temp,
                repo,
                storage_id,
                storage_root,
                bundle_id,
                a,
                b,
            }
        }

        fn push(&self, computer: &TestComputer) -> ProjectOperationResult {
            push_bundle_with_repository(
                &self.repo,
                &computer.project.local_project_id,
                &self.storage_id,
            )
            .unwrap()
        }

        fn compare(&self, computer: &TestComputer) -> ThreadSyncComparison {
            get_project_thread_sync_comparison_with_repository(
                &self.repo,
                &computer.project.local_project_id,
                &self.storage_id,
            )
            .unwrap()
        }

        fn push_status(&self, computer: &TestComputer) -> PushDestinationStatus {
            get_push_destination_status_with_repository(
                &self.repo,
                &computer.project.local_project_id,
                &self.storage_id,
            )
            .unwrap()
        }

        fn plan_pull(&self, computer: &TestComputer) -> RestorePlan {
            ProjectSyncService::new(&self.repo)
                .plan_bundle_restore(&self.storage_id, &self.bundle_id, &computer.binding)
                .unwrap()
        }

        /// Pull every conversation row of `plan` that carries an action.
        fn pull_conversations(&self, plan: &RestorePlan) -> RestoreResult {
            let result = ProjectSyncService::new(&self.repo)
                .apply_bundle_restore(
                    plan,
                    plan.conversation_review
                        .iter()
                        .filter_map(|row| row.action_id.clone())
                        .collect(),
                )
                .unwrap();
            assert!(
                result.success,
                "{} — failed: {:?}",
                result.message, result.failed_actions
            );
            result
        }

        fn link(&self, computer: &TestComputer) -> ProjectStorageLink {
            let config = self.repo.load_config().unwrap();
            project_link(
                &config,
                &computer.project.local_project_id,
                &self.storage_id,
            )
            .unwrap()
            .clone()
        }

        /// The rollout this computer holds for one stored session.
        fn rollout_of(&self, computer: &TestComputer, cloud_thread_id: &CloudThreadId) -> PathBuf {
            let row = self
                .repo
                .load_conversation_bindings()
                .unwrap()
                .bindings
                .into_iter()
                .find(|row| {
                    row.local_project_id == computer.project.local_project_id
                        && row.cloud_thread_id.as_ref() == Some(cloud_thread_id)
                })
                .expect("the computer holds the stored session");
            let checkpoint = self.link(computer).conversation_checkpoints
                [&SyncScopeKey::Provider(codex_key())][&row.thread_id]
                .clone();
            let PhysicalMappingState::Ready { root_mapping, .. } = checkpoint.physical else {
                panic!("the session has no ready mapping");
            };
            PathBuf::from(root_mapping.root_path)
        }

        fn stored_cloud_ids(&self) -> BTreeMap<Option<String>, CloudThreadId> {
            let (_, engine) = storage_engine(&self.repo, &self.storage_id).unwrap();
            stored_cloud_ids(engine.observe(&self.bundle_id).unwrap().snapshot().unwrap())
        }

        /// Scan and push this computer's project files with its sessions, as
        /// the Push review does after a Scan.
        fn push_with_files(&self, computer: &TestComputer) -> ProjectOperationResult {
            let files = inspect_project_files_with_repository(
                &self.repo,
                &computer.project.local_project_id,
                &self.storage_id,
            )
            .unwrap();
            let review = prepare_push_review_with_repository(
                &self.repo,
                &computer.project.local_project_id,
                &self.storage_id,
            )
            .unwrap();
            let mut approval = PushApproval::recommended(&review, &self.storage_id);
            approval
                .recipe
                .entries
                .extend(reviewed_project_content_recipe(&files).entries);
            approval.project_content_review_token = files.review_token;
            ProjectSyncService::new(&self.repo)
                .push_reviewed(
                    &computer.project.local_project_id,
                    &self.storage_id,
                    approval,
                )
                .unwrap()
        }

        /// Apply every row of `plan`, its file actions and every conversation
        /// row that carries an action, and return the result as it is.
        fn pull_everything(&self, plan: &RestorePlan) -> RestoreResult {
            ProjectSyncService::new(&self.repo)
                .apply_bundle_restore(
                    plan,
                    plan.actions
                        .iter()
                        .map(|action| action.action_id.clone())
                        .chain(
                            plan.conversation_review
                                .iter()
                                .filter_map(|row| row.action_id.clone()),
                        )
                        .collect(),
                )
                .unwrap()
        }

        /// Every action id a review offers, files and sessions.
        fn ticked_ids(plan: &RestorePlan) -> BTreeSet<ActionId> {
            plan.actions
                .iter()
                .map(|action| action.action_id.clone())
                .chain(
                    plan.conversation_review
                        .iter()
                        .filter_map(|row| row.action_id.clone()),
                )
                .collect()
        }

        /// The machine-local sync documents, byte for byte: what a refused
        /// Pull leaves exactly as they were.
        fn local_documents(&self) -> Vec<(String, Vec<u8>)> {
            [
                "sync_config.json",
                "conversation_bindings.json",
                "materializations.json",
            ]
            .iter()
            .map(|name| {
                (
                    name.to_string(),
                    std::fs::read(self.repo.root().join(name)).unwrap_or_default(),
                )
            })
            .collect()
        }

        /// The stream's record at `revision`, as the storage names it.
        fn record_at(&self, revision: u64) -> mallard_domain::RecordName {
            record_names_at(&self.storage_root, &self.bundle_id, revision).remove(0)
        }

        /// The stored object of one project file of the selected version.
        fn object_path_of(&self, relative_path: &str) -> PathBuf {
            let (_, engine) = storage_engine(&self.repo, &self.storage_id).unwrap();
            let snapshot = engine.inspect(&self.bundle_id).unwrap();
            let (_, entry) = snapshot
                .manifest
                .find_file(&LogicalPath::parse(format!("project/{relative_path}")).unwrap())
                .expect("the file is stored");
            self.storage_root
                .join(".mallard/v1/repositories")
                .join(self.bundle_id.as_str())
                .join(&entry.object_key)
        }

        fn row_for<'a>(
            comparison: &'a ThreadSyncComparison,
            cloud_thread_id: &CloudThreadId,
        ) -> &'a ThreadSyncEntry {
            comparison
                .entries
                .iter()
                .find(|entry| entry.cloud_thread_id.as_ref() == Some(cloud_thread_id))
                .expect("a row for the stored session")
        }
    }

    /// A rollout path inside one computer's Codex home.
    fn codex_rollout_path(codex_home: &Path, session_id: &str) -> PathBuf {
        codex_home
            .join("sessions/2026/07/22")
            .join(format!("rollout-{session_id}.jsonl"))
    }

    /// T2 and Q1, then N1: another computer pushes a newer version between
    /// the review and the Pull. The Pull applies exactly the version it
    /// reviewed: the installed session has that version's turns, the bases
    /// name it, and the next comparison reads the newer version as changes
    /// to pull.
    #[test]
    fn a_pull_applies_the_version_it_reviewed_when_a_newer_one_was_pushed_since() {
        let world = TwoComputers::new("pinned-pull-store");
        let (a, b) = (&world.a, &world.b);
        let session = "019f7500-0000-7000-8000-0000000000a1";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        let cloud_id = world.stored_cloud_ids()[&Some(session.to_string())].clone();
        let plan = world.plan_pull(b);
        assert_eq!(plan.revision, 2);

        // Version 3: the session continued on A, pushed before B applies.
        append_codex_user_turn(
            &codex_rollout_path(&a.codex, session),
            "message-next",
            "continued on A",
        );
        assert_eq!(world.push(a).revision, Some(3));

        let result = world.pull_everything(&plan);
        assert!(result.success, "{}", result.message);
        assert_eq!(result.stopped, None);
        assert_eq!(result.reviewed_base_advanced, Some(true));
        let installed = std::fs::read_to_string(world.rollout_of(b, &cloud_id)).unwrap();
        assert!(installed.contains("hello"));
        assert!(!installed.contains("continued on A"));
        let link = world.link(b);
        assert!(repository_bases(&link).all(|base| base.revision == 2));
        let comparison = world.compare(b);
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::Advanced {
                base_revision: 2,
                remote_revision: 3
            }
        );
        let row = TwoComputers::row_for(&comparison, &cloud_id);
        assert_eq!(row.state, ThreadSyncState::StorageAhead);
        assert_eq!(
            row.pull_decision.action,
            ConversationReviewAction::MaterializeCloud
        );
    }

    /// T3 and Q3: the pinned version lost its race before the Pull started,
    /// to a record with an earlier stamp planted beside it, as no Push can
    /// write it on R2 or Dropbox. The Pull is refused before anything
    /// changes, and every local document is byte for byte what it was.
    #[test]
    fn a_pull_is_refused_before_anything_changes_when_its_pinned_version_lost_its_race() {
        let world = TwoComputers::new("lost-pin-store");
        let (a, b) = (&world.a, &world.b);
        let session = "019f7500-0000-7000-8000-0000000000a2";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        let plan = world.plan_pull(b);
        let pinned = world.record_at(2);
        plant_rival_publication(
            &world.storage_root,
            &world.bundle_id,
            &world.record_at(1),
            &format!("commit-{}", "e".repeat(24)),
            pinned.created_at_ms() - 1_000,
        );
        let before = world.local_documents();
        let error = ProjectSyncService::new(&world.repo)
            .apply_bundle_restore(&plan, TwoComputers::ticked_ids(&plan).into_iter().collect())
            .unwrap_err();
        assert_eq!(error, REVIEW_SUPERSEDED);
        assert_eq!(world.local_documents(), before);
        assert!(!b.codex.join("sessions").exists());
    }

    /// T4, T5 and Q5: the storage was cleared between the review and the
    /// Pull, and then cleared and pushed again. Both refuse the Pull before
    /// anything changes on this computer.
    #[test]
    fn a_pull_is_refused_before_anything_changes_when_the_storage_was_cleared() {
        let world = TwoComputers::new("cleared-pin-store");
        let (a, b) = (&world.a, &world.b);
        let session = "019f7500-0000-7000-8000-0000000000a3";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        let plan = world.plan_pull(b);
        let ticked: Vec<ActionId> = TwoComputers::ticked_ids(&plan).into_iter().collect();
        let link_before = world.link(b);

        wipe_remote_bundle(&world.storage_root, &world.bundle_id);
        let before = world.local_documents();
        let error = ProjectSyncService::new(&world.repo)
            .apply_bundle_restore(&plan, ticked.clone())
            .unwrap_err();
        assert_eq!(error, REVIEW_SUPERSEDED);
        assert_eq!(world.local_documents(), before);

        // Pushed again: a new history that starts at version 1.
        assert_eq!(world.push(a).revision, Some(1));
        let error = ProjectSyncService::new(&world.repo)
            .apply_bundle_restore(&plan, ticked)
            .unwrap_err();
        assert_eq!(error, REVIEW_SUPERSEDED);
        assert_eq!(world.link(b), link_before);
        assert!(!b.codex.join("sessions").exists());
    }

    /// T11: this computer synced past its review from another window: a
    /// newer review of the same storage was applied, so a base names a later
    /// version than the pin. The older review is refused, and the bases
    /// still name the newer version.
    #[test]
    fn a_pull_is_refused_when_this_computer_synced_past_its_review() {
        let world = TwoComputers::new("synced-past-store");
        let (a, b) = (&world.a, &world.b);
        let session = "019f7500-0000-7000-8000-0000000000a4";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        let older = world.plan_pull(b);
        append_codex_user_turn(
            &codex_rollout_path(&a.codex, session),
            "message-next",
            "continued on A",
        );
        assert_eq!(world.push(a).revision, Some(3));
        let newer = world.plan_pull(b);
        assert_eq!(newer.revision, 3);
        let result = world.pull_everything(&newer);
        assert!(result.success, "{}", result.message);
        let link = world.link(b);
        assert!(repository_bases(&link).all(|base| base.revision == 3));

        let error = ProjectSyncService::new(&world.repo)
            .apply_bundle_restore(
                &older,
                TwoComputers::ticked_ids(&older).into_iter().collect(),
            )
            .unwrap_err();
        assert_eq!(error, REVIEW_SUPERSEDED);
        assert_eq!(world.link(b), link);
    }

    /// T6: a review older than a day is refused with its own sentence.
    #[test]
    fn a_review_older_than_a_day_is_refused() {
        let world = TwoComputers::new("expired-review-store");
        let (a, b) = (&world.a, &world.b);
        write_codex_session(&a.codex, "019f7500-0000-7000-8000-0000000000a5", &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        let mut plan = world.plan_pull(b);
        // Reviewed two days ago: its one-day lifetime is over.
        plan.created_at -= 2 * 86_400;
        plan.expires_at -= 2 * 86_400;
        let error = ProjectSyncService::new(&world.repo)
            .apply_bundle_restore(&plan, TwoComputers::ticked_ids(&plan).into_iter().collect())
            .unwrap_err();
        assert_eq!(error, REVIEW_EXPIRED);
    }

    /// D1 and Q2: a newer version lands while the Pull applies, after its
    /// download. The Pull finishes against the pinned version, its result
    /// lists what it installed, and the next comparison reads the newer
    /// version as changes to pull.
    #[test]
    fn a_pull_finishes_when_a_newer_version_lands_while_it_applies() {
        let world = TwoComputers::new("newer-during-pull-store");
        let (a, b) = (&world.a, &world.b);
        let session = "019f7500-0000-7000-8000-0000000000a6";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        let cloud_id = world.stored_cloud_ids()[&Some(session.to_string())].clone();
        let plan = world.plan_pull(b);
        let (storage_root, bundle_id, pinned) = (
            world.storage_root.clone(),
            world.bundle_id.clone(),
            world.record_at(2),
        );
        pull_test_support::after_conversation_download(move || {
            plant_publication(
                &storage_root,
                &bundle_id,
                &pinned,
                Some(&pinned),
                &format!("commit-{}", "f".repeat(24)),
                pinned.created_at_ms() + 60_000,
            );
        });
        let result = world.pull_everything(&plan);
        assert!(result.success, "{}", result.message);
        assert_eq!(result.stopped, None);
        assert_eq!(
            result
                .applied_action_ids
                .iter()
                .cloned()
                .collect::<BTreeSet<_>>(),
            TwoComputers::ticked_ids(&plan)
        );
        assert!(world.rollout_of(b, &cloud_id).exists());
        assert_eq!(
            world.compare(b).remote_continuity,
            RemoteContinuity::Advanced {
                base_revision: 2,
                remote_revision: 3
            }
        );
    }

    /// D2 and Q6: the storage is cleared while the Pull downloads, and the
    /// app restarted since the review, so nothing of it is in the process
    /// cache. The Pull stops before it installs anything: no session and no
    /// file, every ticked item is not pulled, the result says what is missing
    /// without naming a cause, and the bases did not move. The session is
    /// one this computer already has: a new one is read once in step 2 (K3)
    /// and installs from that verified copy, as after the download (D3).
    #[test]
    fn a_pull_stops_before_installing_anything_when_the_storage_is_cleared_during_its_download() {
        let world = TwoComputers::with_project_files("cleared-during-download-store");
        let (a, b) = (&world.a, &world.b);
        std::fs::write(a.root.join("draft.md"), b"first draft\n").unwrap();
        let session = "019f7500-0000-7000-8000-0000000000a7";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push_with_files(a).revision, Some(2));
        let cloud_id = world.stored_cloud_ids()[&Some(session.to_string())].clone();
        let first = world.plan_pull(b);
        let result = world.pull_everything(&first);
        assert!(result.success, "{}", result.message);
        let rollout = world.rollout_of(b, &cloud_id);
        let installed = std::fs::read(&rollout).unwrap();

        // Version 3: the session continued and the file changed on A.
        append_codex_user_turn(
            &codex_rollout_path(&a.codex, session),
            "message-next",
            "continued on A",
        );
        std::fs::write(a.root.join("draft.md"), b"second draft\n").unwrap();
        assert_eq!(world.push_with_files(a).revision, Some(3));
        let plan = world.plan_pull(b);
        let ticked = TwoComputers::ticked_ids(&plan);
        assert!(plan
            .conversation_review
            .iter()
            .any(|row| row.action == ConversationReviewAction::MaterializeCloud));
        assert!(plan.actions.iter().any(|action| matches!(
            &action.kind,
            RestoreActionKind::WriteProjectFile { logical_path, .. }
                if logical_path.as_str() == "project/draft.md"
        )));
        let (storage_root, bundle_id) = (world.storage_root.clone(), world.bundle_id.clone());
        pull_test_support::before_conversation_download(move || {
            ObjectCache::global().clear();
            wipe_remote_bundle(&storage_root, &bundle_id);
        });
        let result = world.pull_everything(&plan);
        assert!(!result.success);
        assert_eq!(
            result.stopped.as_deref(),
            Some("Part of this version is missing from Project content store. Compare again.")
        );
        assert_eq!(Some(result.message.as_str()), result.stopped.as_deref());
        assert!(
            result.applied_action_ids.is_empty(),
            "{:?}",
            result.applied_action_ids
        );
        assert!(
            result.failed_actions.is_empty(),
            "{:?}",
            result.failed_actions
        );
        assert_eq!(
            result
                .not_pulled_action_ids
                .iter()
                .cloned()
                .collect::<BTreeSet<_>>(),
            ticked
        );
        assert_eq!(result.reviewed_base_advanced, Some(false));
        assert_eq!(std::fs::read(&rollout).unwrap(), installed);
        assert_eq!(
            std::fs::read(b.root.join("draft.md")).unwrap(),
            b"first draft\n"
        );
        assert!(repository_bases(&world.link(b)).all(|base| base.revision == 2));
    }

    /// D3, and the check the plan rests on: a session installs from its
    /// downloaded copy while the storage is empty. The storage is cleared
    /// after the download: the session is installed, the Pull stops at the
    /// first file it cannot read, the file reads not pulled, and the bases
    /// did not move. Then N2: the next comparison reads story 1, the
    /// installed session is a new task under the cloud id it already has,
    /// and one Push recreates the storage.
    #[test]
    fn a_pull_installs_the_downloaded_sessions_and_stops_at_the_files_when_the_storage_is_cleared_after_its_download(
    ) {
        let world = TwoComputers::with_project_files("cleared-after-download-store");
        let (a, b) = (&world.a, &world.b);
        std::fs::write(
            a.root.join("draft.md"),
            b"first draft
",
        )
        .unwrap();
        let session = "019f7500-0000-7000-8000-0000000000a8";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push_with_files(a).revision, Some(2));
        let cloud_id = world.stored_cloud_ids()[&Some(session.to_string())].clone();
        let plan = world.plan_pull(b);
        let session_actions = plan
            .conversation_review
            .iter()
            .filter_map(|row| row.action_id.clone())
            .collect::<BTreeSet<_>>();
        let file_actions = plan
            .actions
            .iter()
            .map(|action| action.action_id.clone())
            .collect::<BTreeSet<_>>();
        assert!(!session_actions.is_empty() && !file_actions.is_empty());
        let (storage_root, bundle_id) = (world.storage_root.clone(), world.bundle_id.clone());
        pull_test_support::after_conversation_download(move || {
            wipe_remote_bundle(&storage_root, &bundle_id);
        });
        let result = world.pull_everything(&plan);
        assert!(!result.success);
        assert_eq!(
            result.stopped.as_deref(),
            Some("Part of this version is missing from Project content store. Compare again.")
        );
        assert_eq!(
            result
                .applied_action_ids
                .iter()
                .cloned()
                .collect::<BTreeSet<_>>(),
            session_actions
        );
        assert_eq!(
            result
                .not_pulled_action_ids
                .iter()
                .cloned()
                .collect::<BTreeSet<_>>(),
            file_actions
        );
        assert!(
            result.failed_actions.is_empty(),
            "{:?}",
            result.failed_actions
        );
        assert_eq!(result.reviewed_base_advanced, Some(false));
        assert!(world.rollout_of(b, &cloud_id).exists());
        assert!(!b.root.join("draft.md").exists());
        assert!(world.link(b).scope_bases.is_empty());

        // N2: story 1. The installed session's acceptance names the cleared
        // history and is read as absent.
        let comparison = world.compare(b);
        assert_eq!(comparison.remote_continuity, RemoteContinuity::Fresh);
        let row = TwoComputers::row_for(&comparison, &cloud_id);
        assert_eq!(row.state, ThreadSyncState::LocalOnly);
        assert_eq!(
            row.push_decision.action,
            ConversationReviewAction::CreateCloud
        );
        assert_eq!(world.push(b).revision, Some(1));
        assert!(world.stored_cloud_ids().values().any(|id| id == &cloud_id));
    }

    /// N7: a folder that a sync product replicates has not received one
    /// object of the pinned version yet. The Pull stops with the same result
    /// and no cause in its text. When the object has arrived, the next review
    /// offers the file again, the installed session reads in sync, and the
    /// Pull finishes.
    #[test]
    fn a_pull_stops_the_same_way_when_an_object_has_not_arrived_and_offers_the_rest_afterwards() {
        let world = TwoComputers::with_project_files("replicating-folder-store");
        let (a, b) = (&world.a, &world.b);
        std::fs::write(
            a.root.join("draft.md"),
            b"first draft
",
        )
        .unwrap();
        let session = "019f7500-0000-7000-8000-0000000000a9";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push_with_files(a).revision, Some(2));
        let cloud_id = world.stored_cloud_ids()[&Some(session.to_string())].clone();
        let object = world.object_path_of("draft.md");
        let aside = object.with_extension("not-arrived");
        std::fs::rename(&object, &aside).unwrap();

        let plan = world.plan_pull(b);
        let result = world.pull_everything(&plan);
        assert!(!result.success);
        assert_eq!(
            result.stopped.as_deref(),
            Some("Part of this version is missing from Project content store. Compare again.")
        );
        assert!(world.rollout_of(b, &cloud_id).exists());
        assert!(!b.root.join("draft.md").exists());
        assert_eq!(result.not_pulled_action_ids.len(), plan.actions.len());

        std::fs::rename(&aside, &object).unwrap();
        let comparison = world.compare(b);
        assert_eq!(
            TwoComputers::row_for(&comparison, &cloud_id).state,
            ThreadSyncState::Synced
        );
        let again = world.plan_pull(b);
        assert!(again.actions.iter().any(|action| matches!(
            &action.kind,
            RestoreActionKind::WriteProjectFile { logical_path, .. }
                if logical_path.as_str() == "project/draft.md"
        )));
        let result = world.pull_everything(&again);
        assert!(result.success, "{}", result.message);
        assert_eq!(
            std::fs::read(b.root.join("draft.md")).unwrap(),
            b"first draft
"
        );
    }

    /// D4: the storage cannot be read after the download. The Pull stops
    /// with the storage's own error, and what was installed stays.
    #[test]
    fn a_pull_stops_with_the_storage_own_error_when_it_cannot_be_read() {
        let world = TwoComputers::with_project_files("unreadable-store");
        let (a, b) = (&world.a, &world.b);
        std::fs::write(
            a.root.join("draft.md"),
            b"first draft
",
        )
        .unwrap();
        let session = "019f7500-0000-7000-8000-0000000000aa";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push_with_files(a).revision, Some(2));
        let cloud_id = world.stored_cloud_ids()[&Some(session.to_string())].clone();
        let plan = world.plan_pull(b);
        // The object becomes something the store refuses to read.
        let object = world.object_path_of("draft.md");
        pull_test_support::after_conversation_download(move || {
            std::fs::remove_file(&object).unwrap();
            std::fs::create_dir(&object).unwrap();
        });
        let result = world.pull_everything(&plan);
        assert!(!result.success);
        let stopped = result.stopped.expect("the Pull stopped");
        assert!(
            stopped.contains("not a regular no-follow file"),
            "the storage's own error, got: {stopped}"
        );
        assert_eq!(result.message, stopped);
        assert!(world.rollout_of(b, &cloud_id).exists());
        assert!(!b.root.join("draft.md").exists());
        assert_eq!(result.not_pulled_action_ids.len(), plan.actions.len());
    }

    /// D6: a stored session whose content does not match what its manifest
    /// says about it fails alone, with its own sentence, and nothing offers a
    /// reset. With that row left unticked, the next Pull marks the areas as
    /// reviewed (rule 5).
    #[test]
    fn a_stored_session_that_cannot_be_read_fails_alone_and_the_next_pull_marks_the_areas_reviewed()
    {
        let world = TwoComputers::new("unreadable-session-store");
        let (a, b) = (&world.a, &world.b);
        write_codex_session(&a.codex, "019f7500-0000-7000-8000-0000000000ab", &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        // Version 3 says something false about the session's lineage.
        let pinned = world.record_at(2);
        plant_edited_publication(
            &world.storage_root,
            &world.bundle_id,
            &pinned,
            Some(&pinned),
            &format!("commit-{}", "d".repeat(24)),
            pinned.created_at_ms() + 60_000,
            |manifest| {
                for (key, scope) in manifest.scopes.iter_mut() {
                    for thread in scope.conversations.values_mut() {
                        thread.lineage_digest = "1".repeat(64);
                    }
                    scope.content_sha256 = scope.compute_content_sha256(key).unwrap();
                }
            },
        );
        let plan = world.plan_pull(b);
        assert_eq!(plan.revision, 3);
        let result = world.pull_everything(&plan);
        assert!(!result.success);
        assert_eq!(result.stopped, None);
        assert_eq!(
            result.failed_actions.len(),
            1,
            "{:?}",
            result.failed_actions
        );
        assert_eq!(
            result.failed_actions[0].message,
            mallard_infrastructure::pull_transcript::STORED_SESSION_UNREADABLE
        );
        assert!(!b.codex.join("sessions").exists());

        let again = world.plan_pull(b);
        let result = ProjectSyncService::new(&world.repo)
            .apply_bundle_restore(&again, Vec::new())
            .unwrap();
        assert!(result.success, "{}", result.message);
        assert_eq!(result.reviewed_base_advanced, Some(true));
        assert!(repository_bases(&world.link(b)).all(|base| base.revision == 3));
    }

    /// Q4: a version a Pull applied is outranked afterwards. The refresh
    /// reads `Displaced` with "last pull", changes no base and no acceptance,
    /// and keeps the installed session, which now compares against the
    /// version that won.
    #[test]
    fn a_version_a_pull_applied_is_reported_displaced_when_it_loses_its_race_afterwards() {
        let world = TwoComputers::new("displaced-pull-store");
        let (a, b) = (&world.a, &world.b);
        let session = "019f7500-0000-7000-8000-0000000000ac";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        let cloud_id = world.stored_cloud_ids()[&Some(session.to_string())].clone();
        let plan = world.plan_pull(b);
        let result = world.pull_everything(&plan);
        assert!(result.success, "{}", result.message);
        let rollout = world.rollout_of(b, &cloud_id);
        assert!(rollout.exists());
        // Another computer's record of the same session, on the same parent,
        // built a second earlier: it outranks the version B pulled.
        let pinned = world.record_at(2);
        plant_publication(
            &world.storage_root,
            &world.bundle_id,
            &pinned,
            Some(&world.record_at(1)),
            &format!("commit-{}", "e".repeat(24)),
            pinned.created_at_ms() - 1_000,
        );

        let before = std::fs::read(world.repo.config_path()).unwrap();
        let comparison = world.compare(b);
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::Displaced {
                base_revision: 2,
                remote_revision: 2,
                saved_by: SavedBy::Pull,
            }
        );
        assert_eq!(std::fs::read(world.repo.config_path()).unwrap(), before);
        assert!(rollout.exists());
        let row = TwoComputers::row_for(&comparison, &cloud_id);
        assert_eq!(row.state, ThreadSyncState::Synced);
        assert_eq!(
            row.pull_decision.action,
            ConversationReviewAction::AdoptCloudMetadata
        );
    }

    /// O2 and O1: a Pull on a cleared, empty storage. A computer that synced
    /// with it before is told there is nothing to pull; one that never did
    /// gets the text that opens the chooser of the storage's other projects.
    #[test]
    fn a_pull_on_a_cleared_storage_this_computer_synced_with_says_there_is_nothing_to_pull() {
        let world = TwoComputers::new("nothing-to-pull-store");
        let (a, b) = (&world.a, &world.b);
        write_codex_session(&a.codex, "019f7500-0000-7000-8000-0000000000ad", &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        wipe_remote_bundle(&world.storage_root, &world.bundle_id);
        let plan = |computer: &TestComputer| {
            ProjectSyncService::new(&world.repo)
                .plan_bundle_restore(&world.storage_id, &world.bundle_id, &computer.binding)
                .unwrap_err()
        };
        assert_eq!(
            plan(a),
            "There is nothing to pull from Project content store."
        );
        assert!(plan(b).contains("does not exist"), "{}", plan(b));
    }

    /// Continue a Codex rollout by one user turn, as the provider would.
    fn append_codex_user_turn(path: &Path, id: &str, text: &str) {
        use std::io::Write as _;
        let ordinal = std::fs::read_to_string(path)
            .unwrap()
            .lines()
            .next_back()
            .and_then(|line| serde_json::from_str::<serde_json::Value>(line).ok())
            .and_then(|record| record.get("ordinal").and_then(serde_json::Value::as_u64))
            .unwrap()
            + 1;
        let mut file = std::fs::OpenOptions::new().append(true).open(path).unwrap();
        serde_json::to_writer(
            &mut file,
            &serde_json::json!({
                "ordinal": ordinal,
                "type": "response_item",
                "payload": {
                    "type": "message",
                    "id": id,
                    "role": "user",
                    "content": [{"type": "input_text", "text": text}]
                }
            }),
        )
        .unwrap();
        file.write_all(b"\n").unwrap();
        file.sync_all().unwrap();
    }

    /// Story 2 with rule 0 and rows S4, A7 and S1. Both computers hold one
    /// session. The storage is cleared, and computer B pushes again with the
    /// session continued. Computer A's acceptance names the cleared history
    /// and still equals its local copy, so against that stale record B's
    /// longer copy would read as a plain update and be installed over A's
    /// own. The record is ignored instead: nothing relates the two copies,
    /// Push asks for a Pull, and Pull keeps both. No row reads "Can't sync",
    /// and nothing asks for an unlink or a reset.
    #[test]
    fn a_stale_acceptance_never_reads_a_recreated_session_as_a_plain_update() {
        let world = TwoComputers::new("recreated-session-store");
        let (a, b) = (&world.a, &world.b);
        let session = "019f7500-0000-7000-8000-0000000000e1";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        let cloud_ids = world.stored_cloud_ids();
        let cloud_thread_id = cloud_ids[&Some(session.to_string())].clone();

        // B pulls the session: both computers now hold it, accepted in
        // version 2.
        world.pull_conversations(&world.plan_pull(b));
        let b_rollout = world.rollout_of(b, &cloud_thread_id);
        let accepted_before = world.link(a);

        // The storage is cleared, B continues the session and pushes again:
        // story 1 on B, under the cloud id the session already had.
        wipe_remote_bundle(&world.storage_root, &world.bundle_id);
        append_codex_user_turn(&b_rollout, "message-b-continued", "continued on B");
        assert_eq!(
            world.push_status(b),
            PushDestinationStatus::Ready { revision: None }
        );
        let recreated = world.push(b);
        assert!(recreated.success, "{}", recreated.message);
        assert_eq!(recreated.revision, Some(1));
        assert_eq!(
            world.stored_cloud_ids().into_values().collect::<Vec<_>>(),
            vec![cloud_thread_id.clone()],
            "B's copy carries the provider id B minted, under the same cloud id"
        );

        // A: the history was replaced, and its area holds other content.
        let comparison = world.compare(a);
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::Replaced {
                base_revision: 2,
                remote_revision: 1
            }
        );
        assert_eq!(
            world.push_status(a),
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteWithoutBase,
                remote_revision: 1,
                base_revision: None,
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );
        // Rule 0: A's saved acceptance still equals its local copy, and the
        // stored copy has more turns. It is S4, never "Update this task".
        let row = comparison_entry(&comparison, session);
        assert_eq!(row.state, ThreadSyncState::Diverged);
        assert_eq!(
            row.push_decision.action,
            ConversationReviewAction::RequirePull
        );
        assert_eq!(row.pull_decision.action, ConversationReviewAction::KeepBoth);
        assert!(row.pull_decision.selectable);
        assert!(comparison
            .entries
            .iter()
            .all(
                |entry| entry.push_decision.action != ConversationReviewAction::Blocked
                    && entry.pull_decision.action != ConversationReviewAction::Blocked
            ));
        // Comparing forgot nothing.
        assert_eq!(world.link(a), accepted_before);

        // The Pull installs the stored session and keeps A's copy.
        let plan = world.plan_pull(a);
        let keep_both = plan
            .conversation_review
            .iter()
            .find(|row| row.cloud_thread_id.as_ref() == Some(&cloud_thread_id))
            .unwrap();
        assert_eq!(keep_both.action, ConversationReviewAction::KeepBoth);
        let pulled = world.pull_conversations(&plan);
        assert_eq!(pulled.preserved_threads.len(), 1);
        let a_source = a
            .codex
            .join(format!("sessions/2026/07/22/rollout-{session}.jsonl"));
        assert_eq!(
            std::fs::read(&a_source).unwrap(),
            command_test_transcript(session, &a.root, &[("message-test", "user", "hello")]),
            "keep both never touches the local copy"
        );
        let installed = std::fs::read_to_string(world.rollout_of(a, &cloud_thread_id)).unwrap();
        assert!(installed.contains("continued on B"));

        // Afterwards A is an ordinary replica of the new history: Push is
        // open, the stored session is in sync, and the preserved copy is a
        // new task that the next Push uploads.
        let settled = world.compare(a);
        assert_eq!(
            settled.remote_continuity,
            RemoteContinuity::InSync { revision: 1 }
        );
        assert_eq!(
            world.push_status(a),
            PushDestinationStatus::Ready { revision: Some(1) }
        );
        assert!(settled
            .entries
            .iter()
            .all(|entry| entry.push_decision.action != ConversationReviewAction::Blocked));
        let stored_row = settled
            .entries
            .iter()
            .find(|entry| entry.cloud_thread_id.as_ref() == Some(&cloud_thread_id))
            .unwrap();
        assert_eq!(stored_row.state, ThreadSyncState::Synced);
        let preserved_row = comparison_entry(&settled, session);
        assert_eq!(
            preserved_row.push_decision.action,
            ConversationReviewAction::CreateCloud
        );
        let link = world.link(a);
        let (_, engine) = storage_engine(&world.repo, &world.storage_id).unwrap();
        let mainline = engine.observe(&world.bundle_id).unwrap().mainline;
        assert!(
            repository_bases(&link).all(|base| mainline.contains(base.revision, &base.commit_id))
        );

        let uploaded = world.push(a);
        assert!(uploaded.success, "{}", uploaded.message);
        assert_eq!(uploaded.revision, Some(2));
        assert_eq!(world.stored_cloud_ids().len(), 2);
    }

    /// Rows S2 and S3 under a stale record. Both computers hold one session,
    /// the storage is cleared, and computer A pushes again. Computer B's
    /// acceptance names the cleared history, so it is ignored, and the stored
    /// copy is proven from its content instead: an equal copy reads "Mark
    /// synced", and an earlier version reads "Update storage". Nothing is
    /// blocked, and nothing asks for a reset.
    #[test]
    fn an_equal_or_an_earlier_stored_copy_is_proven_from_content_under_a_stale_record() {
        let world = TwoComputers::new("adopted-session-store");
        let (a, b) = (&world.a, &world.b);
        let session = "019f7500-0000-7000-8000-0000000000e2";
        write_codex_session(&a.codex, session, &a.root);
        assert_eq!(world.push(a).revision, Some(2));
        let cloud_thread_id = world.stored_cloud_ids()[&Some(session.to_string())].clone();
        world.pull_conversations(&world.plan_pull(b));
        let b_rollout = world.rollout_of(b, &cloud_thread_id);

        // The clear, then story 1 on A: the same session under the same
        // cloud id, and one more session, so that the area's content differs
        // from what B reviewed whatever the clock says.
        wipe_remote_bundle(&world.storage_root, &world.bundle_id);
        write_codex_session(&a.codex, "019f7500-0000-7000-8000-0000000000e3", &a.root);
        let recreated = world.push(a);
        assert!(recreated.success, "{}", recreated.message);
        assert_eq!(recreated.revision, Some(1));
        let saved = world.link(b);
        assert!(saved
            .conversation_checkpoints
            .values()
            .flat_map(BTreeMap::values)
            .all(|checkpoint| checkpoint.accepted.is_some()));

        // S2: B's copy equals the stored one.
        let row_of = |comparison: &ThreadSyncComparison| {
            comparison
                .entries
                .iter()
                .find(|entry| entry.cloud_thread_id.as_ref() == Some(&cloud_thread_id))
                .cloned()
                .unwrap()
        };
        let equal = row_of(&world.compare(b));
        assert_eq!(equal.state, ThreadSyncState::Synced);
        assert_eq!(
            equal.push_decision.action,
            ConversationReviewAction::NoChanges
        );
        assert_eq!(
            equal.pull_decision.action,
            ConversationReviewAction::AdoptCloudMetadata
        );
        assert!(equal.pull_decision.selectable);

        // S3: B continues the session, so the stored copy is an earlier
        // version of it.
        append_codex_user_turn(&b_rollout, "message-b-continued", "continued on B");
        let earlier = row_of(&world.compare(b));
        assert_eq!(earlier.state, ThreadSyncState::LocalAhead);
        assert_eq!(
            earlier.push_decision.action,
            ConversationReviewAction::Publish
        );
        assert!(earlier.push_decision.selectable);
        assert_eq!(
            earlier.pull_decision.action,
            ConversationReviewAction::ReportPushEligible
        );
        // The proof is for this review only: comparing saved nothing.
        assert_eq!(world.link(b), saved);

        // B's area holds content it never reviewed in this history (A7), so
        // a Pull comes first. It has nothing to install for this session: the
        // row only reports "Ready to push". Then B updates the storage with
        // its complete session under the same cloud id.
        assert_eq!(
            world.push_status(b),
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteWithoutBase,
                remote_revision: 1,
                base_revision: None,
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );
        let plan = world.plan_pull(b);
        let reported = plan
            .conversation_review
            .iter()
            .find(|row| row.cloud_thread_id.as_ref() == Some(&cloud_thread_id))
            .unwrap();
        assert_eq!(
            reported.action,
            ConversationReviewAction::ReportPushEligible
        );
        assert_eq!(reported.action_id, None);
        world.pull_conversations(&plan);
        assert_eq!(
            world.push_status(b),
            PushDestinationStatus::Ready { revision: Some(1) }
        );
        let updated = world.push(b);
        assert!(updated.success, "{}", updated.message);
        assert_eq!(updated.revision, Some(2));
        let stored = world.stored_cloud_ids();
        assert_eq!(stored.len(), 2);
        assert!(stored.values().any(|id| id == &cloud_thread_id));
        assert_eq!(row_of(&world.compare(b)).state, ThreadSyncState::Synced);

        // A's record names the new history, so it is usable: S8.
        let continued_elsewhere = row_of(&world.compare(a));
        assert_eq!(continued_elsewhere.state, ThreadSyncState::StorageAhead);
        assert_eq!(
            continued_elsewhere.pull_decision.action,
            ConversationReviewAction::MaterializeCloud
        );
    }

    /// The records of one bundle's stream, moved aside and brought back: a
    /// listing that was short for a while, as a folder storage inside a sync
    /// product reads before it has finished downloading.
    struct HiddenStream {
        stream: PathBuf,
        aside: PathBuf,
    }

    impl HiddenStream {
        fn hide(storage_root: &Path, bundle_id: &BundleId) -> Self {
            let stream = storage_root
                .join(".mallard/v1/repositories/_commits")
                .join(bundle_id.as_str());
            let aside = storage_root.join("records-not-listed-yet");
            std::fs::rename(&stream, &aside).unwrap();
            Self { stream, aside }
        }

        /// The old records show up again, next to whatever was written
        /// while they were not listed.
        fn reveal(self) {
            std::fs::create_dir_all(&self.stream).unwrap();
            for entry in std::fs::read_dir(&self.aside).unwrap() {
                let entry = entry.unwrap();
                std::fs::rename(entry.path(), self.stream.join(entry.file_name())).unwrap();
            }
            std::fs::remove_dir(&self.aside).unwrap();
        }
    }

    /// Story 4, nothing done: the storage only looked empty. Every record is
    /// ignored while its publication is not listed, none is deleted, and
    /// when the listing is complete again the link reads exactly as before.
    #[test]
    fn a_listing_that_was_short_for_a_while_changes_nothing() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("short-listing-store").unwrap();
        let storage_root = temp.path().join("store");
        add_local_storage(&repo, &storage_id, &storage_root);
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let session = "019f7500-0000-7000-8000-0000000000f1";
        write_codex_session(&codex_home, session, &project_root);
        assert_eq!(
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap()
                .revision,
            Some(2)
        );
        let compare = || {
            get_project_thread_sync_comparison_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap()
        };
        let saved_link = || {
            let config = repo.load_config().unwrap();
            project_link(&config, &project.local_project_id, &storage_id)
                .unwrap()
                .clone()
        };
        let before = compare();
        assert_eq!(
            before.remote_continuity,
            RemoteContinuity::InSync { revision: 2 }
        );
        assert_eq!(
            comparison_entry(&before, session).state,
            ThreadSyncState::Synced
        );
        let link_before = saved_link();

        let hidden = HiddenStream::hide(&storage_root, &project.bundle_id);
        let short = compare();
        assert_eq!(
            short.remote_continuity,
            RemoteContinuity::RemoteMissing { base_revision: 2 }
        );
        assert_eq!(
            comparison_entry(&short, session).push_decision.action,
            ConversationReviewAction::CreateCloud
        );
        assert_eq!(saved_link(), link_before);

        hidden.reveal();
        let after = compare();
        assert_eq!(after.remote_continuity, before.remote_continuity);
        assert_eq!(after.scopes, before.scopes);
        let (row_before, row_after) = (
            comparison_entry(&before, session),
            comparison_entry(&after, session),
        );
        assert_eq!(row_after.state, row_before.state);
        assert_eq!(row_after.push_decision, row_before.push_decision);
        assert_eq!(row_after.pull_decision, row_before.pull_decision);
        assert_eq!(saved_link(), link_before);
    }

    /// Story 4, pushed, which is also R4 after the fact: the storage only
    /// looked empty, and this computer pushed a second first version, with
    /// one more session than the real history. When the real history is
    /// listed again, its earlier first version is selected and this Push
    /// reads `Displaced` (R3): nothing is rolled back, and the bases and the
    /// acceptances it saved are kept and read as absent. The area holds
    /// content the real history never had, so it reads as never reviewed
    /// here (A7): one Pull, in which the session the real history holds is
    /// proven equal from its content and reads "Mark synced", and the other
    /// one "Keep local"; then one Push publishes it under the cloud id it
    /// already had.
    #[test]
    fn a_push_onto_a_storage_that_only_looked_empty_reads_displaced() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("looked-empty-store").unwrap();
        let storage_root = temp.path().join("store");
        add_local_storage(&repo, &storage_id, &storage_root);
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let session = "019f7500-0000-7000-8000-0000000000f2";
        write_codex_session(&codex_home, session, &project_root);
        assert_eq!(
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap()
                .revision,
            Some(2)
        );
        let compare = || {
            get_project_thread_sync_comparison_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap()
        };
        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let stored_ids = || {
            stored_cloud_ids(
                engine
                    .observe(&project.bundle_id)
                    .unwrap()
                    .snapshot()
                    .unwrap(),
            )
        };

        // A second session starts while the storage looks empty.
        let hidden = HiddenStream::hide(&storage_root, &project.bundle_id);
        let later = "019f7500-0000-7000-8000-0000000000f3";
        write_codex_session(&codex_home, later, &project_root);
        let second_first =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert!(second_first.success, "{}", second_first.message);
        assert_eq!(second_first.revision, Some(1));
        let second_first_name = record_names_at(&storage_root, &project.bundle_id, 1).remove(0);
        let second_first_ids = stored_ids();
        assert_eq!(second_first_ids.len(), 2);
        hidden.reveal();
        assert_eq!(
            record_names_at(&storage_root, &project.bundle_id, 1).len(),
            2
        );

        // The refresh selects the real history and reports this Push
        // displaced. It writes nothing: the base and the acceptances of the
        // second first version stay.
        let saved_config = || std::fs::read(repo.config_path()).unwrap();
        let before = saved_config();
        let comparison = compare();
        assert_eq!(
            comparison.remote_continuity,
            RemoteContinuity::Displaced {
                base_revision: 1,
                remote_revision: 2,
                saved_by: SavedBy::Push,
            }
        );
        assert_eq!(saved_config(), before);
        let config = repo.load_config().unwrap();
        let link = project_link(&config, &project.local_project_id, &storage_id).unwrap();
        assert!(repository_bases(link).all(|base| base.commit_id == second_first_name.commit_id()));
        let checkpoints = link
            .conversation_checkpoints
            .values()
            .flat_map(BTreeMap::values)
            .collect::<Vec<_>>();
        assert_eq!(checkpoints.len(), 2);
        assert!(checkpoints.iter().all(|checkpoint| {
            checkpoint.accepted.as_ref().is_some_and(|accepted| {
                accepted.accepted_at_commit_id == second_first_name.commit_id()
            })
        }));
        // A7: the area holds a session the real history never had. The
        // area's revision is its own per-branch counter.
        let codex_area = comparison
            .scopes
            .iter()
            .find(|scope| scope.scope == "provider:codex")
            .expect("the codex area is compared")
            .continuity
            .clone();
        assert_eq!(
            codex_area,
            ScopeContinuity::Unreviewed { remote_revision: 1 }
        );
        assert_eq!(
            get_push_destination_status_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap(),
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteWithoutBase,
                remote_revision: 2,
                base_revision: None,
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );
        // S2 for the session the real history holds, proven equal from its
        // content and never from the stale acceptance; S1 for the other.
        let row = |id: &str| comparison_entry(&comparison, id);
        assert_eq!(row(session).state, ThreadSyncState::Synced);
        assert_eq!(
            row(session).pull_decision.action,
            ConversationReviewAction::AdoptCloudMetadata
        );
        assert_eq!(row(later).state, ThreadSyncState::LocalOnly);
        assert_eq!(
            row(later).push_decision.action,
            ConversationReviewAction::CreateCloud
        );
        // The record that was not selected stays in the storage, unused.
        let observation = engine.observe(&project.bundle_id).unwrap();
        assert!(!observation
            .mainline
            .contains_commit(second_first_name.commit_id()));
        assert!(observation.unselected.contains(&second_first_name));

        // "Mark synced" replaces the stale base and that session's
        // acceptance with ones on the real history, and the notice ends.
        let binding = repo
            .load_bindings()
            .unwrap()
            .active_for(&project.local_project_id)
            .cloned()
            .unwrap();
        let plan = ProjectSyncService::new(&repo)
            .plan_bundle_restore(&storage_id, &project.bundle_id, &binding)
            .unwrap();
        let mark_synced = plan
            .conversation_review
            .iter()
            .filter_map(|row| row.action_id.clone())
            .collect::<Vec<_>>();
        assert_eq!(mark_synced.len(), 1);
        ProjectSyncService::new(&repo)
            .apply_bundle_restore(
                &plan,
                plan.actions
                    .iter()
                    .map(|action| action.action_id.clone())
                    .chain(mark_synced)
                    .collect(),
            )
            .unwrap();
        let pulled = compare();
        assert_eq!(
            pulled.remote_continuity,
            RemoteContinuity::InSync { revision: 2 }
        );
        assert_eq!(
            comparison_entry(&pulled, later).push_decision.action,
            ConversationReviewAction::CreateCloud
        );

        // The Push publishes the other session under the cloud id the second
        // first version gave it, and no acceptance is left off the chain.
        let republished =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(republished.revision, Some(3), "{}", republished.message);
        assert_eq!(stored_ids(), second_first_ids);
        let settled = compare();
        assert_eq!(
            settled.remote_continuity,
            RemoteContinuity::InSync { revision: 3 }
        );
        let mainline = engine.observe(&project.bundle_id).unwrap().mainline;
        let config = repo.load_config().unwrap();
        let link = project_link(&config, &project.local_project_id, &storage_id).unwrap();
        assert!(link
            .conversation_checkpoints
            .values()
            .flat_map(BTreeMap::values)
            .filter_map(|checkpoint| checkpoint.accepted.as_ref())
            .all(|accepted| mainline.contains_commit(&accepted.accepted_at_commit_id)));
    }

    /// Identity decides the history, never a revision: a recreated history
    /// that overtook the base reads as never reviewed here (A7), while a base
    /// from the live history reads as a plain advance (A6).
    #[test]
    fn a_recreated_history_reads_as_unreviewed_and_a_live_one_as_advanced() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("overtaken-history-store").unwrap();
        let storage_root = temp.path().join("store");
        add_local_storage(&repo, &storage_id, &storage_root);
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let session_id = "019f7500-0000-7000-8000-0000000000be";
        write_codex_session(&codex_home, session_id, &project_root);

        let first =
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        assert_eq!(first.revision, Some(2));
        let (_, pre_wipe_scopes) =
            reviewed_link_state(&repo, &project.local_project_id, &storage_id);

        // Clear, and push again under the same bundle id.
        wipe_remote_bundle(&storage_root, &project.bundle_id);
        write_codex_session(
            &codex_home,
            "019f7500-0000-7000-8000-0000000000b1",
            &project_root,
        );
        assert_eq!(
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap()
                .revision,
            Some(1)
        );
        assert_eq!(
            push_bundle_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap()
                .revision,
            Some(1),
            "a push without changes publishes nothing"
        );
        let (_, new_lineage_scopes) =
            reviewed_link_state(&repo, &project.local_project_id, &storage_id);

        // Grow the session twice so the new history overtakes the base.
        let messages = [
            ("message-test", "user", "hello"),
            ("message-more", "user", "and more"),
            ("message-most", "user", "and even more"),
        ];
        for (revision, turns) in [(2, 2), (3, 3)] {
            std::fs::write(
                codex_home
                    .join("sessions/2026/07/22")
                    .join(format!("rollout-{}.jsonl", session_id)),
                command_test_transcript(session_id, &project_root, &messages[..turns]),
            )
            .unwrap();
            assert_eq!(
                push_bundle_with_repository(&repo, &project.local_project_id, &storage_id)
                    .unwrap()
                    .revision,
                Some(revision)
            );
        }

        // A base from the cleared history, at a lower revision than the
        // selected publication: not on the chain, so never reviewed here.
        repo.mutate_config(|config| {
            config
                .links
                .iter_mut()
                .find(|link| {
                    link.local_project_id == project.local_project_id
                        && link.storage_id == storage_id
                })
                .unwrap()
                .scope_bases = pre_wipe_scopes.clone();
            Ok(())
        })
        .unwrap();
        assert_eq!(
            get_push_destination_status_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap(),
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteWithoutBase,
                remote_revision: 3,
                base_revision: None,
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );

        // A base from the live history: an ordinary advance that a pull
        // fast-forwards.
        repo.mutate_config(|config| {
            config
                .links
                .iter_mut()
                .find(|link| {
                    link.local_project_id == project.local_project_id
                        && link.storage_id == storage_id
                })
                .unwrap()
                .scope_bases = new_lineage_scopes.clone();
            Ok(())
        })
        .unwrap();
        assert_eq!(
            get_push_destination_status_with_repository(
                &repo,
                &project.local_project_id,
                &storage_id,
            )
            .unwrap(),
            PushDestinationStatus::RequiresPull {
                reason: PushDestinationPullReason::RemoteAdvanced,
                remote_revision: 3,
                base_revision: Some(1),
                blocking_scopes: vec!["provider:codex".to_string()],
            }
        );
    }

    /// Timestamps differ between two builds of the same section; everything
    /// else must match exactly.
    fn strip_volatile(mut value: serde_json::Value) -> serde_json::Value {
        fn strip(value: &mut serde_json::Value) {
            match value {
                serde_json::Value::Object(map) => {
                    map.remove("compared_at");
                    map.remove("generated_at");
                    map.remove("prepared_at");
                    map.remove("scanned_at");
                    for child in map.values_mut() {
                        strip(child);
                    }
                }
                serde_json::Value::Array(items) => {
                    for child in items {
                        strip(child);
                    }
                }
                _ => {}
            }
        }
        strip(&mut value);
        value
    }

