    #[test]
    fn prepare_push_review_matches_standalone_commands() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("composite-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let session_id = "019f7500-0000-7000-8000-0000000000cc";
        write_codex_session(&codex_home, session_id, &project_root);

        // Standalone inventory and the composite review are both read-only and
        // must build the same sections from the same saved recipe.
        let standalone_inventory =
            get_bundle_inventory_with_repository(&repo, &project.local_project_id).unwrap();
        let standalone_threads = get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();

        let context =
            prepare_push_review_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        assert_eq!(
            strip_volatile(serde_json::to_value(&context.inventory).unwrap()),
            strip_volatile(serde_json::to_value(&standalone_inventory).unwrap()),
        );
        // Both commands are comparison-only. Neither captures payloads or
        // applies an age-ordered admission policy. The DTO carries only the
        // aggregate Apply limit and its non-conversation reserve.
        let reviewed_threads = serde_json::to_value(&context.thread_comparison).unwrap();
        let budget = context
            .thread_comparison
            .as_ref()
            .unwrap()
            .capture_budget
            .as_ref()
            .unwrap();
        assert_eq!(budget.limit_bytes, provider_capture::MAX_CAPTURE_BYTES);
        assert_eq!(
            strip_volatile(reviewed_threads),
            strip_volatile(serde_json::to_value(Some(standalone_threads)).unwrap()),
        );
        assert!(context.thread_comparison_error.is_none());
        // A non-git binding keeps the project-files section absent by design.
        assert!(context.project_files.is_none());
        assert!(context.project_files_error.is_none());
        // Preparing either view must not mutate the project recipe.
        let recipe = repo
            .load_config()
            .unwrap()
            .project(&project.local_project_id)
            .unwrap()
            .recipe
            .clone();
        assert!(recipe.entries.is_empty());
        assert_eq!(
            context.project.project.local_project_id,
            project.local_project_id
        );
        assert_eq!(
            context.destination_status,
            PushDestinationStatus::Ready { revision: Some(1) }
        );
    }

    #[test]
    fn subagent_tasks_are_removed_from_inventory_recipe_and_push() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("subagent-push-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);

        let parent_id = "019f7500-0000-7000-8000-0000000000ee";
        let child_id = "019f7500-0000-7000-8000-0000000000ef";
        write_codex_session(&codex_home, parent_id, &project_root);
        let child_path = codex_home
            .join("sessions/2026/07/22")
            .join(format!("rollout-{}.jsonl", child_id));
        std::fs::create_dir_all(child_path.parent().unwrap()).unwrap();
        std::fs::write(
            &child_path,
            command_test_subagent_transcript(
                child_id,
                parent_id,
                &project_root,
                &[("message-child", "assistant", "internal work")],
            ),
        )
        .unwrap();

        let child_resource = ResourceId::parse(format!("codex:session:{}", child_id)).unwrap();
        repo.mutate_config(|config| {
            let current = config
                .projects
                .iter_mut()
                .find(|candidate| candidate.local_project_id == project.local_project_id)
                .unwrap();
            current.recipe.entries.insert(
                child_resource.clone(),
                RecipeEntry {
                    resource_id: child_resource.clone(),
                    apply_policy: contracts::safe_file(),
                    required: false,
                },
            );
            current.recipe.revision = current.recipe.revision.saturating_add(1);
            current.revision = current.revision.saturating_add(1);
            Ok(())
        })
        .unwrap();

        let review =
            prepare_push_review_with_repository(&repo, &project.local_project_id, &storage_id)
                .unwrap();
        assert!(review.inventory.resources.iter().all(|resource| {
            resource.descriptor.resource_id.as_str() != child_resource.as_str()
        }));
        assert!(review
            .thread_comparison
            .as_ref()
            .unwrap()
            .entries
            .iter()
            .all(|entry| entry.provider_thread_id.as_deref() != Some(child_id)));
        assert!(!review
            .inventory
            .recipe
            .entries
            .contains_key(&child_resource));
        // Inventory sanitizes the effective recipe without rewriting project
        // configuration; the reviewed destination recipe is what Push saves.
        assert!(repo
            .load_config()
            .unwrap()
            .project(&project.local_project_id)
            .unwrap()
            .recipe
            .entries
            .contains_key(&child_resource));

        push_bundle_with_repository(&repo, &project.local_project_id, &storage_id).unwrap();
        let (_, engine) = storage_engine(&repo, &storage_id).unwrap();
        let snapshot = engine.inspect(&project.bundle_id).unwrap();
        let codex_scope = snapshot.manifest.provider_scope(&codex_key()).unwrap();
        assert_eq!(codex_scope.conversations.len(), 1);
        assert!(codex_scope
            .conversations
            .values()
            .all(|thread| { thread.source_thread_id.as_deref() != Some(child_id) }));
        assert!(!codex_scope.recipe.entries.contains_key(&child_resource));
    }

    /// Push excludes subagent rollouts at capture, so valid manifests cannot
    /// contain one. This fixture writes one directly
    /// into storage to pin the split introduced by manifest-only refresh:
    /// the comparison trusts the manifest and surfaces the stored thread
    /// without opening it, while Pull planning — which does read payloads —
    /// still refuses to offer it.  If refresh ever starts hiding the row
    /// again, payload reads have crept back into the manifest-only path.
    /// A rollout crossing the conversation bound by append surfaces the
    /// identical blocked row with or without retained observations.
    #[test]
    fn an_oversize_append_blocks_the_row_on_the_next_comparison() {
        let temp = tempfile::tempdir().unwrap();
        let repo = repository(&temp);
        let storage_id = StorageId::parse("oversize-parity-store").unwrap();
        add_local_storage(&repo, &storage_id, &temp.path().join("store"));
        let project = register(&repo);
        let project_root = temp.path().join("project");
        let codex_home = temp.path().join("codex-home");
        bind_and_link_test_replica(&repo, &project, &storage_id, &project_root, &codex_home);
        let provider_id = "019fb004-0000-7000-8000-00000000dd05";
        let base = command_test_transcript(provider_id, &project_root, &[("m-1", "user", "hi")]);
        let session_path = codex_home
            .join("sessions/2026/07/28")
            .join(format!("rollout-2026-07-28T12-00-00-{provider_id}.jsonl"));
        std::fs::create_dir_all(session_path.parent().unwrap()).unwrap();
        std::fs::write(&session_path, &base).unwrap();

        // Retain an observation, then grow the file past the bound in place.
        get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();
        std::fs::OpenOptions::new()
            .write(true)
            .open(&session_path)
            .unwrap()
            .set_len(conversation_file_limit_bytes() + 1)
            .unwrap();
        let warm = get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();
        super::super::observation_cache::observation_cache()
            .reset_and_purge_disk(repo.root())
            .unwrap();
        let cold = get_project_thread_sync_comparison_with_repository(
            &repo,
            &project.local_project_id,
            &storage_id,
        )
        .unwrap();
        assert_eq!(
            serde_json::to_value(&warm.entries).unwrap(),
            serde_json::to_value(&cold.entries).unwrap(),
            "oversize detection does not depend on what was retained"
        );
        let row = warm
            .entries
            .iter()
            .find(|entry| entry.provider_thread_id.as_deref() == Some(provider_id))
            .unwrap();
        assert_eq!(row.state, ThreadSyncState::Unavailable);
        assert!(
            row.status_detail
                .as_deref()
                .unwrap_or_default()
                .contains("exceeds the 100 MiB per-file sync limit"),
            "blocked detail comes from the discovery mapping: {:?}",
            row.status_detail
        );
    }

    struct PushReuseFixture {
        _temp: tempfile::TempDir,
        repo: LocalStateRepository,
        storage: StorageId,
        project: LocalProjectRegistration,
        home: PathBuf,
        source: PathBuf,
        provider_id: String,
    }

    impl PushReuseFixture {
        fn new(count: usize) -> Self {
            let temp = tempfile::tempdir().unwrap();
            let repo = repository(&temp);
            let storage = StorageId::parse("push-reuse-store").unwrap();
            add_local_storage(&repo, &storage, &temp.path().join("store"));
            let project = register(&repo);
            let project_root = temp.path().join("project");
            let home = temp.path().join("codex-home");
            bind_and_link_test_replica(&repo, &project, &storage, &project_root, &home);
            let directory = home.join("sessions/2026/07/28");
            std::fs::create_dir_all(&directory).unwrap();
            let mut source = PathBuf::new();
            let mut provider_id = String::new();
            for index in 0..count {
                provider_id = format!("019fb003-0000-7000-8000-{index:012x}");
                source = directory.join(format!("rollout-2026-07-28T12-00-00-{provider_id}.jsonl"));
                let transcript = command_test_transcript(
                    &provider_id,
                    &project_root,
                    &[("m-1", "user", "hello")],
                );
                std::fs::write(&source, transcript).unwrap();
            }
            let home = std::fs::canonicalize(home).unwrap();
            let source = std::fs::canonicalize(source).unwrap();
            Self {
                _temp: temp,
                repo,
                storage,
                project,
                home,
                source,
                provider_id,
            }
        }

        fn cached(
            &self,
            stamp: &jsonl_tail_io::SourceStamp,
            generation: Option<u64>,
            revision: Option<u64>,
        ) -> BTreeMap<ThreadId, LocalTailObservation> {
            let thread_id = initial_conversation_thread_id(
                &self.project.bundle_id,
                &codex_key(),
                &self.provider_id,
            )
            .unwrap();
            super::super::observation_cache::observation_cache().take_push_observations(
                &self.home,
                self.repo.root(),
                &self.project.local_project_id,
                &self.storage,
                &[super::super::observation_cache::PushObservationQuery {
                    observation: super::super::observation_cache::ObservationQuery {
                        thread_id,
                        checkpoint_generation: generation,
                        binding_revision: revision,
                    },
                    source: &self.source,
                    stamp,
                    provider_thread_id: &self.provider_id,
                    layout: None,
                }],
            )
        }

        fn warm(&self) -> PushReviewContext {
            prepare_push_review_with_repository(
                &self.repo,
                &self.project.local_project_id,
                &self.storage,
            )
            .unwrap()
        }
    }

    #[test]
    fn push_observation_reuse_resolves_once_and_hands_snapshots_to_builders() {
        let fixture = PushReuseFixture::new(41);
        let review = fixture.warm();
        let metrics = mallard_infrastructure::sync_metrics::register_root(&fixture.home);
        let mut capture_end = None;
        let mut review_work = None;
        let result = push_bundle_reviewed_with_progress(
            &fixture.repo, &fixture.project.local_project_id, &fixture.storage,
            recommended_review_recipe(&review, &fixture.storage), empty_project_content_review(),
            &mut |_| {}, &mut |phase, elapsed| {
                if phase == "capture selected payloads" { capture_end = Some(metrics.snapshot()); }
                if phase == "review selected conversations" {
                    let delta = metrics.snapshot().delta_since(capture_end.as_ref().unwrap());
                    eprintln!("41-thread apply review: {elapsed:?}, reads={}, resolves={}, records={}, hits={}",
                        delta.transcript_bytes_read, delta.full_graph_resolves, delta.records_parsed, delta.observation_reuse_hits);
                    review_work = Some(delta);
                }
            },
        ).unwrap();
        assert!(result.success, "{}", result.message);
        let work = review_work.unwrap();
        assert_eq!(work.observation_reuse_hits, 41);
        assert_eq!(work.transcript_bytes_read, 0);
        assert_eq!(work.full_graph_resolves, 41);
        assert!(
            work.records_parsed > 0,
            "selected roots are resolved during review"
        );
        assert_eq!(
            metrics.snapshot().full_graph_resolves,
            41,
            "builders reuse the roots resolved during review"
        );
    }

