    struct SetupFixture {
        _temp: tempfile::TempDir,
        repo: LocalStateRepository,
        project_dir: PathBuf,
        codex_home: PathBuf,
    }

    fn setup_fixture() -> SetupFixture {
        let temp = tempfile::tempdir().unwrap();
        let repo = LocalStateRepository::from_home_dir(temp.path().join("home")).unwrap();
        let project_dir = temp.path().join("work/app");
        let codex_home = temp.path().join("codex-profile/.codex");
        let storage_dir = temp.path().join("bucket");
        std::fs::create_dir_all(&project_dir).unwrap();
        std::fs::create_dir_all(&codex_home).unwrap();
        std::fs::create_dir_all(&storage_dir).unwrap();
        add_local_storage(
            &repo,
            &StorageId::parse("storage-setup-test").unwrap(),
            &storage_dir,
        );
        SetupFixture {
            _temp: temp,
            repo,
            project_dir,
            codex_home,
        }
    }

    /// Create a draft and point it at the fixture's Codex profile and storage.
    fn draft_ready_to_finalize(fixture: &SetupFixture) -> ProjectSetupDraft {
        let created = create_setup_draft_with_repository(
            &fixture.repo,
            &fixture.project_dir.to_string_lossy(),
        )
        .unwrap();
        assert!(!created.resumed);
        let mut draft = created.draft;
        draft.profiles = BTreeMap::from([(
            codex_key(),
            DraftProfileSelection::Pending {
                path: fixture.codex_home.to_string_lossy().into_owned(),
                display_name: String::new(),
            },
        )]);
        draft.storage = Some(DraftStorageSelection {
            storage_id: StorageId::parse("storage-setup-test").unwrap(),
        });
        draft.repository = DraftRepositoryChoice::New;
        update_setup_draft_with_repository(&fixture.repo, draft).unwrap()
    }

    #[test]
    fn setup_name_uses_github_origin_and_keeps_explicit_edits() {
        let fixture = setup_fixture();
        for url in [
            "https://github.com/owner/My--Repo.git",
            "git@github.com:owner/My--Repo.git",
        ] {
            naming_test_git(&fixture.project_dir, &["init", "--initial-branch=main"]);
            naming_test_git(
                &fixture.project_dir,
                &[
                    "config",
                    "remote.upstream.url",
                    "https://github.com/other/Upstream.git",
                ],
            );
            naming_test_git(&fixture.project_dir, &["config", "remote.origin.url", url]);
            assert_eq!(suggested_project_name(&fixture.project_dir), "My--Repo");
        }
        let mut draft = draft_ready_to_finalize(&fixture);
        assert_eq!(draft.display_name, "My--Repo");
        draft.display_name = "Explicit name".into();
        let saved = update_setup_draft_with_repository(&fixture.repo, draft).unwrap();
        assert_eq!(saved.display_name, "Explicit name");
        let detail =
            finalize_project_setup_with_repository(&fixture.repo, &saved.draft_id, saved.revision)
                .unwrap();
        assert_eq!(detail.project.display_name, "Explicit name");
        let (_, engine) = storage_engine(&fixture.repo, &detail.links[0].storage_id).unwrap();
        assert_eq!(
            engine
                .inspect(&detail.project.bundle_id)
                .unwrap()
                .manifest
                .bundle
                .display_name,
            "Explicit name"
        );
    }

    fn naming_test_git(root: &Path, args: &[&str]) {
        let output = std::process::Command::new("git")
            .arg("-C")
            .arg(root)
            .args([
                "-c",
                "core.hooksPath=/dev/null",
                "-c",
                "commit.gpgSign=false",
            ])
            .args(args)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

